ll p[60];
// l = 0, r = x 的情形。
// 高于 y 的位上都是0
ll calc(ll x, int y) {
    ll ans = 0;
    ll prod = 1;
    down (i, y, 0) {
        if (x & 1LL << i) {
            ans += prod * p[i] % mod;
            ans %= mod;
            prod *= 2;
            prod %= mod;
        }
    }
    return (ans + prod) % mod;
}

ll solve(ll l, ll r, int i) {
    // (x, y) x >= l && y <= r && x <= y && (y ^ x) == y - x
    ll ans = 0;
    ll prod = 1;
    down (j, i, 0) {
        int x = get_bit(l, j), y = get_bit(r, j);
        ll mask = (1ULL << j) - 1;
        if (x > y) {
            prod = 0;
            break;
        }
        if (x < y) {
            ans += calc(r & mask, i - 1);
            ans += calc((l & mask) ^ mask, i - 1);
            ans %= mod;
        }
    }
    ans += prod;
    return ans;
}

