int main() {
    ll L, R;
    cin >> L >> R;

    L--;

    // y と x は2進数で同じ桁数である必要がある
    // このとき, y % x = y - x
    // 繰り下がりが無いことが必要十分

    vector<ll>powThree(100);
    powThree[0] = 1;
    for (int i = 1; i < powThree.size(); ++i) {
        powThree[i] = powThree[i-1] * 3 % mod;
    }

    // biL[0] はLの2進1の位の数
    vector<int>biL(62, 0);
    vector<int>biR(62, 0);
    ll one = 1;
    for (int i = 0; i < biL.size(); ++i) {
        if(L & (one << i)){
            biL[i] = 1;
        }
        if(R & (one << i)){
            biR[i] = 1;
        }
    }

    int ketaL = 0;
    int ketaR = 0;
    for (int i = biL.size(); i >= 0; --i) {
        if(biL[i] == 1) {
            ketaL = i;
            break;
        }
    }
    for (int i = biL.size(); i >= 0; --i) {
        if(biR[i] == 1) {
            ketaR = i;
            break;
        }
    }
    ll ans = 0;
    for (int i = ketaL + 1; i < ketaR; ++i) {
        ans += powThree[i];
        ans %= mod;
    }

    // L-1以下のを引く
    int temp = 1;
    ll sumL = 0;
    for (int i = ketaL - 1; i > 0; --i) {
        if(biL[i] == 1){
            sumL += powThree[i] * temp;
            sumL %= mod;
            temp *= 2;
            temp %= mod;
        }

    }
    if(biL[0] == 1){
        sumL += 3 * temp;
        sumL %= mod;
    } else{
        sumL += temp;
        sumL %= mod;
    }

    if(L == 1){
        sumL = 1;
    }
    if(L == 0){
        sumL == 0;
    }


    ans = ans + mod - sumL;
    ans %= mod;


    // R以下のを足す
    temp = 1;
    ll sumR = 0;
    for (int i = ketaR - 1; i > 0; --i) {
        if(biR[i] == 1){
            sumR += powThree[i] * temp;
            sumR %= mod;
            temp *= 2;
            temp %= mod;
        }
    }
    if(biR[0] == 1){
        sumR += 3 * temp;
        sumR %= mod;
    } else{
        sumR += temp;
        sumR %= mod;
    }


    ans = ans + sumR;
    ans %= mod;

    cout << ans;
    return 0;
}

