ll p[60];
// l = 0, r = x 的情形。
// 高于 y 的位上都是0
ll calc(ll x, int y) {
    ll ans = 0;
    ll prod = 1;
    down (i, y, 0) {
        if (x & 1LL << i) {
            ans += prod * p[i] % mod;
            ans %= mod;
            prod *= 2;
            prod %= mod;
        }
    }
    return (ans + prod) % mod;
}

map<pair<ll,ll>,ll> mem;

ll solve(ll l, ll r, int i) {
    // (x, y) x >= l && y <= r && x <= y && (y ^ x) == y - x
    if (l > r) return 0;
    if (l == r) return 1;
    if (l == 0) return calc(r, i);
    // l < r
    // 1,1

    if (l & 1LL << i) {
        return solve(l - (1LL << i), r - (1LL << i), i - 1);
    }
    // 0,0
    if ((r & 1LL << i) == 0) { // 亦可写成 if (r < (1 << i))
        return solve(l, r, i - 1);
    }
    auto iter = mem.find({l, r});
    if (iter != mem.end()) {
        return iter -> second;
    }
    // 1,0
    ll t01 = solve(l, r - (1LL << i), i - 1);
    ll t00 = solve(l, (1LL << i) - 1, i - 1);
    ll t11 = solve(0, r - (1LL << i), i - 1);
    ll res = (t01 + t00 + t11) % mod;
    mem[{l, r}] = res;
    return res;
}

