        function<i64(int, bool, bool)> rec = [&](int pos, bool brr, bool brl) {
            if (pos < 0) {
                return 1ll;
            }

            if (dp[pos][brr][brl] != -1) {
                return dp[pos][brr][brl];
            }

            i64 res = 0;
