typedef long long LL;
const LL N = 1000000007;

LL dp[65][2][2];
LL bx[65],by[65];

LL dfs(LL pos,LL l1,LL l2){
	if(!pos) return 1;
	if(dp[pos][l1][l2] != -1) return dp[pos][l1][l2];
	LL ret = 0;
	LL t1 = l1 ? bx[pos] : 0,t2 = l2 ? by[pos] : 1;
	for(LL y = t1;y <= t2;y ++){
		for(LL x = t1;x <= y;x ++){
			ret += dfs(pos - 1,l1 && x == t1,l2 && y == t2);
			ret %= N;
		}
	}
//	cout << pos << ' '  << l1 << ' ' << l2 << ' ' << ret << endl;
	dp[pos][l1][l2] = ret;
	return ret;
}

int main(){
	memset(dp,-1,sizeof(dp));
	LL l,r,ll = 0,rr = 0,ans = 0;
	cin >> l >> r;
	while(1){ if(!l) break; bx[++ ll] = l & 1; l >>= 1; }
	while(1){ if(!r) break; by[++ rr] = r & 1; r >>= 1; }
	for(LL i = ll;i <= rr;i ++) ans = (ans + dfs(i - 1,i == ll,i == rr)) % N;
	cout << ans << endl;
	return 0;
}

