#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int mod = 1000000007;
const int Maxb = 62;

ll L, R;

int All(ll mask, int lvl, int my)
{
    int res = 1;
    for (int i = my; i >= 0; i--)
        if (i <= lvl) res = ll(res) * 3ll % mod;
        else if (mask & 1ll << ll(i)) res = ll(res) * 2ll % mod;
    return res;
}

int Solve2(ll mask, int lvl, ll lim)
{
    if (mask) {
        int res = 0;
        int pnt = Maxb - 1;
        while (!(mask & 1ll << ll(pnt))) pnt--;
        ll cur = 1ll << ll(pnt);
        if (cur > lim) return 0;
        int mult = 1;
        for (int i = pnt - 1; i >= 0; i--) {
            if (cur + (1ll << ll(i)) <= lim) {
                int my = mult;
                if (i <= lvl) my = 2ll * mult % mod;
                res = (res + ll(All(mask, lvl, i - 1)) * my) % mod;
                if (i > lvl && !bool(mask & 1ll << ll(i))) return res;
                cur |= 1ll << ll(i);
            } else if (i <= lvl) mult = 2ll * mult % mod;
        }
        res = (res + mult) % mod;
        return res;
    } else {
        int res = 0;
        for (int i = lvl; i >= 0; i--)
            res = (res + Solve2(1ll << ll(i), i - 1, lim)) % mod;
        return res;
    }
}

int Solve(ll lim1, ll lim2)
{
    int res = 0;
    ll cur = 0;
    for (int i = Maxb - 1; i >= 0; i--)
        if (lim1 & 1ll << ll(i)) {
            res = (res + Solve2(cur, i - 1, lim2)) % mod;
            cur |= 1ll << ll(i);
        }
    res = (res + Solve2(cur, -1, lim2)) % mod;
    return res;
}

int main()
{
    cin >> L >> R;
    int res = (Solve(R, R) - Solve(R, L - 1) + mod) % mod;
    printf("%d\n", res);
    return 0;
}

