int solve(int si,int ue,int keta){
//	cout<<si<<" "<<ue<<" "<<keta<<endl;
	int dp[80][4]={};
	dp[0][3]=1;

	for(int i=1;i<keta;i++){
		int u=(ue&(1ll<<keta-i-1))>0;
		int s=(si&(1ll<<keta-i-1))>0;
	//	cout<<u<<" "<<s<<endl;
		dp[i][0]+=(3*dp[i-1][0])%inf;

		if(s==0){
			dp[i][0]+=(1*dp[i-1][1])%inf;
			dp[i][1]+=(2*dp[i-1][1])%inf;
		}
		else{
			dp[i][1]+=(1*dp[i-1][1])%inf;
		}

		if(u==1){
			dp[i][0]+=(1*dp[i-1][2])%inf;
			dp[i][2]+=(2*dp[i-1][2])%inf;
		}
		else{
			dp[i][2]+=(1*dp[i-1][2])%inf;
		}


		if(s==u){
			dp[i][3]+=dp[i-1][3];
		}
		else if(s==0 && u==1){
	//		cout<<"d"<<endl;
			dp[i][3]+=dp[i-1][3];
			dp[i][2]+=dp[i-1][3];
			dp[i][1]+=dp[i-1][3];
	//		cout<<dp[i][1]<<endl;
		}
		for(int j=0;j<4;j++)dp[i][j]%=inf;

	}

	int ans=0;
	for(int j=0;j<4;j++)ans+=dp[keta-1][j];
	ans%=inf;
	//cout<<ans<<endl;
	return ans%inf;
}


