ll mod_pow(ll x, ll p, ll M = MOD) {
  ll a = 1;
  while (p) {
    if (p % 2)
      a = a*x%M;
    x = x*x%M;
    p /= 2;
  }
  return a;
}

ll mod_inverse(ll a, ll M = MOD) {
  return mod_pow(a, M - 2, M);
}

ll ketadp(ll l, ll r) {
  int n = 62;
  vector<vector<vll>> dp(n + 1, vector<vll>(2, vll(2, vl(2))));
  dp[n][0][1][1] = 1;
  for (int keta = n; keta > 0; keta--) {
    int nketa = keta - 1;
    rep (al, 2) {
      rep (i, 2) {
        rep (j, 2) {
          if (dp[keta][al][i][j] == 0) continue;
          rep (x, 2) {
            rep (y, 2) {
              if (x == 1 and y == 0) continue;
              int nal;
              if (al == 1) nal = 1;
              else {
                if (x == y) nal = x;
                else continue;
              }
              int ni, nj;
              if (i == 0) {
                ni = 0;
              }
              else {
                if (l & (1LL << nketa)) {
                  if (x == 0) ni = 0;
                  else ni = 1;
                }
                else {
                  if (x == 0) ni = 1;
                  else continue;
                }
              }

              if (j == 0) {
                nj = 0;
              }
              else {
                if (r & (1LL << nketa)) {
                  if (y == 0) nj = 0;
                  else nj = 1;
                }
                else {
                  if (y == 0) nj = 1;
                  else continue;
                }
              }
              (dp[nketa][nal][ni][nj] += dp[keta][al][i][j]) %= MOD;
