class some{
public:
	char enz;//どの演算を行いますか?
	ptr<some> hi,mg;llint ban;
	bool syu;
	bool ramukan;//ラムダの完結
	some(void){ramukan=false;syu=false;enz='Q';ban=0;}
	//syukuがtrueなら縮約済み!やった!
};
ptr<some> hairead(ptr<some> in,int soe){
	ptr<some> gen=in->hi;
	while(gen->enz=='H'){
		if(soe<gen->ban){gen=gen->hi;}
		else{soe-=gen->ban;gen=gen->mg;}
	}
	return gen;
}
ptr<some> haiwrite(ptr<some> in,int soe,ptr<some> suu){

	ptr<some> ata(new some());
	ptr<some> gen(new some());
	(*ata)=(*in);
	(*gen)=(*(in->hi));
	ata->hi=gen;
	if(gen->enz!='H'){ata->hi=suu;return ata;}
	while(-1){
		ptr<some>iti(new some());
		if(soe<gen->ban){
			if(gen->hi->enz!='H'){gen->hi=suu;return ata;}
			(*iti)=(*(gen->hi));
			gen->hi=iti;
			gen=iti;
		}else{
			if(gen->mg->enz!='H'){gen->mg=suu;return ata;}
			soe-=gen->ban;
			(*iti)=(*(gen->mg));
			gen->mg=iti;
			gen=iti;
		}
	}
};
ptr<some> sai_hai(int soe,ptr<some>suu){

	if(soe==1){return suu;}
	ptr<some>ans(new some());
	ans->enz='H';ans->ban=soe/2;
	ans->hi=sai_hai(soe/2,suu);
	ans->mg=sai_hai((soe+1)/2,suu);
	return ans;
}
ptr<some> make_hai(int soe,ptr<some> suu){
	ptr<some>ans(new some());
	ans->enz='h';ans->ban=soe;
	if(soe>0){ans->hi=sai_hai(soe,suu);}
	return ans;
}

ptr<some> unite_hai(ptr<some> v,ptr<some>w){
	if(v->ban==0){return w;}
	if(w->ban==0){return v;}
	ptr<some>ans(new some());
	ptr<some>tgi(new some());
	ans->enz='h';ans->ban=v->ban+w->ban;ans->hi=tgi;
	tgi->enz='H';tgi->ban=v->ban;tgi->hi=v->hi;tgi->mg=w->hi;
	return ans;
}
