bool isoy(ptr<some>tai){return (tai!=nullptr&&(!tai->syu)&&(tai->enz=='#'||tai->enz=='@'));}
bool daishi(ptr<some>&tai,int num,ptr<some>&xca){
	//cerr<<"dai";
	//syutu(tai);
	if(tai->syu){return 0;}
	if(tai->ramukan){return 0;}
	bool hen=0;
	ptr<some>moto=tai;
	ptr<some> iti(new some());(*iti)=(*tai);tai=iti;tai->syu=0;
	if(tai->enz=='&'&&tai->ban==num){tai=xca;hen=1;}
	else if(tai->enz=='&'&&tai->ban>num){tai->ban--;hen=1;}
	else if(tai->enz=='@'){hen|=daishi(tai->hi,num+1,xca);}
	else if(tai->enz=='#'){hen|=daishi(tai->hi,num,xca);hen|=daishi(tai->mg,num,xca);}
	if(hen){tai->syu=0;}else{tai=moto;}
	return hen;
}

