void keisan(ptr<some>in){
	//cerr<<"sai";
	if(in==nullptr||in->syu||in->enz!='#'){return;}
		if(in->hi!=nullptr&&in->hi->enz=='$'){exit(0);}
	//cerr<<"de "<<in->enz;
	//syutu(in);
	if(isoy(in->hi)){keisan(in->hi);}

	if(in->hi->enz=='@'){
		//cerr<<"ramu";
		keisan(in->mg);
		ptr<some> xca=in->mg;
		//syutu(xca);
		ptr<some> tai=in->hi->hi;
		daishi(tai,0,xca);
		(*in)=(*tai);
		keisan(in);
		return;
	}
	if(in->hi->enz=='1'){
		if(isoy(in->mg)){keisan(in->mg);}
		in->enz='3';return;
	}
	else if(in->hi->enz=='2'){in->syu=1;in->enz='4';return;}
	else if(in->hi->enz=='3'){(*in)=(*(in->hi->mg));return;}
	else if(in->hi->enz=='4'){
		if(isoy(in->mg)){keisan(in->mg);}
		(*in)=(*(in->mg));return;
	}else if(isoy(in->mg)){keisan(in->mg);}
	char hiz=in->hi->enz,mgz=in->mg->enz;
	//cerr<<"himg="<<hiz<<mgz<<endl;

	if(hiz=='#'||hiz=='@'||hiz=='&'){in->syu=1;return;}
	if(mgz=='n'){
		bool yatta=1;
		//if(in->hi->enz=='*'&&in->mg->ban==2){cerr<<"hyo";}
		switch(hiz){
			case '+':in->enz='P';in->ban =in->mg->ban;break;
			case 'P':in->enz='n';in->ban =in->hi->ban+in->mg->ban;break;
			case '-':in->enz='M';in->ban =in->mg->ban;break;
			case 'M':in->enz='n';in->ban =in->hi->ban-in->mg->ban;break;
			case '*':in->enz='T';in->ban =in->mg->ban;break;
			case 'T':in->enz='n';in->ban =in->hi->ban*in->mg->ban;break;
			case '/':in->enz='D';in->ban =in->mg->ban;break;
			case 'D':in->enz='n';in->ban =in->hi->ban/in->mg->ban;break;
			case '%':in->enz='A';in->ban =in->mg->ban;break;
			case 'A':in->enz='n';in->ban =in->hi->ban%in->mg->ban;break;
			case 'o':in->enz='O';in->ban =in->mg->ban;break;
			case 'O':in->enz='n';in->ban =max(in->hi->ban,in->mg->ban);break;
			case 'c':in->enz='C';in->ban =in->mg->ban;break;
			case 'C':in->enz='n';in->ban =min(in->hi->ban,in->mg->ban);break;
			case '<':in->enz='S';in->ban =in->mg->ban;break;
			case 'S':in->enz='n';in->ban=((in->hi->ban < in->mg->ban)?1:0);break;
			case '>':in->enz='B';in->ban =in->mg->ban;break;
			case 'B':in->enz='n';in->ban=((in->hi->ban > in->mg->ban)?1:0);break;
			default:yatta=0;
		}
		if(yatta){
			//cerr<<"ya";
			in->hi=nullptr;in->mg=nullptr;in->syu=1;return;
		}
	}
	if(in->enz!='#'){in->hi=nullptr;in->mg=nullptr;}//計算を行ったので
	if(hiz=='v'&&mgz=='n'){in->enz='V';in->ban=in->mg->ban;}
	if(hiz=='V'){(*in)=(*make_hai(in->hi->ban,in->mg));}
	if(hiz=='u'&&mgz=='h'){in->enz='U';in->hi=in->mg;}
	if(hiz=='z'){in->enz='n';in->ban =in->mg->ban;}
	if(hiz=='l'){in->enz='h';in->ban =in->mg->hi->ban;in->hi=in->mg->hi->hi;}
	if(hiz=='m'){in->enz='h';in->ban =in->mg->ban-in->mg->hi->ban;in->hi=in->mg->hi->mg;}
	if(hiz=='U'&&mgz=='h'){(*in)=(*unite_hai(in->hi->hi,in->mg));}
	if(hiz=='h'){

		ptr<some>ata(new some());
		ata->ban=1;ata->enz='h';ata->hi=in->mg;
		(*in)=*unite_hai(in->hi,ata);

	}
	if(hiz=='r'&&mgz=='h'){in->enz='R';in->hi=in->mg;}
	if(hiz=='R'&&mgz=='n'){(*in)=(*hairead(in->hi->hi,in->mg->ban));}
	if(hiz=='w'&&mgz=='h'){in->enz='W';in->hi=in->mg;}
	if(hiz=='W'&&mgz=='n'){in->enz='=';in->hi=in->hi->hi;in->ban=in->mg->ban;}
	if(hiz=='='){(*in)=(*haiwrite(in->hi->hi,in->hi->ban,in->mg));}
	if(hiz=='i'&&mgz=='n'){in->enz=((in->mg->ban)?'1':'2');}
	if(hiz=='j'&&mgz=='n'){in->enz=((in->mg->ban<0)?'1':'2');}
	in->syu=1;return;
}
