class Combination{
public:
  typedef long long ll;
  ll N;
  ll mod;
  vector<ll> fac;
  vector<ll> finv;
  vector<ll> inv;


  Combination(ll N = 1e6,ll mod = 1e9 + 7): N(N), mod(mod), fac(N+1), finv(N+1), inv(N+1){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(Int i = 2; i <= N; i++){
      fac[i] = fac[i-1] * i % mod;
      inv[i] = mod - inv[mod%i] * (mod / i) % mod;
      finv[i] = finv[i-1] * inv[i] % mod;
    }
  }

  function<ll(ll,ll)> get = [&](ll n,ll r){
    if( n < r ) return 0LL;
    if( n < 0 || r < 0) return 0LL;
    return fac[n] * (finv[r] * finv[n-r] % mod) % mod;
  };

};
auto nCr = (new Combination())->get;

ll mod_pow(ll x,ll n){
  ll res=1;
  while(n){
    if(n%2) res=res*x%mod;
    x=x*x%mod;
    n/=2;
  }
  return res;
}


Int L, R;
Int used[100][4][4][2], mem[100][4][4][2];
Int dfs(Int idx, Int sameX, Int sameY, Int f, string hisX = "", string hisY = ""){
  if(idx == -1) return 1;
  if(used[idx][sameX][sameY][f]++) return mem[idx][sameX][sameY][f];

  auto to0 = [&](Int &valid, Int &nsame, Int same){
    nsame = same;
    if(L>>idx&1) valid &= !(same&1); //Lより小さくなる
    if(R>>idx&1) nsame &= 1; //Rより小さくなる
  };

  auto to1 = [&](Int &valid, Int &nsame, Int same){
    nsame = same;
    if((L>>idx&1) == 0) nsame &= 2; //Lより大きくなる
    if((R>>idx&1) == 0) valid &= !(same>>1&1); //Rより大きくなる
  };

  Int res = 0;
  for(Int i=0;i<2;i++)
    for(Int j=0;j<2;j++){
      Int valid = 1;
      Int nsameX, nsameY;
      i==0? to0(valid, nsameX, sameX):to1(valid, nsameX, sameX);
      j==0? to0(valid, nsameY, sameY):to1(valid, nsameY, sameY);
      if(i == 1 && j == 0) valid = 0;
      if(i == 0 && j == 1) valid &= f;
      Int nf = f | i;
      if(valid) res = res + dfs(idx - 1, nsameX, nsameY, nf, hisX + char('0'+i), hisY+char('0'+j));
      res %= mod;
    }
  return mem[idx][sameX][sameY][f] = res;
}

