ll rec(int k, int f1, int f2, int f3){
    if(k==-1)return 1;
    if(dp[k][f1][f2][f3]!=-1)return dp[k][f1][f2][f3];
    ll ans = 0;
    int Y = (y>>k)&1, X = (x>>k)&1;
    if(f1 && f2){
        ans += 3*rec(k-1,1,1,f3);
    }
    if(f1 && !f2){
        if(Y)ans += 2*rec(k-1,1,0,f3) + rec(k-1,1,1,f3);
        else ans += rec(k-1,1,0,f3);
    }
    if(!f1 && f2){
        if(f3){
            if(!X)ans += 2*rec(k-1,0,1,f3)+rec(k-1,1,1,f3);
            else ans += rec(k-1,0,1,f3);
        }
        else {
            if(!X)ans += rec(k-1,0,1,0)+rec(k-1,1,1,1);
            else ans += rec(k-1,0,1,1);
        }
    }
    if(!f1 && !f2){
        if(X==Y){
            if(f3)ans += rec(k-1,0,0,1);
            else {
                if(X==1)ans += rec(k-1,0,0,1);
                else ans += rec(k-1,0,0,0);
            }
        }
        else if(X>Y)return dp[k][f1][f2][f3] = 0;
        else {
            if(!f3){
                ans += rec(k-1,1,0,1);
                ans += rec(k-1,0,1,0);
            }
            else {
                ans += rec(k-1,0,0,f3);
                ans += rec(k-1,1,0,f3);
                ans += rec(k-1,0,1,f3);
            }
        }
    }
    ans %= mod;
    return dp[k][f1][f2][f3]=ans;
}

