string convert (long long x) {
    string ans = "";
    while (x > 0) {
        int temp = x % 2;
        ans += (char)(temp + 48);
        x /= 2;
    }

    reverse(ans.begin(), ans.end());
    return ans;
}

int solve (int pos, int low, int high, int num, int specified) {
    if (pos == n) return dp[pos][low][high][num] = pw[num];
    if (dp[pos][low][high][num] != -1) return dp[pos][low][high][num];

    int ans = 0;
    int l = 0, r = 1;
    if (low) l = a[pos] - '0';
    if (high) r = b[pos] - '0';

    for (int i = l; i <= r; i++) {
        int nlow = 0, nhigh = 0;
        if (low && i == l) nlow = 1;
        if (high && i == r) nhigh = 1;
        if (pos < n - specified && i == 1) continue;
        if (pos == n - specified && i == 0) continue;

        add(ans, solve(pos + 1, nlow, nhigh, num + (i == 0 && pos >= n - specified), specified));
    }

    return dp[pos][low][high][num] = ans;
}

