ll func(vvvvl &DP, ll L, ll R, ll k, ll X, ll Y, ll Z) {
  if (k == -1)
    return 1;
  if (DP[k][X][Y][Z] != -1)
    return DP[k][X][Y][Z];
  ll ans = 0;
  // x=0,y=0
  if (X == 1 || (L >> k) % 2 == 0) {
    ans += func(DP, L, R, k - 1, X, (R >> k) % 2 == 1 ? 1 : Y, Z);
  }
  // x=0,y=1
  if ((X == 1 || (L >> k) % 2 == 0) && (Y == 1 || (R >> k) % 2 == 1) &&
      Z == 1) {
    ans += func(DP, L, R, k - 1, X, Y, Z);
  }
  // x=1,y=1
  if (Y == 1 || (R >> k) % 2 == 1) {
    ans += func(DP, L, R, k - 1, (L >> k) % 2 == 0 ? 1 : X, Y, 1);
  }
  ans %= MOD;
  DP[k][X][Y][Z] = ans;
  return ans;
}

