ll hoge(int d,int S,int LT,int RT) {
	if(d==-1) return S==1;
	if(dp[S][LT][RT][d]>=0) return dp[S][LT][RT][d];

	ll ret=0;

	int a,b;
	FOR(a,2) FOR(b,2) {
		if(a==0 && LT && (L&(1LL<<d))>0) continue;
		if(b==1 && RT && (R&(1LL<<d))==0) continue;
