		int NLT=LT&&(((L>>d)&1)==a);
		int NRT=RT&&(((R>>d)&1)==b);
		int NS=S || (a==1 && b==1);
		ret+=hoge(d-1,NS,NLT,NRT);
	}

	return dp[S][LT][RT][d]=ret%mo;
}

