int mod = 1000000000 + 7;
vector<int> L, R;
vector<vector<vector<vector<int>>>> dp;
// L <= x <= y <= Rでyとxの関係が(1, 1), (1, 0), (0, 0)のどれか
// 最初は(1, 1)じゃないとだめ
long long digit_dp(int digit, bool is_tight_l, bool is_tight_r, bool leading_zero) {
    if (digit >= SIZE(L)) {
        return 1;
    }

    if (dp[digit][is_tight_l][is_tight_r][leading_zero] != -1) {
        return dp[digit][is_tight_l][is_tight_r][leading_zero];
    }

    LL ans = 0;

    // (1, 1)
    if (not is_tight_r or R[digit] == 1) {
        bool next_is_tight_l = is_tight_l and (L[digit] == 1);
        bool next_is_tight_r = is_tight_r and (R[digit] == 1);
        (ans += digit_dp(digit + 1, next_is_tight_l, next_is_tight_r, false)) %= mod;
    }

    // (0, 0)
    if (not is_tight_l or L[digit] == 0) {
        bool next_is_tight_l = is_tight_l and (L[digit] == 0);
        bool next_is_tight_r = is_tight_r and (R[digit] == 0);
        (ans += digit_dp(digit + 1, next_is_tight_l, next_is_tight_r, leading_zero)) %= mod;
    }

    // (1, 0)
    if (not leading_zero) {
        if ((not is_tight_r or R[digit] == 1) and (not is_tight_l or L[digit] == 0)) {
            bool next_is_tight_l = is_tight_l and (L[digit] == 0);
            bool next_is_tight_r = is_tight_r and (R[digit] == 1);
            (ans += digit_dp(digit + 1, next_is_tight_l, next_is_tight_r, false)) %= mod;
        }
    }

    return dp[digit][is_tight_l][is_tight_r][leading_zero] = ans % mod;
}

