#include <bits/stdc++.h>
using namespace std;
#define int long long
#define p (int)(1e9 + 7)

int MOD(int a){
	return (a %= p) >= 0 ? a : a + p;
}

int MSB(int x){
	int ans;
	for(ans = 0; (1ll << ans) <= x; ans++);
	return ans - 1;
}

map<tuple<int, int>, int> dp;
map<tuple<int, int, int>, int> dp_sub;

int solve_sub(int L, int R, int k){
//	printf("solve_sub(%lld, %lld, %lld)\n", L, R, k);
	auto v = dp_sub.find(tuple<int, int, int>(L, R, k));
	if(v != dp_sub.end()){
		return v->second;
	}
	if(k == -1){
		return 1;
	}
	int a = MSB(L), b = MSB(R);
	int ans = 0;
	if((1ll << k) <= R){
		if(a == k){
			ans = MOD(ans + solve_sub(L - (1ll << k), R - (1ll << k), k - 1));
		}
		else{
			ans = MOD(ans + solve_sub(0, R - (1ll << k), k - 1));
		}
	}
	if(L < (1ll << k) && (1ll << k) <= R){
		ans = MOD(ans + solve_sub(L, R - (1ll << k), k - 1));
	}
	if(L < (1ll << k)){
		if(b == k){
			ans = MOD(ans + solve_sub(L, (1ll << k) - 1, k - 1));
		}
		else{
			ans = MOD(ans + solve_sub(L, R, k - 1));
		}
	}
//	printf("solve_sub(%lld, %lld, %lld) = %lld\n", L, R, k, ans);
	dp_sub[tuple<int, int, int>(L, R, k)] = ans;
	return ans;
}

int solve(int L, int R){
//	printf("solve(%lld, %lld)\n", L, R);
	auto v = dp.find(tuple<int, int>(L, R));
	if(v != dp.end()){
		return v->second;
	}
	int ans;
	if(L == R){
		ans = 1;
	}
	else{
		int a = MSB(L), b = MSB(R);
		if(a == b){
			ans = solve(L - (1ll << a), R - (1ll << b));
		}
		else{
			ans = MOD(solve(0, R - (1ll << b)) + solve_sub(L, R - (1ll << b), b - 1) + solve(L, (1ll << b) - 1));
		}
	}
//	printf("solve(%lld, %lld) = %lld\n", L, R, ans);
	dp[tuple<int, int>(L, R)] = ans;
	return ans;
}

signed main(){
	int L, R, i;
	scanf("%lld%lld", &L, &R);
	int ans = 0;
	for(i = 0; ; i++){
//		printf("i = %lld\n", i);
		int lO_O = (1ll << i);
		if(2 * lO_O <= L){
			continue;
		}
		else if(lO_O > R){
			break;
		}
		else if(lO_O <= L && L < 2 * lO_O){
			if(2 * lO_O <= R){
				ans = MOD(ans + solve(L - lO_O, lO_O - 1));
			}
			else{
				ans = MOD(ans + solve(L - lO_O, R - lO_O));
			}
		}
		else{
			if(2 * lO_O <= R){
				ans = MOD(ans + solve(0, lO_O - 1));
			}
			else{
				ans = MOD(ans + solve(0, R - lO_O));
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

