ll calc(ll l, ll r, bool recurse) {
  int bitl = 0;
  int bitr = 0;
  for (int i = 0; ; ++i) {
    if (!(l >> i)) {
      bitl = i;
      break;
    }
  }
  for (int i = 0; ; ++i) {
    if (!(r >> i)) {
      bitr = i;
      break;
    }
  }
  if (bitl == bitr) {
    if (bitl == 0) {
      return 1;
    }
    ll mask = (1 << (bitl-1)) - 1;
    return calc(l & mask, r & mask, true);
  }
  debug2(bitl, bitr);

  ll ans = 0;
  FOR (i, bitl, bitr - 1) {
    ans = (ans + po3[i]) % mod;
  }
  debug(ans);

  for (int i = bitl - 1; i >= 0; --i) {
    ll left_l = (l >> i);
    if (left_l & 1) {
      continue;
    }
    ans = (ans + po2[cnt0(left_l + 1)] * po3[i]) % mod;
  }
  ans = (ans + po2[cnt0(l)]) % mod;
  debug(ans);

  for (int i = bitr - 2; i >= 0; --i) {
    ll left_r = (r >> i);
    if ((left_r & 1) == 0) {
      continue;
    }
    ans = (ans + po2[cnt1(left_r - 1)] * po3[i]) % mod;
  }
  if (recurse && bitl == 0) {
  debug(ans);
    ans = (ans + po2[cnt1(r) + 1]) % mod;
  } else {
    debug(po2[cnt1(r)]);
    ans = (ans + po2[cnt1(r)]) % mod;
  }
  debug(ans);

  return ans;
}

