ll dp[100][2][2][2];

ll L, R;
int length;
const ll MOD = 1000000007;

int main() {
	cin >> L >> R;
	ll cpyL = L, cpyR = R;
	int cnt = 0;
	while (cpyL > 0)cpyL >>= 1, cnt++;
	length = cnt;
	cnt = 0;
	while (cpyR > 0)cpyR >>= 1, cnt++;
	length = max(length, cnt);

	dp[0][1][1][0] = 1;

	for (int i = 0; i < length; i++) {

		int nowRbit = ((R >> (length - i - 1)) & 1), nowLbit = ((L >> (length - i - 1)) & 1);

		for (int j = 0; j < 2; j++)for (int k = 0; k < 2; k++)for (int l = 0; l < 2; l++) {

			ll now = dp[i][j][k][l];
			dp[i][j][k][l] %= MOD;

			for (int x = 0; x < 2; x++)for (int y = 0; y < 2; y++) {
				if (x == 1 && y == 0)continue;

				int nj = j, nk = k, nl = l;
				if (!l && x != y)continue;
				if (!l && x == 1)nl = 1;

				if (j && nowLbit == 1 && x == 0)continue;
				if (j && nowLbit == 0 && x == 1)nj = 0;

				if (k && nowRbit == 0 && y == 1)continue;
				if (k && nowRbit == 1 && y == 0)nk = 0;

				dp[i + 1][nj][nk][nl] += now;
			}

		}
	}

	ll ans = 0;

	for (int j = 0; j < 2; j++)for (int k = 0; k < 2; k++)for (int l = 0; l < 2; l++)
		ans += dp[length][j][k][l];

	cout << ans % MOD << endl;

	return 0;
}

