	if(soe==1){return suu;}
	ptr<some>ans(new some());
	ans->enz='H';ans->ban=soe/2;
	ans->hi=sai_hai(soe/2,suu);
	ans->mg=sai_hai((soe+1)/2,suu);
	return ans;
}
ptr<some> make_hai(int soe,ptr<some> suu){
	ptr<some>ans(new some());
	ans->enz='h';ans->ban=soe;
	if(soe>0){ans->hi=sai_hai(soe,suu);}
	return ans;
}

ptr<some> unite_hai(ptr<some> v,ptr<some>w){
	if(v->ban==0){return w;}
	if(w->ban==0){return v;}
	ptr<some>ans(new some());
	ptr<some>tgi(new some());
	ans->enz='h';ans->ban=v->ban+w->ban;ans->hi=tgi;
	tgi->enz='H';tgi->ban=v->ban;tgi->hi=v->hi;tgi->mg=w->hi;
	return ans;
}
