			case '-':in->enz='M';in->ban =in->mg->ban;break;
			case 'M':in->enz='n';in->ban =in->hi->ban-in->mg->ban;break;
			case '*':in->enz='T';in->ban =in->mg->ban;break;
			case 'T':in->enz='n';in->ban =in->hi->ban*in->mg->ban;break;
			case '/':in->enz='D';in->ban =in->mg->ban;break;
			case 'D':in->enz='n';in->ban =in->hi->ban/in->mg->ban;break;
			case '%':in->enz='A';in->ban =in->mg->ban;break;
			case 'A':in->enz='n';in->ban =in->hi->ban%in->mg->ban;break;
			case 'o':in->enz='O';in->ban =in->mg->ban;break;
