ll find(ll msb, ll isLlarger, ll isRsmaller, ll bit) {
	if (bit < 0)return msb == 1;
	if (dp[msb][isLlarger][isRsmaller][bit] >= 0)return dp[msb][isLlarger][isRsmaller][bit];


	ll ret = 0;
	REP(i, 2) {
		REP(j, 2) {
			if (i > j)continue;
			if (i == 0 && !isLlarger && (l & (1LL << bit)) > 0)continue;
			if (j == 1 && !isRsmaller && (r & (1LL << bit)) == 0)continue;
			if (msb == 0 && i != j)continue;
			ll nmsb = 0;
			if ((i == 1 && j == 1) || msb)nmsb = 1;
			ll nl = isLlarger || (((l >> bit) & 1) != i);
			ll nr = isRsmaller || (((r >> bit) & 1) != j);
			(ret += find(nmsb, nl, nr, bit - 1)) %= MOD;
		}
	}
	return dp[msb][isLlarger][isRsmaller][bit] = ret;
}



