using namespace std;
typedef long long ll;
const ll MOD = 1e9 + 7;

ll roll (ll lo, ll hi)
{
    ll res = 0;
    hi++;
    for (int i = -1; i <= 60; i++)
        for (int j = 0; j <= 60; j++)
        {
            ll iv;
            if (i == -1) iv = 0;
            else iv = (1LL << i);

            if (lo & iv) continue;
            if (!(hi & (1LL << j))) continue;
            ll lval = lo + iv, hval = hi - (1LL << j);
            ll lk = (lval >> (max (i, j))), hk = (hval >> (max (i, j)));
            if ((lk & hk) != lk)
                continue;
            ll nt = 1;
            for (int k = min (i, j); k < max (i, j); k++)
            {
                if (k < 0) continue;
                if (i < j)
                {
                    if (!(lval & (1LL << k)))
                        nt = (2 * nt) % MOD;
                }
                else
                {
                    if (hval & (1LL << k))
                        nt = (2 * nt) % MOD;
                }
            }
            for (int k = 0; k < min (i, j); k++)
                nt = (3 * nt) % MOD;
            res = (res + nt) % MOD;
        }
    return res;
}

