const int mod = 1e9 + 7;

bool vis[64][2][2][2];
long long f[64][2][2][2];
bool Llimit[64], Rlimit[64];

long long dp(int k, bool Ltouch, bool Rtouch, bool first_bit) {
    if (k == -1) return 1;
    if (vis[k][Ltouch][Rtouch][first_bit]) return f[k][Ltouch][Rtouch][first_bit];
    vis[k][Ltouch][Rtouch][first_bit] = true;

    long long &rt = f[k][Ltouch][Rtouch][first_bit];

    // all one. 
    if (!(Rtouch && Rlimit[k] == 0)) {
        bool new_Ltouch = Ltouch;
        if (Llimit[k] == 0) new_Ltouch = false;

        // if (k == 1 && Llimit == false && Rlimit == true && first_bit == true) cout << new_Ltouch << ' ' << Rtouch << endl;
        rt = (rt + dp(k - 1, new_Ltouch, Rtouch, true)) % mod;
    }

    // one and zero
    if (first_bit && !((Rtouch && Rlimit[k] == 0) || (Ltouch && Llimit[k] == 1))) {
        // if (k == 1 && Llimit == false && Rlimit == true && first_bit == true) cout << Ltouch << ' ' << Rtouch << endl;
        rt = (rt + dp(k - 1, Ltouch, Rtouch, true)) % mod;
    }

    // all zero.
    if (!(Ltouch && Llimit[k] == 1)) {
        bool new_Rtouch = Rtouch;
        if (Rlimit[k] == 1) new_Rtouch = false;
                // if (k == 1 && Llimit == false && Rlimit == true && first_bit == true) cout << new_Ltouch << ' ' << Rtouch << endl;

        rt = (rt + dp(k - 1, Ltouch, new_Rtouch, first_bit)) % mod;
    }
    // cout << k << ' ' << Ltouch << ' ' << Rtouch << ' ' << first_bit << ' ' << rt << endl;
    return rt;
}

