const int MOD = 1000000007;


int T, n, m;
ll l, r;

const int N = 64;

ll dp[N][16];

ll calc(ll l, ll r) {
    vi vl, vr;
    while(r) {
        vr.push_back(r & 1);
        r >>= 1;
        vl.push_back(l & 1);
        l >>= 1;
    }
    reverse(ALL(vl));
    reverse(ALL(vr));
    int n = vr.size();
    memset(dp, 0, sizeof(dp));
    dp[0][0]= 1;
    REP(i, n) {
        REP(f, 16) {
            ll t = dp[i][f] % MOD;
            for(int x = 0; x < 2 ; x ++) {
                for (int y = 0; y < 2 ; y ++) {
                    if (!(f & 1) && x < vl[i]) continue;
                    if (!(f & 2) && vr[i] < y) continue;
                    if (!(f & 4) && y < x) continue;
                    if (!(f & 8) && y && !x) continue;
                    if (x && !y) continue;
                    int nf = f;
                    if (vl[i] < x) nf |= 1;
                    if (y < vr[i]) nf |= 2;
                    if (x < y) nf |= 4;
                    if (x) nf |= 8;
                    (dp[i + 1][nf] += t) %= MOD;
                }
            }
        }
    }
    ll ans = 0;
    REP(f, 8) {
        ans += dp[n][8 | f] % MOD;
    }
    return ans % MOD;
}

