constexpr long long int mod = 1000000007LL;
long long int count_uf_lf(const int digit) {
	if (digit < 0) return 1;
	else {
		return 3 * count_uf_lf(digit - 1) % mod;
	}
}
long long int count_uf_lc(const int digit, const long long int lower) {
	if (digit < 0) return 1;
	else {
		if (((1LL << digit) & lower) != 0) {
			return count_uf_lc(digit - 1, lower);
		}
		else {
			return (count_uf_lf(digit - 1) + count_uf_lc(digit - 1, lower) * 2) % mod;
		}
	}
}
long long int count_uc_lf(const int digit, const long long int upper) {
	if (digit < 0) return 1;
	else {
		if (((1LL << digit) & upper) != 0) {
			return (count_uf_lf(digit - 1) + count_uc_lf(digit - 1, upper) * 2) % mod;
		}
		else {
			return count_uc_lf(digit - 1, upper);
		}
	}
}
long long int count_uc_lc(const int digit, const long long int upper, const long long int lower) {
	if (digit < 0) return 1;
	else {
		if (((1LL << digit) & upper) > ((1L << digit) & lower)) {
			return (count_uc_lc(digit - 1, upper, lower) + count_uc_lf(digit - 1, upper) + count_uf_lc(digit - 1, lower)) % mod;
		}
		else if (((1LL << digit) & upper) == ((1L << digit) & lower)) {
			return count_uc_lc(digit - 1, upper, lower);
		}
		else return 0LL;
	}
}
int main() {
	long long int l, r; std::cin >> l >> r;
	long long int bit = 1;
	int digit = 0;
	while (l >= bit * 2) {
		bit *= 2;
		digit += 1;
	}
	long long int pattern = 0;
	while (r >= bit) {
		pattern += count_uc_lc(digit, std::min(bit * 2 - 1, r), std::max(bit, l));
		bit *= 2;
		digit += 1;
		pattern %= mod;
	}
	std::cout << pattern << std::endl;
}

