ll dfs(int x, bool Left, bool Right, bool keep) {
    if(x < 0) return 1;
    if( ~ dp[x][Left][Right] && !keep)
        return dp[x][Left][Right];
    ll ans = 0;
    int l = 0, r = 1;
    if(Left) l = L >> x & 1;
    if(Right) r = R >> x & 1;
    for(int i = l ; i <= 1 ; i++) {
        for (int j = i ; j <= r ; j++) {
            if (j == 1 && keep) {
                if(i == 1) ans += dfs(x-1, Left && i == l, Right && j == r, keep && j == 0);
            }
            else ans += dfs(x-1, Left && i == l, Right && j == r, keep && j == 0);
        }
    }
    ans %= mod;
    if(!keep) dp[x][Left][Right] = ans;
    return ans;
}
