using namespace std;

const long long int MOD = 1000000007;
long long int l,r;

int memo[60][2][2][2];

int get_bit(long long int x, int bit) {
  return (x >> bit) & 1;
}

/**
 * 上位ビットからチェックしていく
 * x,yの状態で判定するが、
 * 必要な状態は引数にある4種類のみ
 * これで、選択できる次のビットの組が決まる
 */
int calc(
    bool equal_l, // xのこれまでのビットがLと同じ
    bool equal_r, // yのこれまでのビットがRと同じ
    bool already_msb, // すでに1が立っているビットを比較済み
    int current_bit) // 現在のビット、上位が大きい
{
  if (current_bit < 0) {
    return 1;
  }

  if (memo[current_bit][equal_l][equal_r][already_msb] != -1) {
    return memo[current_bit][equal_l][equal_r][already_msb];
  }

  int r_bit = get_bit(r, current_bit);
  int l_bit = get_bit(l, current_bit);

  bool can_set_1 = !(equal_r && r_bit == 0); // 1を選べないのは、rと同じ状態、かついまのrが0である場合 -> yがrを超える場合
  bool can_set_0 = !(equal_l && l_bit == 1); // 同様に、xがlを下回る場合を除く

  int result = 0;

  // 1, 1
  if (can_set_1) {
    result += calc(equal_l && l_bit == 1,
        equal_r && r_bit == 1,
        true, //1なので無条件に
        current_bit-1);
    result %= MOD;
  }

  // 0, 0
  if (can_set_0) {
    result += calc(equal_l && l_bit == 0,
        equal_r && r_bit == 0,
        already_msb,
        current_bit-1);
    result %= MOD;
  }

  // 0, 1
  if (
      already_msb && // すでに1を比較していて
      can_set_1 && // yに1を立てられて
      can_set_0 // xに0を立てられる
      ) {
    result += calc(equal_l && l_bit == 0,
        equal_r && r_bit == 1,
        already_msb,
        current_bit-1);
    result %= MOD;
  }

  memo[current_bit][equal_l][equal_r][already_msb] = result;

  return result;
}

int main() {
  cin >> l >> r;

  fill((int*)memo, (int*)memo+60*2*2*2, -1); // 配列はfillで初期化できる
  auto result = calc(true, true, false, 59); // 59は2**60 -> Rの最大値を表現可能なビット数

  cout << result << endl;
}

