void calc_y(ll k)
{
    //cout << "calc y : " << k << ENDL;
    ll mn = (1ll << k);
    ll nowy = mn;
    ll res = 1;
    repr(i, k - 1, -1)
    {
        if ((1ll << i) + nowy - 1 <= y)
        {
            //yを０にすると確実に下回る
            //y０のとき下の桁自由、y１として次へ
            ans = ((ans + (res * thr[i]) % mod)) % mod;
            nowy += (1ll << i);
            res = (res * 2) % mod;
        }
    }
    //もし最後の桁を１にしたときｙ以下なら+res？
    if (nowy<=y)
