int main() {
	ll L,R; cin >> L >> R;
	int N = 60;
	//bit桁dp
	//dp[i][j][z][(x,y)]: i桁目まで見て 既に状態j(L ? X ? Y ? R (?は < or =))が確定していて かつ 既に状態z(x,yの最上位bitが fixed or not)が確定 かつ XとYのi桁目の値が状態(x,y)=(0,0),(0,1),(1,0),(1,1)
	auto dp = multivector(N+1,(1<<3),(1<<1),(1<<2),0LL);
	dp[0][0][0][0] = 1;
	for(int i = 1; i <= N; ++i) {
		int b = N - i;
		int l = ((L>>b)&1);
		int r = ((R>>b)&1);

		//bitdp的な遷移 '=' to '<' の遷移のみを許す。j to k
		for(int j = 0; j < (1<<3); ++j) {			
			for(int k = 0; k < (1<<3); ++k) {
				if((j|k)!=k) continue;

				for(int z = 0; z < 2; ++z) {
					for(int w = 0; w < 2; ++w) {
						if(z && !w) continue;

						for(int x = 0; x <= 1; ++x) {
							for(int y = 0; y <= 1; ++y) {

								//y-x = x^yより必要
								if(x && !y) continue;
								//最上位bitが not fixedのときは x == y == 0 
								if(!w && (x || y)) continue;
								//最上位bitが fixedするときは x == y == 1
								if(!z && w && (!x || !y)) continue;

								// = から = への遷移のときは l == x
								if( !((j>>2)&1) && !((k>>2)&1) && l != x) continue;
								// = から < への遷移のときは l <  x
								if( !((j>>2)&1) &&  ((k>>2)&1) && l >= x) continue;
								// < から < への遷移のときは anyone is ok

								// = から = への遷移のときは x == y
								if( !((j>>1)&1) && !((k>>1)&1) && x != y) continue;
								// = から < への遷移のときは x <  y
								if( !((j>>1)&1) &&  ((k>>1)&1) && x >= y) continue;
								// < から < への遷移のときは anyone is ok

								// = から = への遷移のときは y == r
								if( !((j>>0)&1) && !((k>>0)&1) && y != r) continue;
								// = から < への遷移のときは y <  r
								if( !((j>>0)&1) &&  ((k>>0)&1) && y >= r) continue;
								// < から < への遷移のときは anyone is ok

								//i-1のx,yは気にせず遷移
								(dp[i][k][w][2*x+y] += accumulate(ALL(dp[i-1][j][z]),0LL) ) %= MOD;
							}
						}
					}
				}


			}
		}
	}

	ll ans = 0; 
	for(int j = 0; j < (1<<3); ++j) for(int k = 0; k < (1<<1); ++k) for(int l = 0; l < (1<<2); ++l) (ans += dp[N][j][k][l]) %= MOD;
	cout << ans << endl;
	return 0;
}

