        ret += beki(2, __builtin_popcount(x));
    }
    ret %= mod;
    //cerr << "lower: " << R << " " << idx << " " << ret << endl;
    return ret;
}

ll lower(ll R, ll idx) {
    ll ret = 0;
    if(R < 0) return 0;
    if(R == 0) return 1;
    if(R >= (1LL << (idx + 1))) {
        return beki(3, idx + 1);
    }
    ret += 2 * lower(R - (1LL << idx), idx - 1);
    ret += lower(R, idx - 1);
    ret %= mod;
    //cerr << "lower: " << R << " " << idx << " " << ret << endl;
    //cerr << lower2(R, idx) << endl;
    return ret;
}

ll g(ll R, ll L, ll idx) {
    //cerr << "g: " << R << " " << L << " " << idx << endl;
    if(R < 0) return 0;
    //if(R < L) return 0;
    if(L <= 0) return lower(R, idx);
    if((1LL << (idx + 1)) <= R) return upper(L, idx);
    if(idx <= 1) {
        ll ret = 0;
        for(ll x = L; x <= R; x++) {
            for(ll y = x; y <= R; y++) {
                if((x & y) == x) ret++;
            }
        }
        return ret;
    }
    ll ret = 0;
    ret += g(R - (1LL << idx), L - (1LL << idx), idx - 1);
    ret += g(R - (1LL << idx), L, idx - 1);
    ret += g(R, L, idx - 1);
    return ret % mod;
}

