ll dfs(int pos, int limx, int limy, int lead, ll x, ll y) 
{
	if(pos==-1) return 1;
	if(dp[pos][limx][limy][lead]!=-1) return dp[pos][limx][limy][lead];
	int upx = limx ? (x>>pos)&1 : 1;
