// mod計算クラス
template <class T>
struct calc_mod {
  T n;
  T mod;

  calc_mod(T n, T mod) {
    this->n = n;
    this->mod = mod;
  }

  T plus(const T& a, const T& b) const { return (a + b) % mod; }
  calc_mod<T> operator+(const calc_mod<T>& other) const { return calc_mod<T>(plus(this->n, other.n), mod); }
  calc_mod<T> operator+(const T& other) const { return calc_mod<T>(plus(this->n, other), mod); }
  void operator+=(const calc_mod<T>& other) { this->n = plus(this->n, other.n); }
  void operator+=(const T& other) { this->n = plus(this->n, other); }

  T sub(const T& a, const T& b) const { return (a - b + mod) % mod; }
  calc_mod<T> operator-(const calc_mod<T>& other) const { return calc_mod<T>(sub(this->n, other.n), mod); }
  calc_mod<T> operator-(const T& other) const { return calc_mod<T>(sub(this->n, other), mod); }
  void operator-=(const calc_mod<T>& other) { this->n = sub(this->n, other.n); }
  void operator-=(const T& other) { this->n = sub(this->n, other); }

  T multi(const T& a, const T& b) const { return (a * b) % mod; }
  calc_mod<T> operator*(const calc_mod<T>& other) const { return calc_mod<T>(multi(this->n, other.n), mod); }
  calc_mod<T> operator*(const T& other) const { return calc_mod<T>(multi(this->n, other), mod); }
  void operator*=(const calc_mod<T>& other) { this->n = multi(this->n, other.n); }
  void operator*=(const T& other) { this->n = multi(this->n, other); }

  T div(const T& a, const T& b) const { return a / b; }
  calc_mod<T> operator/(const calc_mod<T>& other) const { return calc_mod<T>(div(this->n, other.n), mod); }
  calc_mod<T> operator/(const T& other) const { return calc_mod<T>(div(this->n, other), mod); }
  void operator/=(const calc_mod<T>& other) { this->n = div(this->n, other.n); }
  void operator/=(const T& other) { this->n = div(this->n, other); }

  T modu(const T& a, const T& b) const { return a % b; }
  calc_mod<T> operator%(const calc_mod<T>& other) const { return calc_mod<T>(modu(this->n, other.n), mod); }
  calc_mod<T> operator%(const T& other) const { return calc_mod<T>(modu(this->n, other), mod); }
  void operator%=(const calc_mod<T>& other) { this->n = modu(this->n, other.n); }
  void operator%=(const T& other) { this->n = modu(this->n, other); }

  //TODO: このあたり、haskellのeqみたいに定義できないか？
  bool operator==(const calc_mod<T>& other) const { return this->n == other.n; }
  bool operator==(const T& other) const { return this->n == other; }
  bool operator!=(const calc_mod<T>& other) const { return this->n != other.n; }
  bool operator!=(const T& other) const { return this->n != other; }

  bool operator>(const calc_mod<T>& other) const { return this->n > other.n; }
  bool operator>(const T& other) const { return this->n > other; }
  bool operator>=(const calc_mod<T>& other) const { return this->n >= other.n; }
  bool operator>=(const T& other) const { return this->n >= other; }
  bool operator<(const calc_mod<T>& other) const { return this->n < other.n; }
  bool operator<(const T& other) const { return this->n < other; }
  bool operator<=(const calc_mod<T>& other) const { return this->n <= other.n; }
  bool operator<=(const T& other) const { return this->n <= other; }

  calc_mod<T> pow(calc_mod<T> other) {
    return this->pow(other.n);
  }
  calc_mod<T> pow(T other) {
    // 累乗は繰り返し自乗法で
    calc_mod<T> result(1, this->mod);
    calc_mod<T> x = *this;
    T b = other;

    for (;b > 0;b /= 2) {
      if (b%2 == 1) {
        result *= x;
      }

      x *= x;
    }

    return result;
  }
};
