        public:
        size_t operator () ( const normalize_value &p ) const{
          return get<0>(p) ^ get<1>(p) ^ get<2>(p);
        }
    };
}
ostream& operator<<(ostream& stream, const normalize_value& p) { // cout<<でも呼べるように
  stream << "(" << get<0>(p) << "," << get<1>(p) << "," << get<2>(p) << ")";
  return stream;
}

normalize_value normalize(point_value l, point_value r, point_value min_x, point_value max_x, point_value min_y, point_value max_y) {
  point_value width = max_x - min_x + 1;
  l = l - min_x;
  l = min(l, width);
  r = r - min_y;
  r = min(r, width);

  if (l>r) {
    swap(l, r);
  }

  return normalize_value(l, r, width);
}

unordered_map<normalize_value, modtype> cache;

modtype sub_block(point_value l, point_value r, point_value min_x, point_value max_x, point_value min_y, point_value max_y) {
  // cout << "sub_block2 called" << endl;
  // cout << dv(l) << dv(r) << dv(min_x) << dv(max_x) << dv(min_y) << dv(max_y) << endl;

  if (l >= max_x && r >= max_y) {
    return count_in_block(log2(max_x-min_x+1)+1);
  }

  if (l < min_x || r < min_y) {
    return modtype(0, MOD);
  }

  // キャッシュ化のため、正規化してmin_x,min_yを0にする
  normalize_value n = normalize(l, r, min_x, max_x, min_y, max_y);
  const auto& ite = cache.find(n);
  if (ite != cache.end()) {
    // cout << "hit cache" << dv(n) << endl;
    return ite->second;
  }

  point_value len = max_x - min_x + 1;
  point_value mid_x = min_x + len/2 - 1;
  point_value mid_y = min_y + len/2 - 1;

  // 4分割して計算
  modtype result = modtype(0, MOD) // +sub_block(l, r, min_x, mid_x, min_y, mid_y) // 回転しているので、左上が空
    + sub_block(l, r, min_x, mid_x, mid_y+1, max_y) // 右上
    + sub_block(l, r, mid_x+1, max_x, min_y, mid_y) // 左下
    + sub_block(l, r, mid_x+1, max_x, mid_y+1, max_y) // 右下
    ;

  cache.emplace(n, result);
  // cout << "emplace cache:" << dv(n) << dv(result) << endl;

  return result;
}

modtype sub_block(point_value l, point_value r, int block) {
  // cout << "sub_block1 called" << endl;

  point_value min_x = block_min_bound(block);
  point_value max_x = block_min_bound(block+1) - 1;
  l = max_x-(l-min_x); // ブロックを回転させて、左上が空になるようにする。4分割したときにキャッシュが効くように
  return sub_block(l, r, min_x, max_x, min_x, max_x);
}

int main() {
  point_value l, r;
  cin >> l >> r;
  modtype result(0, MOD);

  int l_block = block_number(l);
  int r_block = block_number(r);

  // cout << l_block << " " << r_block << endl;

  if (l_block == r_block) { // 2-1
    // cout << "2-1" << endl;
    result = sub_block(l, r, l_block);
    // cout << dv(result) << endl;
  } else { // 2-2
    // cout << "2-2" << endl;
    for (int i = l_block + 1; i < r_block; i++) {
      result += count_in_block(i);
      // cout << dv(result) << endl;
    }

    result += sub_block(l, r, l_block);
    // cout << dv(result) << endl;
    result += sub_block(l, r, r_block);
    // cout << dv(result) << endl;
  }

  cout << result << endl;
}

