const ll MOD = 1e9 + 7;
const int N = (60);
int memo[N][2][2][2];
string L, R;

int dpOverDig(int pos, int highL, int lowR, int MSB) {
  if (pos == (int) R.size()) return 1;
  int &ret = memo[pos][highL][lowR][MSB];
  if (ret != -1) return ret;
  ret = 0;
  if (lowR) {
    if (highL) {
      for (int i = 0; i <= 1; ++i) {
        for (int j = 0; j <= 1; ++j) {
          if (i == 1 and j == 0) continue;
          if (!MSB and i == 0 and j == 1) continue;
          ret += dpOverDig(pos + 1, 1, 1, MSB or (i and j));
          ret %= MOD;
        }
      }
    } else {
      int d = L[pos] - '0';
      for (int i = d; i <= 1; ++i) {
        for (int j = 0; j <= 1; ++j) {
          if (i == 1 and j == 0) continue;
          if (!MSB and i == 0 and j == 1) continue;
          ret += dpOverDig(pos + 1, d < i? 1 : 0, 1, MSB or (i and j));
          ret %= MOD;
        }
      }
    }
  } else {
    if (highL) {
      for (int i = 0; i <= 1; ++i) {
        int d = R[pos] - '0';
        for (int j = 0; j <= d; ++j) {
          if (i == 1 and j == 0) continue;
          if (!MSB and i == 0 and j == 1) continue;
          ret += dpOverDig(pos + 1, 1, j < d? 1 : 0, MSB or (i and j));
          ret %= MOD;
        }
      }
    } else {
      int dL = L[pos] - '0';
      for (int i = dL; i <= 1; ++i) {
        int dR = R[pos] - '0';
        for (int j = 0; j <= dR; ++j) {
          if (i == 1 and j == 0) continue;
          if (!MSB and i == 0 and j == 1) continue;
          ret += dpOverDig(pos + 1, dL < i? 1 : 0, j < dR? 1 : 0, MSB or (i and j));
          ret %= MOD;
        }
      }
    }
  }
  return ret;
}

