	scanf("%lld%lld", &l, &r);
	for(; l>>la; la++); la--;
	for(; r>>ra; ra++); ra--; r = ~r;
	if(ra != la) for(int i = la; i <= ra; i++){
		if(la < i && i < ra) (ans += exp(3,i)) %= MD;
		else{
			ll dp1 = 1, dp2 = 0;
			for(int j = i-1; j >= 0; j--){
				if((la == i ? l : r)>>j&1) (dp2 *= 3) %= MD;
				else{
					dp2 = (dp2*3 + dp1) % MD;
					(dp1 *= 2) %= MD;
				}
			}
			(ans += dp2 + dp1) %= MD;
		}
	}else{
		ll dp1 = 1, dp2 = 0, dp3 = 0, dp4 = 0;
		r = ~r;
		int j = ra-1;
		for(; j >= 0; j--) if((r^l)>>j&1) break;
		for(; j >= 0; j--){
			int lb = l>>j&1, rb = r>>j&1;
			if(lb && rb){
				dp4 =(dp4*3 + dp2) % MD;
				(dp2 *= 2) %= MD;
			}else if(!lb && rb){
				dp4 = (dp4*3 + dp2 + dp3) % MD;
				dp2 = (dp2*2 + dp1) % MD;
				dp3 = (dp3*2 + dp1) % MD;
			}else if(lb && !rb){
				(dp4 *= 3) %= MD;
				dp1 = 0;
			}else if(!lb && !rb){
				dp4 =(dp4*3 + dp3) % MD;
				(dp3 *= 2) %= MD;
			}
		}
		ans = (dp1 + dp2 + dp3 +dp4) % MD;
	}
	printf("%lld\n", ans);
}

