    fpoint& operator/=(const ld a){x /= a, y /= a; return *this;}
    fpoint& operator+=(const fpoint p){x += p.x, y += p.y; return *this;}
    fpoint& operator-=(const fpoint p){x -= p.x, y -= p.y; return *this;}
