typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

/* 
read_graph(n, m, graph, cost, directed, offset)
    cost: if link cost is fixed, put positive integer
          otherwise -1
    directed: if directed true, olse false
    offset: if the given vertex is 1-indexed, -1.
*/

void solve(){
    bool okay = false;
    string S, T, U;
    ll A, B, C, D, N, M, H, W, K, x, y, Q, idx, cnt, num, answer;
    vl as, bs, cs, ds;
    vb2 block; vb visited; Graph graph, tree;
    points ps;
    // generate_array(size, min, max);

    in2(A, B);

    ll n_digits = 61;
    vmi3 dp(2, vmi2(2, vmi(n_digits, 0)));
    PowerMemo p3(n_digits + 5, 3, MOD);

    dp[0][0][0] = 1; bool first = false;
    For(nd, 1, n_digits){
        bool topA = 1LL << (n_digits - 1 - nd) & A;
        bool topB = 1LL << (n_digits - 1 - nd) & B;
        if (topA != topB) first = true;
        else dp[0][0][nd] = dp[0][0][nd - 1];

        dp[1][0][nd] = dp[1][0][nd - 1] * (topB + 1);
        dp[0][1][nd] = dp[0][1][nd - 1];
        dp[1][1][nd] = dp[1][1][nd - 1];

        mint v3 = p3[n_digits - 1 - nd];
        if (first && topB){
            dp[0][1][nd] += dp[0][0][nd - 1];
            dp[1][1][nd] += dp[1][0][nd - 1] * v3;
        }
        if (first && !topA){
            dp[1][0][nd] += dp[0][0][nd - 1];
            dp[1][1][nd] += dp[0][1][nd - 1] * v3;
        }
    }

    mint ans = 0;
    rep(i, 2) rep(j, 2) ans += dp[i][j][n_digits - 1];
    prl(ans + dp[1][0][n_digits - 1]);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

