const int mod = 1e9 + 7;

vector<int> getBits(ll x){
    vector<int> a;
    while (x > 0){
        a.push_back(x & 1);
        x >>= 1;
    }
    reverse(a.begin(), a.end());
    return a;
}

ll calc(vector<int> curL, vector<int> curR, int n){
    for (int k = 0; k < min(curL.size(), curR.size()); k++){
        if (curL[k] > curR[k])
            return 0;
    }
    // print(curL);
    // print(curR);
    ll answer = 1;
    for (int i = curL.size(); i < curR.size(); i++){
        if (curR[i] == 1)
            answer = answer * 2 % mod;
    }
    for (int i = curR.size(); i < curL.size(); i++){
        if (curL[i] == 0)
            answer = answer * 2 % mod;
    }
    for (int i = max(curL.size(), curR.size()); i < n; i++)
        answer = answer * 3 % mod;
    // cout << answer << endl << endl;
    return answer;
}

ll get(ll l, ll r){
    if (l > r)
        return 0;
    // cout << l << " " << r << endl;
    vector<int> L = getBits(l);
    vector<int> R = getBits(r);
    assert(L.size() == R.size());
    int n = L.size();
    int cur = 0;
    while (cur < n && L[cur] == R[cur])
        cur++;
    vector<int> curL;
    ll result = 0;
    for (int i = cur; i < n + 1; i++){
        if (i > cur)
            curL.push_back(L[i - 1]);
        if (i < n && L[i] == 1)
            continue;
        if (i < n)
            curL.push_back(1);
        vector<int> curR;
        for (int j = cur; j < n + 1; j++){
            if (j > cur)
                curR.push_back(R[j - 1]);
            if (j < n && R[j] == 0)
                continue;
            if (j < n)
                curR.push_back(0);
            result += calc(curL, curR, n - cur);
            // print(curL);
            // print(curR);
            // cout << i << " " << j << " " << result << endl;
            // cout << endl;
            curR.pop_back();
        }
        curL.pop_back();
    }
    // cout << result << endl;
    return result % mod;
}

