ll getVal(ll a, ll x, ll y, ll z){
    if(a==-1) return 1;
    if(DP[a][x][y][z]!=-1) return DP[a][x][y][z];
    ll ret = 0;
    if(x || !(l & (1LL<<a))){
        ret += getVal(a-1, x, (r&(1LL<<a))?1:y, z);
    }
    if((x || !(l & (1LL<<a))) && (y || (r&(1LL<<a))) && z){
        ret += getVal(a-1, x, y, z);
    }
    if(y || (r&(1LL<<a))){
        ret += getVal(a-1, (!(l&(1LL<<a)))?1:x, y, 1);
    }
    return DP[a][x][y][z] = ret%MOD;
}

