        const long long MOD = 1e9 + 7;
        auto bin = [&](long long x) {
            string res;
            while (x != 0) {
                res += '0' + (x & 0x1);
                x >>= 1;
            }
            reverse(res.begin(), res.end());
            return res;
        };
        string L = bin(l);
