        if (L.length() < n) {
            L = string(n - L.length(), '0') + L;
        }
        // cout << L << endl;
        // cout << R << endl;
        int m = 2;
        int M = 1 << m;
        vector<vector<long long>> dp(M, vector<long long>(M, 0));
        auto ndp = dp;

        for (int i = 0; i < n; ++i) {
            int a = L[i] - '0';
            int b = R[i] - '0';

            for (auto& V : ndp) {
                for (auto& x : V) {
                    x = 0;
                }
            }

            for (int j = 0; j < M; ++j) {
                int l = 0, r = 1;
                if ((j & 1) == 0) {
                    l = max(l, a);
                }
                if ((j & 2) == 0) {
                    r = min(r, b);
                }
                for (int k = 0; k < M; ++k) {
                    int ll = 0, rr = 1;
                    if ((k & 1) == 0) {
