                    }

                    for (int x = l; x <= r; ++x) {
                        for (int y = ll; y <= rr; ++y) {
                            if (x == 1 && y == 0) {
                                continue;
                            }
                            int nj = j;
                            int nk = k;
                            if (x > a) {
                                nj |= 1;
                            }
                            if (x < b) {
                                nj |= 2;
                            }
                            if (y > a) {
                                nk |= 1;
                            }
                            if (y < b) {
                                nk |= 2;
                            }
                            ndp[nj][nk] += dp[j][k];
                            ndp[nj][nk] %= MOD;
                        }
                    }
                }
             }


            swap(ndp, dp);

            {
                int j = 0;
                string p = string(i, '0');
                p += '1';                
                if (p > L.substr(0, i + 1)) {
                    j |= 1;
                }
                if (p < R.substr(0, i + 1)) {
                    j |= 2;
                }
                if (p < L.substr(0, i + 1)) {

                } else {
                    dp[j][j] += 1;
                    dp[j][j] %= MOD;
                }
            }
            // for (int i = 0; i < M; ++i){
            //     for (int j = 0; j < M; ++j) {
            //         if (dp[i][j] > 0) {
            //             cout << i << "," << j << " " << dp[i][j] << endl;
            //         }
            //     }
            // }
            // cout << endl;
        }

        long long res = 0;
        for (int i = 0; i < M; ++i) {
            for (int j = 0; j < M; ++j) {
                res += dp[i][j];
            }
        }
        res %= MOD;
        return res;
    }
};

