constexpr ll MOD = (ll)(1e9 + 7); // 998244353L;
template<int mod> struct Modll{
	ll val;
	Modll(ll v = 0): val(v %mod){ if (val < 0) val += mod; }
	Modll operator - () { return -val; }
	Modll operator + (const Modll &b) const { return val + b.val; }
	Modll operator - (const Modll &b) const { return val - b.val; }
	Modll operator * (const Modll &b) const { return val * b.val; }
	Modll operator / (const Modll &b) const { return Modll(*this) /= b; }
	Modll operator + (ll b) const { return *this + Modll(b); }
	Modll operator - (ll b) const { return *this - Modll(b); }
	Modll operator * (ll b) const { return *this * Modll(b); }
	friend Modll<mod> operator + (ll a, const Modll<mod> &b) { return b + a; }
	friend Modll<mod> operator - (ll a, const Modll<mod> &b) { return -b + a; }
	friend Modll<mod> operator * (ll a, const Modll<mod> &b) { return b * a; }
	Modll &operator += (const Modll &b) { val=(val+b.val)%mod; return *this; }
	Modll &operator -= (const Modll &b) { val=(val+mod-b.val)%mod; return *this; }
	Modll &operator *= (const Modll &b) { val=(val*b.val)%mod; return *this; }
	Modll &operator /= (const Modll &b) {
		ll c=b.val, d=mod, u=1, v=0;
		while (d){
			ll t = c / d;
			c -= t * d; swap(c, d);
			u -= t * v; swap(u, v);
		}
		val = val * u % mod;
		if (val < 0) val += mod;
		return *this;
	}
	Modll &operator += (ll b) { return *this += Modll(b); }
	Modll &operator -= (ll b) { return *this -= Modll(b); }
	Modll &operator *= (ll b) { return *this *= Modll(b); }
	Modll &operator /= (ll b) { return *this /= Modll(b); }
	bool operator == (const Modll &b) { return val == b.val; }
	bool operator != (const Modll &b) { return val != b.val; }
	bool operator == (ll b) { return *this == Modll(b); }
	bool operator != (ll b) { return *this != Modll(b); }
	friend bool operator == (ll a, const Modll<mod> &b) { return Modll<mod>(a) == b.val; }
	friend bool operator != (ll a, const Modll<mod> &b) { return Modll<mod>(a) != b.val; }
	friend ostream &operator << (ostream &os, const Modll<mod> &a) { return os << a.val; }
	friend istream &operator >> (istream &is, const Modll<mod> &a) { return is >> a.val; }
	Modll pow(ll n){
		if (n == 0) return 1;
		auto b = pow(n / 2);
		return (n%2 == 1) ? b*b*val : b*b;
	}
};
using modll = Modll<MOD>;


vll Binarize(ll a){
	vll aBin;
	bool flag = false;
	REP(i, 64){
		ll tmp = a & (1LL << i);
		if (tmp) flag = true;
		if (!flag) continue;
		if (tmp == 0) aBin.push_back(0);
		else          aBin.push_back(1);
	}
	return std::move(aBin);
}

vll Binarize64(ll a){
	vll aBin(64);
	REP(i, 64){
		aBin[63 - i] = a & 1LL;
		a >>= 1;
	}
	return std::move(aBin);
}


void solve()
{
	ll L, R;
	cin >> L >> R;

	if (L == R){
		cout << 1 << '\n';
		return;
	}

	vll Rb = Binarize64(R);
	vll Lb = Binarize64(L);

	while (Rb[0] == 0){
		Rb.erase(Rb.begin());
		Lb.erase(Lb.begin());
	}
	bool isHeadSame = false;
	while (Rb[0] == Lb[0]){
		isHeadSame = true;
		Rb.erase(Rb.begin());
		Lb.erase(Lb.begin());
	}
	ll N = (ll)Rb.size();

	vector<vector<modll>> dp;
	dp.resize(N, vector<modll>(4, 0));

	if (isHeadSame){
		dp[0][0] = 0;
		dp[0][1] = 1;
		dp[0][2] = 1;
		dp[0][3] = 1;
	}
	else{
		dp[0][0] = 0;
		dp[0][1] = 1;
		dp[0][2] = 0;
		dp[0][3] = 0;
	}

	REPS(i, 1, N-1){
		dp[i][0] += dp[i-1][0]*3;
		if (Rb[i] == 1) dp[i][0] += dp[i-1][1];
		if (Lb[i] == 0) dp[i][0] += dp[i-1][2];

		if (Rb[i] == 0)               dp[i][1] += dp[i-1][1];
		else                          dp[i][1] += dp[i-1][1]*2;
		if (Lb[i] == 0 && Rb[i] == 1) dp[i][1] += dp[i-1][3];

		if (Lb[i] == 1)               dp[i][2] += dp[i-1][2];
		else                          dp[i][2] += dp[i-1][2]*2;
		if (Lb[i] == 0 && Rb[i] == 1) dp[i][2] += dp[i-1][3];

		if (Rb[i] == 0 && Lb[i] == 1) dp[i][3] = 0;
		else                          dp[i][3] = dp[i-1][3];

		if ( !isHeadSame && Sum(Lb, i) == 0 ){
			if (Lb[i] == 0) dp[i][0] += 1;
			else            dp[i][2] += 1;
		}
	}

	cout << Sum(dp[N-1]) << '\n';
}



int main(){
	solve();
	return 0;
}

