long long mod_pow(long long x, long long n){
    if(n == 0) return 1;
    long long res = mod_pow(x*x % mod, n / 2);
    if(n & 1) res = res*x % mod;
    return res;
}

int f(int x){
    return mod_pow(3, x);
}

int calclow(int x){
    int l = 0;
    int ans = 0;
    for(int i = 1; i < 60; i++){
        if(x >= (1LL << i) - 1){
            (ans += f(i - 1)) %= mod;
            // cout << "first " << i << ' ' << f(i - 1) << ' ' << ans << endl;
            l = i;
        }else break;
    }
    x -= (1LL << l) - 1;
    int cnt = 1;
    // cout <<" " << x << " " << ans << endl;
    for(int i = l - 1; i >= 1; i--){
        // cout << x << " " << (1LL << i) << endl;
        if(x >= (1LL << i)){
            (ans += f(i) * cnt * 2 % mod) %= mod;
            x -= (1LL << i);
            // cout << "second " << (1LL << i) << " " << f(i) << " " << ans << endl;
        }else{
            (cnt *= 2) %= mod;
        }
    }
    // cout << " " << ans << endl;
