using namespace std;
using ll = int64_t;
using vecint = vector<int>;
using vecll = vector<ll>;
constexpr ll MOD = 1000000007;

ll solve(ll l, ll r, ll n) {
  vector<vecll> dp(n+1, vecll(4, 0));
  dp[n][0b00] = 1;
  for (int i = n-1; i >= 0; --i) {
    dp[i][0b11] += 3 * dp[i+1][0b11];
    dp[i][0b11] %= MOD;
    bool rhi = (r >> i) & 1;
    bool lhi = (l >> i) & 1;
    if (lhi) {
      dp[i][0b01] += dp[i+1][0b01];
      dp[i][0b01] %= MOD;
      if (rhi) {
        dp[i][0b10] += 3 * dp[i+1][0b10];
        dp[i][0b10] %= MOD;
        dp[i][0b00] += dp[i+1][0b00];
        dp[i][0b00] %= MOD;
      } else {
        dp[i][0b10] += dp[i+1][0b10];
        dp[i][0b10] %= MOD;
      }
    } else {
      dp[i][0b00] += dp[i+1][0b00];
      dp[i][0b00] %= MOD;
      if (rhi) {
        dp[i][0b10] += 2 * dp[i+1][0b10];
        dp[i][0b10] %= MOD;
        dp[i][0b01] += 2 * dp[i+1][0b01];
        dp[i][0b01] %= MOD;

        // 00
        dp[i][0b11] += dp[i+1][0b10];
        dp[i][0b11] %= MOD;
        dp[i][0b01] += dp[i+1][0b00];
        dp[i][0b01] %= MOD;

        // 11
        dp[i][0b11] += dp[i+1][0b01];
        dp[i][0b11] %= MOD;
        dp[i][0b10] += dp[i+1][0b00];
        dp[i][0b10] %= MOD;
      } else {
        dp[i][0b10] += dp[i+1][0b10];
        dp[i][0b10] %= MOD;
        dp[i][0b01] += 3 * dp[i+1][0b01];
        dp[i][0b01] %= MOD;
      }
    }
  }
  return boost::accumulate(dp[0], 0ll) % MOD;
}

int main()
{
  ll l,r;
  cin>>l>>r;
  ll sum = 0;
  ll p2 = 1;
  ll q2 = 2;
  REP(i,60) {
    ll li = max(l, p2);
    ll ri = min(r, q2-1);
    if (li <= ri) {
      sum += solve(li, ri, i);
      sum %= MOD;
    }
    p2 <<= 1;
    q2 <<= 1;
  }
  cout<<sum<<endl;
  return 0;
}

