    ModInt(long long x = 0) :x((x% Mod + Mod) % Mod) {}
    constexpr ModInt& operator+=(const ModInt a) {
        if ((x += a.x) >= Mod) x -= Mod;
        return *this;
    }
    constexpr ModInt& operator-=(const ModInt a) {
        if ((x += Mod - a.x) >= Mod) x -= Mod;
        return *this;
    }
    constexpr ModInt& operator*=(const ModInt a) {
        (x *= a.x) %= Mod;
        return *this;
    }
    constexpr ModInt operator+(const ModInt a) const {
        ModInt res(*this);
        return res += a;
    }
    constexpr ModInt operator-(const ModInt a) const {
        ModInt res(*this);
        return res -= a;
    }
    constexpr ModInt operator*(const ModInt a) const {
        ModInt res(*this);
        return res *= a;
    }
    constexpr ModInt pow(long long t) const {
        if (!t) return 1;
        ModInt a = this->pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    constexpr ModInt inv() const {
        return this->pow(Mod - 2);
    }
    constexpr ModInt& operator/=(const ModInt a) {
        return (*this) *= a.inv();
    }
    constexpr ModInt operator/(const ModInt a) const {
        ModInt res(*this);
        return res /= a;
    }
    constexpr bool operator==(const long long a) const {
        return x == a;
    }
    constexpr bool operator!=(const long long a) const {
        return x != a;
    }
    constexpr bool operator<(const long long a) const {
        return x < a;
    }
    constexpr bool operator>(const long long a) const {
        return x > a;
    }
    constexpr bool operator<=(const long long a) const {
        return x <= a;
    }
    constexpr bool operator>=(const long long a) const {
        return x >= a;
    }

    long long x;

};
