ll l, r;
mint dp[65][2][2][2];
void solve() {
    std::cin >> l >> r;

    dp[60][0][0][0] = 1;
    for (int i = 59; i >= 0; --i) {
        auto lb = (l >> i) & 1;
        auto rb = (r >> i) & 1;

        for (int j = 0; j < 2; ++j)
            for (int k = 0; k < 2; ++k)
                for (int s = 0; s < 2; ++s) {
                    auto val = dp[i + 1][j][k][s];

                    if (val == 0)
                        continue;

                    for (int x = 0; x < 2; ++x)
                        for (int y = 0; y < 2; ++y) {
                            if (x == 1 && y == 0)
                                continue;
                            int nj = j, nk = k, ns = s;

                            if (s == 0 && x != y)
                                continue;
                            if (x == 1 && y == 1)
                                ns = 1;

                            if (j == 0 && x == 0 && lb == 1)
                                continue;
                            if (x == 1 && lb == 0)
                                nj = 1;

                            if (k == 0 && y == 1 && rb == 0)
                                continue;
                            if (y == 0 && rb == 1)
                                nk = 1;

                            dp[i][nj][nk][ns] += val;
                        }
                }
    }

    mint ans;
    for (int j = 0; j < 2; ++j)
        for (int k = 0; k < 2; ++k)
            for (int s = 0; s < 2; ++s)
                ans += dp[0][j][k][s];

    std::cout << ans.x << std::endl;

    return;
}


