ll L, R;
ll mo = 1000000007;
ll dp[2][2][2][61];

/* dp(d, msb, l, r)内のret: x, yのd桁目のより下の値の組み合わせ数
    msb: d桁目より上ですでにMSBとなる桁があったかどうか
    l  : d桁目より上を決めた段階で、L<=xか
    r  : d桁目より上を決めた段階で、y<=Rか

    上を前提にcom()でx, yのd桁目として0, 1を取りうるか見ていく。
*/
ll com(int d, int S, int LT, int RT){
    if(d == -1){
        return S == 1;
    }
    /* メモ */
    if(dp[S][LT][RT][d]>=0){
        return dp[S][LT][RT][d];
    }

    ll ret = 0;

    /* aがxのd桁目、bがyのd桁目 */
    int a, b;
    for(int a=0; a<2; a++){
        for(int b=0; b<2; b++){
            /* x>=Lになっているか */
            if(a==0 && LT && (L&(1LL<<d))>0){
                continue;
            }
            /* y<=Rになっているか */
            if(b==1 && RT && (R&(1LL<<d))==0){
                continue;
            }
            /* y-xで繰り下がりは起こさせない */
            if(a>b){
                continue;
            }
            /* MSBがなくてa==1かつb==1はだめ */
            if(S==0 && a != b){
                continue;
            }
            int NLT = LT && (((L>>d)&1)==a);
            int NRT = RT && (((R>>d)&1)==b);
            int NS = S || (a==1 && b==1);
            ret += com(d-1, NS, NLT, NRT);
        }
    }

    return dp[S][LT][RT][d] = ret % mo;
}

int main(){
    cin>>L>>R;
    MINUS(dp);
    cout<<com(61, 0, 1, 1)<<endl;
}

