ll rec(int n, bool f1, bool f2, bool f3) {
    if (n == -1) return 1;

    ll &res = dp[n][f1][f2][f3];
    if (~res) return res;
    res = 0;

    //nビットではx=0,y=0を選ぶ
    if (f1 || l[n] == 0) // x=0の条件
        res += rec(n - 1, f1, r[n] | f2, f3);
