        res += rec(n - 1, f1, f2, f3);
    //x=1,y=1
    if (f2 || r[n] == 1) //y=1の条件
        res += rec(n - 1, (1 - l[n]) | f1, f2, 1);

    res %= MOD;
    return res;

}

