ModInt<MOD> f(ll pos, bool f1, bool f2, bool f3){
    if(pos == -1) return 1;
    if(memo[pos][f1][f2][f3] != -1) return memo[pos][f1][f2][f3];

    ModInt<MOD> res;
    if(f1 || l[pos] == '0'){
        res += f(pos - 1, f1, (r[pos] == '1')? true : f2, f3);
    }
    if((f1 || l[pos] == '0') && (f2 || r[pos] == '1') && f3){
