int calc(int f0, int f1, int f2, int len) {
	if (len == K) {
		return 1;
	}
	int & res = dp[f0][f1][f2][len];
	if (res != -1) {
		return res;
	}
	res = 0;
	// x = 0, y = 0
	if (!f1 || (f1 && l[len] == 0)) {
		add(res, calc(f0, f1 && (l[len] == 0), f2 && (r[len] == 0), len + 1));
