		if ((!f1 || (f1 && l[len] == 0)) && (!f2 || (f2 && r[len] == 1))) {
			add(res, calc(0, f1 && (l[len] == 0), f2 && (r[len] == 1), len + 1));
		}
	}
	// x = 1, y = 1
	if (!f2 || (f2 && r[len] == 1)) {
		add(res, calc(0, f1 && (l[len] == 1), f2 && (r[len] == 1), len + 1));
	}
	return res;
}

