inline LL Get(LL x)
{
  	if ( x <= 0 ) return 0;
    if ( x == 1 ) return 1;
    if ( x == 2 ) return 3;
    if ( x % 2 == 0 ) return (Get(x / 2LL) * 3LL) % Mod;
    LL sum = (Get(x / 2LL) * 3LL) % Mod, y = -1;
    REP(i, 0, 61) if ( (x >> i) & 1LL ) ++ y; 
    if ( y == -1 ) return sum;
    return (sum + ((1LL << y) % Mod)) % Mod;
}

