      _dp[1][0][1] += dp[1][0][1] * 2; // (0, 0), (0, 1)
      _dp[1][1][1] += dp[1][0][1]; // (1, 1)
      _dp[1][1][1] += dp[1][1][0]; // (0, 0)
      _dp[1][1][0] += dp[1][1][0] * 2; // (0, 1), (1, 1)
      _dp[1][1][1] += dp[1][1][1] * 3; // (0, 0), (0, 1), (1, 1)
    }
    if ((!nthbit(L, i)) && (!nthbit(R, i))) {
      _dp[0][0][0] += dp[0][0][0]; // (0, 0)
      _dp[0][0][1] += dp[0][0][1]; // (0, 0)
      _dp[1][1][1] += dp[0][0][1]; // (1, 1)
      _dp[1][0][0] += dp[1][0][0]; // (0, 0)
