int main() {
    long long l, r; cin >> l >> r;
    long long ans = 0;
    // x ⊂ y
    // (0, 0), (0, 1), (1, 1)
    for (int k = 0; k < 62; k++) {
        long long c = 1LL << k;
        long long d = 1LL << (k+1);
        if (l >= d || c > r) continue;
        long long dp[k+1][4];
        // 0: l < curr && r > curr, 1: l <= curr, 2: r >= curr
        memset(dp, 0, sizeof(dp));
        int s = 0;
        if (c <= l && l < d) s += 1 << 0;
        if (c <= r && r < d) s += 1 << 1;
        dp[k][s]++;
        long long prev = ans;
        for (int i = k-1; i >= 0; i--) {
            if (i < 0) continue;
            bool lb = l & (1LL << i);
            bool rb = r & (1LL << i);

            // dp[i+1][0]
            dp[i][0] += dp[i+1][0] * 3 % mod;

            // dp[i+1][1]
            if (lb) {
                dp[i][1] += dp[i+1][1];
            } else {
                dp[i][0] += dp[i+1][1];
                dp[i][1] += dp[i+1][1] * 2 % mod; 
            }

            // dp[i+1][2]
            if (rb) {
                dp[i][2] += dp[i+1][2] * 2 % mod;
                dp[i][0] += dp[i+1][2];
            } else {
                dp[i][2] += dp[i+1][2];
            }

            // dp[i+1][3]
            if (lb == rb) {
                dp[i][3] += dp[i+1][3];
            } else if (rb) {
                dp[i][1] += dp[i+1][3];
                dp[i][2] += dp[i+1][3];
                dp[i][3] += dp[i+1][3];
            }
        }

        for (int j = 0; j < 4; j++) {
            ans = (ans + dp[0][j]) % mod;
        }
    }

    cout << ans << endl;
    return 0;
}

