int f(int k) {
	auto it = map.find(k);
	if (it != map.end()) return it->second;
	int& res = map[k];
	if (k <= 1) return res = 1;
	if (k & 1) return res = (2 * f(k / 2) + f(k / 2 + 1)) % MOD;
	else return res = 3 * f(k / 2) % MOD;
}

int g(int l, int r) {
	if (l > r) return 0;
	if (l == r) return 1;
	int ans = 0;
	RREP(k, 61) {
		if ((l & (1ll << k)) == (r & (1ll << k))) continue;
		{
			int t = l & ((1ll << k) - 1);
			(ans += f((1ll << k) - t)) %= MOD;
		}
		{
			int t = r & ((1ll << k) - 1);
			(ans += f(t + 1)) %= MOD;
		}
		(ans += g(l, r - (1ll << k))) %= MOD;
		break;
	}
	return ans;
}

