mint rec(int pos, bool f1, bool f2, bool f3) {
  if (pos < 0) return 1;

  bool &b = vis[pos][f1][f2][f3];
  mint &v = dp[pos][f1][f2][f3];
  if (b) return v;
  b = true;

  int br = (r >> pos) & 1;
  int bl = (l >> pos) & 1;

  mint res = 0;
  // 00
  if (f2 || !bl)
    res += rec(pos-1,f1,f2,br?true:f3);
  // 01
  if (f1 && (f2 || !bl) && (f3 || br))
    res += rec(pos-1,f1,f2,f3);
  // 11
  if (f3 || br)
    res += rec(pos-1,true,!bl?true:f2,f3);

  return v = res;
}

