using namespace std;
typedef long long ll;

const ll MOD = 1000000007;

ll pow2i[64];

ll power(ll x, ll n){
    ll res = 1;
    for(ll i = 0; i < n; i++) res = (res * x) % MOD;
    return res;
}

ll foo(ll i, ll k){
    ll res = power(3, i);
    ll s = pow2i[i] - k - 1;
    ll t = 0;
    for(ll j = i + 1; j >= 0; j--){
        if(pow2i[j] & s){
            res = (res + MOD - power(3, j) * power(2, t) % MOD) % MOD;
            t++;
        }
    }
    return res;
}

ll foo2(ll i, ll j){
    ll res = 0;
    j++;
    ll t = 0;
    for(ll k = i + 1; k >= 0; k--){
        if(pow2i[k] & j){
            res = (res + power(3, k) * power(2, t) % MOD) % MOD;
            t++;
        }
    }
    return res;
}

ll rec(ll i, ll j, ll k){
    if(k < 0) return 0;
    if(i == 0) return 1;
    if(k > j) return rec(i, j, j);
    if(pow2i[i - 1] > k){
        if(pow2i[i - 1] > j) return rec(i - 1, j, k);
        else return (rec(i - 1, j - pow2i[i - 1], k) + foo(i - 1, k)) % MOD;
    }
    return (rec(i - 1, j - pow2i[i - 1], k - pow2i[i - 1]) +
            foo2(i - 1, j - pow2i[i - 1]) + 
            foo(i - 1, pow2i[i - 1] - 1)) % MOD;
}

ll count(ll l, ll r){
    ll res = 0;
    ll noise = 0;
    ll temp = 1;
    while(temp <= l + 1){
        temp *= 2;
        noise++;
    }
    noise--;
    for(ll i = 0; i < noise; i++) res = (res + power(3, i)) % MOD;
    l -= pow2i[noise];
    r -= pow2i[noise];
    r = min(r, pow2i[noise] - 1);
    res = (res + rec(noise + 1, r, l)) % MOD;
    return res;
}

int main()
{
    pow2i[0] = 1;
    for(ll i = 1; i < 64; i++){
        pow2i[i] = pow2i[i - 1] * 2;
    }
    ll l, r;
    cin >> l >> r;
    cout << (count(r, r) + MOD - count(l - 1, r)) % MOD << endl;
}

