ULL dp(int pos, bool up, bool down) {
    //printf("%d %d %d\n", pos, up, down);
    if (pos == -1) return 1;
    if (!up && !down) {
        return p[pos+1];
    }
    int low = down ? L[pos] : 0;
    int high = up ? R[pos] : 1;
    ULL ref = 0;
    for (int i=low; i<=high; ++i) {
        int tim = 1;
        if (i==0 && high == 1 && down && !up) tim = 2;
        if (i==1 && low == 0 && up && !down) tim = 2;
        ref = (ref + tim*dp(pos-1, up&&i==high, down&&i==low)) % MOD;
    }
    if (high == 1 && low ==0 && up && down)
        ref = (ref + dp(pos-1, true, true)) % MOD;
    return ref;
}

