template <typename T>
void ri(T &x) {
    char c;
    bool minus = false;
    while ((c=getchar())<'0' || '9'<c)
        if (c == '-') minus = true;
    x = c - '0';
    while ('0'<=(c=getchar()) && c<='9')
        x = 10 * x - '0' + c;
    if (minus) x = -x;
}

