const int mod = 1e9 + 7;

long long l, r;
string a, b;
int dp[70][2][2][70], n, fl, fr, pw[70], res = 0;

void add (int &x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}

string convert (long long x) {
    string ans = "";
    while (x > 0) {
        int temp = x % 2;
        ans += (char)(temp + 48);
        x /= 2;
    }

    reverse(ans.begin(), ans.end());
    return ans;
}

int solve (int pos, int low, int high, int num, int specified, int type, int num2) {
    if (pos == n) {
        if (!type) return dp[pos][low][high][num] = pw[num];
        return dp[pos][low][high][num] = pw[num2 - 1];
    }

    if (dp[pos][low][high][num] != -1) return dp[pos][low][high][num];

    int ans = 0;
    int l = 0, r = 1;
    if (low) l = a[pos] - '0';
    if (high) r = b[pos] - '0';

    for (int i = l; i <= r; i++) {
        int nlow = 0, nhigh = 0;
        if (low && i == l) nlow = 1;
        if (high && i == r) nhigh = 1;
        if (pos < n - specified && i == 1) continue;
        if (pos == n - specified && i == 0) continue;
        if (type == 2 && i == 1) continue;
        if (type == 3 && i == 0) continue;

        int ntype = type;
        if (type >= 2) ntype -= 2;
        add(ans, solve(pos + 1, nlow, nhigh, num + (i == 0 && pos >= n - specified && type != 2), specified, ntype, num2 + (i == 1 && type != 3)));
    }

    return dp[pos][low][high][num] = ans;
}

