    int fdiff = 0, nzero = 0, none = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] != b[i]) {
            fdiff = i;
            break;
        }

        if (a[i] == 0) nzero++;
        else none++;
    }

    //cout << fdiff << " " << nzero << " " << none << "\n";
    for (int i = fl; i <= fr; i++) {
        memset(dp, -1, sizeof(dp));
        if (fl != fr) solve(0, 1, 1, 0, i, i == fr, 0);
        else {
            solve(fdiff, 1, 1, 0, i, 2, 0);
            for (int j = 0; j < 70; j++) {
                int sum = 0;
                for (int ll = 0; ll < 2; ll++) {
                    for (int rr = 0; rr < 2; rr++) {
                        add(sum, max(0, dp[fdiff][ll][rr][j]));
                    }
                }

                add(res, sum);
            }

            memset(dp, -1, sizeof(dp));
