            for (int j = 0; j < 70; j++) {
                int sum = 0;
                for (int ll = 0; ll < 2; ll++) {
                    for (int rr = 0; rr < 2; rr++) {
                        add(sum, max(0, dp[fdiff][ll][rr][j]));
                    }
                }

                add(res, sum);
            }

            add(res, (r - l + 1) % mod);
            break;
        }

        for (int j = 0; j < 70; j++) {
            int sum = 0;
            for (int ll = 0; ll < 2; ll++) {
                for (int rr = 0; rr < 2; rr++) {
                    add(sum, max(0, dp[0][ll][rr][j]));
                }
            }

            add(res, sum);
        }
    }

    cout << res;
