	Int t = 1, u = 1;
	while(t < l) t <<= 1;
	u = t >> 1;
	mint ans = func(r) - func(l-1);
	if(l < t){
		ans -= func(t-1) - func(l-1);
		ans += func(u-1+t-l) - func(u-1);
	}
	cout << (l == r ? mint(1) : ans) << "\n";
}

