const int N = 65;

int l, r;
int dp[N][2][2][2];

int solve(int idx, bool equal_L, bool equal_R, bool start){
   if(idx < 0){
      return start == 1;
   }

   int &ans = dp[idx][equal_L][equal_R][start];
   if(~ans)
      return ans;

   ans = 0;

   bool nf1 = equal_R, nf2 = equal_L;
   int bit_R = (r & (1LL << idx)) > 0;
   int bit_L = (l & (1LL << idx)) > 0;

   for (int i = 0; i < 2; ++i)
   {
      for (int j = 0; j < 2; ++j)
      {
         if(j > i)
            continue;
         bool tnf1 = nf1, tnf2 = nf2;
         if(nf1 == 1 and i > bit_R){
            continue;
         }
         else if(nf1 == 1 and i < bit_R){
            tnf1 = 0;
         }

         if(nf2 == 1 and j < bit_L){
            continue;
         }
         else if(nf2 == 1 and j > bit_L){
            tnf2 = 0;
         }

         if(start == 0){
            if(i != j)
               continue;
         }
         bool nstart = start;
         nstart |= (i > 0 && j > 0);
         ans += solve(idx-1, tnf2, tnf1, nstart);
         ans %= mod;
      }
   }

   return ans;
}

