							if (x && y) ns = 1;
							if (!j && lb && !x) continue;
							if (!lb && x) nj = 1;
							if (!k && !rb && y) continue;
							if (rb && !y) nk = 1;
							dp[i][nj][nk][ns] += dp[i + 1][j][k][s];
							dp[i][nj][nk][ns] %= MOD;
						}
					}
				}
			}
		}
	}
	long long ans = 0;
	for (int j = 0; j < 2; j++) {
		for (int k = 0; k < 2; k++) {
			for (int s = 0; s < 2; s++) {
				ans += dp[0][j][k][s];
				ans %= MOD;
			}
		}
	}
	cout << ans << endl;

	return 0;
}

