            if(!g&&bx+by==1)continue;
            if(!fl&&bl[i]&&!bx)continue;
            if(!fr&&!br[i]&&by)continue;
            dp[i+1][fl | (bx > bl[i])][fr | (by < br[i])][g | bx | by] += dp[i][fl][fr][g]%=mod;
        }
    }
    ll ans=0;
    rep(fl,2)rep(fr,2)rep(g,2)ans=(ans+dp[n][fl][fr][g])%mod;
    printf("%lld\n",ans);
    return 0;
}

