int ans = 0;

int s1(vector<int> &v, int cur, int bits){
	if(cur==bits+1) return 1;
	if(v[cur]==0) return s1(v,cur+1,bits);
	else {
		int ans1 = 0;
		int temp = 2*s1(v,cur+1,bits);
		temp %= MOD;
		int left = bits - cur - 1;
		ans1 = power(3,left);
		ans1 += temp;
		ans1 %=MOD;
		return ans1;
	}
}

int s2(vector<int> &v, int cur, int bits){
	if(cur==bits+1) return 1;
	if(v[cur]==1) return s2(v,cur+1,bits);
	else {
		int ans1 = 0;
		int temp = 2*s2(v,cur+1,bits);
		temp %= MOD;
		int left = bits - cur - 1;
		ans1 += power(3,left);
		ans1 += temp;
		ans1 %=MOD;
		return ans1;
	}
}



