ll MOD = 1'000'000'007;
vector<vector<ll>> memo;
ll L, R;

ll solve(int i = 60, int A = 0, int B = 0, int C = 0){
    ll L0 = L & (1ll << i);
    bool Lcond = L0 == 0 or A;
    ll R1 = R & (1ll << i);
    bool Rcond = R1 > 0 or B;
    ll k = 4*A + 2*B + C;
    if(i < 0) return 1;
    if(memo[i][k] != -1) return memo[i][k];
    ll ans = 0;

    if(Lcond){
        // xi 0, yi 0
        ans += solve(i-1, A, R1 > 0 ? 1 : B, C);
    }

    if(Lcond and Rcond and C){
        // xi 0, yi 1
        ans += solve(i-1, A, B, C);
    }

    if(Rcond){
        // xi 1, yi 1
        ans += solve(i-1, L0 == 0 ? 1 : A, B, 1);
    }
    return memo[i][k] = ans % MOD;
}

