const long long MOD = 1000000007;

long long LDP(long long N) {
	long long COUNT = 0, BIT[64] = {}, DP[65][3] = {};
	for (int i = 0; i < 64; i++) {
		BIT[i] = N % 2;
		N /= 2;
	}
	long long Cur = 1, END = 0;
	for (int i = 0; i < 64; i++) {
		if (BIT[i] == 1) {
			END = Cur;
			Cur *= 1;
			Cur %= MOD;
		}
		else {
			Cur *= 2;
			Cur %= MOD;
		}
	}
	COUNT = END;
	bool flag = true;
	for (int i = 63; i >= 0; i--) {
		if (BIT[i] == 0) continue;
		Cur = 1, END = 0;
		if (flag) {
			for (int j = 0; j < i; j++) {
				COUNT += Cur;
				COUNT %= MOD;
				Cur *= 3;
				Cur %= MOD;
			}
			flag = false;
			continue;
		}
		for (int j = 0; j < 65; j++) DP[j][0] = DP[j][1] = DP[j][2] = 0;
		DP[0][0] = 1;
		for (int j = 0; j < 64; j++) {
			long long SUM = DP[j][0] + DP[j][1] + DP[j][2];
			SUM %= MOD;
			if (j < i) {
				DP[j + 1][0] = SUM;
				DP[j + 1][1] = SUM;
				DP[j + 1][2] = SUM;
				END = DP[j + 1][0];
			}
			else if (BIT[j] == 1 && i != j) {
				DP[j + 1][0] = SUM;
				DP[j + 1][1] = 0;
				DP[j + 1][2] = 0;
				END = DP[j + 1][0];
			}
			else {
				DP[j + 1][0] = 0;
				DP[j + 1][1] = SUM;
				DP[j + 1][2] = SUM;
			}
		}
		COUNT += END;
		COUNT %= MOD;
	}
	return COUNT;
}

