int solve(int idx, bool equal_L, bool equal_R, bool start){
   if(idx < 0){
      return start == 1;
   }

   int &ans = dp[idx][equal_L][equal_R][start];
   if(~ans)
      return ans;

   ans = 0;

   int miy = 0, mxy = 1, mix = 0, mxx = 1;

   bool nf1 = equal_R, nf2 = equal_L;
   int bit_R = (r & (1LL << idx)) > 0;

   if(nf1 == 0);
   else{
      mxy = (bit_R);
   }

   bool bit_L = (l & (1LL << idx)) > 0;
   if(nf2 == 0);
   else{
      mix = (bit_L);
   }

   for (int i = miy; i <= mxy; ++i)
   {
      for (int j = mix; j <= mxx; ++j)
      {
         if(j > i)
            continue;
         bool tnf1 = nf1, tnf2 = nf2;
         if(nf1 == 1 and i < bit_R){
            tnf1 = 0;
         }
         if(nf2 == 1 and j > bit_L){
            tnf2 = 0;
         }
         if(start == 0){
            if(i == 1 and j == 0)
               continue;
            if(i == 0 and j == 1)
               continue;
         }
         bool nstart = start;
         nstart |= (i > 0 && j > 0);
         ans += solve(idx-1, tnf2, tnf1, nstart);
         ans %= mod;
      }
   }

   return ans;
}

