    rep(i, 0, MAX) rep(j, 0, 2) dp[i][j] = 0;
    // cerr << lk << " " << rk << endl;
    if(lk == rk){
        while(rk == lk){
            bool flagl, flagr;
            flagl = flagr = true;
            rrep(i, 0, lk) if((L >> i) & 1){ lk = i;flagl = false; break;}
            rrep(i, 0, rk) if((R >> i) & 1){ rk = i;flagr = false; break;}
            if(flagl) lk = -1;
            if(flagr) rk = -1;
            if(lk == -1 && rk == -1){
                cout << ans << endl;
                return 0;
            }
        }
        lk++, rk++;
    }
    dp[rk][1] = 1;
    rrep(i, 0, rk){
        if(R >> i & 1){
            dp[i][1] = dp[i+1][1] * 2;
            dp[i][0] = dp[i+1][1] + dp[i+1][0] * 3;
        }
        else{
            dp[i][1] = dp[i+1][1];
            dp[i][0] = dp[i+1][0] * 3;
        }
    }
    ans += dp[0][0] + dp[0][1];
    //cerr << ans << endl;
    if(lk != 0){
        rep(i, 0, MAX) rep(j, 0, 2) dp[i][j] = 0;
        dp[lk][1] = 1;
        rrep(i, 0, lk){
            if(L >> i & 1){
                dp[i][1] = dp[i+1][1];
                dp[i][0] = dp[i+1][0] * 3;
            }
            else{
                dp[i][1] = dp[i+1][1] * 2;
                dp[i][0] = dp[i+1][1] + dp[i+1][0] * 3;
            }
        }
        ans += dp[0][0] + dp[0][1];
    }

    cout << ans << endl;

    return 0;
}

