int64 dfs(int64 dig=0, bool u_r = 0, bool o_l = 0, bool st = 0) {
    if (~dp[dig][u_r][o_l][st]) return dp[dig][u_r][o_l][st];
    int64 &res = dp[dig][u_r][o_l][st];
    res = 0;
    if (dig == r.size()) {
        return res = 1;
    }

    int64 rlim = (u_r ? 2 : r[dig]+1);
    int64 llim = (o_l ? 0 : l[dig]);
    REP(i, rlim) {
        FOR(j, llim, i+1) {
            if (!st && i != j) continue;
            res += dfs(dig+1, u_r || (i+1 != rlim), o_l || (j != llim), st || (i == 1 && j == 1));
            res %= mod;
        }
    }
    return res;
}

