int main(){
    using namespace std;
    constexpr unsigned long MOD = 1000000007;
    unsigned long L, R;
    cin >> L >> R;

    auto modpow = [&MOD](unsigned long n, unsigned long b = 3, unsigned long c = 1){
        unsigned long r = c, p = b;
        while(n){
            if(n & 1)(r *= p) %= MOD;
            (p *= p) %= MOD;
            n >>= 1;
        }
        return r;
    };

    auto f = [&MOD, &L, &R, &modpow](unsigned long l, unsigned long r, unsigned long n) -> unsigned long{
        if(R < l || r <= L)return 0;
        if(L <= l && r <= R + 1)return modpow(n);
        auto lower = [&MOD, &modpow](unsigned long R, unsigned long n){
            unsigned long ret{0}, c{0};
            for(unsigned long i = n; --i;)if(R & (1UL << i))ret += modpow(c++, 2, modpow(i));
            return (ret += modpow(c, 2, 1 + 2 * (R & 1))) %= MOD;
        };
        auto upper = [&MOD, &modpow](unsigned long L, unsigned long n){
            unsigned long ret{0}, c{0};
            for(unsigned long i = n; --i;)if(!(L & (1UL << i)))ret += modpow(c++, 2, modpow(i));
            return (ret += modpow(c, 2, 1 + 2 * (~L & 1))) %= MOD;
        };
        if(l < L){
            if(r > R + 1){
                abort();
                unsigned long ret{0}, c{0}, d{0};
                for(unsigned long i = n; --i;){
                    if(~L & R & (1UL << i))return modpow(c, 2, upper(L & (1UL << i) - 1, i)) + modpow(d, 2, lower(R & (1UL << i) - 1, i));
                    c += 1 & (~L >> i);
                    d += 1 & (R >> i);
                }
                return 1;
            }
            else return upper(L, n);
        }else{
            return lower(R, n);
        }
    };

    unsigned long ans{0};
    for(unsigned long i = 1, j = 2, k = 0; i <= R; ++k){
        (ans += f(i, j, k)) %= MOD;
        swap(i *= 4, j);
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

long long prime = 1000000007;

// for 0 <= l <= r. Gets all pairs (x,y) such that l <= x <= y <= r and y&x == x.
long long simple_calc(long long l, long long r) {
    if (l == 0 && (r+1)&(-r-1) == (r+1)) {
        long long ans = 1;
        while (r > 0) {
            ans = (ans * 3) % prime;
            r /= 2;
        }
        return ans;
    }
    int K = 60;
    vector<vector<long long>> count(K+1, vector<long long>(4, 0));
    count[K][0] = 1;
    // Consider the bits K-1, K-2, .., i bits of l and r, say they correspond to l_i, r_i. (l_i = floor(l/2^i)*2^i and same for r_i)
    // Now count[i][j] counts the number of pairs (x, y) that are divisible by 2^u such that l_i <= x <= y <= r_i with y&x == x and such that:
    // if j = 0 then l = x, y = r
    // if j = 1 then l < x, y = r
    // if j = 2 then l = x, y < r
    // if j = 3 then l < x, y < r
    // Now say we want to calculate it for i-1:
    // Now we have four cases depending on whether the i-1 bit is set in x and y.
    // count[i-1][0] = count[i][0] * (!bit_x || bit_y)
    // count[i-1][1] = count[i][1] * (1 + bit_y) + bit_y * (1 - bit_x) * count[i][0]
    // count[i-1][2] = count[i][2] * (2 - bit_x) + (1 - bit_x) * bit_y * count[i][0]
    // count[i-1][3] = count[i][3] * 3 + (1 - bit_x) * count[i][2] + bit_y * count[i][1]
    for (int i = K; i >= 1; --i) {
        bool bit_x = (l & (1LL << (i-1))) != 0;
        bool bit_y = (r & (1LL << (i-1))) != 0;
        count[i-1][0] = count[i][0] * (!bit_x || bit_y);
        count[i-1][1] = (count[i][1] * (1 + bit_y) + bit_y * (1 - bit_x) * count[i][0]) % prime;
        count[i-1][2] = (count[i][2] * (2 - bit_x) + (1 - bit_x) * bit_y * count[i][0]) % prime;
        count[i-1][3] = (count[i][3] * 3 + (1 - bit_x) * count[i][2] + bit_y * count[i][1]) % prime;
    }
    return count[0][0] + count[0][1] + count[0][2] + count[0][3];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    long long l, r;
    cin >> l >> r;
    long long sum = 0;
    for (int bit = 60; bit >= 0; --bit) {
        // intersects interval with [2^bit, 2^(bit+1)-1]
        long long new_l = max(l, (1LL << bit));
        long long new_r = min(r, (1LL << (bit+1))-1);
        if (new_l <= new_r) {
            sum = (sum + simple_calc(new_l - (1LL << bit), new_r - (1LL << bit))) % prime;
        }
    }
    cout << sum << endl;
    return 0;
}

