#define int long long
//template
int pw(int n,int k){
  if(k<0)return pw(n,k+MOD-1);
  int res=1;
  while(k){
    if(k&1)res*=n;res%=MOD;
    n*=n;n%=MOD;
    k>>=1;
  }
  return res;
}
int f(int a){//最上位bitがa個目の全てのペア
  return pw(3,a-1);
}
int fm(int l){//x>=lのf(a),ただしaはlの最上位bit
  string s;int cnt=0,res=0,now=0;
  while(l){
    if(l&1)s+="1";
    else s+="0",cnt++;
    l>>=1;
  }
  res=pw(2,cnt);
  for(char p:s){
    if(p=='0')res+=pw(3,now)*pw(2,--cnt)%MOD;res%=MOD;
    now++;
  }
  return res;
}
int FM(int r){//y<=r
  string s;int cnt=0,res=0,now=0;
  while(r){
    if(r&1)s+="1",cnt++;
    else s+="0";
    r>>=1;
  }
  res=pw(2,cnt-1);
  for(char p:s){
    if(now==s.size()-1)continue;
    if(p=='1')res+=pw(2,--cnt-1)*pw(3,now)%MOD;res%=MOD;
    now++;
  }
  return res;
}
