const int64_t BIT=60,MOD=1e9+7;
bool Free[BIT+5][2][2][2];
int64_t l,r,F[BIT+5][2][2][2];
vector<int64_t> L,R;

vector<int64_t> Bin(int64_t x)
{
	vector<int64_t> rs;
	for(int64_t i=0;i<=BIT;i++)
	{
		rs.push_back(x%2);
		x/=2;
	}
	reverse(rs.begin(),rs.end());
	return rs;
}

int64_t DP(int64_t i,int64_t isOne,int64_t isGreater,int64_t isSmaller)
{
	if(i==BIT+1)
		return 1;
	if(Free[i][isOne][isGreater][isSmaller]==true)
		return F[i][isOne][isGreater][isSmaller];
	Free[i][isOne][isGreater][isSmaller]=true;
	int64_t rs=0;
	for(int64_t t1=(isGreater==false?L[i]:0);t1<=1;t1++)
		for(int64_t t2=t1;t2<=(isSmaller==false?R[i]:1);t2++)
		{
			int64_t newIsGreater=isGreater|(t1>L[i]);
			int64_t newIsSmaller=isSmaller|(t2<R[i]);
			if(isOne==false&&t1==0&&t2==1)
				continue;
			int64_t newIsOne=isOne|(t1==1);
			rs=(rs+DP(i+1,newIsOne,newIsGreater,newIsSmaller))%MOD;
		}
	return F[i][isOne][isGreater][isSmaller]=rs;
}

