const int Mod = 1e9 + 7;
ll dp[64][2][2][2], L, R;

ll solve(int now, bool l, bool r, bool bf)
{
	if (now == -1) return 1;
	ll &ans = dp[now][l][r][bf];
	if (ans >= 0) return ans;
	ans = 0;
	bool P = (L >> now) & 1;
	bool Q = (R >> now) & 1;
	for (int i = 0; i <= 1; i++) {
		for (int j = 0; j <= 1; j++) {
			if (l && i == 0 && P) continue;
			if (r && j == 1 && !Q) continue;
			if (i > j) continue;
			if (!bf && (i != j)) continue;
			ans += solve(now - 1, l && (i == P), r & (j == Q), bf || i);
		}
	}
	ans %= Mod;
	return ans;
}

