ull mi(ull a, ull b) {
    return (a + MOD * MOD - b) % MOD;
}

ull mpow(ull a, ull b) {
    if (b == 0) return 1ULL;
    ull ans = mpow(a,b/2);
    ans *= ans;
    ans %= MOD;
    if (b & 1) ans *= a;
    return ans % MOD;
}

ull ff(ull k, ull n) {
    if (n == (1ULL << k)) {
        return mpow(3ULL,k);
    }
    if (n <= (1ULL << (k - 1))) {
        return ff(k-1,n);
    }
    return (mpow(3ULL,k-1) + 2ULL * ff(k-1,n-(1ULL<<(k-1)))) % MOD;
}

ull f(ull n) {
    if (n == 0) return 0ULL;
    if (n == 1) return 1ULL;
    ull k = 0;
    ull tmp = n;
    while (tmp) {
        tmp /= 2;
        k++;
    }
    k--;
    ull before = 1ULL << k;
    before--;
    ull ret = f(before) + ff(k,n-before);
    return ret % MOD;
}

void solve() {
    ull X,Y;
    cin >> X >> Y;
    cout << mi(f(Y),f(X-1)) << endl;
}

