#define REP(i,n) for(int i = 0; i < (int)(n); i++)

uint64_t p3[100];
uint64_t mod = 1000000007;

map<pair<uint64_t, uint64_t>, uint64_t> memo;

uint64_t solve(uint64_t l, uint64_t r, int b){
  if(l > r) return 0;
  if(l == r) return 1;
  if(l == 0 && r == (1ull << b) - 1){
    return p3[b];
  }
  auto it = memo.find(make_pair(l, r));
  if(it != memo.end()){
    return it->second;
  }
  uint64_t h = 1ull << (b - 1);
  uint64_t ret = 0;
  // 0, 0
  if(l < h){
    ret += solve(l, min(r, h - 1), b - 1);
  }
  // 0, 1
  if(l < h && r >= h){
    ret += solve(l, r - h, b - 1);
  }
  // 1, 1
  if(r >= h){
    ret += solve(max(l, h) - h, r - h, b - 1);
  }
  ret %= mod;
  memo[make_pair(l, r)] = ret;
  return ret;
}

int main(){
  uint64_t l, r;
  cin >> l >> r;
  p3[0] = 1;
  REP(i, 100) if(i > 0){
    p3[i] = p3[i - 1] * 3 % mod;
  }
  uint64_t ret = 0;
  REP(b, 62){
    uint64_t m = 1ull << b;
    uint64_t n = m * 2 - 1;
    if(l <= n && r >= m){
      ret += solve(max(l, m) - m, min(r, n) - m, b);
      ret %= mod;
    }
  }
  cout << ret << endl;
  return 0;
}

