#define MEM(a,b) memset((a),(b),sizeof(a))
const LL INF = 1e9 + 7;
const int N = 3e2 + 10;
int s1[N], s2[N];
LL dp[N][4][2][2][2];
int cnt = 0;
LL dfs(int pos, int s,
	bool up1 = true, bool lead1 = true,
	bool up2 = true, bool lead2 = true)
{
	if (lead1 ^ lead2) return 0;
	if (s == 1) return 0;
	if (pos == -1) return 1;
	if (dp[pos][s][up1][up2][lead1 && lead2] != -1) return dp[pos][s][up1][up2][lead1 && lead2];
	//cnt++;
	LL& res = dp[pos][s][up1][up2][lead1 && lead2] = 0;
	int l1 = 0, r1 = up1 ? s1[pos] : 1;
	int l2 = 0, r2 = up2 ? s2[pos] : 1;
	for (int i = l1; i <= r1; i++)
	{
		for (int j = l2; j <= r2; j++)
		{
			res += dfs(pos - 1, i * 2 + j,
				up1 && i == s1[pos], lead1 && i == 0,
				up2 && j == s2[pos], lead2 && j == 0);
		}
	}
	res %= INF;
	return res;
}
LL solve(LL l, LL r)
{
	MEM(dp, -1);
	MEM(s1, 0);
	MEM(s2, 0);
	int len1 = 0;
	int len2 = 0;
	while (r)
	{
		s1[len1++] = r % 2;
		r /= 2;
	}
	while (l)
	{
		s2[len2++] = l % 2;
		l /= 2;
	}
	return dfs(len1 - 1, 0);
}
int main()
{
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);
	MEM(dp, -1);
	LL l, r;
	cin >> l >> r;
	int ans2 = solve(r, r);
	int ans1 = solve(l - 1, r);
	//cout << cnt << endl;
	int ans = ans2 - ans1;
	if (ans < 0) ans += INF;
	cout << ans << endl;
	return 0;
}

