int64_t const MOD = 1e9+7;

template<int64_t Prime>
struct mod_int {
  int64_t v_;
  mod_int(int64_t x=0) : v_(x) { normalize(); }
  void normalize() { ((v_ %= Prime) += Prime) %= Prime; }
  mod_int operator+=(mod_int const& r){ (v_ += r.v_) %= Prime; return *this; }
  mod_int operator-=(mod_int const& r){ (v_ += Prime - r.v_) %= Prime; return *this; }
  mod_int operator*=(mod_int const& r){ (v_ *= r.v_) %= Prime; return *this; }
  mod_int operator+(mod_int const& r) { mod_int res(*this); return res += r; }
  mod_int operator-(mod_int const& r) { mod_int res(*this); return res -= r; }
  mod_int operator*(mod_int const& r) { mod_int res(*this); return res *= r; }
  mod_int pow(int x) const {
    int64_t res = 1, v = v_;
    while(x > 0) {
      if(x&1) (res *= v) %= Prime;
      x/=2; (v *= v) %= Prime;
    }
    return mod_int(res);
  }
  mod_int inv() const { return pow(Prime-2); }
};
typedef mod_int<MOD> mint;

template<typename T>
struct optional {
  bool valid;
  T v_;
  optional(): valid(false) {}
  T& operator=(T const& v)
    { v_ = v; valid = true; return v_; }
};

optional<mint> dp[60][2][2][2];
int bL[60], bR[60];

mint calc(int i, bool tl, bool tr, bool has1) {
  if(i < 0) return 1;
  if(dp[i][tl][tr][has1].valid) return dp[i][tl][tr][has1].v_;
  bool canbe1 = (bR[i]==1 || !tr);
  bool canbe0 = (bL[i]==0 || !tl);

  mint res;
  // y[i]=x[i]=1
  if(canbe1) res = calc(i-1, tl && bL[i]==1, tr, true);
  // y[i]=1; x[i]=0
  if(canbe1&canbe0&has1) res += calc(i-1, tl, tr, has1);
  // y[i]=x[i]=0
  if(canbe0) res += calc(i-1, tl, tr && bR[i]==0, has1);

  return dp[i][tl][tr][has1] = res;
}

int main() {
  int64_t L, R; std::cin >> L >> R;
  for(int i = 0; i < 60; ++i) {
    int64_t b = (int64_t)1 << i;
    bL[i] = (b&L)? 1: 0;
    bR[i] = (b&R)? 1: 0;
  }
  fin(calc(59, true, true, 0).v_);
  return 0;
}

