ll dp[63][1<<3];
void mod_add(ll &a, ll b){
	a += b;
	a %= MOD;
}

int main(){
	ll l, r;cin >> l >> r;
	dp[0][0] = 1;

	REP(i, 62){
		REP(j, (1LL<<3)){
			REP(x, 2)REP(y, 2){
				if(x == 1 && y == 0)continue;
				int nj = j;
				if(!(nj & 1)){
					int tmp = ((l & (1LL << (61-i))) != 0);
					if(x < tmp)continue;
					else if(x > tmp)nj |= 1;
				}
				if(!(nj & 2)){
					int tmp = ((r & (1LL << (61-i))) != 0);
					if(y > tmp)continue;
					else if(y < tmp)nj |= 2;
				}
				if(!(nj & 4)){
					if(x + y != 0 && x + y != 2)continue;
					if(x + y == 2)nj |= 4;
				}
				mod_add(dp[i+1][nj], dp[i][j]);
			}
		}
	}

	ll ans = 0;
	REP(i, 8)mod_add(ans, dp[62][i]);
