#include <bits/stdc++.h>
#define MOD 1000000007LL
using namespace std;
typedef long long ll;
typedef pair<int,int> P;

ll l,r;
ll bit[2][65];
ll dp[66][2][2];
ll ans;

void solve(ll l,ll r){
	if(l>r)return;
	//printf("%lld %lld\n",l,r);
	int v=0;
	ll tl=l,tr=r;
	while(l>0){
		bit[0][v]=l%2LL;
		v++;
		l/=2LL;
	}
	v=0;
	while(r>0){
		bit[1][v]=r%2LL;
		v++;
		r/=2LL;
	}
	memset(dp,0,sizeof(dp));
	if(bit[0][v-1]==0){
		dp[v-1][1][0]=1;
	}else{
		dp[v-1][0][0]=1;
	}
	for(int i=v-2;i>=0;i--){
		for(int j=0;j<2;j++){
			for(int k=0;k<2;k++){
				for(int a=0;a<2;a++){
					if(j==0 && a==0 && bit[0][i]==1)continue;
					int nj=j;
					if(a==1 && bit[0][i]==0)nj=1;
					for(int b=0;b<2;b++){
						if(k==0 && b==1 && bit[1][i]==0)continue;
						if(a==1 && b==0)continue;
						int nk=k;
						if(b==0 && bit[1][i]==1)nk=1;
						dp[i][nj][nk]+=dp[i+1][j][k];
						dp[i][nj][nk]%=MOD;
					}
				}
			}
		}
	}
	for(int i=0;i<2;i++){
		for(int j=0;j<2;j++){
			ans+=dp[0][i][j];
			ans%=MOD;
		}
	}
	l=tl;
	r=tr;
	ll ig=1;
	for(int i=0;i<v-1;i++){
		ig*=2LL;
	}
	ig--;
	solve(l,ig);
}

int main(void){
	scanf("%lld%lld",&l,&r);
	if(r==1LL){
		printf("1\n");
		return 0;
	}
	solve(l,r);
	printf("%lld\n",ans);
	return 0;
}

