// key: 下から数えてiビット目以上は決まっているとき，x, y の下からiビット目の値
// value: パターン数
ll memo[62][2][2]; 
ll L, R;

// 次に決めるべきはiビット目，L < x 確定済みか， y < R 確定済みか
ll dfs(int i, int flag_x, int flag_y) {
    if(i == -1) return 1LL;
    if(memo[i][flag_x][flag_y]) return memo[i][flag_x][flag_y];

    ll ret = 0LL;
    // 0, 0
    if(flag_x || !(L & (1LL << i))) {
        ret += dfs(i-1, flag_x, flag_y || (R & (1LL << i)));
        ret %= MOD;
    }

    // 0, 1
    if((flag_x || !(L & (1LL << i))) && (flag_y || (R & (1LL << i)))) {
        ret += dfs(i-1, flag_x, flag_y);
        ret %= MOD;
    }

    // 1, 1
    if(flag_y || (R & (1LL << i))) {
        ret += dfs(i-1, flag_x || !(L & (1LL << i)), flag_y);
        ret %= MOD;
    }

    return memo[i][flag_x][flag_y] = ret;
}

