const int mod = 1e9 + 7;

LL dp[65][2][2],l,r; 

LL dfs(int x, bool left, bool right, bool zero) {
    if (x < 0)return 1; 
    if (dp[x][left][right] >= 0 && ! zero)return dp[x][left][right]; 
    LL ans = 0; 
    int l = 0, r = 1; 
    if(left) l = l >> x & 1; 
    if(right) r = r >> x & 1; 
    for (int i = l; i <= 1; i++){
        for (int j = i; j <= r; j++) {
            if(j == 1 && zero) {
                if(i == 1) ans += dfs(x-1, left && i == l, right && j == r, zero && j == 0); 
            }
            else ans += dfs(x-1, left && i == l, right && j == r, zero && j == 0); 
        }
    }
    ans %= mod; 
    if(!zero) dp[x][left][right] = ans; 
    return ans; 
}

