//thr[i]:3^(i-1)
//calc_x（k）：xがx以上になるようなk桁の整数。yはFREE
//calc＿xy（k）：xがx以上、yがy以下になるようなk桁の整数。
void calc_x(ll k)
{
    ll nowx = (1ll << k);
    ll res = 1;
    repr(i,k-1,-1){
        if ((x>>i)&1){
            nowx += (1ll << i);
        }
        else{
            ans = (ans + thr[i] * res % mod) % mod;
            res = (res * 2) % mod;
        }
    }
    ans = (ans + res) % mod;
}
void calc_y(ll k)
{
    ll nowy = (1ll << k);
    ll res = 1;
    repr(i,k-1,-1){
        if ((y>>i)&1){
            ans = (ans + thr[i] * res % mod) % mod;
            nowy += (1ll << i);
            res = (res * 2) % mod;
        }
        else{
            continue;
        }
    }
    ans = (ans + res) % mod;
}
void calc_xy(ll k)
{
    ll nowx, nowy;
    nowx = nowy = (1ll << k);
    repr(i,k-1,-1){
        bool bx = ((x >> i) & 1), by = ((y >> i) & 1);
        if (bx&&by){
            //x1y1
            nowx += (1ll << i);
            nowy += (1ll << i);
        }
        else if (bx){
            //x1y0
            return;
        }
        else if (by){
            //x0y1
            //x1y0できない
            //x0y0：yのみFREE
            x -= nowx;
            x += (1ll << i);
            calc_x(i);
            x -= (1ll << i);
            x += nowx;
            //x1y1：xのみFREE
            y -= nowy;
            calc_y(i);
            y += nowy;
            //x0y1：次
            nowy += (1ll << i);
        }
        else{
            //x0y0
            //y0固定なのでx0y0のみ。特に何もできない。
            continue;
        }
    }
    ans = (ans + 1) % mod;
}
