    {
        ll mn = (1ll << k);
        ll mx = (1ll << (k + 1)) - 1;
        if (y < mn)
            break;
        if (mx < x)
            continue;
        if (mn <= x && y <= mx)
        {
            if (mn == x && y == mx)
            {
                ans = (ans + thr[k]) % mod;
            }
            else
                calc_xy(k);
        }
        else if (mn < x)
        {
            calc_x(k);
        }
        else if (y < mx)
        {
            calc_y(k);
        }
        else
        {
            ans = (ans + thr[k]) % mod;
        }
    }
    cout << ans << ENDL;
}

