template<class Type>
Type solve(Type res = Type()){
    ll L,R; cin >> L >> R;

    // bit , L <= x , y <= R , bit
    auto memo = make_v<ll>(60,2,2,2);
    fill_v(memo,-1);
    auto dfs = [&](auto self,int pos=59,int flag1=0,int flag2=0,int flag3=0) -> ll{
        if(pos == -1){
            return 1;
        }
        ll& ret = memo[pos][flag1][flag2][flag3];
        if(~ret){
            return ret;
        }
        ret = 0;

        if(flag1 || ((L>>pos)&1) == 0){
            ret += self(self,pos-1,flag1,((R>>pos)&1) || flag2,flag3);
        }
        if((flag1 || ((L>>pos)&1) == 0) && (flag2 || ((R>>pos)&1) == 1) && flag3){
            ret += self(self,pos-1,flag1,flag2,flag3);
        }
        if(flag2 || ((R>>pos)&1) == 1){
            ret += self(self,pos-1,(((L>>pos)&1) == 0) || flag1,flag2,1);
        }
        ret %= MOD;

        return ret;
    };
    res = dfs(dfs);
    return res;
}
