signed main(){
	int L,R;
	in(L,R);
	string s="",t="";
	while(L){
		t+='0'+(L&1);
		L>>=1;
	}
	while(R){
		s+='0'+(R&1);
		R>>=1;
	}
	while(s.size()>t.size())t+='0';
	int mostLeft = -1;
	reverse(ALL(s));
	reverse(ALL(t));
	REP(i,t.size()){
		if(t[i]=='1'){
			mostLeft = i;
			break;
		}
	}
	REP(i,s.size()){
		if(i<=mostLeft)dp[i+1][i==0][i==mostLeft] += 1;
		REP(j,2)REP(k,2){
			int limj = j ? s[i] - '0' : 1;
			int limk = k ? t[i] - '0' : 0;
			REP(l,limj+1)FOR(m,limk,2){
				if(l < m)continue;
				if(k && m < (t[i] - '0'))continue;
				dp[i+1][j&((s[i]-'0')==l)][k&((t[i]-'0')==m)]+=dp[i][j][k];
			}
		}
	}
	mint ans = 0;
	REP(i,2)REP(j,2){
		ans+=dp[s.size()][i][j];
	}
	out(ans);
}

