void calc_x(ll k)
{
   // cout << "calc x : " << k << ENDL;
    ll mn = (1ll << k);
    ll nowx = mn;
    ll res = 1;
    repr(i, k - 1, -1)
    {
        //ｘを１にしたら確実に超える
        //０にして次へ。
        //１にしないと下回る。１にする
        if ((1ll << i) + nowx >= x)
        {
            ans += (res * thr[i]) % mod;
            ans %= mod;
            res = (res * 2) % mod;
        }
        else
        {
            nowx += (1ll << i);
        }
    }
}
void calc_y(ll k)
{
    //cout << "calc y : " << k << ENDL;
    ll mn = (1ll << k);
    ll nowy = mn;
    ll res = 1;
    repr(i, k - 1, -1)
    {
        if ((1ll << i) + nowy - 1 <= y)
        {
            //yを０にすると確実に下回る
            //y０のとき下の桁自由、y１として次へ
            ans = ((ans + (res * thr[i]) % mod)) % mod;
            nowy += (1ll << i);
            res = (res * 2) % mod;
        }
    }
    //もし最後の桁を１にしたときｙ以下なら+res？
    if (nowy<=y)
        ans = (ans + res) % mod;
}
void calc_xy(ll k)
{
    ll mn = (1ll << k);
    ll nowx = mn, nowy = mn;
    ll res = 1;
    /*必要なもの：
    ｘがFREEになったあと、yの場合の数を求めるもの
    ｙがFREEになったあと、xの場合の数を求めるもの
    x確定、y確定なものの場合の数：１？
    片方FREEとしてｘ、ｙでDPをする。

    */
    repr(i, k - 1, -1)
    {
        //cout << i << " " << ans << ENDL;
        //ｘ：１にしたらxを超えるなら、１にして自由、０にする
        //１にしてもｘを超えないとき、０にしたら絶対無理。１にする
        //ｙ：０にしたら必ずyを下回る。０にして自由、１にする
        //１にしたら超えるから０にする
        bool bx = ((1ll << i) + nowx >= x), by = ((1ll << i) + nowy - 1 <= y);
        if (bx && by)
        {
            //x1y1にするとxがFREEなのでyだけのものを関数でやる
            y -= nowy;
            calc_y(i);
            y += nowy;
            //x０y０にする
            ll tmp = x;
            x -= nowx;
            x += (1ll << i);
            calc_x(i);
            x = tmp;
            //次のstepはx0y1のやつ
            nowy += (1ll << i);
        }
        else if (bx)
        {
            //yが0固定なのでx0y0のみ
            y -= nowy;
            calc_y(i);
            y += nowy;
        }
        else if (by)
        {
            //xが1固定なのでx1y1
            nowx += (1ll << i);
            nowy += (1ll << i);
        }
        else
        {
            //xが1、yが0のみ。実現不可能。
            return;
        }
    }
    ans = (ans + 1) % mod;
}
int main()
{
