		for (int jj = 0; jj < vertex.size() * 2; ++jj) {
			for (int i = 0; i < vertex.size(); ++i) {
				for (auto& edge : vertex[i].edges) {
					auto tmp = val(i).dis + edge.w;
					if (val(edge.next).dis > tmp) {
