				for (auto& edge : vertex[i].edges) {
					if (val(edge.next).dis > val(i).dis + edge.w) {
						return false;
					}
				}
			}
		}
		else {
			assert(false);	//なんかうまくできてないっぽい
			int v = posEnd;
