long long memo[60][2][2][2];

long long f( int pos, int flagX, int flagY, int flagZ )
{
	if( pos == -1 ) return 1;
	if( memo[pos][flagX][flagY][flagZ] >= 0 ) return memo[pos][flagX][flagY][flagZ];
	long long ret = 0;
	if( flagX || l[pos] == 0 ) {
		int flag = flagY;
		if( r[pos] ) flag = 1;
		ret += f( pos - 1, flagX, flag, flagZ );
	}
	if( ( flagX || l[pos] == 0 ) &&
		( flagY || r[pos] ) && flagZ ) {
		ret += f( pos - 1, flagX, flagY, flagZ );
	}
	if( flagY || r[pos] ) {
		int flag = flagX;
		if( l[pos] == 0 ) flag = 1;
		ret += f( pos - 1, flag, flagY, 1 );
	}
	ret %= MOD;
	memo[pos][flagX][flagY][flagZ] = ret;
	return ret;
}

