using namespace std;

const long long MOD = 1000000007;

long long LDP(long long N) {
	long long COUNT = 0, BIT[64] = {};
	for (int i = 0; i < 64; i++) {
		BIT[i] = N % 2;
		N /= 2;
	}
	long long Cur = 1, END = 0;
	for (int i = 0; i < 64; i++) {
		if (BIT[i] == 1) {
			END = Cur;
			Cur *= 1;
			Cur %= MOD;
		}
		else {
			Cur *= 2;
			Cur %= MOD;
		}
	}
	COUNT = END;
	bool flag = true;
	for (int i = 63; i >= 0; i--) {
		if (BIT[i] == 0) continue;
		Cur = 1, END = 0;
		if (flag) {
			for (int j = 0; j < i; j++) {
				COUNT += Cur;
				COUNT %= MOD;
				Cur *= 3;
				Cur %= MOD;
			}
			flag = false;
			continue;
		}
		for (int j = 0; j < 64; j++) {
			if (j < i) {
				Cur *= 3;
				Cur %= MOD;
			}
			else {
				if (BIT[j] == 1 && i != j) {
					END = Cur;
					Cur *= 1;
					Cur %= MOD;
				}
				else {
					Cur *= 2;
					Cur %= MOD;
				}
			}
		}
		COUNT += END;
		COUNT %= MOD;
	}
	return COUNT;
}

long long RDP(long long N) {
	long long COUNT = 0, BIT[64] = {};
	for (int i = 0; i < 64; i++) {
		BIT[i] = N % 2;
		N /= 2;
	}
	long long Cur = 1, END = 0;
	for (int i = 0; i < 64; i++) {
		if (BIT[i] == 1) {
			END = Cur;
			Cur *= 2;
			Cur %= MOD;
		}
		else {
			Cur *= 1;
			Cur %= MOD;
		}
	}
	COUNT = END;
	bool flag = true;
	for (int i = 63; i >= 0; i--) {
		if (BIT[i] == 0) continue;
		Cur = 1, END = 0;
		if (flag) {
			for (int j = 0; j < i; j++) {
				COUNT += Cur;
				COUNT %= MOD;
				Cur *= 3;
				Cur %= MOD;
			}
			flag = false;
			continue;
		}
		for (int j = 0; j < 64; j++) {
			if (j < i) {
				Cur *= 3;
				Cur %= MOD;
			}
			else {
				if (BIT[j] == 1 && i != j) {
					END = Cur;
					Cur *= 2;
					Cur %= MOD;
				}
				else {
					Cur *= 1;
					Cur %= MOD;
				}
			}
		}
		COUNT += END;
		COUNT %= MOD;
	}
	return COUNT;
}

