ll calc(ll pos, bool is_l, bool is_r, bool ch = 0) {
    if(pos < 0) return !is_l or !is_r;
    if(dp[pos][is_l][is_r][ch] != -1) return dp[pos][is_l][is_r][ch];
    ll &res = dp[pos][is_l][is_r][ch];
    res = 0;
    // 1 1
    if(!is_r or b[pos])
        (res += calc(pos - 1, is_l && a[pos], is_r, 1)) %= mod;

