    long long beg = (1ull << (sz - 1));
    long long end = (1ull << sz) - 1;
    if (beg > R) continue;
    if (end < L) continue;
    ans += solve(sz, max(0ll, L-beg), min(end - beg, R - beg));
    ans %= mod;
  }
  printf("%lld\n", ans);
  return 0;
}

