	if(dp[len][bl][br][cl][have] != -1) return dp[len][bl][br][cl][have];
	int kl = bl ? (L >> len & 1) : 0;
	int kr = br ? (R >> len & 1) : 1;
	int dl = cl ? (L >> len & 1) : 0;
	int re = 0;
	if(0 >= kl && 0 <= kr && !dl) {
		re = add(re,dfs(len-1,bl&&kl==0,br&&kr==0,cl&&kl==0,have));
	}
	if(1 >= kl && 1 <= kr) {
		re = add(re,dfs(len-1,bl&&kl==1,br&&kr==1,cl&&kl==1,1));
		if(dl == 0 && have) re = add(dfs(len-1,bl&&kl==1,br&&kr==1,cl,have),re);
	}
	return dp[len][bl][br][cl][have] = re;
}
int main()
{
	memset(dp,-1,sizeof(dp));
	scanf("%lld%lld",&L,&R);
	printf("%d\n",dfs(62,1,1,1,0));
	return 0;
}

/**
 * x % y == x xor y というのは、
 * 2進数の桁数が同じ (違うとxorがyより大きくなる)
 * かつxはyの0である桁を1に変えたもの (%もxorも、変えた桁が1、変えない桁が0になる)
 *
 * 図にすると
 *   1 2 3 4 5 6 7 8 9 x
 * 1 *
 * 2   * *
 * 3     *
 * 4       * * * *
 * 5         *   *
 * 6           * *
 * 7             *
 * 8               * *
 * 9                 *
 * y
 *
 * 2**nで一つのブロックであり、n+1のブロックはnのブロックを3個並べた形になる
 *
 * よって方針としては
 * 1. L,Rが所属するブロックを算出
 * 2-1. L,Rが同じブロックの場合、そのブロックを分割して計算
 * 2-2. 違う場合は、L,Rの間にあるブロック + Lが分割するブロック + Rが分割するブロック
 */

