int tp[2][64];
void put(int id, long long v){
	for(int i = 0; i < 64; i++, v /= 2) tp[id][i] = v % 2;
}
int dp[64][2][2][2];
int count(int pos, int bg0, int sm1, int some){
	if(pos == -1) return 1;
	int & vdp = dp[pos][bg0][sm1][some];
	if(vdp != -1) return vdp;
	int l0 = bg0 ? 0 : tp[0][pos];
	int l1 = sm1 ? 1 : tp[1][pos];
	int ans = 0;
	for(int v0 = l0; v0 <= 1; v0++){
		for(int v1 = 0; v1 <= l1; v1++){
			if(some){
				if(v1 >= v0)
				       	ans += count(pos - 1, bg0 || (v0 > tp[0][pos]), sm1 || (v1 < tp[1][pos]), some);
			} else {
				if(v1 == v0)
				       	ans += count(pos - 1, bg0 || (v0 > tp[0][pos]), sm1 || (v1 < tp[1][pos]), some || (v1 > 0));
			}
			if(ans >= mod) ans -= mod;
		}
	}
	return vdp = ans;
}
