#include <bits/stdc++.h>

using namespace std;

#define ll long long
#define mod ((long long)1e9 + 7)

ll r, l;

ll sol(int k) {
	ll dp[62][2][2];
	for (int i = 0; i < 62; ++i)
		for (int j = 0; j < 2; ++j)
			for (int l = 0; l < 2; ++l)
				dp[i][j][l] = 0;
	bool f1 = false;
	for (int i = 0; i < k; ++i) {
		bool ri = r & ((ll)1 << (61 - i));
		f1 = ri;
		if (f1) break;
	}
	bool f2 = false;
	for (int i = 0; i < k; ++i) {
		bool li = l & ((ll)1 << (61 - i));
		f2 = f2 || li;
	}
	if (f2) return 0;

	bool rb = r & ((ll)1 << (61 - k));
	bool lb = l & ((ll)1 << (61 - k));

	if ((!f1) && (!rb)) return 0;

	if (f1) {
		if (lb) {
			dp[k][0][1] = 1;
			dp[k][0][0] = 0; dp[k][1][1] = 0; dp[k][1][0] = 0;
		}
		else {
			dp[k][0][0] = 1;
			dp[k][0][1] = 0; dp[k][1][1] = 0; dp[k][1][0] = 0;
		}
	}
	else {
		if (lb) {
			dp[k][1][1] = 1;
			dp[k][0][0] = 0; dp[k][0][1] = 0; dp[k][1][0] = 0;
		}
		else {
			dp[k][1][0] = 1;
			dp[k][0][1] = 0; dp[k][1][1] = 0; dp[k][0][0] = 0;
		}
	}


	for (int i = k + 1; i < 62; ++i) {
		bool ri = r & ((ll)1 << (61 - i));
		bool li = l & ((ll)1 << (61 - i));
		// 0 0 の遷移
		dp[i][0][0] = ((3 * dp[i - 1][0][0]) % mod);
		if (!li) {
			dp[i][0][0] += dp[i - 1][0][1];;
			dp[i][0][0] %= mod;
		}
		if (ri) {
			dp[i][0][0] += dp[i - 1][1][0];
			dp[i][0][0] %= mod;
		}
		// 1 1の遷移
		if ((!ri) && li)
			dp[i][1][1] = 0;
		else
			dp[i][1][1] = dp[i][1][1];
		// 0 1の遷移
		dp[i][0][1] = 0;
		if (!li) {
			dp[i][0][1] += (2 * dp[i - 1][0][1] % mod);
			dp[i][0][1] %= mod;
		}
		else {
			dp[i][0][1] += dp[i - 1][0][1] % mod;
			dp[i][0][1] %= mod;
		}
		if (ri && (!li)) {
			dp[i][0][1] += dp[i - 1][1][1] % mod;
			dp[i][0][1] %= mod;
		}
		// 1 0 の遷移
		dp[i][1][0] = 0;
		if (ri) {
			dp[i][1][0] += dp[i - 1][1][0] * 2 % mod;
			dp[i][1][0] %= mod;
		}
		else {
			dp[i][1][0] += dp[i - 1][1][0] % mod;
			dp[i][1][0] %= mod;
		}
		if ((!li) && ri) {
			dp[i][1][0] += dp[i - 1][1][1];
			dp[i][1][0] %= mod;
		}
	}
	ll r = 0;
	for (int i = 0; i < 2; ++i)
		for (int j = 0; j < 2; ++j)
			r = (r + dp[61][i][j]) % mod;
	return r;
}

signed main() {
	cin >> l >> r;

	ll ans = 0;
	for (int i = 0; i < 62; ++i) {
		//cout << sol(i) << endl;
		ans = (ans + sol(i)) % mod;
	}

	cout << ans << endl;

	return 0;
}

