int solve(int bit, bool a, bool b, bool s){
    if(bit == -1) return 1;
    int &ret = dp[bit][a][b][s];
    if(ret != -1) return ret;
    ret = 0;
    // 0 0
    if(a || ((l >> bit) & 1) == 0) ret += solve(bit - 1, a, b || ((r >> bit) & 1), s);
    if(ret >= mod) ret -= mod;
    // 0 1
    if(s && (a || ((l >> bit) & 1) == 0) && (b || ((r >> bit) & 1) == 1)) ret += solve(bit - 1, a, b, s);
    if(ret >= mod) ret -= mod;
    // 1 1
    if(b || ((r >> bit) & 1) == 1) ret += solve(bit - 1, a || ((l >> bit) & 1) == 0, b, 1);
    if(ret >= mod) ret -= mod;
    return ret;
}
