const LL INF = 1e9 + 7;
const int N = 2e2 + 10;
int s1[N], s2[N];
LL dp[N][4];
int cnt = 0;
LL dfs(int pos, int s, 
	bool lo1 = true, bool up1 = true, bool lead1 = true, 
	bool lo2 = true, bool up2 = true, bool lead2 = true)
{
	if (lead1 ^ lead2) return 0;
	if (s == 1) return 0;
	if (pos == -1) return 1;
	if (!lo1 && !up1 && !lead1 && !lo2 && !up2 && !lead2 && dp[pos][s] != -1) return dp[pos][s];
	cnt++;
	LL res = 0;
	int l1 = lo1 ? s2[pos] : 0, r1 = up1 ? s1[pos] : 1;
	int l2 = lo2 ? s2[pos] : 0, r2 = up2 ? s1[pos] : 1;
	for (int i = l1; i <= r1; i++)
	{
		for (int j = l2; j <= r2; j++)
		{
			res += dfs(pos - 1, i * 2 + j,
				lo1 && i == s2[pos], up1 && i == s1[pos], lead1 && i == 0,
				lo2 && j == s2[pos], up2 && j == s1[pos], lead2 && j == 0);
		}
	}
	res %= INF;
	if (!lo1 && !up1 && !lead1 && !lo2 && !up2 && !lead2) dp[pos][s] = res;
	return res;
}
LL solve(LL l, LL r)
{
	MEM(s1, 0);
	MEM(s2, 0);
	int len1 = 0;
	int len2 = 0;
	while (r)
	{
		s1[len1++] = r % 2;
		r /= 2;
	}
	while (l)
	{
		s2[len2++] = l % 2;
		l /= 2;
	}
	return dfs(len1, 0);
}
