long long solve() {
  long long ans = 0;
  for(int i = 0; i < fin; ++i) {
    long long nbase = 1LL << i, nmax = (1LL << (i + 1)) - 1,
              now = 0;
    if(nmax < l || nbase > r) continue;
    now += cnt(nbase, min(r, nmax), i + 1);
    if(nbase < l) now -= cnt(nbase, l - 1, i + 1);
    now += N;
    now %= N;
    ans += now;
    ans %= N;
  }
  return ans;
}

long long cnt(long long base, long long x, long long dig) {
  vector<vector<long long>> dp;
  dp.assign(dig, vector<long long>(2, 0));
  x -= base;
  dp[0][0] = 1;
  for(int i = 0; i < dig - 1; ++i) {
    if((x >> (dig - 2 - i)) & 1) {
      // 1, use 1 can use 0 or 1
      dp[i + 1][0] += dp[i][0] * 2 % N;
      dp[i + 1][1] += dp[i][1] * 2 % N;
      // 1, use 0
      dp[i + 1][1] += (dp[i][0] + dp[i][1]) % N;
    }
    else {
      dp[i + 1][0] += dp[i][0];
      dp[i + 1][1] += dp[i][1] * 3 % N;
    }
  }
  return (dp[dig - 1][0] + dp[dig - 1][1]) % N;
}

