				dp[t][1][1] = (dp[t-1][1][0] + dp[t-1][1][1] * 3) % MOD; 
			}
		}
		long long tmp = dp[d-1][0][0] + dp[d-1][0][1] + dp[d-1][1][0] + dp[d-1][1][1]; 
