const int MOD = (1e9 + 7);
ll add(ll a, ll b)
{
	a+=b;
	a%=MOD;
	return a;
}
ll ms(ll a, ll b)
{
	a-=b; a%=MOD;
	if(a<0) a+=MOD;
	return a;
}
ll mult(ll a, ll b)
{
	a%=MOD; b%=MOD;
	return (a*1LL*b)%MOD;
}
ll modpow(ll a, ll b)
{
	ll r=1;
	while(b)
	{
		if(b&1) r=mult(r,a);
		a=mult(a,a);
		b>>=1;
	}
	return r;
}
int choose(int a, int b)
{
	if(a<b) return 0;
	if(b==0) return 1;
	if(a==b) return 1;
	return mult(fact[a],mult(ifact[b],ifact[a-b]));
}
int inverse(int a)
{
	return modpow(a,MOD-2);
}
void init(int _n)
{
	fact.clear(); ifact.clear(); inv.clear(); pow2.clear(); pow3.clear();
	fact.resize(_n+1);
	ifact.resize(_n+1);
	inv.resize(_n+1);
	pow3.resize(_n+1);
	pow2.resize(_n+1);
	pow2[0]=1;
	pow3[0]=1;
	ifact[0]=1;
	fact[0]=1;
	for(int i=1;i<=_n;i++)
	{
		pow2[i]=add(pow2[i-1],pow2[i-1]);
		pow3[i]=add(pow3[i-1],add(pow3[i-1],pow3[i-1]));
		fact[i]=mult(fact[i-1],i);
		//ifact[i]=mult(ifact[i-1],inv[i]);
	}
	ifact[_n] = inverse(fact[_n]);
	for(int i=_n-1;i>=1;i--)
	{
		ifact[i] = mult(ifact[i + 1], i + 1);
	}
	for(int i=1;i<=_n;i++)
	{
		inv[i] = mult(fact[i-1],ifact[i]);
	}
}

ll F[111];
ll G[111];
ll solve(int bit, ll curL, ll curR)
{
	if(curL<0||curR<0) return 0;
	if(bit<0) return 1;
	ll ans = 0;
	if(curR>=(1LL<<(bit+1))-1&&curL>=(1LL<<(bit+1))-1)
	{
		return pow3[bit+1];
	}
	if(curR>=(1LL<<(bit+1))-1)
	{
		ll coeff = 1;
		for(int i=bit;i>=0;i--)
		{
			if(curL<(1LL<<i))
			{
				coeff=add(coeff,coeff);
				continue;
			}	
			//pick 0
			ans=add(ans,mult(mult(coeff,2),F[i]));
			curL-=(1LL<<i);
		}
		ans=add(ans,coeff);
		return ans;
	}
	if(curL>=curR)
	{
		ll coeff = 1;
		for(int i=bit;i>=0;i--)
		{
			if(curR<(1LL<<i))
			{
				continue;
			}	
			//pick 0
			ans=add(ans,mult(coeff,G[i]));
			curR-=(1LL<<i); coeff=mult(coeff,2);
		}
		ans=add(ans,coeff);
		return ans;
	}
	ans=add(ans,solve(bit-1,curL,curR));
	//if y bit is 1, x bit is 0
	ans=add(ans,solve(bit-1,curL,curR-(1LL<<bit)));
	ans=add(ans,solve(bit-1,curL-(1LL<<bit),curR-(1LL<<bit)));	
	return ans;
}

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	init(101001);
	ll l,r; cin>>l>>r;
	F[0]=1;
	for(int i=1;i<=61;i++)
	{
		for(int j=0;j<=i;j++)
		{
			F[i]=add(F[i], mult(choose(i,j),pow2[j]));
		}
	}
	G[0]=1;
	for(int i=1;i<=61;i++)
	{
		for(int j=0;j<=i;j++)
		{
			G[i]=add(G[i], mult(choose(i,j),pow2[j]));
		}
	}
	ll ans = 0;
	for(int i=61;i>=0;i--)
	{
		if((1LL<<i)>r) continue;
		//start from y=(1LL<<i),x=(1LL<<i)
		ll curr = r-(1LL<<i);
		ll a = solve(i-1,curr,curr);
		ll b = solve(i-1,l-(1LL<<i)-1,curr);
		ans=add(ans,ms(a,b));
	}
	cout<<ans<<'\n';
}

