ll search(ll index, ll flagL, ll flagR, ll flagMSB){
  //fprintf(stderr, "%lld %lld %lld %lld\n", index, flagL, flagR, flagMSB);
  if(index<0) return 1;
  if(dp[index][flagL][flagR][flagMSB]>=0) return dp[index][flagL][flagR][flagMSB];

  ll ans = 0;

  // x = y = 0
  if(flagL==0 && (L>>index)%2==1) goto TMP1;
  if(flagR==0 && (R>>index)%2==1){
    ans += search(index-1, flagL, 1, flagMSB);
  }else{
    ans += search(index-1, flagL, flagR, flagMSB);
  }

TMP1:
  // x = 0, y = 1
  if(flagL==0 && (L>>index)%2==1) goto TMP2;
  if(flagR==0 && (R>>index)%2==0) goto TMP2;
  if(flagMSB==0) goto TMP2;
  ans += search(index-1, flagL, flagR, flagMSB);
TMP2:
  ans %= MOD;

  // x = y = 1
  if(flagR==0 && (R>>index)%2==0) goto TMP3;
  if(flagL==0 && (L>>index)%2==0){
    ans += search(index-1, 1, flagR, 1);
  }else{
    ans += search(index-1, flagL, flagR, 1);
  }
TMP3:
  ans %= MOD;
  return dp[index][flagL][flagR][flagMSB] = ans;
}

