    std::vector<int> l, r;
    for (int i = 0; i < 60; i++) {
        l.push_back((L >> i) & 1);
        r.push_back((R >> i) & 1);
    }
    std::reverse(l.begin(), l.end());
    std::reverse(r.begin(), r.end());
    std::vector<std::vector<Mint>> dp(60, std::vector<Mint>(8));
    auto func = [&](const auto &self, int pos=0,
            bool lflag=true, bool rflag=true, bool msbflag=false) {
        if (pos >= 60) return Mint(1);
        int flagid = lflag + 2 * rflag + 4 * msbflag;
        if (dp[pos][flagid] != 0) return dp[pos][flagid];

        if (!lflag || l[pos] == 0)
            dp[pos][flagid] += self(self, pos + 1,
                lflag && l[pos] == 0, rflag && r[pos] == 0, msbflag);
        if (!rflag || r[pos] == 1)
            dp[pos][flagid] += self(self, pos + 1,
                lflag && l[pos] == 1, rflag && r[pos] == 1, true);
        if (msbflag && (!lflag || l[pos] == 0) && (!rflag || r[pos] == 1))
            dp[pos][flagid] += self(self, pos + 1,
                lflag && l[pos] == 0, rflag && r[pos] == 1, msbflag);
        return dp[pos][flagid];
    };
    func(func);
    std::cout << dp[0][3] << std::endl;
    return 0;
}

