const int NMAX = int(1e7);
ll fact[NMAX+1], finv[NMAX+1], inv[NMAX+1];

void comb_init(int N) {
    // init
    REP(i, 2) {
        fact[i] = 1;
        finv[i] = 1;
        inv[i] = 1;
    }

    FOR(i, 2, N+1) {
        fact[i] = fact[i-1] * i % MOD;
        inv[i] = MOD - MOD / i * inv[MOD % i] % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}

mint comb(int n, int k) {
    if (n < k || n < 0 || k < 0) return 0;

    return mint(fact[n]) * finv[k] * finv[n-k];
}

mint calc(ll x, bool l = false) {
    vector<ll> v;
    while(x > 0) {
        if (x & 1) v.pb(1);
        else v.pb(0);
        x >>= 1;
    }

    reverse(ALL(v));

    ll bit_all = accumulate(ALL(v), 0);

    debug(bit_all, v)

    mint ret = 0;
    ll cnt = 0;
    bool first = true;
    REP(i, v.size()) {
        if (v[i] == 0) continue;

        // not use this digit
        if (l) {
            if (!first) {
                ll N = v.size() - i - 1;
                REP(j, N) {
                    ret += comb(N, j) * mint(2).pow(v.size() - cnt - 1);
                }
            }
            first = false;
        } else {
            ll N = v.size() - i - 1;
            if (N > 0) {
                FOR(j, 1, N + 1) {
                    ret += comb(N, j) * mint(2).pow(j + cnt - 1);
                }
            }
        }

        // use this digit
        if (l) {
            ret += mint(2).pow(v.size() - cnt - 1);
        } else {
            ret += mint(2).pow(bit_all - cnt - 1);
        }
        cnt++;
    }

    return ret;
}

mint calc2(ll x) {
    ll t = x;
    mint ret = 0;
    ll cnt = 0;
    while((x >> 1) > 0) {
        REP(i, cnt + 1) {
            ret += comb(cnt, i) * mint(2).pow(cnt - i);
        }
        x >>= 1; cnt++;
        debug(ret, x, cnt)
    }

    debug(calc(t, true))

    ret += calc(t, true);

    return ret;
}

