		int ans1 = 0;
		int temp = 2*s2(v,cur+1,bits);
		temp %= MOD;
		int left = bits - cur - 1;
		ans1 = power(3,left);
		ans1 += temp;
		ans1 %= MOD;
		return ans1;
	}
}



