ll dfs(int p,int lim,int fl,int x0){
	if(!p) return x0;
	if(~dp[p][lim][fl][x0]) return dp[p][lim][fl][x0];
	//cout<<p<<' '<<lim<<' '<<fl<<' '<<x0<<endl;
