			ll now = dp[i][j][k][l];
			dp[i][j][k][l] %= MOD;

			for (int x = 0; x < 2; x++)for (int y = 0; y < 2; y++) {
				if (x == 1 && y == 0)continue;

				int nj = j, nk = k, nl = l;
