				dp[i + 1][nj][nk][nl] += now;
				dp[i + 1][nj][nk][nl] %= MOD;
			}

		}
	}

	ll ans = 0;

	for (int j = 0; j < 2; j++)for (int k = 0; k < 2; k++)for (int l = 0; l < 2; l++)
