const int N = 200;
const int MOD = 1000000000 + 7;

int a[N], b[N];
long long dp[N];

long long get(int pivot, bool first, bool less_x, bool less_y, bool greater_x, bool greater_y) {
  if (pivot == 0) {
    return 1;
  }
  if (less_x && less_y && greater_x && greater_y && !first && dp[pivot] != -1) {
    return dp[pivot];
  }
  int lower_x = greater_x ? 0 : a[pivot];
  int lower_y = greater_y ? 0 : a[pivot];
  int upper_x = less_x ? 1 : b[pivot];
  int upper_y = less_y ? 1 : b[pivot];
  long long result = 0, temp = 0;
  for (int i = lower_y; i <= upper_y; ++ i) {
    if (first && i == 0) continue;
    for (int j = lower_x; j <= upper_x; ++ j) {
      if (first && j == 0) continue;
      if (j > i) continue;
      temp = get(pivot - 1, false, less_x || j < upper_x, less_y || i < upper_y, greater_x || j > lower_x, greater_y || i > lower_y);
      result = (result + temp) % MOD;
    }
  }
  if (less_x && less_y && greater_x && greater_y && !first) {
    dp[pivot] = result;
  }
  return result;
}

long long solve(long long x, long long y) {
  int len_a = 0;
  while (x) {
    a[++ len_a] = x % 2;
    x /= 2;
  }

  int len_b = 0;
  while (y) {
    b[++ len_b] = y % 2;
    y /= 2;
  }

  long long result = 0;
  for (int len = len_b; len >= len_a; -- len) {
    result += get(len, true, len < len_b, len < len_b, len > len_a, len > len_a);
    result %= MOD;
  }
  // std::cerr << y << " " << result << std::endl;
  return result;
}

