const ll mod = 1000000007;
ll beki(ll a, ll b) {
    if(b == 0) return 1;
    ll ret = beki(a, b / 2);
    ret = ret * ret % mod;
    if(b & 1) ret = ret * a % mod;
    return ret;
}
ll digit(ll a) {
    if(a == 0) return 0;
    return 1 + digit(a / 2);
}
ll L, R;
ll ans;
void g(ll index, ll factor) {
    if(index == 0) return;
    if(1LL << (index - 1) & L) {
        ans -= factor * 2 * beki(3, index - 1);
        ans %= mod;
        ans += mod;
        ans %= mod;
        g(index - 1, factor);
        return;
    } else {
        g(index - 1, factor * 2 % mod);
        return;
    }
}

void f(ll index, ll factor) {
    if(index == 0) return;
    //cerr << (1LL << (index-1)) << " " << L << endl;
    if(1LL << (index - 1) & R) {
        f(index - 1, factor * 2 % mod);
        return;
    } else {
        ans -= factor * 2 * beki(3, index - 1);
        ans %= mod;
        ans += mod;
        ans %= mod;
        f(index - 1, factor);
        return;
    }
}

void h(ll index, ll factor, bool Ltight, bool Rtight) {
    if(Ltight && Rtight) {
        ans -= factor * beki(3, index);
        ans %= mod;
        ans += mod;
        ans %= mod;
        return;
    }
    if(index == 0) return;
    ll Lnow = (1LL << (index - 1)) & L;
    ll Rnow = (1LL << (index - 1)) & R;
    for(ll l = 0; l <= 1; l++) {
        for(ll r = 0; r <= l; r++) {
            if(Ltight && Lnow && (l == 0)) continue;
            if(Rtight && (Rnow == 0) && r) continue;
            bool NewLtight = Ltight;
            if(Lnow == 0 && l == 1) NewLtight = false;
            bool NewRtight = Rtight;
            if(Rnow == 1 && r == 0) NewRtight = false;
            h(index - 1, factor, NewLtight, NewRtight);
        }
    }
}

