int dp[N][2][2][2];
ll L, R;

int add(int x, int y) {
	int ret = (x + y);
	if (ret >= mod) {
		ret -= mod;
	}
	return ret;
}
int solveDp(int ind, int msb, int xeq, int yeq) {
	if (ind < 0) {
		if (msb) {
			return 1;
		}
		return 0;
	}
	int &ret = dp[ind][msb][xeq][yeq];
	if (ret != -1) {
		return ret;
	}
	ret = 0;
	for (int i = 0; i < 2; ++i) {
		for (int j = 0; j < 2; ++j) {
			if (i > j) {
				continue;
			}
			if (xeq && i == 0 && L&(1LL << ind)) {
				continue;
			}
			if (yeq && j == 1 && (R&(1LL << ind)) == 0)
			{
				continue;
			}
			int nxeq, nyeq;
			nxeq = xeq;
			nyeq = yeq;
			if (xeq && i == 1 && (L&(1LL << ind)) ==0 ) {
				nxeq = 0;
			}
			if (yeq && j == 0 && (R&(1LL << ind))) {
				nyeq = 0;
			}
			if (msb == 0) {
				if (i != j) {
					continue;
				}
				if (i == 1) {
					ret = add(ret, solveDp(ind - 1, 1, nxeq, nyeq));
				}
				else {
					ret = add(ret, solveDp(ind - 1, 0, nxeq, nyeq));
				}
			}
			else {
				ret = add(ret, solveDp(ind - 1, 1, nxeq, nyeq));
			}
		}
	}
	return ret;
}
void solve() {
	scanf("%lld %lld", &L, &R);
	memset(dp, -1, sizeof(dp));
	printf("%d\n", solveDp(N-1, 0, 1, 1));
}
