		return 0;
	}
	if (i == 0) {
		return 0;
	}

	int64_t num = (1LL << i) / 2;
	if (r == num) {
		return getfull(i);
	}

	if (r <= num / 2) {
		return getpart(i - 1, r);
	}
	else {
		return (getfull(i - 1) + 2 * getpart(i - 1, r - (num / 2))) % kRem;
	}
}

int64_t solve(int64_t l, int64_t r)
{
	int64_t posl = pos(l);
	int64_t posr = pos(r);

	int64_t reml = (l - ((1LL << (posl - 1)) - 1));
	int64_t remr = (r - ((1LL << (posr - 1)) - 1));

	int64_t ans = 0;

	FOR_LE(i, posl, posr - 1) {
		ans += getfull(i);
	}
	ans += getpart(posr, remr);

	ans -= (getfull(posl) - getpart(posl, (1LL << (posl - 1)) - reml));

	ans %= kRem;
	if (ans < 0) ans += kRem;

	return ans;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int64_t l, r;  cin >> l >> r;

	int64_t ans = solve(l - 1, r);

	cout << ans << endl;

	return 0;
}

