const lint mod = 1e9 + 7;

lint powmod(long x, long n){
  lint ret = 1;
  while(n > 0){
    if(n&1) ret *= x, ret %= mod, n -= 1;
    else x *= x, x %= mod, n >>= 1;
  }
  return ret;
}

map<lint, lint> mp;

lint g(lint n){
    if(n <= 0) return 0;
    if(n == 1) return 1;
    if(mp.find(n) != mp.end()) return mp[n];
    lint ret;
    if(n & 1) ret = (2*g(n/2) + g(n/2+1)) % mod;
    else ret = 3*g(n/2) % mod;
    return mp[n] = ret;
}

lint f(lint n){
    lint cur = 1;
    int k = 0;
    while(cur*2-1 <= n){
        cur *= 2;
        ++k;
    }
    lint ret = (powmod(3, k)-1+mod) % mod * powmod(2, mod-2) % mod;
    ret = (ret + g(n-cur+1)) % mod;
    return ret;
}

int main(){
    lint l, r;
    scanf("%lld%lld", &l, &r);
    lint ans = f(r);
    lint cur = 1;
    int k = 0;
    while(cur-1 < l-1){
        if(!cur) ++cur;
        else cur *= 2;
        ++k;
    }
    lint a = (powmod(3, k)-1+mod) % mod * powmod(2, mod-2) % mod;
    lint b = g(cur-l);
    ans = (ans - a + b + mod) % mod;
    printf("%lld\n", ans);
}

