int128_t solve(int128_t msb) {
    if (msb < msbL || msbR < msb) {
        return 0;
    }
    assert(msbL <= msb && msb <= msbR);

    int128_t dp[70][2][2] = {}; // dp[i][x][y] : i桁まで見て、xの条件が確定or未確定、yの条件が確定or未確定の状態数。
    dp[msb][msbL < msb ? 1 : 0][msb < msbR ? 1 : 0] = 1;

    rev (i, msb - 1, 0) {
        int128_t Lb = (L >> i) & 1;
        int128_t Rb = (R >> i) & 1;
        rep (px, 0, 1) { rep (py, 0, 1) {
            rep (xb, 0, 1) { rep (yb, 0, 1) {
                if (yb == 0 && xb == 1) { continue; }

                int128_t nx = px;
                if (nx == 0) {
                    if (Lb == 1 && xb == 0) {
                        continue;
                    } else if (Lb == 0 && xb == 1) {
                        nx = 1;
                    }
                }

                int128_t ny = py;
                if (ny == 0) {
                    if (Rb == 0 && yb == 1) {
                        continue;
                    } else if (Rb == 1 && yb == 0) {
                        ny = 1;
                    }
                }

                dp[i][nx][ny] += dp[i+1][px][py];
                dp[i][nx][ny] %= MOD;
            }}
        }}
    }

    return (dp[0][0][0] + dp[0][0][1] + dp[0][1][0] + dp[0][1][1]) % MOD;

}

