vector<int> L,R; 
int dp[65][2][2][2]; 
int rec(int pos, int ly, int gx, int ms){
  if(pos==sz(R)) return 1; 
  if(dp[pos][ly][gx][ms]!=-1) return dp[pos][ly][gx][ms]; 
  int ret=0; 
  for(int y=0;y<=1;y++){
    for(int x=0;x<=1;x++){
      if(y>=x){
        if( ms ){
          if((y<R[pos] || ly) && (x>L[pos] || gx)){
            add_self(ret,rec(pos+1,1,1,ms)); 
          }
          else if((y<R[pos] || ly) && (x==L[pos])){
            add_self(ret,rec(pos+1,1,0,ms)); 
          }
          else if((y==R[pos]) && (x>L[pos] || gx)){
            add_self(ret, rec(pos+1,0,1,ms)); 
          }
          else if(y==R[pos] && x==L[pos]){
            add_self(ret,rec(pos+1,0,0,ms)); 
          }
        }
        else if(x==y){
          if((y<R[pos] || ly) && (x>L[pos] || gx)){
            add_self(ret,rec(pos+1,1,1,y==1)); 
          }
          else if((y<R[pos] || ly) && (x==L[pos])){
            add_self(ret,rec(pos+1,1,0,y==1)); 
          }
          else if((y==R[pos]) && (x>L[pos] || gx)){
            add_self(ret, rec(pos+1,0,1,y==1)); 
          }
          else if(y==R[pos] && x==L[pos]){
            add_self(ret,rec(pos+1,0,0,x==1)); 
          }
        }
      }
    }
  }
  return dp[pos][ly][gx][ms]=ret; 
}

void solve(){
  ll l,r; cin>>l>>r; 
  while(r){
    R.push_back(r%2); 
    r>>=1; 
  }
  while(l){
    L.push_back(l%2); 
    l>>=1; 
  }
  while(sz(L)<sz(R)) L.push_back(0); 
  reverse(all(R)); 
  reverse(all(L)); 
  memset(dp,-1,sizeof(dp)); 
  int ans=rec(0,0,0,0); 
  cout<<ans<<endl; 
}

int main(){
  clock_t beg=clock(); 
  solve(); 
  clock_t end=clock(); 
  fprintf(stderr,"%.2lf sec\n",(double)(end-beg)/CLOCKS_PER_SEC); 
}

