	cin >> l >> r;
	ll ans = solve(l, r);
	ll st = 1; ll cnt = 1;
	while ((st << 1) <= l) {
		st <<= 1;
		cnt *= 3; cnt %= mod;
	}
	ans -= cnt;
	ans += solve(st, 3 * st - l - 1);
	cout << (ans + mod) % mod << '\n';
}

