inline mint pw(mint a, long long n) {
    mint res = 1;
    while (n > 0) {
        if (n & 1) {
            res *= a;
        }
        a *= a;
        n >>= 1;
    }
    return res;
}
vector<mint> fact, finv;
inline void cinit(int n) {
    fact.resize(n, 1);
    finv.resize(n, 1);
    for (int i = 2; i < n; i++) {
        fact[i] = fact[i - 1] * i;
    }
    finv[n - 1] /= fact[n - 1];
    for (int i = n - 2; i >= 2; i--) {
        finv[i] = finv[i + 1] * (i + 1);
    }
}
inline mint C(int n, int k) {
    if (n < k || k < 0 || n < 0) return 0;
    return fact[n] * finv[k] * finv[n - k];
}
inline mint H(int n, int k) {
    return C(n + k - 1, k);
}

map<tuple<int, ll, ll>, mint> mp;

mint solve(int d, ll l, ll r) {
    if (mp[{d, l, r}] != 0) {
        return mp[{d, l, r}];
    }
    ll s = 1LL << d, t = (1LL << (d + 1)) - 1;
    if (r < s || t < l) {
        return 0;
    }
    if (l <= s && t <= r) {
        return mp[{d, l, r}] = pw(3, d);
    }
    r = min(r, t);
    l = max(l, s);
    ll mid = s + (1LL << (d - 1));
    ll dif = 1LL << (d - 1);
    if (r < mid) {
        return mp[{d, l, r}] = solve(d - 1, l - dif, r - dif);
    }
    if (mid <= l) {
        return mp[{d, l, r}] = solve(d - 1, l - s, r - s);
    }
    mint res = solve(d - 1, l - dif, r) + solve(d - 1, dif, r - s);
    ll a = l - dif, b = r - s;
    if (a <= b) {
        res += solve(d - 1, a, b);
    }
    return mp[{d, l, r}] = res;
}

