    if(n & 1) res = res * x % m;
    return res;
}

void solve() {
    ll L, R; cin >> L >> R;
    ll ans = 0;
    rep(k, 62) {
        if(R < (1<<k)) continue;
        if((1<<k)* 2 - 1LL < L) continue;
        ll mimi = max(1<<k, L);
        ll maxi = min(mini * 2 - 1LL, R);
        ll dp[100][3][2][2];
        memset(dp, 0, sizeof(dp));
        dp[0][0][0][0] = 1LL;
        for(int i = 0; i < k; i++) {
            int p = (L & (1<<(k - i - 1)) ? 1 : 0);
            int q = (R & (1<<(k - i - 1)) ? 1 : 0);
            rep(a, 3) {
                rep(b, 2) {
                    rep(c, 2) {

                            if(b == 1 && c == 1) {
                                rep(d, 3) (dp[i + 1][d][b][c] += dp[i][a][b][c]) %= mod;
                            } else if(b == 1 && c == 0) {
                                if(q == 1) {
                                    rep(d, 3) (dp[i + 1][d][b][c] += dp[i][a][b][c]) %= mod;
                                } else {
                                    if(c == 0)(dp[i + 1][1][b][c] += dp[i][a][b][c]) %= mod;
                                    if(c == 0)(dp[i + 1][2][b][c] += dp[i][a][b][c]) %= mod;
                                }
                            } else if(b == 0 && c == 1) {
                                if(p == 1) {
                                    rep(d, 3) (dp[i + 1][d][b][c] += dp[i][a][b][c]) %= mod;
                                } else {
                                    if(b == 0)(dp[i + 1][2][b][c] += dp[i][a][b][c]) %= mod;
                                }
                            } else if(b == 0 && c == 0) {
                                if(p == 1 && q == 1) {
                                    rep(d, 3)(dp[i + 1][d][b][c] += dp[i][a][b][c]) %= mod;
                                } else if(p == 0 && q == 1) {
                                    if(b == 0)(dp[i + 1][2][b][c] += dp[i][a][b][c]) %= mod;
                                } else if(p == 1 && q == 0) {
                                    if(c == 0)(dp[i + 1][1][b][c] += dp[i][a][b][c]) %= mod;
                                    if(c == 0)(dp[i + 1][2][b][c] += dp[i][a][b][c]) %= mod;
                                } else {
                                    if(b == 0 && c == 0)(dp[i + 1][2][b][c] += dp[i][a][b][c]) %= mod;
                                }

                        }
                    }
                }
            }
            rep(j, 3) {
                rep(a, 2) {
                    rep(b, 2) {
                        (ans += dp[k][j][a][b]) %= mod;
                    }
                }
            }
        }
    }
    cout << (ans + mod) % mod << endl;
}

