using namespace std;
typedef long long ll;
typedef bitset<65> bitnum;
const ll mof = 1e9+7;
ll mem[70][2][2];
ll dp(int pos,bitnum& l,bitnum& r,bool isu, bool isd) {
	if(pos < 0)
	{
		return 1;
	}
	if(mem[pos][isu][isd]){
		return mem[pos][isu][isd];
	}
	ll ret = 0;
	// 0 0
	if(!(isd && l[pos]))
	{
		bool nu=isu,nd=isd;
		if(isu && r[pos])
		{
			nu = 0;
		}
		ret += dp(pos-1,l,r,nu,nd);
	}
	// 1 1
	if(!(isu && !r[pos]))
	{
		bool nu=isu,nd=isd;
		if(isd && !l[pos]){
			nd = 0;
		}
		ret += dp(pos-1,l,r,nu,nd);
	}
	// 1 0
	if(!(isu && !r[pos]) && !(isd && l[pos]))
	{
		bool nu = isu,nd = isd;
		ret += dp(pos-1,l,r,nu,nd);
	}
	ret %= mof;
	mem[pos][isu][isd] = ret;
	return ret;
}
ll solve(ll L,ll R) {
	bitnum l,r;
	for(int i=0;i<64;++i)
	{
		if(L>>i & 1)
			l[i] = 1;
		if(R>>i & 1)
			r[i] = 1;
	}
	int high,low;
	for(high = 64;high>=0;--high) {
		if(r[high]) break;
	} 
	for(low = 64;low >=0;--low) {
		if(l[low]) break;
	}
	ll ans = 0;
	for(int b=high;b>=low;--b) {
		ans += dp(b-1,l,r,b==high,b==low);
		ans %= mof;
	}
	return ans;
}
int main() {
	ll L,R;
	cin>>L>>R;
	cout<<solve(L,R)<<endl;
}

