vl pow2, pow3;

ll CutUnder(int LOG, ll n) {
  ll ret = 0;
  int d = 0;
  while (LOG--) {
    if ((n>>LOG) & 1) continue;
    (ret += pow2[d] * pow3[LOG]) %= MOD;
    ++d;
  }
  (ret += pow2[d]) %= MOD;
  return ret;
}

ll CutOver(int LOG, ll n) {
  ll ret = 0;
  int d = 0;
  while (LOG--) {
    if ((n>>LOG) & 1) {
      (ret += pow2[d] * pow3[LOG]) %= MOD;
      ++d;
    }
  }
  (ret += pow2[d]) %= MOD;
  return ret;
}

ll SameRange(int LOG, ll L, ll R) {
  if (L > R) return 0;
  if (L == R) return 1;

  --LOG;

  if (((L>>LOG) & 1) == ((R>>LOG) & 1)) {
    return SameRange(LOG, L, R);
  }

  return (CutUnder(LOG, L) + CutOver(LOG, R) + SameRange(LOG, L+(1LL<<LOG), R)) % MOD;
}

void solve() {
  ll L, R; cin >> L >> R;

  pow2.resize(64);
  pow2[0] = 1;
  rep(i,64) pow2[i+1] = pow2[i] * 2 % MOD;

  pow3.resize(64);
  pow3[0] = 1;
  rep(i,64) pow3[i+1] = pow3[i] * 3 % MOD;

  int l = 64, r = 64;
  while (--l >= 0) if (L>>l) break;
  while (--r >= 0) if (R>>r) break;

  if (l == r) {
    cout << SameRange(l, L, R) << endl;
    return;
  }

  ll ans = (CutUnder(l, L) + CutOver(r, R)) % MOD;
  for (int i=l+1; i<r; ++i) (ans += pow3[i]) %= MOD;
  cout << ans << endl;
}

