long long qiu(long long a,long long b){
	if(a>b)return 0;
	if(a==b)return 1;
	long long c=log2(a);
	long long d=log2(b);
	long long e=1ll<<(d-1);
	if(c!=d)return (qiu(a,2*e-1)+qiu(2*e,b))%mod;
	if(b==4*e-1){
		return (pow3[d-1]+2*qiu(5*e-1-a,2*e-1))%mod;
	}
	if(b<3*e){
		return qiu(a-e,b-e);
	}
	if(a==2*e){
		return (pow3[d-1]+2*qiu(a-e,b-2*e))%mod;
	}
	if(a>=3*e){
		return qiu(a-2*e,b-2*e);
	}
	return (qiu(a,3*e-1)+qiu(3*e,b)+qiu(a,b-3*e))%mod;
}
