lint F(int bit, int xg, int yl, int fs)
{
    if (bit == -1) {
        return fs == 1 ;
    }

    lint& ans = dp[bit][xg][yl][fs];
    if (ans >= 0) {
        return ans;
    }

    int LBit = (L >> bit) & 1, RBit = (R >> bit) & 1;

    ans = 0;
    FOR(yb, 0, 2)
        FOR(xb, 0, 2) {
            if (xg == 0 && xb < LBit)
                continue;
            if (yl == 0 && yb > RBit)
                continue;
            if (xb == 1 && yb == 0)
                continue;
            if (fs == 0 && yb == 1 && xb == 0)
                continue;

            ans = (ans + F(bit - 1, xg | (xb > LBit),
                            yl | (yb < RBit), fs | (yb == 1))) % MOD;
        }

    return ans;
}

