void solve()
{
    ll a, b;
    scanf("%lld%lld", &a, &b);
    int n = 0;
    {
        ll curr = b;
        while (curr) {
            curr /= 2;
            n++;
        }
    }

    dp[0][0][0][0] = 1;
    int i, j, k, l, x0, y0;
    for (i = 0; i < n; i++) {
        int ii = n - 1 - i;
        int tmp1 = ((b & ((ll)1 << ii)) ? 1 : 0);
        int tmp0 = ((a & ((ll)1 << ii)) ? 1 : 0);
        //printf("(%d%d)", tmp0, tmp1);
        for (j = 0; j < 2; j++) {
            for (k = 0; k < 2; k++) {
                for (l = 0; l < 2; l++) {
                    if (dp[i][j][k] == 0) continue;

                    for (y0 = 0; y0 < 2; y0++) {
                        if (k == 0 && y0 > tmp1) continue;

                        for (x0 = 0; x0 <= y0; x0++) {
                            if (j == 0 && x0 < tmp0) continue;
                            if (l == 0 && y0 != x0) continue;

                            int j2 = (((j || x0 > tmp0)) ? 1 : 0);
                            int k2 = ((k || y0 < tmp1) ? 1 : 0);
                            int l2 = ((l || y0 == 1) ? 1 : 0);
                            dp[i + 1][j2][k2][l2] = (dp[i + 1][j2][k2][l2] + dp[i][j][k][l]) % MOD;
                        }
                    }
                }
            }
        }
    }

    ll ans = 0;
    for (j = 0; j < 2; j++) {
        for (k = 0; k < 2; k++) {
            ans = (ans + dp[n][j][k][1]) % MOD;
        }
    }
    printf("%lld\n", ans);
    return;
