					rep(l,2) dp[i+1][1][k][l] += dp[i][1][k][l]; //0,0
				}
				rep(l,2){ //0
					dp[i+1][0][0][l] += dp[i][0][0][l];
				}
			}
		}
	}
	mint ans = 0;
	rep(i,2) rep(j,2) rep(k,2) ans += dp[n][i][j][k];
	cout << ans.value() << "\n";
}

