ll func(int k, int r,int res) {
	int now = 1LL << k;
	if (r <= now) {
		return res;
	}
	int nex = 1LL << (k + 1);
	if (r > nex) {
		return func(k, nex,res);
	}
	if (r == nex) {
		return dp[k];
	}

	int half = now + now / 2;
	if (r - now <= 10) {
		FOR(x, now, r) {
			FOR(y, x, r) {
				if (y%x == y ^ x)res++;
				res %= MOD;
			}
		}
		return res;
	}
	else if (r >= half) {
		res += dp[k - 1];
		res %= MOD;
		return func(k - 1, r - now, res);
	}
	else {
		return func(k - 1, r - now, res) * 2 % MOD;
	}
}
