long long dfs(int x,int limit,int limit2,bool key,int flg) {
	if(~dp[x][limit][limit2][flg]&&key)return dp[x][limit][limit2][flg];
	if(x==0)return 1;
	int res=0,up=limit?num[x]:1,up2=limit2?num[x]:1,down=flg?num2[x]:0;
	if(down==0)res=(res+dfs(x-1,limit&&up==0,limit2&&up2==0,key,flg))%mo;
	if(up2){
		if(key&&!down)res=(res+dfs(x-1,limit&&up==0,limit2,key,flg&&down==0))%mo;
		if(up)res=(res+dfs(x-1,limit,limit2,1,flg&&down))%mo;
	}
	if(key)dp[x][limit][limit2][flg]=res;
	return res;
}
