class factorials
{
    std::vector<mint> fact, finv;

  public:
    factorials()=default;

    void build(int n)
    {
      fact.resize(n), finv.resize(n);
      fact.at(0) = 1;
      for (int i = 1; i < n; i++) fact.at(i) = fact.at(i - 1) * mint(i);
      finv.at(n - 1) = mint(1) / fact.at(n - 1);
      for (int i = n - 2; i >= 0; i--) finv.at(i) = finv.at(i + 1) * mint(i + 1);
    }

    // Factorial.
    auto operator()(int i) const {return fact.at(i);}

    // Inverse of Facgorial.
    auto inv       (int i) const {return finv.at(i);}

    // Binominal Coefficient.
    auto binom(int i, int j) const
    {
      assert(0 <= i);
      if (j < 0 ||i < j) return mint(0);
      return fact.at(i) * finv.at(j) * finv.at(i - j);
    }

    // Deal Apples.
    auto deal(int i, int j) const
    {
      return binom(i + j - 1, j - 1);
    }
};

int main()
{
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  auto fact = factorials{};
  fact.build(60);
  auto factor = [&] (lint x)
  {
    std::vector<int> ret;
    while (x)
    {
      ret.push_back(x % 2);
      x /= 2;
    }
    return ret;
  };
  auto unite = [&] (auto seq)
  {
    lint ret = 0;
    while (!seq.empty())
    {
      ret *= 2;
      ret += seq.back();
      seq.pop_back();
    }
    return ret;
  };
  auto cal_x_cnt = [&] (const auto& seq)
  {
    int   lp = seq.size();
    std::vector<mint> x_cnt(lp, 0);
    if (seq.empty())
    {
      return x_cnt;
    }
    int now = 0;
    for (int i = lp - 2; i >= 0; i--)
    {
      if (seq.at(i) == 0)
      {
        rep(j, 0, i + 1)
        {
          x_cnt.at(now + j) += fact.binom(i, j);
        }
        now++;
      }
    }
    x_cnt.at(now)++;
    return x_cnt;
  };
  auto cal_y_cnt = [&] (const auto& seq)
  {
    int   rp = seq.size();
    std::vector<mint> y_cnt(rp, 0);
    int now = 0;
    for (int i = rp - 2; i >= 0; i--)
    {
      if (seq.at(i) == 1)
      {
        rep(j, 0, i + 1)
        {
          y_cnt.at(now + j) += fact.binom(i, j);
        }
        now++;
      }
    }
    y_cnt.at(now)++;
    return y_cnt;
  };
  lint L, R; std::cin >> L >> R;
  auto l_seq = factor(L);
  auto r_seq = factor(R);
  if (l_seq.size() == r_seq.size())
  {
    while(l_seq.back() == r_seq.back())
    {
      l_seq.pop_back(), r_seq.pop_back();
    }
    assert(l_seq.back() == 0 && r_seq.back() == 1);
    while(!l_seq.empty() && l_seq.back() == 0)
    {
      l_seq.pop_back();
    }
  }
  int lp = l_seq.size();
  int rp = r_seq.size();
  assert(lp < rp);
  auto x_cnt = cal_x_cnt(l_seq);
  auto y_cnt = cal_y_cnt(r_seq);
  mint ret = 0;
  rep(j, 0, lp)
  {
    ret += power(mint(2), j) * x_cnt.at(j);
  }
  rep(j, 0, rp)
  {
    ret += power(mint(2), j) * y_cnt.at(j);
  }
  rep(i, lp + 1, rp)
  {
    ret += power(mint(3), i - 1);
  }
  if (lp == 0)
  {
    ret += unite(r_seq) + 1;
  }
  std::cout << ret << std::endl;
}

