    int x;
    ModInt() : x(0) {}
    ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}
    ModInt &operator+=(const ModInt &p) {
        if((x += p.x) >= mod) x -= mod;
        return *this;
    }
    ModInt &operator-=(const ModInt &p) {
        if((x += mod - p.x) >= mod) x -= mod;
        return *this;
    }
    ModInt &operator*=(const ModInt &p) {
        x = (int) (1LL * x * p.x % mod);
        return *this;
    }
    ModInt &operator/=(const ModInt &p) {
        *this *= p.inverse();
        return *this;
    }
    ModInt operator-() const { return ModInt(-x); }
    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }
    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }
    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }
    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }
    bool operator==(const ModInt &p) const { return x == p.x; }
    bool operator!=(const ModInt &p) const { return x != p.x; }
    ModInt inverse() const {
        int a = x, b = mod, u = 1, v = 0, t;
        while(b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }
    ModInt pow(int64_t n) const {
        ModInt ret(1), mul(x);
        while(n > 0) {
            if(n & 1) ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }
    friend ostream &operator<<(ostream &os, const ModInt &p) {
        return os << p.x;
    }
    friend istream &operator>>(istream &is, ModInt &a) {
        int64_t t;
        is >> t;
        a = ModInt< mod >(t);
        return (is);
    }
    static int get_mod() { return mod; }
};
using modint = ModInt< mod >;

int pl[65];
int pr[65];
modint memo[65][2][2][2];
bool ok[65][2][2][2];

modint f(int pos, bool flagX, bool flagY, bool flagZ) {
    if (pos == -1) return modint(1);
    if (ok[pos][flagX][flagY][flagZ]) return memo[pos][flagX][flagY][flagZ];
    modint ret;
    //x=0, y=0
    if (flagX || pl[pos] == 0) {
        ret += f(pos-1, flagX, (pr[pos] == 1? 1: flagY), flagZ);
    }
    //x=0, y=1
    if ((flagX || pl[pos] == 0) && (flagY || pr[pos] == 1) && flagZ) {
        ret += f(pos-1, flagX, flagY, flagZ);
    }
    //x=1, y=1
    if (flagY || pr[pos] == 1) {
        ret += f(pos-1, (pl[pos] == 0? 1: flagX), flagY, 1); 
    }
    memo[pos][flagX][flagY][flagZ] = ret;
    ok[pos][flagX][flagY][flagZ] = 1;
    return ret;
}

