    if ( x % 2 == 0 ) return (Get(x / 2) * 3) % Mod;
    LL sum = (Get(x / 2) * 3) % Mod, y = -1;
    REP(i, 0, 63) if ( (x >> i) & 1LL ) ++ y; 
    if ( y == -1 ) return sum;
    return (sum + ((1LL << y) % Mod)) % Mod;
