#include <iostream>
using namespace std;
constexpr int MOD = 1e9 + 7;

long L, R;
long dp[66][2][2][2];

// y % x = y ^ x and x <= y
// y % x is less than x. 
// when (y>>1) > x, MSB(y) == MSB(y^x) > x. so this doesnt fulfill the condition.
// then (x<<1) >= y >= x. In this case, y % x == y - x.
//
// On the other hand, xor is addition without carry-up.
// Digit that will carry when y + x and not when y ^ x, can be found by y & x.
// finally y ^ x is y + x - (y & x)<<1
// Requirement : y % x = y ^ x (y>=x) => y - x = y + x - (y & x)<<1 => x == y & x
//

int main() {
	cin >> L >> R;

	dp[0][0][0][0] = 1;

	// l = 1 : x is already more than L
	// r = 1 : y is already less than R
	// j = 1 : MSB of x and y is matched
	//
	// (x, y) = (1, 1), (0, 1), (0, 0) is required on each digit
	bool x[3] = {1, 0, 0}, y[3] = {1, 1, 0};

	for(int i = 0; i < 60; ++i) {
		bool lb = L>>(59-i)&1, rb = R>>(59-i)&1;

		for(int l = 0; l < 2; ++l) {
			for(int r = 0; r < 2; ++r) {
				for(int j = 0; j < 2; ++j) {

					// loop for updating
					for(int k = 0; k < 3; ++k) {
						if(!l && !x[k] && lb) continue;
						if(!r && y[k] && !rb) continue;
						if(!j && x[k] ^ y[k]) continue;

						int nl = (x[k] ^ lb   ? 1 : l);
						int nr = (y[k] ^ rb   ? 1 : r);
						int nj = (x[k] & y[k] ? 1 : j);

						(dp[i+1][nl][nr][nj] += dp[i][l][r][j]) %= MOD;
					}

				}
			}
		}
	}

	long ans = 0;
	for(int l=0;l<2;++l) for(int r=0;r<2;++r) ans = (ans + dp[60][l][r][1]) % MOD;

	cout << ans << '\n';
    return 0;
}

