vector<ll> d2(63, 1), d3(63, 1);

ll f(ll N) {
	if (N == 0)return 0;
	if (N == 1)return 1;

	auto it = upper_bound(all(d2), N);it--;
	ll ans = d3[it - d2.begin()] + 2 * f(N - *it);ans %= MOD;
	return ans;
}

