const int MOD = 1e9 + 7;
const int K = 61;

int dp[K][2][2];

int gb(int i, int j) {
	return (i >> j) & 1;
}

int proc(int lmask, int mn, int mx) {
	mn -= (1LL << lmask);
	mn = max(mn, (int)0);
	mx = min(mx, (1LL << lmask) - 1);
	if (lmask == 0) {
		return mx >= 0 && mn <= 0;
	}
	if (mn >= (1LL << lmask)) {
		return 0;
	}
	for (int i = 0; i < K; i++) {
		for (int f = 0; f < 2; f++) {
			for (int s = 0; s < 2; s++) {
				dp[i][f][s] = 0;
			}
		}
	}
	dp[lmask][0][0] = 1; 
	for (int i = lmask; i > 0; i--) {
		for (int wf = 0; wf < 2; wf++) {
			for (int ws = 0; ws < 2; ws++) {
				if (dp[i][wf][ws] == 0) continue;
				for (int f = 0; f < 2; f++) {
					for (int s = 0; s < 2; s++) {
						if ((f & s) != s) continue;
						if (!wf && f > gb(mx, i - 1)) continue;
						if (!ws && s < gb(mn, i - 1)) continue;
						int nwf = (wf | (f < gb(mx, i - 1)));
						int nws = (ws | (s > gb(mn, i - 1)));
						dp[i - 1][nwf][nws] += dp[i][wf][ws];
						dp[i - 1][nwf][nws] %= MOD;
					}
				}
			}
		}
	}
	int ans = 0;
	for (int f = 0; f < 2; f++) {
		for (int s = 0; s < 2; s++) {
			ans += dp[0][f][s];
			ans %= MOD;
		}
	}
	return ans;
}

