#define MOD   (1000000007LL)

S ll cnts[70];
S ull bit_one[70];
S ull all_one[70];

void prepare()
{
    S ll perms[70];
    S ll perm_invs[70];

    memset(cnts, 0, sizeof(cnts));
    make_perms(perms,  perm_invs, 70, MOD);

    rep (len, 70) {
        rep (onecnt, len+1) {
            ll incr = 1LL;

            // 1s' position in x
            incr *= perms[len]; incr %= MOD;
            incr *= perm_invs[onecnt]; incr %= MOD;
            incr *= perm_invs[len-onecnt]; incr %= MOD;

            // bit patterns in y
            incr *= mod_pow(2LL, len-onecnt, MOD); incr %= MOD;

            cnts[len] += incr;
            cnts[len] %= MOD;
        }
    }

    rep (pos, 70) {
        bit_one[pos] = (1ULL << pos);
        all_one[pos] = (1ULL << pos) - 1ULL;
    }
}

ll solve(ull left, ull right, ull xbits, ull ybits, ll pos)
{
    ll ret = 0LL;

    ull xmin0 = xbits;
    ull xmax0 = (xbits | all_one[pos]);
    ull ymin0 = ybits;
    ull ymax0 = (ybits | all_one[pos]);

    ull xmin1 = (xbits | bit_one[pos]);
    ull xmax1 = (xbits | bit_one[pos] | all_one[pos]);
    ull ymin1 = (ybits | bit_one[pos]);
    ull ymax1 = (ybits | bit_one[pos] | all_one[pos]);

    // xbit == 0, ybit == 0
    if (xmin0 > right || xmax0 < left || ymin0 > right || ymax0 < left) {
        ;
    }
    else if (xmin0 < left || xmax0 > right || ymin0 < left || ymax0 > right) {
        ret += solve(left, right, xbits, ybits, pos - 1);
        // ret %= MOD;
    }
    else {
        ret += cnts[pos];
        // ret %= MOD;
    }

    // xbit == 0, ybit == 1
    if (xmin0 > right || xmax0 < left || ymin1 > right || ymax1 < left) {
        ;
    }
    else if (xmin0 < left || xmax0 > right || ymin1 < left || ymax1 > right) {
        ret += solve(left, right, xbits, ybits | bit_one[pos], pos - 1);
        // ret %= MOD;
    }
    else {
        ret += cnts[pos];
        // ret %= MOD;
    }

    // xbit == 1, ybit == 1
    if (xmin1 > right || xmax1 < left || ymin1 > right || ymax1 < left) {
        ;
    }
    else if (xmin1 < left || xmax1 > right || ymin1 < left || ymax1 > right) {
        ret += solve(left, right, xbits | bit_one[pos], ybits | bit_one[pos], pos - 1);
        // ret %= MOD;
    }
    else {
        ret += cnts[pos];
        // ret %= MOD;
    }

    return ret % MOD;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll left; llin(left);
    ll right; llin(right);

    prepare();

    ll ans = 0LL;

    // (x, y) = (1, 1)
    if (left == 1) ans++;

    srep (pos1, 1, 60) {
        ull bit_one = 1ULL << pos1;
        ull lleft = max((ull)left, bit_one);
        ull lright = min((ull)right, (bit_one - 1ULL) + bit_one);
        ans += solve(lleft, lright, bit_one, bit_one, pos1 - 1);
        ans %= MOD;
    }

    cout << ans << endl;
}

