ll func(int idx, int flag)
{
  if(idx == len) {
    return inv(2);
  }
  if(dp[idx][flag] > -1) {
    return dp[idx][flag];
  }
  ll res = 0;
  if(flag) {
    for(int i = 0; i < 2; i ++) {
      res = add(res, mul(i + 1, func(idx + 1, 1)));
    }
  } else {
    int d = s[idx] - '0';
    res = add(res, mul(d + 1, func(idx + 1, 0)));
    for(int i = 0; i < d; i ++) {
      res = add(res, mul(i + 1, func(idx + 1, 1)));
    }
  }
  return dp[idx][flag] = res;
}

string convert(ll n)
{
  string ans = "";
  while(n > 0) {
    ans += char((n % 2) + '0');
    n /= 2;
  }
  reverse(all(ans));
  return ans;
}

