        // 1 << iを決める

        // flagがfalseな時は等しい


        // 0, 0で遷移
        dp[i][(ma >> i) & 1][1][0] += dp[i + 1][0][1][0];
        dp[i][(ma >> i) & 1][1][1] += dp[i + 1][0][1][1];
        dp[i][1][1][0] += dp[i + 1][1][1][0];
        dp[i][1][1][1] += dp[i + 1][1][1][1];
        // k=miなので、miの該当bitが立ってたら遷移できない
        if(!(mi & (1LL << i))){
            dp[i][(ma >> i) & 1][0][0] += dp[i + 1][0][0][0];
            dp[i][(ma >> i) & 1][0][1] += dp[i + 1][0][0][1];
            dp[i][1][0][0] += dp[i + 1][1][0][0];
            dp[i][1][0][1] += dp[i + 1][1][0][1];
        }

        // 1, 0で遷移
        // MSBが立ってないと遷移できない
        dp[i][1][1][1] += dp[i + 1][1][1][1];
        if(!(mi & (1LL << i)))
            dp[i][1][0][1] += dp[i + 1][1][0][1];
        if(ma & (1LL << i))
            dp[i][0][1][1] += dp[i + 1][0][1][1];
        if(!(mi & (1LL << i)) && (ma & (1LL << i)))
            dp[i][0][0][1] += dp[i + 1][0][0][1];

        // 1, 1で遷移
        dp[i][1][1][1] += dp[i + 1][1][1][0];
        dp[i][1][1][1] += dp[i + 1][1][1][1];
        dp[i][1][!(mi & (1LL << i))][1] += dp[i + 1][1][0][0];
        dp[i][1][!(mi & (1LL << i))][1] += dp[i + 1][1][0][1];
        // j=maなので、maの該当bitが立ってなかったら遷移できない
        if(ma & (1LL << i)){
            dp[i][0][1][1] += dp[i + 1][0][1][0];
            dp[i][0][1][1] += dp[i + 1][0][1][1];
            dp[i][0][!(mi & (1LL << i))][1] += dp[i + 1][0][0][0];
            dp[i][0][!(mi & (1LL << i))][1] += dp[i + 1][0][0][1];
        }
    }
    mint ans = 0;
    for(int i = 0; i < 2; ++i)
        for(int j = 0; j < 2; ++j)
            for(int k = 0; k < 2; ++k)
                ans += dp[0][i][j][k];
    cout << ans << endl;

}

