vector<ll> L;
vector<ll> H;

bool valid(ll pos, ll i, ll j, ll sameH, ll sameL, ll isFirst) {

  if (i < j)
    return false;
  if (sameH && (i > H[pos]))
    return false;
  if (sameL && (j < L[pos]))
    return false;

  if (isFirst) {
    if (i == 1)
      return i == j;
  }
  return true;
}

ll recur(ll posH, ll sameH, ll sameL, ll isFirst);
ll solve(ll pos, ll i, ll j, ll sameH, ll sameL, ll isFirst) {

  ll nsameH;
  if (sameH && i == H[pos])
    nsameH = 1;
  else
    nsameH = 0;

  ll nsameL;
  if (sameL && j == L[pos])
    nsameL = 1;
  else
    nsameL = 0;

  if (i) {
    if (isFirst)
      isFirst = 0;
  }

  return recur(pos + 1, nsameH, nsameL, isFirst);
}
ll n;

ll dp[70][2][2][2];

ll recur(ll posH, ll sameH, ll sameL, ll isFirst) {

  if (posH == n) {
    return 1;
  }
  ll &ans = dp[posH][sameH][sameL][isFirst];
  if (ans != -1)
    return ans;

  ans = 0;
  for (ll i = 0; i < 2; i++) {
    for (ll j = 0; j < 2; j++) {
      if (valid(posH, i, j, sameH, sameL, isFirst)) {
        ans += solve(posH, i, j, sameH, sameL, isFirst);
      }
    }
  }

  ans %= mod;
  return ans;
}

