ll ans;
void g(ll index, ll factor) {
    if(index == 0) return;
    if(1LL << (index - 1) & L) {
        cerr << "minus:" << factor * 2 * beki(3, index-1) << endl;
        ans -= factor * 2 * beki(3, index - 1);
        ans %= mod;
        ans += mod;
        ans %= mod;
        g(index - 1, factor);
        return;
    } else {
        g(index - 1, factor * 2 % mod);
        return;
    }
}

void f(ll index, ll factor) {
    if(index == 0) return;
    //cerr << (1LL << (index-1)) << " " << L << endl;
    if(1LL << (index - 1) & R) {
        f(index - 1, factor * 2 % mod);
