int pow(int n, int k) {//n^k(mod p)
	if (k != 0) {
		if (p % 2 == 0) {
			int x = pow(n, k / 2);
			return (long long)x*x%p;
		}
		else {
			int x = pow(n, k - 1);
			return (long long)x*n%p;
		}
	}
	return 1;
}

int rev(int n) {//nの逆元
	return pow(n, p - 2);
}

int bino(int n, int m) {//nCm(mod p)
	int me = 1;
	int ans = 1;
	for (int i = 0;i < n + m;i++) {
		me = (long long)(i + 1) * ans % p;
		if (i == m - 1) {
			ans = (long long)rev(me) * ans%p;
		}
		if (i == m - n - 1) {
			ans = (long long)(rev(me))*ans%p;
		}
	}
	ans = (long long)(ans*me%p);
	return ans;
}

