    ans+=fm(L);ans++;ans%=MOD;
    cout<<ans<<endl;
    return 0;
  }
  ans-=f(cnt-1);ans+=MOD;ans%=MOD;
  ans+=fm(L);ans+=FM(R);ans%=MOD;
  cout<<ans<<endl;

}

