namespace n91 {
using mint = modint<1000000007>;

using tup = std::tuple<u64, u64, u64>;

std::map<tup, mint> memo;

mint sub(const u64 l, const u64 r, const u64 p) {
  if (r < l) {
    return static_cast<mint>(0);
  }
  if (l == r) {
    return static_cast<mint>(1);
  }
  if (memo.find(tup(l, r, p)) == memo.end()) {
    auto &v = memo[tup(l, r, p)];
    const u64 np = p / static_cast<u64>(2);
    if (r < p) {
      v = sub(l, r, np);
    } else if (p <= l) {
      v = sub(l - p, r - p, np);
    } else {
      v = sub(l, p - static_cast<u64>(1), np) +
          sub(static_cast<u64>(0), r - p, np) + sub(l, r - p, np);
    }
  }
  return memo[tup(l, r, p)];
}

mint solve(const u64 l, const u64 r, const u64 p) {
  if (r < l) {
    return static_cast<mint>(0);
  }
  if (l == r) {
    return static_cast<mint>(1);
  }
  const u64 np = p / static_cast<u64>(2);
  if (r < p) {
    return solve(l, r, np);
  } else if (p <= l) {
    return sub(l - p, r - p, np);
  } else {
    return solve(l, p - static_cast<u64>(1), np) +
           sub(static_cast<u64>(0), r - p, np);
  }
}

