struct comb {
    vector<Num> f;
    explicit comb(int n){
        f.resize(n + 1);
        f[0] = 1;
        up (i, 1, n) f[i] = f[i - 1] * i;
    }
    Num get(int x, int y) const {
        assert(x <= SZ(f) - 1);
        assert(x >= 0 && y >= 0);
        if (x < y) return 0;
        return f[x] / f[y] / f[x - y];
    }
};


