T max_less_or_equal(const vector<T>& v, T x) {
    return *(upper_bound(begin(v), end(v), x) - 1);
}

// xより大きい要素のうち最小のものを返す
template <typename T>
T min_greater(const vector<T>& v, T x) {
    return *upper_bound(begin(v), end(v), x);
}

// x以上の要素のうち最小のものを返す
template <typename T>
T min_greater_or_equal(const vector<T>& v, T x) {
    return *lower_bound(begin(v), end(v), x);
}

constexpr int inf = 1.01e9;
constexpr i64 inf64 = 4.01e18;
constexpr double eps = 1e-9;

void solve() {
    i64 L,R;
    cin >> L >> R;

    constexpr i64 mod = 1'000'000'007;
    static fp<mod> dp[61][2][2][2]; // (i桁目以上が確定している, L<=xが確定しているか, y<=Rが確定しているか, 既にビットを立てた桁があるか)
    dp[60][0][0][0]=1;
    for(i64 i=60; i>0; --i){
        i64 lb=(L>>(i-1))&1;
        i64 rb=(R>>(i-1))&1;
        rep(j,0,2){
            rep(k,0,2){
                rep(l,0,2){
                    rep(x,0,2){
                        rep(y,0,2){
                            i64 ni=i,nj=j,nk=k,nl=l;

                            ni=i-1;

                            if(j==0 and lb==1 and x==0) continue; // X<Lとなってしまう
                            if(x==1 and lb==0) nj=1; // X>Lが確定

                            if(k==0 and rb==0 and y==1) continue; // X>Rとなってしまう
                            if(y==0 and rb==1) nk=1; // X>Rが確定

                            if(x==1 and y==0) continue; // "XがYに含まれる"という条件が満たされなくなってしまう
                            if(l==0 and x==0 and y==1) continue; // "先頭ビットが等しい"という条件が満たされなくなってしまう
                            if(x==1 and y==1) nl=1; // 先頭ビットをすでに立てていることが確定

                            dp[ni][nj][nk][nl]+=dp[i][j][k][l];
                        }
                    }
                }
            }
        }
    }

    fp<mod> ans=0;
    rep(j,0,2) rep(k,0,2) rep(l,0,2) ans+=dp[0][j][k][l];

    cout << ans << endl;
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

