int main(){
	long long L, R; cin >> L >> R; 
	long long MOD = 1000000007; 
	long long ans = 0;
	for(int d = 1; d <= 60; d++){
		long long left = (1LL << (d-1)); long long right = (1LL << d); 
		if(L >= right || R < left) continue; 
		long long dp[62][2][2] = {}; // dp[i桁目][xの以上確定][yの以下確定]
		if(L < left && R >= right) dp[0][1][1] = 1; 
		else if(L < left) dp[0][1][0] = 1; 
		else if(R >= right) dp[0][0][1] = 1; 
		else dp[0][0][0] = 1; 
		for(int t = 1; t < d; t++){
			bool a = (max(L, left) >> (d-1-t)) & 1; 
			bool b = (min(R, right-1) >> (d-1-t)) & 1; 
			if(!a & !b){
				dp[t][0][0] = dp[t-1][0][0]; 
				dp[t][0][1] = dp[t-1][0][1] * 2 % MOD;
				dp[t][1][0] = dp[t-1][1][0]; 
				dp[t][1][1] = (dp[t-1][0][1] + dp[t-1][1][1] * 3) % MOD; 
			}
			else if(!a & b){
				dp[t][0][0] = dp[t-1][0][0]; 
				dp[t][0][1] = (dp[t-1][0][0] + dp[t-1][0][1] * 2) % MOD;
				dp[t][1][0] = (dp[t-1][0][0] + dp[t-1][1][0] * 2) % MOD;
				dp[t][1][1] = (dp[t-1][0][1] + dp[t-1][1][0] + dp[t-1][1][1] * 3) % MOD; 
			}
			else if(a & !b){
				dp[t][0][1] = dp[t-1][0][1];
				dp[t][1][0] = dp[t-1][1][0];
				dp[t][1][1] = dp[t-1][1][1] * 3 % MOD; 
			}
			else if(a & b){
				dp[t][0][0] = dp[t-1][0][0]; 
				dp[t][0][1] = dp[t-1][0][1];
				dp[t][1][0] = dp[t-1][1][0] * 2 % MOD; 
				dp[t][1][1] = (dp[t-1][1][0] + dp[t-1][1][1] * 3) % MOD; 
			}
		}
		long long tmp = dp[d-1][0][0] + dp[d-1][0][1] + dp[d-1][1][0] + dp[d-1][1][1]; 
		ans += tmp; ans %= MOD; 
	}
	cout << ans << endl; 
}

