  for (auto i = 60 - 1; i >= 0; i--)
  {
    int lb = L >> i & 1;
    int rb = R >> i & 1;
    for (auto j = 0; j < 2; j++) // j = 0 : x \geq L が未確定
    {
      for (auto k = 0; k < 2; k++) // k = 0 : k \leq R が未確定
      {
        for (auto s = 0; s < 2; s++)
        {
          mint pre{dp[i + 1][j][k][s]}; // 前の状態
          for (auto x = 0; x < 2; x++)
          {
            for (auto y = 0; y < 2; y++)
            {
              if (x && !y) // x = 1, y = 0 はアウト
              {
                continue;
              }
              int nj{j}, nk{k}, ns{s}; // 次の状態を計算して足しこむ
              if (!s && x != y)
              {
                continue;
              }
              if (x && y)
              {
                ns = 1;
              }
              if (!j && !x && lb)
              {
                continue;
              }
              if (x && !lb)
              {
                nj = 1;
              }
              if (!k && y && !rb)
              {
                continue;
              }
              if (!y && rb)
              {
                nk = 1;
              }
              dp[i][nj][nk][ns] += pre;
            }
          }
        }
      }
    }
  }
  mint ans{0};
