        }else{
            arg4 = is_max_bit;
        }
        ans += calc_ans(bit - 1, arg2, arg3, arg4);
    }
    if(((R >> bit & 1) == 1 || equal_R == 0) && ((L >> bit & 1) == 0 || equal_L == 0) && is_max_bit == 1){
        arg2 = equal_R;
        arg3 = equal_L;
        arg4 = is_max_bit;

        ans += calc_ans(bit - 1, arg2, arg3, arg4);
    }
    if((L >> bit & 1) == 0 || equal_L == 0){
        if(equal_R == 1 && (R >> bit & 1) == 1){
            arg2 = 0;
        }else{
            arg2 = equal_R;
        }
        arg3 = equal_L;
        arg4 = is_max_bit;

        ans += calc_ans(bit - 1, arg2, arg3, arg4);
    }
    ans %= (llint) 1e9 + 7;
    memo[bit][equal_R][equal_L][is_max_bit] = ans;

    return ans;
}

