    for(int i = 0; i < 64; i ++){
        for(int j = 0; j < 2; j ++){
            for(int k = 0; k < 2; k ++){
                for(int l = 0; l < 2; l ++){
                    memo[i][j][k][l] = -1;
                }
            }
        }
