int ta(int l, int r){
    if (l>r) {
        return 0;
    }
    if (l==r) {
        return 1;
    }
    int ans=0;
    itn cnt=0,cnt2=0;
    int k=l;
    while (k) {
        cnt++;
        k>>=1;
    }
    k=r;
    while (k) {
        cnt2++;
        k>>=1;
    }
    if (cnt!=cnt2) {
        RREP(i,cnt+1,cnt2-1){
            int ka=modpow(3, i-1);
            ans+=ka;
            ans%=mod;
        }
        ans+=solve(l, cnt);
        ans%=mod;
        ans+=solve2(r, cnt2);
        ans%=mod;
        return ans;
    }else{
        rev_rep(i,cnt){
            if ((!(l&(1ll<<i)))&&(r&(1ll<<i))) {
                if (!i) {
                    return 3;
                }
                int ll=((1ll<<i)-1ll)&l;
                ans=solve(ll+(1ll<<i), i+1);
                int rr=((1ll<<i)-1ll)&r;
                ans+=solve2(rr+(1ll<<i), i+1);
                ans%=mod;
                ans%=mod;
                ans+=ta(ll+(1ll<<i),rr+(1ll<<i));
                ans%=mod;
                return ans;
            }
        }
        return 1;
    }
    return ans;
}
