int getCountOfPair(bitset<64> l, bitset<64> r){
    int i = 63;
    lint between = 0, right = 1, left = 0;
    while(i >= 0 && !r[i--]);
    left |= l[i + 1];
    for(;i >= 0; i--){
        between = (!left + between * 3 + right * r[i]) % MOD;
        between = (MOD * 2 + between - left * l[i] * 2) % MOD;
        right = (right << r[i]) % MOD;
        if(left) left = (left << (!l[i])) % MOD;
        else left |= l[i];
    }
    return (int)(between + right) % MOD;
}

int cnt(lint l, lint r){
    int k = 0;
    for(int y = l; y <= r; y++)
        for(int x = l; x <= r; x ++)
            if(y % x == (y ^ x))
                k++;
    return k;
}

