mint f (ll digit, ll x, ll y, ll msb) {
    if (digit == -1) return mint(1);
    if (used[digit][x][y][msb]) return dp[digit][x][y][msb];
    mint ret(0);

    ll l = (L >> digit) & 1;
    ll r = (R >> digit) & 1;

    if (x or !l) {
        ret += f(digit-1, x, r?1:y, msb);
    }
    if ((x or !l) and (y or r) and msb) {
        ret += f(digit-1, x, y, msb);
    }
    if (y or r) {
        ret += f(digit-1, l==0?1:x, y, 1);
    }

    dp[digit][x][y][msb] = ret;
    used[digit][x][y][msb] = true;
    return ret;
}

