				(dp[i][j + 1][0] += dp[i - 1][j][0]) %= mod;
				(dp[i][j + 1][1] += dp[i - 1][j][1]) %= mod;
				(dp[i][j][1] += (dp[i - 1][j][0] + dp[i - 1][j][1])) %= mod;
			}
		}else{
			for(j=0;j<dig;j++){
				(dp[i][j][0] += dp[i - 1][j][0]) %= mod;
				(dp[i][j + 1][1] += dp[i - 1][j][1]) %= mod;
				(dp[i][j][1] += dp[i - 1][j][1]) %= mod;
