    ll l, r; cin >> l >> r;
    V< V< V< V<modi> > > > dp(61, V< V< V<modi> > >(2, V< V<modi> > (2, V<modi>(2, 0))));
    // dp[i][j][k][l]: i ビット目でLと同じかそれ以上(j=0: Lと同じ)でRと同じかそれ以下(k=0: Rと同じ)であって
    // MSB が同じになったか(l=1: すでに同じになった)どうか
    dp[60][0][0][0] = 1;
    for (int i = 59; i >= 0; i--) {
        int lbit = (l >> i) & 1, rbit = (r >> i) & 1;
        for (int j = 0; j < 2; j++) {
            for (int k = 0; k < 2; k++) {
                for (int a = 0; a < 2; a++) {
                    for (int x = 0; x < 2; x++) for (int y = 0; y < 2; y++) {
                        if (x == 1 && y == 0) continue;
                        int nj = j, nk = k, na = a;
                        // L より小さい
                        if (j == 0 && x == 0 && lbit == 1) continue;
                        if (x == 1 && lbit == 0) nj = 1; // 大きくなる
                        // R より大きい
                        if (k == 0 && y == 1 && rbit == 0) continue;
                        if (y == 0 && rbit == 1) nk = 1; // 小さくなる
                        if (a == 0 && x != y) continue;
                        if (x == 1 && y == 1) na = 1;
                        dp[i][nj][nk][na] += dp[i + 1][j][k][a];
                    }
                }
            }
        }
    }

    modi ans = 0;
    for (int j = 0; j < 2; j++) {
        for (int k = 0; k < 2; k++) {
            for (int a = 0; a < 2; a++) ans += dp[0][j][k][a];
        }
    }
    cout << ans << '\n';
    return 0;
}

