ll leftval = 0LL;
ll rightval = 0LL;
ll cache[70][2][2][2];
ll mod = (ll)pow(10LL, 9LL) + 7LL;

ll solve(ll pos, int is_x_ge, int is_y_le, int is_msb)
{
    if (pos < 0LL) return 1LL;
    if (cache[pos][is_x_ge][is_y_le][is_msb] >= 0LL) return cache[pos][is_x_ge][is_y_le][is_msb];

    if (!is_msb) {
        if ( (1LL<<(pos+1LL)) - 1LL < leftval) return 0LL;
    }

    ll left_bit = (leftval>>pos) & 1LL;
    ll right_bit = (rightval>>pos) & 1LL;

    ll ret0 = 0LL;
    if (!is_msb && pos) {
        ret0 = solve(pos - 1LL, 0, right_bit | is_y_le, 0);
        if ((1LL<<pos) > rightval) {
            return cache[pos][is_x_ge][is_y_le][is_msb] = ret0;
        }
    }

    // xbit == 0, ybit == 0
    ll ret1 = 0LL;
    if (is_msb && (is_x_ge || !left_bit)) {
        ret1 = solve(pos - 1LL, is_x_ge, is_y_le | right_bit, 1);
    }

    // xbit == 0, ybit == 1
    ll ret2 = 0LL;
    if (is_msb && (is_y_le || right_bit) && (is_x_ge || !left_bit)) {
        ret2 = solve(pos - 1LL, is_x_ge, is_y_le, 1);
    }

    // xbit == 1, ybit == 1
    ll ret3 = 0LL;
    if (is_y_le || right_bit) {
        ret3 = solve(pos - 1LL, is_x_ge | (!left_bit), is_y_le, 1);
    }

    debug_printf("----\nreturn pos=%lld is_x_ge=%d is_y_le=%d is_msb=%d "
                 "left_bit=%lld right_bit=%lld\n",
                 pos, is_x_ge, is_y_le, is_msb, left_bit, right_bit);
    debug_printf("return ret0=%lld ret1=%lld ret2=%lld ret3=%lld\n",
                 ret0, ret1, ret2, ret3);

    cache[pos][is_x_ge][is_y_le][is_msb] = (ret0 + ret1 + ret2 + ret3) % mod;
    return cache[pos][is_x_ge][is_y_le][is_msb];
}

