int nextR (int k, int check, int bit) {
    if ((R >> k) & 1) {
        if (check == 0 && bit == 1) return 0;
        return 1;
    }
    if (check == 1) return 1;
    if (bit == 0) return 0;
    return -1;
}

int nextL (int k, int check, int bit) {
    if ((L >> k) & 1) {
        if (check == 1) return 1;
        if (bit == 1) return 0;
        return -1;
    }
    if (check == 0 && bit == 0) return 0;
    return 1;
}

modint solve() {
    dp[MAX][0][0][0] = modint(1);
    REPR (k, MAX) {
        REP (y, 2) REP (x, 2) {
            int nl, nr;
            REP (m, 2) {
                nl = nextL(k, x, 0), nr = nextR(k, y, 0);
                if (nl >= 0 && nr >= 0) dp[k][nl][nr][m] += dp[k+1][x][y][m];
                nl = nextL(k, x, 1), nr = nextR(k, y, 1);
                if (nl >= 0 && nr >= 0) dp[k][nl][nr][1] += dp[k+1][x][y][m];
            }
            nl = nextL(k, x, 0), nr = nextR(k, y, 1);
            if (nl >= 0 && nr >= 0) dp[k][nl][nr][1] += dp[k+1][x][y][1];
        }
    }

    modint ans;
    REP (a, 2) REP (b, 2)
        ans += dp[0][a][b][1];
    return ans;
}

