    for (int i = 0; i < f.size(); ++i) {
        if (f[i] == '1') {
            if (i == 0) {
                dpf[i] = 1;
            } else {
                dpf[i] = dpf[i - 1];
            }
        } else {
            if (i == 0) {
                dpf[i] = 3;
            } else {
                dpf[i] = (2LL * dpf[i - 1]) % mod;
                dpf[i] += p3[i];
                dpf[i] %= mod;
            }
        }
    }
    for (int i = 0; i < t.size(); ++i) {
        if (t[i] == '0') {
            if (i == 0) {
                dpt[i] = 1;
            } else {
                dpt[i] = dpt[i - 1];
            }
        } else {
            if (i == 0) {
                dpt[i] = 3;
            } else {
                dpt[i] = (2LL * dpt[i - 1]) % mod;
                dpt[i] += p3[i];
                dpt[i] %= mod;
            }
        }
    }

    for (int i = 0; i < f.size(); ++i) {
        if (f[i] == '1' && t[i] == '0') {
            dp[i] = 0;
        }
        if (f[i] == '0' && t[i] == '1') {
            if (i == 0) {
                dp[i] = 3;
            } else {
                dp[i] = (dpt[i - 1] + dpf[i - 1] + dp[i - 1]) % mod;
            }
        }
        if (f[i] == '1' && t[i] == '1') {
            if (i == 0) {
                dp[i] = 1;
            } else {
                dp[i] = dp[i - 1];
            }
        }
        if (f[i] == '0' && t[i] == '0') {
            if (i == 0) {
                dp[i] = 1;
            } else {
                dp[i] = dp[i - 1];
            }
        }
    }
    //cout << "$ " << dp[0] << ' ' << dpt[0] << ' ' << dpf[0] << endl;
    return dp[f.size() - 1];
}

