        unsigned long r = c, p = b;
        while(n){
            if(n & 1)(r *= p) %= MOD;
            (p *= p) %= MOD;
            n >>= 1;
        }
        return r;
    };

    auto f = [&MOD, &L, &R, &modpow](unsigned long l, unsigned long r, unsigned long n) -> unsigned long{
        if(R < l || r < L)return 0;
        if(L <= l && r <= R)return modpow(n);
        auto lower = [&MOD, &R, &modpow](unsigned long n){
            unsigned long ret{0}, c{0};
            for(unsigned long i = n; --i;)if((R - 1) & (1UL << i))ret += modpow(c++, 2, modpow(i));
            return (ret += modpow(c, 2, 1 + 2 * ((R - 1) & 1))) %= MOD;
        };
        auto upper = [&MOD, &L, &modpow](unsigned long n){
            unsigned long ret{0}, c{0};
            for(unsigned long i = n; --i;)if(!(L & (1UL << i)))ret += modpow(c++, 2, modpow(i));
            return (ret += modpow(c, 2, 1 + 2 * (~L & 1))) %= MOD;
        };
        if(l < L){
            if(r > R)return (lower(n) + upper(n) + MOD - modpow(n)) % MOD;
            else return upper(n);
        }else{
            return lower(n);
        }
    };

    unsigned long ans{0};
    for(unsigned long i = 1, j = 2, k = 0; i <= R; ++k){
        (ans += f(i, j, k)) %= MOD;
