	for (int a = lgr ? 0 : s[id] - '0'; a <= (sml ? 1 : t[id] - '0'); ++ a) {
		for (int b = lgr ? 0 : s[id] - '0'; b <= (sml ? 1 : t[id] - '0'); ++ b) {
			if (!fst && b && !a) continue;
			if (a > b) continue;
			res += DP(id + 1, sml | b < t[id] - '0', lgr | a > s[id] - '0', fst | b, smll | a < b);
			if (res >= mod) res -= mod;
		}
	}
//	printf("%d %d %d %d %d = %d\n", id, sml, lgr, fst, smll, res);
	return rem = res;
}

