//////      階乗を全て求める -> 二項係数を求める

long invs[MAX], facts[MAX], finvs[MAX];
long listlen = 0;  // invs, facts, finvsの配列長
void computeAll(long n) {
    if (n >= MAX)
        cerr << "modlong error: index out of range in computeAll" << '\n';
    long i;
    if (listlen == 0) {
        invs[1] = 1;
        facts[0] = 1;
        facts[1] = 1;
        finvs[0] = 1;
        finvs[1] = 1;
        i = 2;
    } else {
        i = listlen;
    }
    if (n < 2) return;
    for (; i <= n; i++) {
        invs[i] = -invs[MOD % i] * (MOD / i) % MOD;
        facts[i] = facts[i - 1] * i % MOD;
        finvs[i] = finvs[i - 1] * invs[i] % MOD;
    }
    listlen = n + 1;  // 次呼び出すときはn+1以降から再開すれば良い
}
// コンビネーション
modlong modComb(long n, long k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    if (listlen <= n) computeAll(n);  // 毎回足りない分だけ補う
    return modlong(facts[n]) * finvs[k] * finvs[n - k];
}
// 階乗
modlong modFact(long n) {
    if (listlen <= n) computeAll(n);  // 毎回足りない分だけ補う
    return modlong(facts[n]);
}

#define update(d, e, f, a, b, c) dp[i][a][b][c] += dp[i+1][d][e][f]

int main() {
    long l, r;
    cin >> l >> r;
    bool lbit[70]={0},
         rbit[70]={0};
    int lcnt=0, rcnt=0;
    for (; l>0; l/=2) {
        lbit[lcnt] = l % 2;
        lcnt++;
    }
    for (; r>0; r/=2) {
        rbit[rcnt] = r % 2;
        rcnt++;
    }

    modlong dp[71][2][2][2] = {{{{0}}}}; // 桁数,先頭bitが出たか,xとl,yとrが剥がれたか
    dp[rcnt][0][0][0] = 1;
    for (int i=69; i>=0; i--) {
        update(1, 1, 1, 1, 1, 1) * 3;
        if (lbit[i]) {
            update(0, 0, 1, 1, 0, 1);
            update(1, 0, 1, 1, 0, 1);
            if (rbit[i]) {
                update(0, 0, 0, 1, 0, 0);
                update(1, 0, 0, 1, 0, 0);
                update(1, 1, 0, 1, 1, 0) * 2;
                update(1, 1, 0, 1, 1, 1);
            } else {
                update(1, 1, 0, 1, 1, 0);
            }
        } else {
            update(0, 0, 1, 0, 0, 1);
            update(0, 0, 1, 1, 1, 1);
            update(1, 0, 1, 1, 0, 1) * 2;
            update(1, 0, 1, 1, 1, 1);
            if (rbit[i]) {
                update(0, 0, 0, 0, 0, 1);
                update(0, 0, 0, 1, 1, 0);
                update(1, 0, 0, 1, 0, 0);
                update(1, 0, 0, 1, 0, 1);
                update(1, 0, 0, 1, 1, 0);
                update(1, 1, 0, 1, 1, 0) * 2;
                update(1, 1, 0, 1, 1, 1);
            } else {
                update(0, 0, 0, 0, 0, 0);
                update(1, 0, 0, 1, 0, 0);
                update(1, 1, 0, 1, 1, 0);
            }
        }
    }
    cout << dp[0][1][0][0] + dp[0][1][0][1] + dp[0][1][1][0] + dp[0][1][1][1] << '\n';
    return 0;
}

