using mint=modint<1000000007>;

void solve() {
    bool lbit[64]={},rbit[64]={};
    int h=0;
    {
        i64 __L=L;
        while(__L) {
            lbit[h]=__L&1;
            __L>>=1;
            ++h;
        }
    }
    int w=0;
    {
        i64 __L=R;
        while(__L) {
            rbit[w]=__L&1;
            __L>>=1;
            ++w;
        }
    }
    --h,--w;

    mint ans=0;

    for(int ii=h; ii<=w; ++ii) { // highest bit of x and y
        mint dp[64][2][2]={};
        dp[ii][ii>h][ii<w]=1;

        for(int i=ii-1; i>=0; --i) {
            auto crt=dp[1+i];
            auto nxt=dp[i];

            nxt[1][1]+=crt[1][1]*3;

            if(lbit[i]) {
                if(rbit[i]) {
                    nxt[0][0]+=crt[0][0];
                    nxt[0][1]+=crt[0][1];
                    nxt[1][0]+=crt[1][0]*2;
                    nxt[1][1]+=crt[1][0];
                } else {
                    nxt[0][1]+=crt[0][1];
                    nxt[1][0]+=crt[1][0];
                }
            } else {
                if(rbit[i]) {
                    nxt[0][0]+=crt[0][0];
                    nxt[0][1]+=crt[0][0];
                    nxt[1][0]+=crt[0][0];
                    nxt[1][0]+=crt[1][0]*2;
                    nxt[1][1]+=crt[1][0];
                    nxt[0][1]+=crt[0][1]*2;
                    nxt[1][1]+=crt[0][1];
                } else {
                    nxt[0][0]+=crt[0][0];
                    nxt[1][0]+=crt[1][0];
                    nxt[0][1]+=crt[0][1]*2;
                    nxt[1][1]+=crt[0][1];
                }
            }
        }

        for(int x=0; x<2; ++x) {
            for(int y=0; y<2; ++y) {
                ans+=dp[0][x][y];
            }
        }
    }

    write(ans);

}

