                            if(x && y)
                                ns = 1;
                            if(!j && !x && lb)
                                continue;
                            if(x && !lb)
                                nj = 1;
                            if(!k && y && !rb)
                                continue;
                            if(!y && rb)
                                nk = 1;

                            dp[i][nj][nk][ns] += pre;
                            dp[i][nj][nk][ns] %= MOD;
                        }
                    }
                }
            }
        }
    }

    Int ans = 0;
    for(int j = 0;j < 2;j++) {
        for(int k = 0;k < 2;k++) {
            for(int s = 0;s < 2;s++) {
                ans += dp[0][j][k][s];
                ans %= MOD;
            }
        }
    }

    cout<<ans<<endl;


    return 0;
}

