        int rb = (R >> i) & 1u;

        for (int more = 0; more < 2; more++) for (int less = 0; less < 2; less++) for (int bit = 0; bit < 2; bit++) {
            mint<MOD> before = dp[i+1][more][less][bit];

            for (int x = 0; x < 2; x++) for (int y = 0; y < 2; y++) {
                if (!y && x) continue;
                int n_more = more, n_less = less, n_bit = bit;

                if (!bit && x != y) continue;
                if (x && y) n_bit = 1;

                if (!more && !x && lb) continue;
                if (x && !lb) n_more = 1;

                if (!less && y && !rb) continue;
                if (!y && rb) n_less = 1;

                dp[i][n_more][n_less][n_bit] += before;
            }
        }
    }

    mint<MOD> ans;
    for (int more = 0; more < 2; more++) for (int less = 0; less < 2; less++) for (int bit = 0; bit < 2; bit++) {
        ans += dp[0][more][less][bit];
    }

