mint calc1(ll x, ll N) {
    vector<mint> dp1(65),dp2(65);
    dp1[0] = 1;
    rep(i,64) {
        if ((x>>(63-i))&1) {
            if ((N>>(63-i))&1) {
                dp1[i+1] = dp1[i];
                dp2[i+1] = dp2[i];
            } else {
                dp2[i+1] = dp2[i];
            }
        } else {
            if ((N>>(63-i))&1) {
                dp1[i+1] = dp1[i];
                dp2[i+1] = dp2[i]*2 + dp1[i];
            } else {
                dp1[i+1] = dp1[i];
                dp2[i+1] = dp2[i]*2;
            }
        }
    }

    return dp1[64] + dp2[64];
}

mint calc2(ll x, ll N) {
    if (N <= 0) return 0;
    vector<mint> dp1(65),dp2(65);
    dp1[0] = 1;
    rep(i,64) {
        if ((x>>(63-i))&1) {
            if ((N>>(63-i))&1) {
                dp1[i+1] = dp1[i];
                dp2[i+1] = dp2[i]*2 + dp1[i];
            } else {
                dp1[i+1] = dp1[i];
                dp2[i+1] = dp2[i]*2;
            }
        } else {
            if ((N>>(63-i))&1) {
                dp2[i+1] = dp2[i] + dp1[i];
            } else {
                dp1[i+1] = dp1[i];
                dp2[i+1] = dp2[i];
            }
        }
    }

    return dp1[64] + dp2[64];
}

mint dfs(ll L, ll R) {
    if (L==R) return 0;
    if (L%2==1) {
        return dfs(L+1,R) + calc1(L,min(R-1,L*2-1));
    } else if (R%2==1) {
        return dfs(L,R-1) + calc2(R-1,R-1) - calc2(R-1,max(L-1,(R-1)/2));
    } else {
        return dfs(L>>1,R>>1)*3;
    }
}

