uint64_t p3[100];
uint64_t mod = 1000000007;

uint64_t solve(uint64_t l, uint64_t r, int b){
  if(l > r) return 0;
  if(l == r) return 1;
  if(l == 0 && r == (1ull << b) - 1){
    return p3[b];
  }
  uint64_t h = 1ull << (b - 1);
  uint64_t ret = 0;
  // 0, 0
  if(l < h){
    ret += solve(l, min(r, h - 1), b - 1);
  }
  // 0, 1
  if(l < h && r >= h){
    ret += solve(l, r - h, b - 1);
  }
  // 1, 1
  if(r >= h){
    ret += solve(max(l, h) - h, r - h, b - 1);
  }
  return ret % mod;
}

