{
    pow2i[0] = 1;
    for(ll i = 1; i < 64; i++){
        pow2i[i] = pow2i[i - 1] * 2;
    }
    ll l, r;
    cin >> l >> r;
    cout << (count(r, r) + MOD - count(l - 1, r)) % MOD << endl;
}

