ll solve(ll left, ll right, ll top)
{
    ll minval = (1LL<<top);
    ll maxval = (1LL<<(top+1LL)) - 1LL;
    minval = max(minval, left);
    maxval = min(maxval, right);

    if (minval > maxval) return 0;

    ll dp[2][2];  // (min, max)
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;
    ll dp_prev[2][2];

    rrep (pos, top) {
        memcpy(dp_prev, dp, sizeof(dp_prev));
        memset(dp, 0, sizeof(dp));

        if (maxval & (1LL<<pos)) {
            if (minval & (1LL<<pos)) {
                dp[0][0] = dp_prev[0][0];
                dp[0][1] = dp_prev[0][1];
                dp[1][0] = dp_prev[1][0] * 2LL;
                dp[1][1] = dp_prev[1][0];
            }
            else {
                dp[0][0] = dp_prev[0][0];
                dp[0][1] = dp_prev[0][0] + dp_prev[0][1] * 2LL;
                dp[1][0] = dp_prev[0][0] + dp_prev[1][0] * 2LL;
                dp[1][1] = dp_prev[0][1] + dp_prev[1][0];
            }
        }
        else {
            if (minval & (1LL<<pos)) {
                dp[0][0] = 0;
                dp[0][1] = dp_prev[0][1];
                dp[1][0] = dp_prev[1][0];
                dp[1][1] = 0;
            }
            else {
                dp[0][0] = dp_prev[0][0];
                dp[0][1] = dp_prev[0][1] * 2LL;
                dp[1][0] = dp_prev[1][0];
                dp[1][1] = dp_prev[0][1];
            }
        }

        dp[1][1] += dp_prev[1][1] * 3LL;

        dp[0][0] %= MOD;
        dp[0][1] %= MOD;
        dp[1][0] %= MOD;
        dp[1][1] %= MOD;
    }

    ll ret = 0;
    rep (i, 2) rep (j, 2) ret += dp[i][j];
    return ret % MOD;
}

void _main()
{
    ll left; llin(left);
    ll right; llin(right);

    ll ans = 0;
    rep (top, 63) {
        ans += solve(left, right, top);
        ans %= MOD;
    }

    debug_printf("----------- ans\n");
    cout << ans << endl;
}

