int main(){
  ll L,R,ans=0;
  cin>>L>>R;

  ll LL=L,RR=R,LC=0,RC=0,LS[61],RS[61];
  REP(i,61){
    LS[i]=0;
    RS[i]=0;
  }
  while(LL>0){
    LS[LC]=LL%2;
    LL/=2;
    LC++;
  }
  while(RR>0){
    RS[RC]=RR%2;
    RR/=2;
    RC++;
  }

  for(int i=LC+1; i<RC; ++i){
    ans+=power(3,i-1);
    ans%=MOD;
  }

  if(LC==RC){
    ll DP[RC][4]; // 0全て確定 1L以上確定 2R以下確定 3未確定
    REP(j,4){
      REP(i,RC) DP[i][j]=0;
    }
    DP[RC-1][3]=1;

    for(int i=RC-2; i>=0; --i){
      DP[i][0]+=DP[i+1][0]*3;
      DP[i][1]+=DP[i+1][1];
      DP[i][2]+=DP[i+1][2];
      DP[i][3]+=DP[i+1][3];

      if(LS[i]==1 && RS[i]==1){
        DP[i][0]+=DP[i+1][1];
        DP[i][1]+=0;
        DP[i][2]+=0;
        DP[i][3]+=0;
      }
      if(LS[i]==0 && RS[i]==1){
        DP[i][0]+=DP[i+1][1]+DP[i+1][2];
        DP[i][1]+=DP[i+1][3];
        DP[i][2]+=DP[i+1][3];
        DP[i][3]+=0;
      }
      if(LS[i]==1 && RS[i]==0){
        DP[i][0]+=0;
        DP[i][1]+=0;
        DP[i][2]+=0;
        DP[i][3]+=0;
      }
      if(LS[i]==0 && RS[i]==0){
        DP[i][0]+=DP[i+1][2];
        DP[i][1]+=0;
        DP[i][2]+=0;
        DP[i][3]+=0;
      }

      DP[i][0]%=MOD;
      DP[i][1]%=MOD;
      DP[i][2]%=MOD;
      DP[i][3]%=MOD;
    }

    ans+=DP[0][0]+DP[0][1]+DP[0][2]+DP[0][3];
    ans%=MOD;
  }
  else{
    ll DPR[RC][2],DPL[LC][2]; // 0確定 1未確定
    REP(j,2){
      REP(i,RC) DPR[i][j]=0;
      REP(i,LC) DPL[i][j]=0;
    }
    DPR[RC-1][1]=1;
    DPL[LC-1][1]=1;

    for(int i=RC-2; i>=0; --i){
      DPR[i][0]+=DPR[i+1][0]*3;
      DPR[i][1]+=DPR[i+1][1];
      if(RS[i]==1){
        DPR[i][0]+=DPR[i+1][1];
        DPR[i][1]+=DPR[i+1][1];
      }
      DPR[i][0]%=MOD;
      DPR[i][1]%=MOD;
    }

    for(int i=LC-2; i>=0; --i){
      DPL[i][0]+=DPL[i+1][0]*3;
      DPL[i][1]+=DPL[i+1][1];
      if(LS[i]==0){
        DPL[i][0]+=DPL[i+1][1];
        DPL[i][1]+=DPL[i+1][1];
      }
      DPL[i][0]%=MOD;
      DPL[i][1]%=MOD;
    }

    ans+=DPR[0][0]+DPR[0][1];
    ans+=DPL[0][0]+DPL[0][1];
    ans%=MOD;
  }

  co(ans);
  return 0;
}

