ll kai_mod(ll x){
  if(x == 0) return 1;
  return x * kai_mod(x-1) % MOD;
}


//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll tmpL, tmpR;
void solve(){
  vector<ll> L(64, 0), R(64, 0);
  rep(i, 64){
    L[i] = (tmpL>>(63-i)) & 1;
    R[i] = (tmpR>>(63-i)) & 1;
  }

  ll dp[65][2][2][2];//L < x, y < R, 最上位が確定
  rep(i, 65)rep(j, 2)rep(k, 2)rep(l, 2) dp[i][j][k][l] = 0;
  dp[0][0][0][0] = 1;
  for(ll i = 1; i <= 64; i++){
    if(L[i-1] == 1 && R[i-1] == 1){
      dp[i][1][1][1] = dp[i-1][1][0][1] + 3 * dp[i-1][1][1][1];
      dp[i][1][0][1] = 2 * dp[i-1][1][0][1];
      dp[i][0][1][1] = dp[i-1][0][1][1] + dp[i-1][0][1][0];
      dp[i][0][0][1] = dp[i-1][0][0][0] + dp[i-1][0][0][1];
    }else if(L[i-1] == 1 && R[i-1] == 0){
      dp[i][1][1][1] = 3 * dp[i-1][1][1][1];
      dp[i][1][0][1] = dp[i-1][1][0][1];
      dp[i][0][1][1] = dp[i-1][0][1][1] + dp[i-1][0][1][0];
    }else if(L[i-1] == 0 && R[i-1] == 1){
      dp[i][1][1][1] = dp[i-1][0][1][1] + dp[i-1][1][0][1] + 3 * dp[i-1][1][1][1] + dp[i-1][0][1][0];
      dp[i][1][0][1] = dp[i-1][0][0][1] + 2 * dp[i-1][1][0][1] + dp[i-1][0][0][0];
      dp[i][0][1][1] = dp[i-1][0][0][1] + 2 * dp[i-1][0][1][1];
      dp[i][0][0][1] = dp[i-1][0][0][1];
      dp[i][0][1][0] = dp[i-1][0][0][0] + dp[i-1][0][1][0];
    }else{
      dp[i][1][1][1] = dp[i-1][0][1][1] + 3 * dp[i-1][1][1][1] + dp[i-1][0][1][0];
      dp[i][1][0][1] = dp[i-1][1][0][1];
      dp[i][0][1][1] = 2 * dp[i-1][0][1][1];
      dp[i][0][0][1] = dp[i-1][0][0][1];
      dp[i][0][1][0] = dp[i-1][0][1][0];
      dp[i][0][0][0] = dp[i-1][0][0][0];
    }
    rep(j, 2)rep(k, 2)rep(l, 2) dp[i][j][k][l] %= MOD;
  }
  ll res = 0;
  rep(i, 2)rep(j, 2)rep(k, 2) res = (res + dp[64][i][j][k]) % MOD;
  cout << res << endl;
}



