const long long MOD = 1000000007;
ll modpow(ll a,long long b){
  ll base=a,ans=1LL;
  while(b){
    if(b&1){
      ans=ans*base%MOD;
    }
    base=base*base%MOD;
    b>>=1;
  }
  return ans;
}
#define LSB(a) (a&-a)
void solve(long long L, long long R){
  ll ans=0;
  if(__builtin_clzll(L)==__builtin_clzll(R)){
    while(L!=0&&__builtin_clzll(L)==__builtin_clzll(R)){
      L&=(1<<(63-__builtin_clzll(L)))-1;
      R&=(1<<(63-__builtin_clzll(R)))-1;
      dump(L);
      dump(R);
    }
  }
  if(L==0){
    ans=(R+1)%MOD;
    ++L;
  }
  ll l=1,r=1;
  ll lc=0,rc=0;
  while(l<L){
    l*=2;
    ++lc;
  }
  ll cpyl=l;
  for(;L<=l&&l*2-1<=R;l*=2){
    ll r=ans;
    ll lc=__builtin_ctzll(l);
    ans+=modpow(3LL,lc);
    dump(ans-r);
    ans%=MOD;
  }
  while(L<cpyl){
    ll s=ans;
    ans+=modpow(3LL,__builtin_ctzll(L))*modpow(2LL,64-__builtin_clzll(L)-__builtin_ctzll(L)-__builtin_popcountll(L))%MOD;
    ans%=MOD;
    dump(ans-s);
    L+=LSB(L);
  }
  while(l<=R){
    ll tmp=0;
    while((1LL<<tmp)&R){
      ++tmp;
    }
    ll t=ans;
    ans+=modpow(3LL,tmp)*modpow(2LL,__builtin_popcountll(R)-1-tmp)%MOD;
    ans%=MOD;
    dump(ans-t);
    R-=(1LL<<tmp);
  }
  cout<<ans%MOD<<endl;
}

int main(){
    long long L;
    scanf("%lld",&L);
    long long R;
    scanf("%lld",&R);
    solve(L, R);
