				dp[i][j] = 0;

		if(fst == bitr && fst == bitl)
			dp[fst][3] = 1;
		else if (fst == bitr) {
			dp[fst][1] = 1;
		}
		else if (fst == bitl) {
			dp[fst][2] = 1;
		}
		else {
			dp[fst][0] = 1;
		}

		for (ll bit = fst - 1; bit >= 0; bit--) {
			ll kek = 1LL << bit;
			dp[bit][0] += dp[bit + 1][0] * 3;
			bool f = false;
			if ((kek & l) && (kek & r)) {
				dp[bit][1] += dp[bit + 1][1] * 2; dp[bit][0] += dp[bit + 1][1];
				dp[bit][2] += dp[bit + 1][2];
			}
			else if (kek & r) {
				dp[bit][1] += dp[bit + 1][1] * 2; dp[bit][0] += dp[bit + 1][1];
				dp[bit][2] += dp[bit + 1][2] * 2; dp[bit][0] += dp[bit + 1][2];
				dp[bit][2] += dp[bit + 1][3]; dp[bit][1] += dp[bit + 1][3];
			}
			else if (kek & l) {
				f = true;
				dp[bit][1] += dp[bit + 1][1];
				dp[bit][2] += dp[bit + 1][2];
			}
			else {
				dp[bit][1] += dp[bit + 1][1];
				dp[bit][2] += dp[bit + 1][2] * 2; dp[bit][0] += dp[bit + 1][2];
			}
			if (f) dp[bit][3] = 0;
			else {
				dp[bit][3] = dp[bit + 1][3];
			}
			for (ll i = 0; i < 4; i++) dp[bit][i] %= mod;
		}
		ans += (dp[0][0] + dp[0][1] + dp[0][2] + dp[0][3]) % mod;
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}
