    }else{
        if(!b) return s;
        return 2-s;
    }
}

int64_t calc(int64_t X, int64_t Y){
    int64_t dp[62][3][3][3] = {0};
    dp[61][0][0][0] = 1;
    for(int d=60; d>=0; d--) for(int a=0; a<2; a++) for(int b=0; b<2; b++) for(int c=0; c<2; c++){
        vector<pair<int, int>> cand = {{1, 1}, {0, 1}, {0, 0}};
        for(auto& p : cand){
            int x = p.first, y = p.second;
            if(c == 0 && x+y == 1) continue;
            add(dp[d][rc(nth_bit(X, d), a, x)][rc(nth_bit(Y, d), b, y)][c|(x+y==2)], dp[d+1][a][b][c]);
