ll dp[100][100][2] = {},mod = 1000000007;
ll pw(ll a, ll x){
	ll res = 1;
	while(x){
		while(!(x&1)){
			(a *= a) %= mod;
			x /= 2;
		}
		(res *= a) %= mod;
		x--;
	}
	return res;
}

ll solve(ll x){
	int i,j,k,dig = 0;
	ll t = x;
	vector<ll> v,w;
	while(t){
		v.push_back(t&1);
		t /= 2;
		dig++;
	}
	for(i=0;i<v.size();i++){
		w.push_back(v[(v.size() - i - 1)]);
	}
	for(i=0;i<100;i++){
		for(j=0;j<100;j++){
			for(k=0;k<2;k++){
				dp[i][j][k] = 0;
			}
		}
	}
	dp[0][1][0] = 1;
	for(i=1;i<dig;i++){
		dp[i][1][1]++;
		if(w[i]==1){
			for(j=0;j<=dig;j++){
				(dp[i][j + 1][0] += dp[i - 1][j][0]) %= mod;
				(dp[i][j + 1][1] += dp[i - 1][j][1]) %= mod;
				(dp[i][j][1] += (dp[i - 1][j][0] + dp[i - 1][j][1])) %= mod;
			}
		}else{
			for(j=0;j<dig;j++){
				(dp[i][j][0] += dp[i - 1][j][0]) %= mod;
				(dp[i][j + 1][1] += dp[i - 1][j][1]) %= mod;
				(dp[i][j][1] += dp[i - 1][j][1]) %= mod;
			}
		}
	}
	ll ret = 0;
	for(i=1;i<=dig;i++){
		(ret += (dp[dig - 1][i][0] + dp[dig - 1][i][1])*pw(2,i - 1)%mod) %= mod;
	}
	return ret;
}

