auto dfs(bool f1, bool f2, bool f3, int k)
{
  if (k == -1) return mint(1);
  auto& ret = dp[f1][f2][f3][k];
  if (ckd[f1][f2][f3][k]) return ret;
  auto l = (L >> k) & 1;
  auto r = (R >> k) & 1;
  rep(p, 0, 2) rep(q, p, 2)
  {
    if (!f1 && (p < l)) continue;
    if (!f2 && (r < q)) continue;
    if (!f3 && (p < q)) continue;
    ret += dfs
    (
      f1 || l < p,
      f2 || q < r,
      f3 || p || q,
      k - 1
    );
  }
  ckd[f1][f2][f3][k] = true;
  return ret;
}

