ll A(ll n){
    if(n == 0) return 0;
    ll d = 1;
    ll deg = 1;
    while(d <= n){
        d *= 2;
        deg++;
    }
    d /= 2;
    deg--;
    ll col = n - d + 1;
    // cout << deg << " " << col << " "  << sier(deg, col) << endl;
    ll ret = 0;
    ret += sier(deg, col);
    ll tri = 1;
    for(int i = 1; i < deg; i++){
        ret += tri;
        tri *= 3;
        ret %= MOD;
        tri %= MOD;
    }
    return ret;
}

ll B(ll n){
    if(n == 0) return 0;
    ll d = 1;
    ll deg = 1;
    while(d <= n){
        d *= 2;
        deg++;
    }
    d /= 2;
    deg--;
    ll col = n - d + 1;
    // cout << deg << " " << col << " "  << sier(deg, col) << endl;
    ll ret = 0;
    ret += sier(deg, (1 << (deg - 1))) - sier(deg, (1 << (deg - 1)) - col);
    ll tri = 1;
    for(int i = 1; i < deg; i++){
        ret += tri;
        tri *= 3;
        ret %= MOD;
        tri %= MOD;
    }
    return ret;
}

ll sier(ll deg, ll col){
    if(deg == 1) return col;
    ll ret = 0;
    ret = sier(deg - 1, col / 2) * 3;
    ret %= MOD;
    if(col % 2 == 1){
        ret += pow(2, popcnt(pow(2, deg) - 1 + col) - 1);
    }
    return ret;
}

ll popcnt(ll x){
    ll ret = 0;
    while(x > 0){
        if(x % 2 == 1) ret++;
        x /= 2;
    }
    return ret;
}

