// l = 0, r = x 的情形。
// 高于 y 的位上都是0
int calc(ll x, int y) {
    int ans = 0;
    int prod = 1;
    down (i, y, 0) {
        if (x & 1ULL << i) {
            ans += prod * p[i] % mod;
            ans %= mod;
            prod *= 2;
            prod %= mod;
        }
    }
    return (ans + prod) % mod;
}

map<pair<ll,ll>,ll> mem;

ll solve(ll l, ll r, int i) {
    // (x, y) x >= l && y <= r && x <= y && (y ^ x) == y - x
    if (l == r) return 1;
    if (l == 0) return calc(r, i);
    // l < r
    // 1,1

    if (l & 1ULL << i) {
        return solve(l - (1ULL << i), r - (1ULL << i), i - 1);
    }
    // 0,0
    if ((r & 1ULL << i) == 0) { // 亦可写成 if (r < (1 << i))
        return solve(l, r, i - 1);
    }
    auto iter = mem.find({l, r});
    if (iter != mem.end()) {
        return iter -> second;
    }
    // 1,0
    ll mask = (1ULL << i) - 1;
    ll res = 0;
    if (l <= (r & mask))
        res += solve(l, r & mask, i - 1);
    res += solve(l, mask, i - 1);
    res += solve(0, r & mask, i - 1);
    res %= mod;
    mem[{l, r}] = res;
    return res;
}

