map<tuple<ll,ll,ll,ll,bool>,mint> memo;
mint solve(ll LX,ll RX,ll LY,ll RY,bool same){
	if(LX > RX || LY > RY) return 0;
	if(LX+LY+RX+RY == 0) return same ? 1 : 0;
	tuple<ll,ll,ll,ll,bool> t(LX,RX,LY,RY,same);
	if(memo.count(t)) return memo[t];
	mint res = 0;
	rep(x,2) rep(y,x+1){
		bool nsame = same;
		if(x != y) nsame = false;
		if(x==1 && y==1) nsame = true;
		res += solve((LX-x+1)/2,(RX-x+2)/2-1,(LY-y+1)/2,(RY-y+2)/2-1,nsame);
	}
	return memo[t] = res;
}

