  for(char p:s)cnt+=(p=='0');
  res=pw(2,cnt);
  reverse(s.begin(),s.end());
  for(char p:s){
    if(p=='1')res+=pw(3,now)*pw(2,cnt+1)%MOD;
    else cnt--;
    now++;res%=MOD;
  }
  return res;
}
int FM2(string t){//y>=r
  int cnt=0,res=0,now=0;
  for(auto p:t)cnt+=(p=='1');
  reverse(t.begin(),t.end());
  res=pw(2,cnt);
  for(char p:t){
    if(p=='0')res+=pw(2,cnt+1)*pw(3,now)%MOD;
    else cnt--;
    now++;res%=MOD;
  }
  return res;
}
int super(int l,int r){
  string s,t;
  while(l){
    if(l&1)s+="1";
    else s+="0";
    l>>=1;
  }
  while(r){
    if(r&1)t+="1";
    else t+="0";
    r>>=1;
  }
  reverse(s.begin(),s.end());reverse(t.begin(),t.end());
  //cout<<s<<" "<<t<<endl;
  int N=s.size(),res=0;
  for(int i=1;i<N;i++){
    if(s[i]=='1'){
      if(t[i]=='1'){
        res+=FM2(t.substr(i+1,N-i-1));//sを0にした
      }
      else{
        res+=FM2(t.substr(i+1,N-i-1));//sを0にしてtはそのまま
        //cout<<res<<endl;
        res+=pw(3,N-i-1);//sを0にしてtを1にした
        //cout<<res<<endl;
        res+=fm2(s.substr(i+1,N-i-1));//sはそのままtを1にした
        res%=MOD;return res;//どれかを必ず行う
      }
    }
    else{
      if(t[i]=='1'){
        ;
      }
      else{
        res+=fm2(s.substr(i+1,N-i-1));//tを1にした
      }
    }
    res%=MOD;//cout<<res<<endl;
  }
  bool f=true;
  for(int i=0;i<N;i++)if(s[i]=='1'&&t[i]=='0')f=false;
  if(f)res++;
  return res;
}
//main
signed main(){
  int L,R,i;cin>>L>>R;if(L==R){cout<<1<<endl;return 0;}
  int ans=0,cnt=1;
  for(i=1;i<R;i*=2,cnt++){
    if(i>L)ans+=f(cnt);
    ans%=MOD;
  }
  if(i==R){
    ans+=fm(L);ans++;ans%=MOD;
    cout<<ans<<endl;
    return 0;
