  //cout<<ans<<endl;
  if(ans==0){
    bool f=true;
    for(int k=1;k<=L;k*=2)if(k==L)f=false;
    if(f)ans+=super(L-1,R+1);
  }
  //cout<<"NOW:"<<ans<<endl;
  ans-=f(cnt-1);ans+=MOD;ans%=MOD;
  ans+=fm(L);ans+=FM(R);ans%=MOD;
