long long powMod(long long x, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

ll count2(ll L, ll S, int loose, int d) {
    // 残り d 桁
    if (d == 0) return 1;
    if (loose == 0) {
        // どちらも張り付いている
        // L で次に 1 が出てくる場所を調べる
        int next = -1;
        reprev(i, d) {
            if ((L & (1LL << i)) != 0) {
                next = i;
                break;
            }
        }
        if (next == -1) {
            // L の残りは 0 のみ
            return 1;
        }
        if ((S & (1LL << next)) != 0) {
            // S でも 1 が立っている
            ll a = count2(L, S, 0, next);
            ll b = count2(L, S, 3, next);
            ll c = count2(L, S, 2, next);
            ll ret = a + b + c;
            ret %= MOD;
            return ret;
        } else {
            // L だけ 1
            ll ret = count2(L, S, 0, next) + count2(L, S, 1, next);
            ret %= MOD;
            return ret;
        }
    } else if (loose == 1) {
        // S だけ張り付いている
        // 次に S に 1 が出てくる場所を調べる
        int next = -1;
        reprev(i, d) {
            if ((S & (1LL << i)) != 0) {
                next = i;
                break;
            }
        }
        if (next == -1) {
            // S は残り 0 のみ
            return powMod(2, d, MOD);
        } else {
            // next 桁が 1
            ll ret = powMod(2, d - next - 1, MOD) * count2(L, S, 1, next) % MOD;
            ret += powMod(2, d - next, MOD) * powMod(3, next, MOD) % MOD;
            ret %= MOD;
            return ret;
        }

    } else if (loose == 2) {
        // どちらも緩んでいる
        return powMod(3, d, MOD);
    } else {
        // L だけ張り付いている
        // L で次に 1 が出てくる場所を調べる
        int next = -1;
        reprev(i, d) {
            if ((L & (1LL << i)) != 0) {
                next = i;
                break;
            }
        }
        if (next == -1) {
            // L の残りは 0 のみ
            return 1;
        }
        ll a = 2 * count2(L, S, 3, next);
        ll b = powMod(3, next, MOD);
        ll ret = a + b;
        ret %= MOD;
        return ret;
    }
}

ll count(ll L, ll S) {
    ll ans = 0;
    int loose = 0;
    reprev(i, 63) {
        if (loose == 0 && (L >> 1) >= (1LL << i)) loose = 1;
        if (loose == 1 && (S >> 1) >= (1LL << i)) loose = 2;
        if (S < (1LL << i)) continue;

        ans += count2(L, S, loose, i);
        ans %= MOD;
    }
    return ans;
}

