ll f(int d, int msb, int lt, int rt) {
  if(d == -1) return msb == 1;
  if(dp[msb][lt][rt][d] >= 0) return dp[msb][lt][rt][d];

  ll ret = 0;

  for(int a=0;a<2;++a) {
    for(int b=0;b<2;++b) {
      if(a == 0 && lt && (l & (1ll<<d)) > 0) continue;
      if(b == 1 && rt && (r & (1ll<<d)) == 0) continue;
