      if(msb == 0 && a != b) continue;
      int nlt = lt && (((l>>d)&1)==a);
      int nrt = rt && (((r>>d)&1)==b);
      int nmsb = msb || (a == 1 && b == 1);
      ret += f(d-1, nmsb, nlt, nrt);
    }
  }

  return dp[msb][lt][rt][d] = ret % MOD;

}

