#define MOD   (1000000007LL)

S ll cnts[70];

void prepare()
{
    S ll perms[70];
    S ll perm_invs[70];

    memset(cnts, 0, sizeof(cnts));
    make_perms(perms,  perm_invs, 70, MOD);

    rep (len, 70) {
        rep (onecnt, len+1) {
            ll incr = 1LL;

            // 1s' position in x
            incr *= perms[len]; incr %= MOD;
            incr *= perm_invs[onecnt]; incr %= MOD;
            incr *= perm_invs[len-onecnt]; incr %= MOD;

            // bit patterns in y
            incr *= mod_pow(2LL, len-onecnt, MOD); incr %= MOD;

            cnts[len] += incr;
            cnts[len] %= MOD;
        }
    }
}

ll solve(ull left, ull right, ull xbits, ull ybits, ll pos)
{
    ull bit_one = (1ULL<<pos);
    ull all_one = (1ULL<<pos) - 1ULL;
    ll ret = 0LL;

    // xbit == 0, ybit == 0
    ull xmin1 = xbits;
    ull xmax1 = (xbits | all_one);
    ull ymin1 = ybits;
    ull ymax1 = (ybits | all_one);

    if (xmin1 > right || xmax1 < left || ymin1 > right || ymax1 < left) {
        ;
    }
    else if (xmin1 < left || xmax1 > right || ymin1 < left || ymax1 > right) {
        ret += solve(left, right, xbits, ybits, pos - 1);
        ret %= MOD;
    }
    else {
        ret += cnts[pos];
        ret %= MOD;
    }

    // xbit == 0, ybit == 1
    ull xmin2 = xbits;
    ull xmax2 = (xbits | all_one);
    ull ymin2 = (ybits | bit_one);
    ull ymax2 = (ybits | bit_one | all_one);

    if (xmin2 > right || xmax2 < left || ymin2 > right || ymax2 < left) {
        ;
    }
    else if (xmin2 < left || xmax2 > right || ymin2 < left || ymax2 > right) {
        ret += solve(left, right, xbits, ybits | bit_one, pos - 1);
        ret %= MOD;
    }
    else {
        ret += cnts[pos];
        ret %= MOD;
    }

    // xbit == 1, ybit == 1
    ull xmin3 = (xbits | bit_one);
    ull xmax3 = (xbits | bit_one | all_one);
    ull ymin3 = (ybits | bit_one);
    ull ymax3 = (ybits | bit_one | all_one);

    if (xmin3 > right || xmax3 < left || ymin3 > right || ymax3 < left) {
        ;
    }
    else if (xmin3 < left || xmax3 > right || ymin3 < left || ymax3 > right) {
        ret += solve(left, right, xbits | bit_one, ybits | bit_one, pos - 1);
        ret %= MOD;
    }
    else {
        ret += cnts[pos];
        ret %= MOD;
    }

    debug_printf("xbits=%lld ybits=%lld pos=%lld --> ret=%lld\n",
                 xbits, ybits, pos, ret);

    return ret;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll left; llin(left);
    ll right; llin(right);

    prepare();

    ll ans = 0LL;

    // (x, y) = (1, 1)
    if (left == 1) ans++;

    srep (pos1, 1, 63) {
        ull bit_one = 1ULL << pos1;
        ull lleft = max((ull)left, bit_one);
        ull lright = min((ull)right, (bit_one - 1ULL) + bit_one);
        ans += solve(lleft, lright, bit_one, bit_one, pos1 - 1);
        ans %= MOD;
    }

    cout << ans << endl;
}

