        _LL minbit = (((lmin & (1LL << b)) != 0) ? 1 : 0);
        _LL maxbit = (((lmax & (1LL << b)) != 0) ? 1 : 0);
        if( minbit == 1 && maxbit == 1 ) 
        {
            next[0] = current[0];
            next[1] = current[1];
            next[2] = current[2] * 2;
            next[3] = current[2] + current[3] * 3;
        }
        if( minbit == 0 && maxbit == 1 ) 
        {
            next[0] = current[0];
            next[1] = current[0] + current[1] * 2;
            next[2] = current[0] + current[2] * 2;
            next[3] = current[1] + current[2] + current[3] * 3;
        }
        if( minbit == 1 && maxbit == 0 ) 
        {
            next[0] = 0;
            next[1] = current[1];
            next[2] = current[2];
            next[3] = current[3] * 3;
        }
        if( minbit == 0 && maxbit == 0 )
        {
            next[0] = current[0];
            next[1] = current[1] * 2;
            next[2] = current[2];
            next[3] = current[1] + current[3] * 3;
        }
        swap(current, next);
    }
    ModInt ret = 0;
    rep(j, 4) ret += current[j];
    return ret;
}

