ll dp[65][2][2][2];

ll f(int i, bool bot, bool top, bool first) {
    if (i<0) return 1;
    ll &res = dp[i][bot][top][first];
    if (~res) return res;

    res = 0;
    for (int xb=0; xb<=1; xb++) {
	for (int yb=0; yb<=1; yb++) {

	    if (xb>yb) continue;
