ll countmax[64][64]={};
ll countNmax[64][64]={};
ll calc(ll x){
	FOR(i,0,64)FOR(j,0,64){
		countmax[i][j]=0;
		countNmax[i][j]=0;
	}
	string s;
	while(x){
		s = (x&1?"1":"0")+s;
		x /= 2;
	}
	ll ls = s.size();
	countmax[0][1] = 1;
	countNmax[0][0] = 1;
	FOR(i,1,ls){
		FOR(j,1,64){
			countmax[i][j] = countmax[i-1][j-(s[i]=='1')];
		}
		FOR(j,0,64){
			if(j){
				countNmax[i][j] = (countNmax[i-1][j]+countNmax[i-1][j-1])%MOD;
			}else{
				countNmax[i][j] = (countNmax[i-1][j])%MOD;
			}
		}
		if(s[i] == '1'){
			FOR(j,1,64){
				(countNmax[i][j] += countmax[i-1][j])%=MOD;
			}
		}
	}

	FOR(i,0,64){
		countNmax[ls-1][i] += countmax[ls-1][i];
	}

	ll res=0,t=1;
	FOR(i,1,ls){
		ll n = countNmax[ls-1][i];
		res += t*n%MOD;
		res %= MOD;
		t*=2LL;
		t%=MOD;
	}
	return res;
}



