ll L,R;
modint dp[64][2][2];
int visited[64][2][2];
int m;

// iビット目を見ている(i <= m)
// fl ... i+1ビット目以下でL以上が確定している？(No -> Lと一致)
// fr ... i+1ビット目以上でR以下が確定している？(No -> Rと一致)
modint f(int i,int fl,int fr) {
  if(i == -1) {
    return modint(1);
  }
  else if(visited[i][fl][fr] == 1) return dp[i][fl][fr];
  else {
    modint ret = 0;
    // xに0を入れられるか？
    int l0 = fl || ( (L >> i) & 1 ) == 0;
    // yに1を入れられるか？
    int r1 = fr || ( (R >> i) & 1 ) == 1;

    // xに1を入れたときのflは？
    int l1 = fl || ( (L >> i) & 1 ) == 0;
    // yに0を入れたときfrは？
    int r0 = fr || ( (R >> i) & 1 ) == 1;

    if(i != m){
      // x 0 y 0
      if(l0){
        ret += f(i - 1 , fl , r0);
      }
      // x 0 y 1
      if(l0 && r1){
        ret += f(i - 1 , fl , fr);
      }
    }
    // x 1 y 1
    if(r1){
      ret += f(i - 1 , l1 , fr);
    }
    visited[i][fl][fr] = 1;
    return dp[i][fl][fr] = ret;
  }
  return 1;
};


