  for(; m <= 60; m++){
    rep(i,64) rep(j,2) rep(k,2) dp[i][j][k] = visited[i][j][k] = 0;
    if( m < msb(L) || msb(R) < m) continue;
    int il = msb(L) != m , ir = msb(R) != m;
    ans += f( m , il , ir); 
    trc(m , il , ir, ans);
  }
  out(ans);


}

