using namespace std;

int64_t kRem = 1000000007;

map<pair<int64_t, int64_t>, int64_t> memo;

bool is_full(int64_t val) {
	return ((val + 1) & val) == 0;
}

int64_t pos(int64_t v) {
	int64_t ans = 0;
	while (v != 0) {
		v >>= 1;
		ans++;
	}
	return ans;
}

multimap<int64_t, int64_t> memo_full;
int64_t getfull(int64_t i) {
	if (i == 0) return 0;
	if (i == 1) return 1;

	auto it = memo_full.find(i);
	if (it != memo_full.end()) {
		return it->second;
	}

	int64_t ans = (3 * getfull(i - 1)) % kRem;
	memo_full.insert({ i, ans });
	return ans;
}

int64_t getpart(int64_t i, int64_t r)
{
	if (r == 0) {
		return 0;
	}
	if (i == 0) {
		return 0;
	}

	int64_t num = (1LL << i) / 2;
	if (r == num) {
		return getfull(i);
	}

	if (r <= num / 2) {
		return getpart(i - 1, r);
	}
	else {
		return (getfull(i - 1) + 2 * getpart(i - 1, r - (num / 2))) % kRem;
	}
}

int64_t solve(int64_t l, int64_t r)
{
	int64_t posl = pos(l);
	int64_t posr = pos(r);

	int64_t reml = (l - ((1LL << (posl - 1)) - 1));
	int64_t remr = (r - ((1LL << (posr - 1)) - 1));

	int64_t ans = 0;

	FOR_LE(i, posl, posr - 1) {
		ans += getfull(i);
		ans %= kRem;
	}
	ans += getpart(posr, remr);
	ans %= kRem;

	ans -= (getfull(posl) - getpart(posl, (1LL << (posl - 1)) - reml));

	ans %= kRem;
	if (ans < 0) ans += kRem;

	return ans;
}

