// 1000000007 で割ったあまりを扱う構造体
template <int MOD> struct Fp {
    long long val;
    constexpr Fp(long long v = 0) noexcept : val(v % MOD) {
        if(val < 0) v += MOD;
    }
    constexpr int getmod() { return MOD; }
    constexpr Fp operator-() const noexcept { return val ? MOD - val : 0; }
    constexpr Fp operator+(const Fp &r) const noexcept {
        return Fp(*this) += r;
    }
    constexpr Fp operator-(const Fp &r) const noexcept {
        return Fp(*this) -= r;
    }
    constexpr Fp operator*(const Fp &r) const noexcept {
        return Fp(*this) *= r;
    }
    constexpr Fp operator/(const Fp &r) const noexcept {
        return Fp(*this) /= r;
    }
    constexpr Fp &operator+=(const Fp &r) noexcept {
        val += r.val;
        if(val >= MOD) val -= MOD;
        return *this;
    }
    constexpr Fp &operator-=(const Fp &r) noexcept {
        val -= r.val;
        if(val < 0) val += MOD;
        return *this;
    }
    constexpr Fp &operator*=(const Fp &r) noexcept {
        val = val * r.val % MOD;
        return *this;
    }
    constexpr Fp &operator/=(const Fp &r) noexcept {
        long long a = r.val, b = MOD, u = 1, v = 0;
        while(b) {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        val = val * u % MOD;
        if(val < 0) val += MOD;
        return *this;
    }
    constexpr bool operator==(const Fp &r) const noexcept {
        return this->val == r.val;
    }
    constexpr bool operator!=(const Fp &r) const noexcept {
        return this->val != r.val;
    }
    friend constexpr ostream &operator<<(ostream &os, const Fp<MOD> &x) noexcept {
        return os << x.val;
    }
    friend constexpr istream &operator>>(istream &is, Fp<MOD> &x) noexcept {
        return is >> x.val;
    }
    friend constexpr Fp<MOD> modpow(const Fp<MOD> &a, long long n) noexcept {
        if(n == 0) return 1;
        auto t = modpow(a, n / 2);
        t = t * t;
        if(n & 1) t = t * a;
        return t;
    }
};

using mint = Fp<MOD>;

ll L, R;
mint dp[63][2][2][2];
bool memo[63][2][2][2];

mint calcdp(ll bit, bool mbit, bool mt, bool lt) {
    if(bit == -1) return mbit == 1;
    mint &res = dp[bit][mbit][mt][lt];
    if(memo[bit][mbit][mt][lt]) return res;
    res = 0;
    REP(x, 2) REP(y, 2) {
        if(x == 0 && !mt && ((L >> bit) & 1) == 1) continue; // lessthan
        if(y == 1 && !lt && ((R >> bit) & 1) == 0) continue; // morethan
        if(x == 1 && y == 0) continue;                       // x-y==xxory
        if(!mbit && x != y) continue;                        // mbit==mbit
        bool nmt = mt || ((L >> bit) & 1) < x;
        bool nlt = lt || ((R >> bit) & 1) > y;
        bool nmbit = mbit || (x & y);
        res += calcdp(bit - 1, nmbit, nmt, nlt);
    }
    memo[bit][mbit][mt][lt] = 1;
    return res;
}

