ll A[N], B[N];

ll Dfs(int k, int flh, int flr, int fll) {
//     cout << k << " " << flh << " " << flr << " " << fll << " " << f[k][flh][flr][fll] << endl;
    if (k == 0) return flh;
    if (~f[k][flh][flr][fll]) return f[k][flh][flr][fll];
    ll res = 0;
    int upr = (flr ? A[k] : 1), dwl = (fll ? B[k] : 0);
    if (!flh && upr)
        res = Dfs(k - 1, 1, flr, fll && dwl == 1);
    if (!flh && !dwl)
        (res += Dfs(k - 1, 0, flr && upr == 0, fll && dwl == 0)) %= Mod;
    else if (flh) rep (i, dwl, 1) rep (j, i, upr)
        (res += Dfs(k - 1, 1, flr && upr == j, fll && dwl == i)) %= Mod;
//     cout << k << " " << flh << " " << flr << " " << fll << " " << res << endl;
    return f[k][flh][flr][fll] = res;
}

ll Solve(ll L, ll R) {
    A[0] = B[0] = 0;
    memset(f, -1, sizeof f);
    while (R) A[++A[0]] = R & 1, R >>= 1;
    while (L) B[++B[0]] = L & 1, L >>= 1;
    return Dfs(A[0], 0, 1, 1);
}

