//const int128_t MAX_N = ;
const int128_t MOD = 1e9 + 7;
//const int128_t INF = std::numeric_limits<int64_t>::max();
//using pair = std::pair<int64_t, int>;

int128_t msbR, msbL;

int128_t solve(int128_t msb) {
    if (msb < msbL || msbR < msb) {
        return 0;
    }
    assert(msbL <= msb && msb <= msbR);

    int128_t dp[70][2][2] = {}; // dp[i][x][y] : i桁まで見て、xの条件が確定or未確定、yの条件が確定or未確定の状態数。

    if (msb == msbL && msb == msbR) {
        dp[msb][0][0] = 1;
    } else if (msbL < msb && msb == msbR) {
        dp[msb][1][0] = 1;
    } else if (msbL == msb && msb < msbR) {
        dp[msb][0][1] = 1;
    } else if (msbL < msb && msb < msbR) {
        dp[msb][1][1] = 1;
    } else {
        assert(false);
    }

    rev (i, msb - 1, 0) {
        rep (px, 0, 1) { rep (py, 0, 1) {
            rep (xb, 0, 1) { rep (yb, 0, 1) {
                if (yb == 0 && xb == 1) { continue; }

                int128_t nx = px;
                if (nx == 0) {
                    int128_t tL = (L >> i) & 1;
                    if (tL == 1 && xb == 0) {
                        continue;
                    } else if (tL == 0 && xb == 1) {
                        nx = 1;
                    }
                }

                int128_t ny = py;
                if (ny == 0) {
                    int128_t tR = (R >> i) & 1;
                    if (tR == 0 && yb == 1) {
                        continue;
                    } else if (tR == 1 && yb == 0) {
                        ny = 1;
                    }
                }

                dp[i][nx][ny] += dp[i+1][px][py];
                dp[i][nx][ny] %= MOD;
            }}
        }}
    }

    return (dp[0][0][0] + dp[0][0][1] + dp[0][1][0] + dp[0][1][1]) % MOD;

}

int main(int argc, char **argv) {
    std::cin >> L >> R;

    digR = digit(R, 2);
    digL = digit(L, 2);

    msbR = digR.size() - 1;
    msbL = digL.size() - 1;
    assert(msbL <= msbR);

    int128_t ret = 0;

    rep (i, msbL, msbR) {
        ret += solve(i);
        ret %= MOD;
    }

    std::cout << ret << std::endl;

    return 0;
}

