ll dfs(int d, int x_high, int x_low, int y_high, int y_low){
    if(dp[d][x_high][x_low][y_high][y_low]!=-1){
        return dp[d][x_high][x_low][y_high][y_low];
    }
    if(d==0){
        ll ans = 0;
        // xy=11?
        if(!(x_high && (R&1)==0)){
            dump();
            ans++;
        }
        // xy=10?
        if(!(x_high && (R&1)==0) && !(y_low && (L&1) == 1)){
            dump();
            ans++;
        }
        // xy=00?
        if(!(y_low && (L&1) == 1)){
            dump();
            ans++;
        }
        return dp[d][x_high][x_low][y_high][y_low] = ans;
    }
    ll ans = 0;

    if(!(x_high && (R>>d&1)==0)){
        // xy==11 OK
        int new_x_low = x_low && (L>>d&1)==1;
        int new_y_low = y_low && (L>>d&1)==1;
        (ans += dfs(d-1, x_high, new_x_low, y_high, new_y_low)) %= MOD;
    }
    if(!(x_high && (R>>d&1)==0) && !(y_low && (L>>d&1) == 1)){
        // xy==10 OK
        int new_x_low = x_low && (L>>d&1)==1;
        int new_y_high = y_high && (R>>d&1)==0;
        (ans += dfs(d-1, x_high, new_x_low, new_y_high, y_low)) %= MOD;
    }
    if(!(y_low && (L>>d&1) == 1)){
        // xy==00 OK
        int new_x_high = x_high && (R>>d&1)==0;
        int new_y_high = y_high && (R>>d&1)==0;
        (ans += dfs(d-1, new_x_high, x_low, new_y_high, y_low)) %= MOD;
    }

    return dp[d][x_high][x_low][y_high][y_low] = ans;
}

