const long long MOD = 1000000007;
ll modpow(ll a,long long b){
  ll base=a,ans=1LL;
  assert(b>=0);
  while(b){
    if(b&1){
      ans=ans*base%MOD;
    }
    base=base*base%MOD;
    b>>=1;
  }
  return ans;
}
#define LSB(a) (a&-a)
void solve(long long L, long long R){
  ll l=1,r=1;
  ll lc=0,rc=0;
  while(l<L){
    l*=2;
    ++lc;
  }
  ll cpyl=l;
  ll ans=0;
  for(;L<=l&&l*2-1<=R;l*=2){
    dump(l);
    dump(l*2-1);
    ll lc=__builtin_ctzll(l);
    dump(lc);
    dump(modpow(3LL,lc));
    ans+=modpow(3LL,lc);
    ans%=MOD;
  }
  while(L<cpyl){
    dump(__builtin_ctzll(L));
    dump(64-__builtin_clzll(L)-__builtin_ctzll(L)-__builtin_popcountll(L));
    ans+=modpow(3LL,__builtin_ctzll(L))*modpow(2LL,64-__builtin_clzll(L)-__builtin_ctzll(L)-__builtin_popcountll(L))%MOD;
    ans%=MOD;
    L+=LSB(L);
  }
  while(l<R){
    ll tmp=0;
    while((1LL<<tmp)&R){
      ++tmp;
    }
    dump(__builtin_popcountll(R)-1);
    dump(tmp);
    ans+=modpow(3LL,tmp)*modpow(2LL,__builtin_popcountll(R)-1-tmp)%MOD;
    ans%=MOD;
    R-=(1LL<<tmp);
  }
  cout<<ans%MOD<<endl;
}

