map<pair<ll, ll>, ll> mp, mp2;

ll rec(ll L, ll R);
ll rec2(ll L, ll R);

ll rec(ll L, ll R) {
    ll mod = 1e9+7;
    if (L > R) return 0;
    if (L == R) return 1;
    if (L == 0 && R == 1) {
        return 2;
    }
    if (mp.find({L, R}) != mp.end()) return mp[{L, R}];

    ll res = 0;
    res += rec(L/2, (R-1)/2);
    res += rec2((L+1)/2, (R-1)/2);
    res += rec((L+1)/2, R/2);
    return mp[{L, R}] = res%mod;
}

ll rec2(ll L, ll R) {
    ll mod = 1e9+7;
    if (L > R) return 0;
    if (L == R) {
        if (R == 0) return 0;
        return 1;
    }
    if (L == 0 && R == 1) {
        return 1;
    }
    if (mp2.find({L, R}) != mp2.end()) return mp2[{L, R}];

    ll res = 0;
    res += rec(L/2, (R-1)/2);
    res += rec2((L+1)/2, (R-1)/2);
    res += rec2((L+1)/2, R/2);
    return mp2[{L, R}] = res%mod;
}

