class PermComb {
public:
  int mod;
  int sz;
  vll fact;
  vll frev;

  PermComb(int mod, int sz) : mod(mod), sz(sz), fact(sz+1), frev(sz+1) {
    fact[0] = 1;
    rep (i, sz) {
      fact[i+1] = fact[i] * (i+1) % mod;
    }

    rep (i, sz+1) {
      frev[i] = po(fact[i], mod-2);
    }
  }

  ll po(ll k, ll x) {
    ll ret = 1;
    while (x) {
      if (x & 1) {
        ret = ret * k % mod;
      }
      k = k * k % mod;
      x >>= 1;
    }
    return ret;
  }

  ll perm(int n, int k) {
    assert (sz >= n && sz >= k);
    if (n < 0 || k < 0 || n < k) {
      return 0;
    }
    return fact[n] * frev[n-k] % mod;
  }

  ll comb(int n, int k) {
    assert (sz >= n && sz >= k);
    if (n < 0 || k < 0 || n < k) {
      return 0;
    }
    return fact[n] * frev[n-k] % mod * frev[k] % mod;
  }
};


