LL func(int p, int free){
	if(p==-1)return 1;
	if(p==0){
		if(free==3){
			return 3;
		}
		if(free==0){
			if((R&1)&&(L&1))return 1;
			if((R&1)&&(~L&1))return 3;
			if((~R&1)&&(L&1))return 0;
			if((~R&1)&&(~L&1))return 1;
		}
		if(free==1){
			if(R&1)return 3;
			if(~R&1)return 1;
		}
		if(free==2){
			if(L&1)return 1;
			if(~L&1)return 3;
		}
	}
	if(dp[p][free]>=0)return dp[p][free];
	LL res = 0;

	if(free==3){
		res += 3 * func(p-1, 3);
		res %= MOD;
	}
	if(free==0){
		if((R&BIT(p))&&(L&BIT(p)))res +=  func(p-1, 0);
		if((R&BIT(p))&&(~L&BIT(p)))res += func(p-1, 0) + func(p-1, 2) + func(p-1, 1);
		if((~R&BIT(p))&&(~L&BIT(p)))res += func(p-1, 0);
		res %= MOD;
	}
	if(free==1){
		if(R&BIT(p))res += func(p-1, 3) + 2 * func(p-1, 1);
		if(~R&BIT(p))res += func(p-1, 1);
		res %= MOD;
	}
	if(free==2){
		if(L&BIT(p))res += func(p-1, 2);
		if(~L&BIT(p))res += 2 * func(p-1, 2) + func(p-1, 3);
		res %= MOD;
	}
	return dp[p][free] = res;
}

