		int free = 3;
		if(L>=2*BIT(i))continue;
		if(getplace(L)==i){
			free ^= 1;
		}
		if(getplace(R)==i){
			free ^= 2;
		}
		ans += func(i-1, free);
		ans %= MOD;
		setdp();
	}
	cout << ans << endl;
	return 0;
}

