typedef long long ll;

const ll MOD = 1000000007;

ll ansl(ll n){
    if(n == 0) return 0;
    int p = log2(n + 1);
    ll b = 1;
    for(int i = 0; i <= p; i++) b *= 2;
    ll t = b - n - 1;
    ll res = 0;
    int k[64];
    for(int i = 0; i < 64; i++){
        if(t % 2) k[i] = 1;
        else k[i] = 0;
        t /= 2;
    }
    ll ma = 1;
    for(int i = 63; i >= 0; i--){
        ll q = 1;
        for(int j = 0; j < i; j++) q = q * 3 % MOD;
        if(k[i]){
            res = (res + ma * q) % MOD;
            ma = ma * 2 % MOD;
        }
    }
    ll res2 = 1;
    for(int i = 0; i < p; i++) res2 = res2 * 3 % MOD;
    return (res2 - res + (res2 - 1) / 2 + MOD) % MOD;
}

ll ansr(ll n){
    if(n == 0) return 0;
    int p = log2(n + 1);
    ll b = 1;
    for(int i = 0; i < p; i++) b *= 2;
    ll t = n - b + 1;
    ll res = 0;
    int k[64];
    for(int i = 0; i < 64; i++){
        if(t % 2) k[i] = 1;
        else k[i] = 0;
        t /= 2;
    }
    ll ma = 1;
    for(int i = 63; i >= 0; i--){
        ll q = 1;
        for(int j = 0; j < i; j++) q = q * 3 % MOD;
        if(k[i]){
            res = (res + ma * q) % MOD;
            ma = ma * 2 % MOD;
        }
    }
    ll res2 = 1;
    for(int i = 0; i < p; i++) res2 = res2 * 3 % MOD;
    return (res + (res2 - 1) / 2) % MOD;
}

