long long calc(bitset<64> L, bitset<64> R, int d, int lf, int rf){
    //cerr << L << endl;
    //cerr << R << endl;
    //cerr << d << " " << lf << " " << rf << endl;

    long long dp[100][2][2];
    REP(i, 100) REP(j, 2) REP(k, 2)
        dp[i][j][k] = 0;
    dp[d][lf][rf] = 1;
    for(int dd=d; dd>0; dd--){
        for(int x=0; x<2; x++){
            for(int y=0; y<2; y++){
                if(x==1 && y==0) continue;
                for(int l=0; l<2; l++){
                    for(int r=0; r<2; r++){
                        if(l==0 && L[dd-1]==1 && x==0) continue;
                        if(r==0 && R[dd-1]==0 && y==1) continue;
                        int l2 = l;
                        int r2 = r;
                        if(L[dd-1]==0 && x==1) l2 = 1;
                        if(R[dd-1]==1 && y==0) r2 = 1;
                        dp[dd-1][l2][r2] += dp[dd][l][r];
                        dp[dd-1][l2][r2] %= MOD;
                    }
                }
            }
        }
    }
    long long ret = 0;
    REP(i, 2) REP(j, 2){
        ret += dp[0][i][j];
        ret %= MOD;
    }
    return ret;
}

