inline int floormod(int a, int mod) {
  if (a > 0) return (a % mod);
  else if (a % mod == 0 ) return 0;
  else return (a % mod) + mod;
}

inline int modpow(int a, int n, int mod) {
  if (a == 0) return 0;
  int res = 1;
  while (n > 0) {
    if (n & 1) res = floormod(res * a , mod);
    a = floormod(a * a , mod);
    n >>= 1;
  }
  return res;
}

int modinv(int a, int mod) {
  return modpow(a, mod - 2, mod);
}

const int MAX = 3100;
int fac[MAX], finv[MAX], inv[MAX];
inline void COMinit(int mod) {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % mod;
    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
    finv[i] = finv[i - 1] * inv[i] % mod;
  }
}
inline int COM(int n, int k, int mod) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}


