ll upper(ll L, ll idx) {
    ll ret = 0;
    for(ll x = L; x < (1LL << (idx + 1)); x++) {
        for(ll y = x; y < (1LL << (idx + 1)); y++) {
            if((y&x) == x) ret++;
        }
    }
    ret %= mod;
    //cerr << "upper: " << L << " " << idx << " " << ret << endl;
    return ret;
}

ll lower(ll R, ll idx) {
    ll ret = 0;
    for(ll x = 0; x <= min(R, (1LL << (idx + 1)) - 1); x++) {
        ret += beki(2, __builtin_popcount(x));
    }
    ret %= mod;
    //cerr << "lower: " << R << " " << idx << " " << ret << endl;
    return ret;
}

ll g(ll R, ll L, ll idx) {
    //cerr << "g: " << R << " " << L << " " << idx << endl;
    //if(R < L) return 0;
    if(L <= 0) return lower(R, idx);
    if((1LL << (idx + 1)) <= R) return upper(L, idx);
    if(idx <= 1) {
        ll ret = 0;
        for(ll x = L; x <= R; x++) {
            for(ll y = x; y <= R; y++) {
                if((x & y) == x) ret++;
            }
        }
        return ret;
    }
    ll ret = 0;
    ret += g(R - (1LL << idx), L - (1LL << idx), idx - 1);
    ret += g(R - (1LL << idx), L, idx - 1);
    ret += g(R, L, idx - 1);
    return ret % mod;
}

