ll dp[64][2][2][2], L, R;
ll dfs(int now, bool l, bool r, bool bf) {
  if (now == -1) return 1;
  ll& ans = dp[now][l][r][bf];
  if (ans >= 0) return ans;
  ans = 0;
  bool ll = (L >> now) & 1, rr = (R >> now) & 1;
  for (int i = 0; i <= 1; i++) {
    for (int j = 0; j <= 1; j++) {
      if (l && i == 0 && ll) continue;
      if (r && j == 1 && !rr) continue;
      if (i > j) continue;
      if (!bf && (i != j)) continue;
      ans += dfs(now - 1, l & (i == ll), r & (j == rr), bf || i);
    }
  }
  ans %= M;
  return ans;
}

