          dp[i][0][0][0] += dp[i-1][0][0][0];
          dp[i][0][0][1] += dp[i-1][0][0][1];
        }
        if (x[i] == 0) {
          dp[i][1][0][0] += dp[i-1][1][0][0];
          dp[i][1][0][1] += dp[i-1][1][0][1];
        }
        if (y[i] == 1) {
          dp[i][1][1][0] += dp[i-1][0][1][0];
          dp[i][1][1][1] += dp[i-1][0][1][1];
        } else {
          dp[i][0][1][0] += dp[i-1][0][1][0];
          dp[i][0][1][1] += dp[i-1][0][1][1];
        }

        // y=1; x=0
        dp[i][1][1][1] += dp[i-1][1][1][1];
        if (y[i] == 1 && x[i] == 0) {
          dp[i][0][0][1] += dp[i-1][0][0][1];
        }
        if (x[i] == 0) {
          dp[i][1][0][1] += dp[i-1][1][0][1];
        }
        if (y[i] == 1) {
          dp[i][0][1][1] += dp[i-1][0][1][1];
        }

        // y=1; x=1
        dp[i][1][1][1] += dp[i-1][1][1][1];
        dp[i][1][1][1] += dp[i-1][1][1][0];
        if (y[i] == 1 && x[i] == 1) {
          dp[i][0][0][1] += dp[i-1][0][0][0];
          dp[i][0][0][1] += dp[i-1][0][0][1];
        } else if (y[i] == 1 && x[i] == 0) {
          dp[i][0][1][1] += dp[i-1][0][0][0];
          dp[i][0][1][1] += dp[i-1][0][0][1];
        }
        if (x[i] == 1) {
          dp[i][1][0][1] += dp[i-1][1][0][0];
          dp[i][1][0][1] += dp[i-1][1][0][1];
        } else if (x[i] == 0) {
          dp[i][1][1][1] += dp[i-1][1][0][0];
          dp[i][1][1][1] += dp[i-1][1][0][1];
        }
        if (y[i] == 1) {
          dp[i][0][1][1] += dp[i-1][0][1][0];
          dp[i][0][1][1] += dp[i-1][0][1][1];
        }
      }
      mint ans = 0;
      rep(i, 2) rep(j, 2) rep(k, 2) {
        ans += dp[n-1][i][j][k];
      }
      return ans;
    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      ll L, R; cin >> L >> R;
      cout << count(L, R).x << endl;
    }
};

