int binpow(int x, int y){
    if (y == 0) return 1;
    if (y % 2) return x * binpow(x, y - 1) % mod;
    int z = binpow(x, y / 2);
    return z * z % mod;
}
int solve1(int hb, int r, int c){
    int b = c;
    int res = 0;
    for (int i = hb - 1; i >= 0; i--){
        if ((1LL << i) & r){
            res = (res + binpow(2, b) * binpow(3, i)) % mod;
            b++;
        }
    }
    res = (res + binpow(2, b)) % mod;
    return res;
}
int solve2(int hb, int l){
    int b = 0;
    int res = 0;
    for (int i = hb - 1; i >= 0; i--){
        if (!((1LL << i) & l)){
            res = (res + binpow(2, b) * binpow(3, i)) % mod;
            b++;
        }
    }
    res = (res + binpow(2, b)) % mod;
    return res;
}
