int main(){
    long long int l, r;
    cin >> l >> r;

    dp[60][0][0][0] = 1;
    for(int i=59; i>=0; i--){// digit DP
        for(int j=0; j<2; j++){
            for(int k=0; k<2; k++){
                for(int s=0; s<2; s++){

                    for(int nx=0; nx<2; nx++){
                        for(int ny=0; ny<2; ny++){
                            if(nx == 1 && ny == 0) continue;

                            int nj = j, nk = k, ns = s;

                            // s : MSB
                            if(s == 0 && nx != ny) continue;
                            if(nx == 1 && ny == 1) ns = 1;

                            // j : L <= x
                            if(j == 0 && nx == 0 && ((l>>i) & 1)) continue;// x < L
                            if(nx == 1 && !((l>>i) & 1)) nj = 1; 

                            // k : y <= R
                            if(k == 0 && ny == 1 && !((r>>i) & 1)) continue;// y > R
                            if(ny == 0 && ((r>>i) & 1)) nk = 1; 

                            dp[i][nj][nk][ns] += dp[i+1][j][k][s];
                            dp[i][nj][nk][ns] %= MOD;
                        }
                    }

                }
            }
        }
    }

    long long int ans = 0;
    for(int j=0; j<2; j++){
        for(int k=0; k<2; k++){
            for(int s=0; s<2; s++){
                ans += dp[0][j][k][s];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

