mint dp[100][2][2][2];

mint solve(string L, string R) {
  memset(dp,0,sizeof(dp));
  dp[0][0][0][0] = 1;
  REP(i,64) {
    bool l = L[i] == '1';
    bool r = R[i] == '1';
    REP(j,2) {
      REP(k,2) {
        REP(s,2) {
          REP(p1,2) {
            REP(p2,2) {
              if (p1 > p2) continue;
              if (!j && l && !p1) continue; // lより下
              if (!k && !r && p2) continue; // rより上
              if (!s && p1 != p2) continue;
              int jj = j || (l < p1);
              int kk = k || (r > p2);
              int ss = s || (p1 && p2);
              dp[i+1][jj][kk][ss] += dp[i][j][k][s];
            }
          }
        }
      }
    }
  }
  mint ans = 0;
  REP(j,2)REP(k,2)REP(p,2) ans+=dp[64][j][k][p];
  return ans;
}

int main() {
  ll L,R;
  while(cin>>L>>R) {
    string ls = to_binary(L);
    string rs = to_binary(R);
    cout << solve(ls,rs) << endl;
  }
}

