ll dp[63][2][2][2] = {}; //{[丁度, 大きい], [丁度, 小さい]}

int main() {
  ll L, R;
  int A[62] = {}, B[62] = {};

  cin >> L >> R;

  //cout << test(L, R) << endl;

  for (int i=0; i<62; i++) {
    A[61-i] = L % 2;
    B[61-i] = R % 2;
    L /= 2;
    R /= 2;
  }

  dp[0][0][0][0] = 1;

  for (int i=0; i<62; i++) {
    // (0, 0), (0, 1), (1, 1)
    for (int j=0; j<2; j++) {
      for (int k=0; k<2; k++) {
        for (int l=0; l<2; l++) {

          for (int x=0; x<2; x++) {
            for (int y=x; y<2; y++) {
              if (j == 0 && x < A[i]) continue;
              if (k == 0 && B[i] < y) continue;

              int nextj = j == 0 ? A[i] < x : 1;
              int nextk = k == 0 ? y < B[i] : 1;
              int nextl = l == 0 ? x == 1 : 1;

              if (nextl == 0 && y == 1) continue;

              dp[i+1][nextj][nextk][nextl] += dp[i][j][k][l];
              dp[i+1][nextj][nextk][nextl] %= mod;
            }
          }
        }
      }
    }
  }

  ll ans = 0;
  for (int i=0; i<4; i++) {
    ans += dp[62][i/2][i%2][0] + dp[62][i/2][i%2][1];
  }

  cout << ans % mod << endl;

  return 0;
}

