/*
     x1: 0000 0001 0010 0101 0110 0111 0111
     x2: xxxx 0001 0011 0100 0101 1000 0110
x1 & x2: 0000 0001 0010 0100 0100 0000 0110

      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S & (1 << i) -> if true, i in S
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}
__builtin_popcountl(i) -> the number of 1 in binary

#Conditional Operator
condition ? true : false;

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 12000;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

/* 
read_graph(n, m, graph, cost, directed, offset)
    cost: if link cost is fixed, put positive integer
          otherwise -1
    directed: if directed true, olse false
    offset: if the given vertex is 1-indexed, -1.
*/

void solve(){
    bool okay = false;
    string S, T, U;
    ll A, B, C, D, N, M, H, W, K, x, y, Q, idx, cnt, num, answer;
    vl as, bs, cs, ds;
    vb2 block; vb visited; Graph graph, tree;
    points ps;
    // generate_array(size, min, max);

    in2(A, B);

    ll n_digits = 61;
    vmi4 dp(2, vmi3(2, vmi2(2, vmi(n_digits, 0))));
    PowerMemo p3(n_digits + 5, 3, MOD);

    dp[0][0][0][0] = 1;
    For(nd, 1, n_digits){
        K = n_digits - 1 - nd;
        bool topA = 1LL << K & A;
        bool topB = 1LL << K & B;

        // 0 0 0
        if (!topA && !topB) dp[0][0][0][nd] = dp[0][0][0][nd - 1];

        // 1 0 0
        if (topA == topB) dp[1][0][0][nd] = dp[1][0][0][nd - 1];
        if (topA && topB) dp[1][0][0][nd] += dp[0][0][0][nd - 1];

        // 0 1 0 does not exist
        // 1 1 0
        dp[1][1][0][nd] = dp[1][1][0][nd - 1] * (1 + topB);
        if (!topA && topB) dp[1][1][0][nd] += dp[0][0][0][nd - 1] + dp[1][0][0][nd - 1] * 2;

        // 0 0 1
        if (!topA) dp[0][0][1][nd] = dp[0][0][1][nd - 1];
        if (!topA && topB) dp[0][0][1][nd] += dp[0][0][0][nd - 1];

        // 1 0 1
        dp[1][0][1][nd] = dp[1][0][1][nd - 1];
        if (!topA && topB) dp[1][0][1][nd] += dp[1][0][0][nd - 1];
        if (topA) dp[1][0][1][nd] += dp[0][0][1][nd - 1];

        // 0 1 1 does not exist
        // 1 1 1
        ll n0 = __builtin_popcountl(A) - __builtin_popcountl(A >> K);
        mint v3 = p3[K], v32 = p3[n0];
        dp[1][1][1][nd] = dp[1][1][1][nd - 1];
        if (!topA) dp[1][1][1][nd] += dp[1][0][1][nd - 1] * v3 + dp[1][0][1][nd - 1] * v32;
        if (topB) dp[1][1][1][nd] += dp[1][1][0][nd - 1] * v3;
        if (!topA) dp[1][1][1][nd] += dp[0][0][1][nd - 1] * v3;
    }

    /*
      01100100
      00001010
    x 000011   ->  18 -> 12
    o 00001011 ->   2
    o 00001010 ->   1
    */

    mint ans = 0;
    rep(i, 2) rep(j, 2) ans += dp[1][i][j][n_digits - 1];
    prl(ans);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

