using namespace std;

template <std::int64_t M>
class modint {
 public:
  int64_t a;

  explicit constexpr modint(const int64_t x = 0) noexcept : a((x % M + M) % M) {}
  constexpr int64_t &value() noexcept { return a; }
  constexpr const int64_t &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= M) {
      a -= M;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += M;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % M;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    int64_t exp = M - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};

// L<=X<=Y<=R と Y%X = Y^X が条件
// まず場合分けをする
// 1) X = Y の場合、Y%X = Y^X == 0 なのでOK
// 2) X < Y の場合
//  2A) 2進数でXとYの桁数が同じ
//    Y^X = Y+X-2(Y&X)
//    Y%X = Y-X なぜならX<Y<2XよりY/X=1なので
//    つまり、X = X ^ Y
//    ある桁においてX=1でY=0はNG（そのほかの3つの場合でOK）
//  2B) 2進数でXとYの桁数が同じ
//    NG Y%Xは1から始まり、MODは0から始まるため

// dp[i][j][k][s]: 上からi桁番目まで見た時の個数。 
// jはX>=Lが確定しているかどうか
// kはY<=Rが確定しているかどうか
// sは先頭ビットが既に現れたかどうか

using mint = modint<1000000007>;
mint dp[64][2][2][2];

signed main() {
  ll L, R;
  cin >> L >> R;

  dp[63][0][0][0] = mint(1);
  for (ll i = 63; i>=1; i--) rep(j,2) rep(k,2) rep(s,2) {
    mint cur = dp[i][j][k][s];

    rep(x,2) rep(y,2) {
      if (x == 1 && y == 0) continue;

      ll ni = i - 1, nj = j, nk = k, ns = s;
      ll lb = (L>>ni) & 1;
      ll rb = (R>>ni) & 1;

      // j: X>=Lの判定
      if (!nj && lb == 1 && x == 0) continue;
      if (lb == 0 && x == 1) nj = 1;

      // k: Y<=Rの判定
      if (!nk && rb == 0 && y == 1) continue;
      if (rb == 1 && y == 0) nk = 1;

      // s: 先頭ビットが既出か判定
      if (!ns && (x^y == 1)) continue;
      if (x == 1 && y == 1) ns = 1;

      dp[ni][nj][nk][ns] += cur;
    }
  }

  mint ans(0);
  rep(j,2) rep(k,2) rep(s,2) {
    ans += dp[0][j][k][s];
  }
  cout << ans.value() << endl;
  return 0;
}

