ll dfs(int p,int lim,int fl,int x0){
	if(!p) return x0;
	if(~dp[p][lim][fl][x0]) return dp[p][lim][fl][x0];
	//cout<<p<<' '<<lim<<' '<<fl<<' '<<x0<<endl;
	ll Up=lim?a[p]:1;
	ll res=0;
	rep(i,0,Up) {
		if(i) {
			res+=dfs(p-1,(lim&&i==Up),1,1);//1
			if(fl) res+=dfs(p-1,(lim&&i==Up),1,x0);//0
		} else res+=dfs(p-1,lim&&(i==Up),fl,x0);//0
	}
	res%=P;
	dp[p][lim][fl][x0]=res%P;
	return res%P;
}

