	ll L, R;
	cin >> L >> R;

	int lb[M], rb[M];
	rep(i, M) {
		lb[i] = L % 2;
		rb[i] = R % 2;
		L /= 2;
		R /= 2;
	}
	// for (auto l : lb) { cout << l; } cout << endl;
