typedef long long ll;
const int mod = 1e9 + 7;
ll L, R, dp[66][2][2];

ll solve(int x, int left, int right, bool flag) {
    if (x < 0) return 1;
    if (!flag && dp[x][left][right] != -1) return dp[x][left][right];
    int l = 0, r = 1;
    if (left) l = (L >> x & 1);
    if (right) r = (R >> x & 1);
    ll ret = 0;
    rep(i, l, 1) {
        rep(j, i, r) {
            if (j == 1 && flag) {  // 遇到最高位了
                if (i == 1)
                    ret += solve(x - 1, left && i == l, right && j == r, 0);
            } else
                ret += solve(x - 1, left && i == l, right && j == r, flag && j == 0);
        }
    }
    ret %= mod;
    if (!flag) dp[x][left][right] = ret;
    return ret;
}

int main() {
    cin >> L >> R;
    memset(dp, -1, sizeof(dp));
    printf("%lld\n", solve(60, 1, 1, 1));
    return 0;
}

