int main(){

    ll L, R; cin >> L >> R;

    mint<> ans(0);

    //L以上の最小の2冪、R以下の最大の2冪
    ll lh = 0;
    while((1ll << lh) < L)lh++;
    ll rh = 0;
    while((1ll << rh) < R)rh++;
    rh--;

    if(lh <= rh){
        ans += (mint<>(3).pow(rh) - mint<>(3).pow(lh)) / mint<>(2);
        ll lb = (1ll << lh);
        ll rb = (1ll << rh);
        ll lb2 = (lb >> 1);
        ans += calc(lb2, lb - (L - lb2) - 1);
        ans += calc(rb, R);
    } else {
        ll use = R - L + 1;
        ll tmp = 1;
        while(tmp < use)tmp <<= 1;
        ll tmp2 = tmp >> 1;
        R -= L;
        L = 0;
        if(tmp2 == L){
            ans += calc(L, R);
        } else if(tmp == R){
            ans += calc(L, R);
        } else {
            ll l = 0, r = tmp - tmp2;
            while(1){
                ll m = (l + r) / 2;
                if(L <= m and m <= R){
                    ans += calc(L, m - L);
                    ans += calc(m, R);
                    ans -= mint<>(1);
                    break;
                } else if(R < m){
                    r = m;
                } else {
                    l = m;
                }
            }
        }
    }

    cout << ans << endl;
    return 0;

}

