    for(int i = (a ? 0 : s[pos]) ; i <= (b ? 1 : t[pos]) ; ++i){
        for(int j = max(i , (c ? 0 : s[pos])) ; j <= (d ? 1 : t[pos]) ; ++j){
            if(j == 1 && (e | i) == 0)continue;
            res += cal(pos + 1 , a | (i > s[pos]) , b | (i < t[pos]) ,
                       c | (j > s[pos]) , d | (j < t[pos]) , e | i);
            if(res >= mod)res -= mod;
        }
    }
    return res;
}

