ll solve(ll from, ll to) {
    //cout << from << ' '<< to << endl;
    string f = tostr(from), t = tostr(to);
    //cout << f << endl;
    //cout << t << endl;

    if (f.size() != t.size()) {
        exit(228);
    }
    if (f.back() != '1' || t.back() != '1') {
        exit(228);
    }
    memset(dp, 0, sizeof(dp));
    memset(dpf, 0, sizeof(dpf));
    memset(dpt, 0, sizeof(dpt));
    for (int i = 0; i < f.size(); ++i) {
        if (f[i] == '1') {
            if (i == 0) {
                dpf[i] = 1;
            } else {
                dpf[i] = dpf[i - 1];
            }
        } else {
            if (i == 0) {
                dpf[i] = 3;
            } else {
                dpf[i] = 2 * dpf[i - 1];
                dpf[i] += p3[i];
            }
        }
    }
    for (int i = 0; i < t.size(); ++i) {
        if (t[i] == '0') {
            if (i == 0) {
                dpt[i] = 1;
            } else {
                dpt[i] = dpt[i - 1];
            }
        } else {
            if (i == 0) {
                dpt[i] = 3;
            } else {
                dpt[i] = 2 * dpt[i - 1];
                dpt[i] += p3[i];
            }
        }
    }

    for (int i = 0; i < f.size(); ++i) {
        if (f[i] == '1' && t[i] == '0') {
            dp[i] = 0;
        }
        if (f[i] == '0' && t[i] == '1') {
            if (i == 0) {
                dp[i] = 3;
            } else {
                dp[i] = dpt[i - 1] + dpf[i - 1] + dp[i - 1];
            }
        }
        if (f[i] == '1' && t[i] == '1') {
            if (i == 0) {
                dp[i] = 1;
            } else {
                dp[i] = dp[i - 1];
            }
        }
        if (f[i] == '0' && t[i] == '0') {
            if (i == 0) {
                dp[i] = 1;
            } else {
                dp[i] = dp[i - 1];
            }
        }
    }
    //cout << "$ " << dp[0] << ' ' << dpt[0] << ' ' << dpf[0] << endl;
    return dp[f.size() - 1];
}

