using namespace std;

using ll = long long;

const ll MD = 1e9 + 7;

ll power(ll a, ll b) {
  ll x = 1, y = a;
  while (b > 0) {
    if (b % 2) x = (x * y) % MD;
    y = (y * y) % MD;
    b /= 2;
  }
  return x % MD;
}

ll inv(ll x) {
  return power(x, MD - 2);
}

ll eval(ll x) {
  if (x == 0) return 0;
  else if (x == 1) return 1;

  ll e = (ll)log2(x);
  ll ans = power(3, e);
  ll off = x - (1LL << e);
  ll next = (2 * eval(off)) % MD;
  return (ans + next) % MD;
}

ll calc(ll x) {
  ll e = (ll)log2(x);
  ll ans = ((power(3, e) - 1) * inv(2)) % MD;
  ll off = x - (1LL << e) + 1;
  return (ans + eval(off)) % MD;
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(NULL);

  ll L, R; cin >> L >> R;
  ll ans = (calc(R) - calc(L - 1)) % MD;
  cout << ans << endl;

  return 0; 
}

