ll l, r;
ll dp[66][2][2][2];

ll memo(int idx, int flag, int flagL, int flagR) {
	if(idx == -1) {
		return flag;
	}
	if(dp[idx][flag][flagL][flagR] != -1) return dp[idx][flag][flagL][flagR];
	if(flag) {
		if(flagL) {
			if(flagR) {
				return dp[idx][flag][flagL][flagR] = mul(memo(idx-1, flag, flagL, flagR), 3);
			}
			else {
				if((r&(1LL<<idx)) > 0) {
					return dp[idx][flag][flagL][flagR] = add(memo(idx-1, flag, flagL, 1), mul(2, memo(idx-1, flag, flagL, 0)));
				}
				else {
					return dp[idx][flag][flagL][flagR] = memo(idx-1, flag, flagL, flagR);
				}
			}
		}
		else {
			if(flagR) {
				if((l&(1LL<<idx)) == 0) {
					return dp[idx][flag][flagL][flagR] = add(mul(memo(idx-1, flag, 0, flagR), 2), memo(idx-1, flag, 1, flagR));
				}
				else {
					return dp[idx][flag][flagL][flagR] = memo(idx-1, flag, flagL, flagR);
				}
			}
			else {
				if((r&(1LL<<idx)) == (l&(1LL<<idx))) {
					return dp[idx][flag][flagL][flagR] = memo(idx-1, flag, flagL, flagR);
				}
				else {
					return dp[idx][flag][flagL][flagR] = add(memo(idx-1, flag, 0, 0), add(memo(idx-1, flag, 0, 1), memo(idx-1, flag, 1, 0)));	
				}
			}
		}
	}
	else {
		if((r&(1LL<<idx)) == (l&(1LL<<idx))) {
			if((r&(1LL<<idx)) > 0) {
				if(flagL) return dp[idx][flag][flagL][flagR] = memo(idx-1, 1, 0, 0);
				else dp[idx][flag][flagL][flagR] = 0;
			}
			else {
				if(flagR) return dp[idx][flag][flagL][flagR] = memo(idx-1, 0, 0, 0);
				else dp[idx][flag][flagL][flagR] = 0;
			}
		}
		else {
			if((r&(1LL<<idx)) > 0) {
				return dp[idx][flag][flagL][flagR] = add(memo(idx-1, 1, 1, 0), memo(idx-1, 0, 0, 1));
			}
			else {
				return dp[idx][flag][flagL][flagR] = 0;
			}
		}
	}
}

