int main() {
	long long L, R;
	cin >> L >> R;
	dp[60][0][0][0] = 1;
	for (int i = 59; i >= 0; --i) {
		int lb = (L >> i) & 1;
		int rb = (R >> i) & 1;
		for (int j = 0; j < 2; ++j) {
			for (int k = 0; k < 2; ++k) {
				for (int l = 0; l < 2; ++l) {
					mint pre = dp[i + 1][j][k][l];
					for (int x = 0; x < 2; ++x) {
						for (int y = 0; y < 2; ++y) {
							if ((1 == x) && (0 == y)) {//(1,0)
								continue;
							}
							int nj = j;
							int nk = k;
							int nl = l;
							//nl
							if ((0 == l)) {
								if (x != y) {
									continue;
								}
								if ((1 == x) && (1 == y)) {
									nl = 1;
								}
							}
							//j: L<=X
							if ((1 == lb) && (0 == x) && (0 == j)) {
								continue;
							}
							if (0 == j) {
								if ((1 == x) && (0 == lb)) {
									nj = 1;
								}
							}
							//k: Y <=R
							if ((0 == rb)&&(1 == y)&&(0 == k)) {
								continue;
							}
							if (0 == k) {
								if ((0 == y)&&(1 == rb)) {
									nk = 1;
								}
							}

							dp[i][nj][nk][nl] += pre;
						}
					}
				}
			}
		}
	}
	mint ans = 0;
	for (int j = 0; j < 2; ++j) {
		for (int k = 0; k < 2; ++k) {
			for (int l = 0; l < 2; ++l) {
				ans += dp[0][j][k][l];
			}
		}
	}
	cout << ans << endl;
	return 0;
}

