	if( !(up && R(n)==0) ) ret = add( ret, f( n-1, bo && L(n) == 1, up && R(n) == 1, 1 ) );

	if( s && !(bo && L(n)) && !(up && R(n)==0) ) ret = add( ret, f( n-1, bo && L(n) == 0, up && R(n) == 1, 1 ) );

	return ret;
}

