signed main(void){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int L, R; cin >> L >> R;
  dp[60][0][0][0] = 1;
  for(int i = 59; i >= 0; i--){
    int ld = L>>i & 1, rd = R>>i & 1; //  (2進で)下からi桁目だけ見る (0-indexed)
    REP(j, 2) REP(k, 2) REP(s, 2){
      int tmp = dp[i+1][j][k][s];
      REP(x, 2) REP(y, 2){ // x, yの下からi桁目
        if(x and !y) continue; // x=1, y=0 はアウト

        int nj = j, nk = k, ns = s;
        if(!s and x!=y) continue; // 桁が揃わないのでアウト
        if(x and y) ns = 1;
        // j :  L<=x ?
        if(!j and !x and ld) continue; // x < L が確定するのでアウト
        if(x and !ld) nj = 1;
        // k :  y<=R ?
        if(!k and y and !rd) continue; // R < r が確定するのでアウト
        if(!y and rd) nk = 1;

        dp[i][nj][nk][ns] += tmp;
        dp[i][nj][nk][ns] %= MOD;
      }
    }
  }
  int ans = 0;
  REP(j, 2)REP(k, 2)REP(s, 2){
    // j==0 -> x==L, j==1 -> L<=x
    // k==0 -> y==R, k==1 -> y<=R
    // s==0 -> 全部桁同じ, s==1 -> 最上位が揃う
    ans += dp[0][j][k][s];
    ans %= MOD;
  }
  cout << ans << endl;
}

