ll L, R;

ll dp[64][2][2];
ll solve(int i, int girix, int giriy){
    if(i == -1) return 1;
    if(dp[i][girix][giriy] != -1) return dp[i][girix][giriy];
    ll ret = 0;

    // x=0, y=0
    if(girix==0){
        if(giriy==1 && ((R>>i)&1)==0) ret += solve(i-1, 0, 1);
        else ret += solve(i-1, 0, 0);
    }
    else if(((L>>i)&1) == 0){
        if(giriy==1 && ((R>>i)&1)==0) ret += solve(i-1, 1, 1);
        else ret += solve(i-1, 1, 0);
    }

    // x=0, y=1
    if(girix==0){
        if(giriy==1 && ((R>>i)&1)==0) ret += 0;
        else if(giriy==1 && ((R>>i)&1)==1) ret += solve(i-1, 0, 1);
        else ret += solve(i-1, 0, 0);
    }
    else if(((L>>i)&1) == 0){
        if(giriy==1 && ((R>>i)&1)==0) ret += 0;
        else if(giriy==1 && ((R>>i)&1)==0) ret += solve(i-1, 1, 1);
        else ret += solve(i-1, 1, 0);
    }

    // x=1, y=1
    if(girix==0 || ((L>>i)&1) == 0){
        if(giriy==1 && ((R>>i)&1)==0) ret += 0;
        else if(giriy==1 && ((R>>i)&1)==1) ret += solve(i-1, 0, 1);
        else ret += solve(i-1, 0, 0);
    }
    else{
        if(giriy==1 && ((R>>i)&1)==0) ret += 0;
        else if(giriy==1 && ((R>>i)&1)==0) ret += solve(i-1, 1, 1);
        else ret += solve(i-1, 1, 0);
    }

    return dp[i][girix][giriy] = ret % MOD;
}

