ll calc(ll x){
    if(x == 0) return 0;
    ll res = 0;
    int f[64] = {};
    ll r_ = x;
    int s = 0;
    int cnt = 0;
    rep(i,64){
        f[63-i] = r_ % 2;
        cnt += f[63-i];
        r_ /= 2;
        if(f[63-i]) s = 63-i;
    }

    ll dp[64][70];
    rep(i,64)rep(j,70)dp[i][j] = 0;

    int now = 0;
    srep(i,s+1,64){
        if(f[i]){
            dp[i][now] = 1;
            now++;
        }
        rep(j,64){
            dp[i][j+1] += dp[i-1][j];
            dp[i][j+1] %= MOD;
            dp[i][j] += dp[i-1][j];
            dp[i][j] %= MOD;
        }
    }
    dp[63][now]++;
    ll two[65];
    two[0] = 1;
    srep(i,1,65) two[i] = two[i-1] * 2 % MOD;
    rep(j,65){
        res += dp[63][j] * two[j];
        res %= MOD;
    }

    rep(i,64) f[i] = 1;
    srep(loop,s+1,64){
        // cout << loop << ' ' << res << endl;
        rep(i,64)rep(j,70)dp[i][j] = 0;
        now = 0;
        srep(i,loop+1,64){
            if(f[i]){
                dp[i][now] = 1;
                now++;
            }
            rep(j,64){
                dp[i][j+1] += dp[i-1][j];
                dp[i][j+1] %= MOD;
                dp[i][j] += dp[i-1][j];
                dp[i][j] %= MOD;
            }
        }
