const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

mint dp[61][2][2][2];
/*
the first dimension is about the bit position
the second dimension is whether x >= l
the third dimension is whether y <= r
ther last dimension is whether the first "1"bit is placed 
*/


int main()
{
    ll l, r;
    cin >> l >> r;
    // 59<log(10^18)<60
    dp[60][0][0][0] = 1;
    //process from the high bit position to low bit position
    for (int i = 59; i >= 0; i--)
    {
        //take out the ith bit of l and r
        int lb = l >> i & 1;
        int rb = r >> i & 1;
        for (int j = 0; j < 2; j++)
        for (int k = 0; k < 2; k++)
        for (int s = 0; s < 2; s++)
        {
            //the previous state
            mint pre = dp[i + 1][j][k][s];
            /*
            there are 3 possibilities for next state
            they are all about the ith bit position
            1. x = 1, y = 1
            2. x = 0, y = 0
            3. x = 0, y = 1
            */
            for (int x = 0; x < 2; x++)
            for (int y = 0; y < 2; y++)
            {
                // x = 1, y = 0 is impossible
                if (x && !y) continue;
                // for next state
                int nj = j, nk = k, ns = s; 
                //s = 0, which means the first 1bit is not placed. Under this condition, x = y = 0
                if (!s && x != y) continue; 
                // if the first 1bit is set
                if (x && y) ns = 1;
                // if x < l
                if (!j && !x && lb) continue;
                if (x && !lb) nj = 1;
                // if y > r
                if (!k && y && !rb) continue;
                if (!y && rb) nk = 1;
                // the ans of next state += previous state
                dp[i][nj][nk][ns] += pre;
            }
        }
    }
    mint ans;
    // add up the ans
    for (int j = 0; j < 2; j++)
    for (int k = 0; k < 2; k++)
    for (int s = 0; s < 2; s++)
    ans += dp[0][j][k][s];
    cout << ans.x << endl;
    return 0;
}

#include <bits/stdc++.h>

int main(){
    using namespace std;
    constexpr unsigned long MOD = 1000000007;
    unsigned long L, R;
    cin >> L >> R;

    auto modpow = [&MOD](unsigned long n, unsigned long b = 3, unsigned long c = 1){
        unsigned long r = c, p = b;
        while(n){
            if(n & 1)(r *= p) %= MOD;
            (p *= p) %= MOD;
            n >>= 1;
        }
        return r;
    };

    auto f = [&MOD, &L, &R, &modpow](unsigned long l, unsigned long r, unsigned long n) -> unsigned long{
        if(R < l || r <= L)return 0;
        if(L <= l && r <= R + 1)return modpow(n);
        auto lower = [&MOD, &R, &modpow](unsigned long n){
            unsigned long ret{0}, c{0};
            for(unsigned long i = n; --i;)if(R & (1UL << i))ret += modpow(c++, 2, modpow(i));
            return (ret += modpow(c, 2, 1 + 2 * (R & 1))) %= MOD;
        };
        auto upper = [&MOD, &L, &modpow](unsigned long n){
            unsigned long ret{0}, c{0};
            for(unsigned long i = n; --i;)if(!(L & (1UL << i)))ret += modpow(c++, 2, modpow(i));
            return (ret += modpow(c, 2, 1 + 2 * (~L & 1))) %= MOD;
        };
        if(l < L){
            if(r > R)return (lower(n) + upper(n) + MOD - modpow(n)) % MOD;
            else return upper(n);
        }else{
            return lower(n);
        }
    };

    unsigned long ans{0};
    for(unsigned long i = 1, j = 2, k = 0; i <= R; ++k){
        (ans += f(i, j, k)) %= MOD;
        swap(i *= 4, j);
    }
    cout << ans << endl;
    return 0;
}

