mint memo[61][2][2][2]; //上位i桁,L<x,y<R,MSB決まったか
int L,R;

mint dfs(int bit, int f1, int f2, int f3){
  if(bit < 0) return 1;
  mint res = 0;
  // x:0 y:0 -> 上位はOK、下位は既に越えている or 0
  if(f1||((1LL<<bit)&L)==0) res += dfs(bit-1,f1,f2|(((1LL<<bit)&R)>0),f3);
  // x:0 y:1 -> 上位は既に小さい or 1, 下位は既に越えている or 0, MSBが確定している
  if(f3&&(f1||((1LL<<bit)&L)==0)&&(f2||((1LL<<bit)&R))) res += dfs(bit-1,f1,f2,1);
  // x:1 y:1 MSBが確定、下位はok,上位は既に小さい or 1
  if(f2||((1LL<<bit)&R))res += dfs(bit-1,f1|(((1LL<<bit)&L)==0),f2,1);
  // x:1 y:0 -> NG

  return memo[bit][f1][f2][f3] = res;
}

