     *  x と y の最上位ビットは同じ場所
     *  x & y = x
     *  (x, y) = (1, 1), (0, 1), (0, 0)
     */
    /**
     *  dp[i][j][k][l] 
     *      i: i桁目
     *      j: 0: L == x  / 1: L < x
     *      k: 0: y == R  / 1: y < R
     *      l: 最上位ビットを踏んだ
     */
    static MODINT s_amsqDp[64][2][2][2];

    s_amsqDp[63][0][0][0] = 1;
    for (SDWORD lBit = 62; 0 <= lBit; lBit--) {
        SDWORD lLb = (sqL >> lBit) & 1;
        SQWORD lRb = (sqR >> lBit) & 1;
        for (SDWORD lJ = 0; lJ <= 1; lJ++)
        for (SDWORD lK = 0; lK <= 1; lK++)
        for (SDWORD lMsb = 0; lMsb <= 1; lMsb++) {
