LL dfs(int t, int x, int y, int z) {
	if (t == -1) return 1;

	LL& ans = dp[t][x][y][z];
	if (ans != -1) return ans;

	ans = 0;

	for (int a = 0; a < 2; ++a) {
		for (int b = 0; b <= a; ++b) {
			int t1 = x, t2 = y, t3 = z;

			if (x == 1 && (1LL << t) * a > ((1LL << t) & r))
