			if ((1LL << t) * a < ((1LL << t) & r))
				x = 0;
			if ((1LL << t) * b > ((1LL << t) & l))
				y = 0;
			if (z == 0 && a == b && a == 1)
				z = 1;

			ans += dfs(t - 1, x, y, z);
			ans %= MOD;

			x = t1, y = t2, z = t3;
		}
	}

	return ans;
}

