void calc_b(long long int X) {

	for (int i = 0; i < 70; i++) { b[i] = 0; }

	int q = 1;
	while (X > 0) {
		b[q] = X % 2;
		X /= 2;
		q++;
	}
}


void CALC(long long int X) {

	calc_b(X);

	for (int i = 0; i < 70; i++) {
		for (int j = 0; j < 70; j++) {
			for (int k = 0; k <= 1; k++) {
				dp[i][j][k] = 0;
			}
		}
	}

	dp[69][0][0] = 1;

	for (int i = 68; i >= 1; i--) {
		for (int flag = 0; flag <= 1; flag++) {
			int m;
			if (flag == 1) { m = 1; }
			else { m = b[i]; }

			for (int k = 0; k <= m; k++) {
				for (int num = 0; num < 70; num++) {
					dp[i][num + k][flag | (k < m)] += dp[i + 1][num][flag]; dp[i][num + k][flag | (k < m)] %= MOD;
				}
			}
		}
	}
}

void CALC2(long long int X, int M) {

	calc_b(X);

	for (int i = 0; i < 70; i++) {
		for (int j = 0; j < 70; j++) {
			for (int k = 0; k <= 1; k++) {
				dp[i][j][k] = 0;
			}
		}
	}

	long long int tmp = 0;

	for (int i = 69; i >= M + 1; i--) {
		tmp *= 2;
		tmp += b[i];
	}

	dp[M + 1][0][1] = tmp;
	dp[M + 1][0][0] = 1;


	for (int i = M; i >= 1; i--) {
		for (int flag = 0; flag <= 1; flag++) {
			int m;
			if (flag == 1) { m = 1; }
			else { m = b[i]; }

			for (int k = 0; k <= m; k++) {
				for (int num = 0; num < 70; num++) {
					dp[i][num + k][flag | (k < m)] += dp[i + 1][num][flag]; dp[i][num + k][flag | (k < m)] %= MOD;
				}
			}
		}
	}
}


