ll dp[2][2][2][63];
ll f(int d, int msb, int flagX, int flagY){
  // flagX:=x>L
  // flagY:=y<R
  if(d==-1) return (msb==1);
  if(dp[msb][flagX][flagY][d]>0) return dp[msb][flagX][flagY][d];
  ll ret=0;
  for (int x = 0; x < 2; x++)
  {
    for (int y = 0; y < 2; y++)
    {
      if(x==0 && !flagX && ((L>>d)&1)>0) continue;
      if(y==1 && !flagY && ((R>>d)&1)==0) continue;
      if(x>y) continue;
      if(msb==0 && x!=y) continue;
      int Nmsb = (msb || (x==1 && y==1) );
      int NflagX = (flagX||(((L>>d)&1)<x));
      int NflagY = (flagY||(((R>>d)&1)>y));
      ret+=f(d-1,Nmsb,NflagX,NflagY);
    }
  }
  // vector<ll> dbg={d,msb,flagX,flagY,ret};
  // DBG(dbg)
  return dp[msb][flagX][flagY][d]=ret%mod;
}

