int num1[66],num2[66];
ll dp[66][2][2][2];int isused[66][2][2][2];
ll dfs(int now,int fi,int l1,int l2)
{
    if(now<0)return 1;
    if(isused[now][fi][l1][l2])return dp[now][fi][l1][l2];
    dp[now][fi][l1][l2]=0,isused[now][fi][l1][l2]=1;
    int k1=l1?num1[now]+1:2,k2=l2?num2[now]+1:2;
    rep(i,0,k1)rep(j,0,k2)
    {
        if(fi&&i!=j)continue;
        if(i<j)continue;
        add(dp[now][fi][l1][l2],dfs(now-1,fi&&!i,l1&&(i==num1[now]),l2&&(j==num2[now])));
    }
    return dp[now][fi][l1][l2];
}
ll solve(ll x1,ll x2)
{
    memset(isused,0,sizeof(isused));memset(num1,0,sizeof(num1));memset(num2,0,sizeof(num2));
    int k1=0,k2=0;
    while(x1)num1[k1++]=x1%2,x1/=2;
    while(x2)num2[k2++]=x2%2,x2/=2;
    return dfs(max(k1,k2)-1,1,1,1);
}
