mint dp[61][2][2][2];

mint rec(i64 L, i64 R) {
  rep(i, 61) rep(j, 2) rep(k, 2) rep(l, 2) {
    dp[i][j][k][l] = 0;
  }
  dp[0][0][0][0] = 1;
  rep(i, 60) {
    int keta = 59 - i;
    int Rd = (R >> keta) & 1;
    int Ld = (L >> keta) & 1;

    rep(j, 2) rep(k, 2) rep(l, 2) rep(dx, 2) rep(dz, 2) {
      if (dx == 1 && dz == 1) continue;

      int dy = dx | dz;

      if (j == 0 && Rd < dy) continue;
      if (k == 0 && Ld < dx) continue;
      if (l == 0 && dx < dz) continue;

      int ni = i + 1;
      int nj = (j == 0 && Rd == dy) ? 0 : 1;
      int nk = (k == 0 && Ld == dx) ? 0 : 1;
      int nl = (l == 0 && dx == dz) ? 0 : 1;

      dp[ni][nj][nk][nl] += dp[i][j][k][l];
    }
  }
  mint ret = 0;
  rep(j, 2) rep(k, 2) ret += dp[60][j][k][1];
  return ret;
}

void solve() {
  i64 L, R;
  cin >> L >> R;
  mint ans = rec(R, R) - rec(L - 1, R);
  cout << ans << endl;
}

