constexpr ll mod = 1000000007;
constexpr ll modsize = 0;
vector<ll> fac(modsize);
vector<ll> inv(modsize);
vector<ll> facinv(modsize);

void modcalc() {
	if (modsize == 0) abort();
	fac[0] = 1; fac[1] = 1; inv[1] = 1;
	facinv[0] = 1; facinv[1] = 1;
	for (ll i = 2; i < modsize; i++) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		facinv[i] = facinv[i - 1] * inv[i] % mod;
	}
}

ll modinv(ll a) {
	if (a == 0) abort();
	ll b = mod, u = 1, v = 0;
	while (b) {
		ll t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;
	return u;
}

ll modpow(ll a, ll b) {
	ll ans = 1;
	a %= mod;
	while (b) {
		if (b & 1) ans = ans * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return ans;
}

ll modcomb(ll n, ll k) {
	if (n < 0 || k < 0 || n < k) return 0;
	return fac[n] * facinv[k] % mod * facinv[n - k] % mod;
}

ll modperm(ll n, ll k) {
	if (n < 0 || k < 0 || n < k) return 0;
	return fac[n] * facinv[n - k] % mod;
}

ll modhom(ll n, ll k) {
	if (n < 0 || k < 0 || n == 0 && k > 0) return 0;
	if (n == 0 && k == 0) return 1;
	return fac[n + k - 1] * facinv[k] % mod * facinv[n - 1] % mod;
}

ll solve(ll l, ll r) {
	if (l > r) return 0;
	ll ans = 0;
	ll st = 1;
	while (st < l) st <<= 1;
	ll prev = st;
	bool flag = false; ll coeff = 1;
	while (st <= r) {
		for (ll i = prev; i >= 1; (i >>= 1)) {
			if (st + i <= r + 1) {
				if (flag) {
					coeff *= 2; coeff %= mod; prev = i;
				}
				else prev <<= 1;
				if (i != st) flag = true;
				ll tmp = i; ll cnt = 0;
				while (tmp > 1) {
					tmp >>= 1; cnt++;
				}
				ans += modpow(3, cnt)*coeff % mod;
				if (ans >= mod) ans -= mod;
				st += i;
				break;
			}
		}
	}
	return ans;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(20);

	ll l, r;
	cin >> l >> r;
	ll ans = solve(l, r);
	ll st = 1; ll cnt = 1;
	while (st < l) st <<= 1;
	ans += solve(st / 2, 3 * st / 2 - 1 - l);
	cout << ans % mod << '\n';
}

