using namespace std;

typedef long long ll;

const ll MOD = 1000000007;

ll A, B;
ll D[80][2][2];
bool bit_set(ll n, int k) {
  return n & (1LL << k);
}

ll solve(int n, int less, int greater) {
  if (n == -1) {
    return 1;
  }
  if (D[n][less][greater] != -1) {
    return D[n][less][greater];
  }
  ll res = 0;
  if (less) {
    if (greater) {
      res = (3 * solve(n - 1, 1, 1)) % MOD;
    } else {
      if (bit_set(A, n)) {
        res = solve(n - 1, 1, 0);
      } else {
        res = (solve(n - 1, 1, 1) + 2 * solve(n - 1, 1, 0)) % MOD;
      }
    }
  } else {
    if (greater) {
      if (bit_set(B, n)) {
        res = (solve(n - 1, 1, 1) + 2 * solve(n - 1, 0, 1)) % MOD;
      } else {
        res = solve(n - 1, 0, 1);
      }
    } else {
      if (bit_set(B, n)) {
        if (bit_set(A, n)) {
          res = solve(n - 1, 0, 0);
        } else {
          res = (solve(n - 1, 1, 0) + solve(n - 1, 0, 0) + solve(n - 1, 0, 1)) % MOD;
        }
      } else {
        if (!bit_set(A, n)) {
          res = solve(n - 1, 0, 0);
        }
      }
    }
  }
  return D[n][less][greater] = res;
}

int main() {
  scanf("%lld %lld", &A, &B);
  memset(D, -1, sizeof(D));
  ll res = 0;
  for (int i = 61; i >= 0; i--) {
    ll maxVal = (1LL << (i + 1)) - 1;
    ll minVal = (1LL << i);
    if (minVal <= B && maxVal >= A) {
      if (maxVal < B && minVal > A) {
        res += solve(i - 1, 1, 1);
      } else if (minVal > A) {
        res += solve(i - 1, 0, 1);
      } else if (maxVal < B) {
        res += solve(i - 1, 1, 0);
      } else {
        res += solve(i - 1, 0, 0);
      }
      res %= MOD;
    }
  }
  printf("%lld\n", res);
  return 0;
}

