int dp[100][2][2][2];

void solve(long long L, long long R){
    int res = 0;

    int t = 62;
    dp[t][1][1][1] = 1;

    for(int i = t; i > 0; --i) {
        int ls = (L >> (i - 1)) & 1, rs = (R >> (i - 1)) & 1;

        // 0, 0, 0
        dp[i - 1][0][0][0] += dp[i][0][0][0] * 3 % MOD;
        dp[i - 1][0][0][0] %= MOD;

        // 0, 0, 1
        // This case doesn't exist

        // 1, 0, 0
        dp[i - 1][1][0][0] += (1 + rs) * dp[i][1][0][0] % MOD + rs * (1 - ls) * (dp[i][1][1][1] + dp[i][1][1][0]) % MOD;
        dp[i - 1][1][0][0] %= MOD;

        // 1, 0, 1
        // This case doesn't exist
        if (rs) {
            // 1, 0, 0

            dp[i - 1][0][0][0] += dp[i][1][0][0] * 1 % MOD;
            dp[i - 1][0][0][0] %= MOD;
        }

        // 0, 1, 0
        dp[i - 1][0][1][0] = ((2 - ls) * dp[i][0][1][0] % MOD + ls * dp[i][0][1][1]) % MOD + rs * (1 - ls) * dp[i][1][1][0];
        dp[i - 1][0][1][0] %= MOD;
        if (!ls) {
            // 0, 1, 0
            dp[i - 1][0][0][0] += dp[i][0][1][0] * 1 % MOD;
            dp[i - 1][0][0][0] %= MOD;

            // 0, 1, 1
            dp[i - 1][0][0][0] += dp[i][0][1][1] * 1 % MOD;
            dp[i - 1][0][0][0] %= MOD;
        }


        dp[i - 1][0][1][1] = (1 - ls) * (dp[i][0][1][1] + dp[i][1][1][1] * rs) % MOD;

        if (rs || !ls) {
            // 1, 1, 0
            dp[i - 1][1][1][0] = (dp[i][1][1][0] + dp[i][1][1][1] * rs * ls) % MOD;
        }

        if (rs && !ls) {
        } else if (!rs && !ls) {
            // 1, 1, 1
            dp[i - 1][1][1][1] += dp[i][1][1][1] * 1 % MOD;
            dp[i - 1][1][1][1] %= MOD;

            // 1, 1, 0
        }
    }

    for(int i = 0; i < 2; ++i) for(int j = 0; j < 2; ++j)  {
                res = (res + dp[0][i][j][0]) % MOD;
            }

    cout << res << endl;
}

