int log2(long long a){
	if(a==1)return 0;
	return log2(a/2)+1;
}
long long qiu(long long a,long long b){
	if(a>b)return 0;
	if(a==b)return 1;
	long long c=log2(a);
	long long d=log2(b);
	if(c!=d)return (qiu(a,(1ll<<d)-1)+qiu(1ll<<d,b))%mod;
	if(b<(3ll<<(d-1))){
		return qiu(a-(1ll<<(d-1)),b-(1ll<<(d-1)));
	}
	if(a==(1ll<<d)){
		return (pow3[d-1]+2*qiu(a,b-(1ll<<(d-1))))%mod;
	}
	if(a>=(3ll<<(d-1))){
		return qiu(a-(1ll<<d),b-(1ll<<d));
	}
	return (qiu(a,(3ll<<(d-1))-1)+qiu((3ll<<(d-1)),b)+qiu(a,b-(1ll<<(d-1))))%mod;

}
