long long res(long long len, long long xR, long long yR)
{
    long long mins = (1LL << len) / 2;
    long long maxs = mins * 2 - 1;
    if (mins > xR || mins > yR) return 0;
    long long dp[2][2];
    dp[0][0] = 1;
    dp[0][1] = 0, dp[1][0] = 0, dp[1][1] = 0;
    if (maxs <= xR)
    {
        dp[0][0] = 0, dp[1][0] = 1;
    }
    if (maxs <= yR)
    {
        dp[0][0] = 0, dp[0][1] = 1;
    }
    if (maxs <= xR && maxs <= yR)
    {
        dp[0][0] = 0, dp[0][1] = 0, dp[1][0] = 0, dp[1][1] = 1;
    }
    for (int deg = len - 2; deg >= 0; deg--)
    {
        ll dp2[2][2];
        dp2[0][0] = 0, dp2[1][0] = 0, dp2[0][1] = 0, dp2[1][1] = 0;
        for (int state1 = 0; state1 < 2; state1++)
        {
            for (int state2 = 0; state2 < 2; state2++)
            {
                for (int pu1 = 0; pu1 < 2; pu1++)
                {
                    for (int pu2 = pu1; pu2 < 2; pu2++)
                    {
                        int can = 1;
                        long long digit1 = ((1LL << deg) & xR);
                        long long digit2 = ((1LL << deg) & yR);
                        if (digit1 == 0 && state1 == 0 && pu1 == 1)
                            can = 0;
                        if (digit2 == 0 && state2 == 0 && pu2 == 1)
                            can = 0;
                        if (!can) break;
                        int broke1 = 0, broke2 = 0;

                        if (state1 == 0 && digit1 >= 1 && pu1 == 0)
                            broke1 = 1;
                        if (state2 == 0 && digit2 >= 1 && pu2 == 0)
                            broke2 = 1;

                        dp2[state1 ^ broke1][state2 ^ broke2] += dp[state1][state2];
                    }
                }
            }
        }
        dp[0][0] = dp2[0][0] % MOD;
        dp[1][0] = dp2[1][0] % MOD;
        dp[0][1] = dp2[0][1] % MOD;
        dp[1][1] = dp2[1][1] % MOD;
    }
    return (dp[0][0] + dp[0][1] + dp[1][0] + dp[1][1]) % MOD;
}

