constexpr ll MOD = 1000000007;

ll solve(ll l, ll r, ll n) {
  vector<vecll> dp(n+1, vecll(4, 0));
  REP(flags,4) {
    dp[0][flags] = 1;
  }
  REP(i,n) {
    bool rhi = (r >> i) & 1;
    bool lhi = (l >> i) & 1;
    REP(flags,4) {
      if ((flags & 0b10) || !lhi) {
        int oldflags = flags | rhi;
        dp[i+1][flags] += dp[i][oldflags];
        dp[i+1][flags] %= MOD;
      }
      if (((flags & 0b10) || !lhi) && ((flags & 0b01) || rhi)) {
        int oldflags = flags;
        dp[i+1][flags] += dp[i][oldflags];
        dp[i+1][flags] %= MOD;
      }
      if ((flags & 0b01) || rhi) {
        int oldflags = flags | (!lhi << 1);
        dp[i+1][flags] += dp[i][oldflags];
        dp[i+1][flags] %= MOD;
      }
    }
  }
  return dp[n][0];
}

