int solve(ll l,ll r) {

	dp[61][0][0][0]=1;

	for(int i=61;i>0;i--) {

		for(int a=0;a<2;a++) {

			for(int b=0;b<2;b++) {

				for(int c=0;c<2;c++) {

					// put 1,1

					if(a || (r>>(i-1))&1) 
						dp[i-1][a][b || !((l>>(i-1))&1)][1]=add(dp[i-1][a][b || !((l>>(i-1))&1)][1],dp[i][a][b][c]);

					// put 1,0

					if(c && (b || !((l>>(i-1))&1)) && (a || (r>>(i-1))&1))
						dp[i-1][a][b][c]=add(dp[i-1][a][b][c],dp[i][a][b][c]);

					// put 0,0 

					if((b || !((l>>(i-1))&1)))
						dp[i-1][(a || (r>>(i-1))&1)][b][c]=add(dp[i-1][(a || (r>>(i-1))&1)][b][c],dp[i][a][b][c]);

				}

			}

		}

	}

	int res=0;

	for(int a=0;a<2;a++) {

		for(int b=0;b<2;b++) {

			res=add(res,dp[0][a][b][1]);

		}

	}

	return res;

}

