template <std::uint_fast64_t Modulus> class mint {
public:
  ll a;
  constexpr mint(const ll x = 0) noexcept : a(x % Modulus) {}
  constexpr ll &value() noexcept { return a; }
  constexpr const ll &value() const noexcept { return a; }
  constexpr mint operator+(const mint rhs) const noexcept {
    return mint(*this) += rhs;
  }
  constexpr mint operator-(const mint rhs) const noexcept {
    return mint(*this) -= rhs;
  }
  constexpr mint operator*(const mint rhs) const noexcept {
    return mint(*this) *= rhs;
  }
  constexpr mint operator/(const mint rhs) const noexcept {
    return mint(*this) /= rhs;
  }
  constexpr mint &operator+=(const mint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr mint &operator-=(const mint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr mint &operator*=(const mint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr mint &operator/=(mint rhs) noexcept {
    ll exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};

constexpr ll MOD=1000000007;
void solve(){
  ll L,R; cin>>L>>R;
  auto dp=make_v(2,2,2,mint<MOD>(0)); // dp[msb][mt][lt]
  dp[0][0][0]=1;
  rep(d,60,-1,-1){ // 0-paddingと見て、上からd桁目を見ている
    ll lb=(L>>d)&1,rb=(R>>d)&1;
    auto newdp=make_v(2,2,2,mint<MOD>(0));
    rep(msb,2)rep(mt,2)rep(lt,2)rep(x,2)rep(y,2){
      ll nmsb=msb,nmt=mt,nlt=lt;
      if(x>y) continue;
      // msb
      if((!msb)&&(x!=y)) continue;
      if(x==1&&y==1) nmsb=1;
      // more than L
      if((!mt)&&x<lb) continue;
      if(x>lb) nmt=1;
      // less than R
      if((!lt)&&y>rb) continue;
      if(y<rb) nlt=1;
      newdp[nmsb][nmt][nlt]+=dp[msb][mt][lt];
    }
    dp=newdp;
  }
  mint<MOD> ans=0;
  rep(msb,2)rep(mt,2)rep(lt,2) ans+=dp[msb][mt][lt];
  cout<<ans.a<<"\n";
}

