const int MOD = (int)1e9 + 7;
const int BITS = 63;

int add(int x, int y) {
	return (x + y >= MOD ? x + y - MOD : x + y);
}

int mult(int x, int y) {
	return (x * 1LL * y) % MOD;
}

vector<int> convert(ll number) {
	vector<int> rez(BITS);

	for(int i = 0; i < BITS; ++i) {
		rez[BITS - 1 - i] = number & 1;
		number /= 2;
	}

	return rez;
}

int first_one(const vector<int>& seq) {
	for(int i = 0; i < len(seq); ++i) {
		if(seq[i] == 1) {
			return i;
		}
	}

	return NIL;
}

int pow3[BITS];

void precalc() {
	pow3[0] = 1;

	for(int i = 1; i < BITS; ++i) {
		pow3[i] = mult(3, pow3[i - 1]);
	}
}

void solve() {
	auto L = convert(fetch<ll>() - 1);
	auto R = convert(fetch<ll>() + 1);
	int answ = 0;

	DBG(L); DBG(R);

	for(int i = 0; i < BITS; ++i) {
		if(L[i] == 1) {
			continue;
		}

		for(int j = 0; j < BITS; ++j) {
			if(R[j] == 0) {
				continue;
			}

			vector<int> x(BITS, NIL), y(BITS, NIL);

			for(int k = 0; k < i; ++k) {
				x[k] = L[k];
			}

			x[i] = L[i] ^ 1;

			for(int k = 0; k < j; ++k) {
				y[k] = R[k];
			}

			y[j] = R[j] ^ 1;
			int lt = 1;

			for(int k = 0; k < BITS; ++k) {
				if(x[k] == 1 && y[k] == 0) {
					lt = 0;
					break;
				}
			}

			int fstx = first_one(x);
			int fsty = first_one(y);

			if(lt && (fstx == fsty || fstx == NIL || fsty == NIL)) {
				DBG(x); DBG(y);
				vector<int> dp(BITS + 1, 1);

				for(int i = BITS - 1; i >= 0; --i) {
					dp[i] = 0;

					for(int xb = 0; xb <= 1; ++xb) {
						for(int yb = xb; yb <= 1; ++yb) {
							if((x[i] == xb || x[i] == -1) && (y[i] == yb || y[i] == -1)) {
								dp[i] = add(dp[i], dp[i + 1]);
							}
						}
					}
				}

				for(int k = 0; k < BITS; ++k) {
					if(x[k] != 0 && y[k] != 0) {
						answ = add(answ, dp[k + 1]);
					}

					if(x[k] == 1 || y[k] == 1) {
						break;
					}
				}
			}
		}
	}

	cout << answ << '\n';
}

int main() {
	fast_io();

	precalc();
	solve();

	return 0;
}

#include "bits/stdc++.h"
using namespace std;

const long long MOD = 1000000007;

long long LDP(long long N) {
	long long COUNT = 0, BIT[64] = {};
	for (int i = 0; i < 64; i++) {
		BIT[i] = N % 2;
		N /= 2;
	}
	long long Cur = 1, END = 0;
	for (int i = 0; i < 64; i++) {
		if (BIT[i] == 1) {
			END = Cur;
			Cur *= 1;
			Cur %= MOD;
		}
		else {
			Cur *= 2;
			Cur %= MOD;
		}
	}
	COUNT = END;
	bool flag = true;
	for (int i = 63; i >= 0; i--) {
		if (BIT[i] == 0) continue;
		Cur = 1, END = 0;
		if (flag) {
			for (int j = 0; j < i; j++) {
				COUNT += Cur;
				COUNT %= MOD;
				Cur *= 3;
				Cur %= MOD;
			}
			flag = false;
			continue;
		}
		for (int j = 0; j < 64; j++) {
			if (j < i) {
				Cur *= 3;
				Cur %= MOD;
			}
			else {
				if (BIT[j] == 1 && i != j) {
					END = Cur;
					Cur *= 1;
					Cur %= MOD;
				}
				else {
					Cur *= 2;
					Cur %= MOD;
				}
			}
		}
		COUNT += END;
		COUNT %= MOD;
	}
	return COUNT;
}

long long RDP(long long N) {
	long long COUNT = 0, BIT[64] = {};
	for (int i = 0; i < 64; i++) {
		BIT[i] = N % 2;
		N /= 2;
	}
	long long Cur = 1, END = 0;
	for (int i = 0; i < 64; i++) {
		if (BIT[i] == 1) {
			END = Cur;
			Cur *= 2;
			Cur %= MOD;
		}
		else {
			Cur *= 1;
			Cur %= MOD;
		}
	}
	COUNT = END;
	bool flag = true;
	for (int i = 63; i >= 0; i--) {
		if (BIT[i] == 0) continue;
		Cur = 1, END = 0;
		if (flag) {
			for (int j = 0; j < i; j++) {
				COUNT += Cur;
				COUNT %= MOD;
				Cur *= 3;
				Cur %= MOD;
			}
			flag = false;
			continue;
		}
		for (int j = 0; j < 64; j++) {
			if (j < i) {
				Cur *= 3;
				Cur %= MOD;
			}
			else {
				if (BIT[j] == 1 && i != j) {
					END = Cur;
					Cur *= 2;
					Cur %= MOD;
				}
				else {
					Cur *= 1;
					Cur %= MOD;
				}
			}
		}
		COUNT += END;
		COUNT %= MOD;
	}
	return COUNT;
}

int main() {
	long long L, R;
	cin >> L >> R;
	if (L == R) {
		cout << 1 << endl;
		return 0;
	}
	while (1) {
		long long LMBS = 1, RMBS = 1;
		while (L > LMBS * 2) LMBS *= 2;
		while (R > RMBS * 2) RMBS *= 2;
		if (LMBS != RMBS) break;
		if (L == LMBS || R == RMBS) break;
		L -= LMBS;
		R -= RMBS;
	}
	cout << (RDP(R) - LDP(L - 1) + MOD) % MOD << endl;
}

