int fm(int l){//x>=lのf(a),ただしaはlの最上位bit
  //cout<<"L:"<<l<<endl;
  string s;int cnt=0,res=0,now=0;
  while(l){
    if(l&1)s+="1";
    else s+="0",cnt++;
    l>>=1;
  }
  res=pw(2,cnt);
  for(char p:s){
    if(p=='0')res+=pw(3,now)*pw(2,--cnt)%MOD;res%=MOD;
    now++;
  }
  return res;
}
int FM(int r){//y<=r
  //cout<<"R:"<<r<<endl;
  string s;int cnt=0,res=0,now=0;
  while(r){
    if(r&1)s+="1",cnt++;
    else s+="0";
    r>>=1;
  }
  res=pw(2,cnt-1);
  for(char p:s){
    if(now==s.size()-1)continue;
    if(p=='1')res+=pw(2,--cnt-1)*pw(3,now)%MOD;res%=MOD;
    now++;
  }
  return res;
}
int fm2(string s){//x<=lのf(a)
  int cnt=0,res=0,now=0;
  for(char p:s)cnt+=(p=='0');
  res=pw(2,cnt);
  reverse(s.begin(),s.end());
  for(char p:s){
    if(p=='1')res+=pw(3,now)*pw(2,cnt+1)%MOD;
    else cnt--;
    now++;res%=MOD;
  }
  return res;
}
int FM2(string t){//y>=r
  int cnt=0,res=0,now=0;
  for(auto p:t)cnt+=(p=='1');
  reverse(t.begin(),t.end());
  res=pw(2,cnt);
  for(char p:t){
    if(p=='0')res+=pw(2,cnt+1)*pw(3,now)%MOD;
    else cnt--;
    now++;res%=MOD;
  }
  return res;
}
