  vector<char> bR = tobin(R);
  int szL = bL.size();
  int szR = bR.size();

  function<bool(int)> breakable = [&](int i) {
    return i == 0 || (bR.at(i-1) == 1 && bL.at(i-1) == 0);
  };

  Fp cnt = 0;
  if (szR == szL) {
    for (int i = szR - 1; i >= 0; i--) {
