	  Fp sc = 1;
	  for (int p = i - 2; p >= j; p--) if (bL.at(p) == 0) sc *= 2;
	  for (int p = j - 2; p >= 0; p--) sc *= 3;
	  cnt += sc;
	}
      }
    }
  }else { // szR > szL
    // cases where MSB of x == szR-1
    for (int i = szR - 1; i >= 0; i--) {
      if (!(i == 0 || bR.at(i-1) == 1)) continue;
      Fp sc = 1;
      for (int p = szR - 2; p >= i; p--) if (bR.at(p) == 1) sc *= 2;
      for (int p = i - 2; p >= 0; p--) sc *= 3;
      cnt += sc;
    }
    // cases where szL-1 < MSB of x < szR-1
    for (int i = szR - 2; i > szL - 1; i--) {
      Fp sc = 1;
      for (int p = i - 1; p >= 0; p--) sc *= 3;
      cnt += sc;
    }
    // cases where MSB of x == szL-1
    for (int i = szL - 1; i >= 0; i--) {
      if (!(i == 0 || bL.at(i-1) == 0)) continue;
      Fp sc = 1;
      for (int p = szL - 2; p >= i; p--) if (bL.at(p) == 0) sc *= 2;
      for (int p = i - 2; p >= 0; p--) sc *= 3;
      cnt += sc;
    }
  }
  cout << cnt << endl;

  return 0;
