int main() {
  // l <= x <= y <=r, x == x&yとなる(x,y)の個数を求める
  // 桁dpでいい感じに求められそう?
  ll l, r; cin >> l >> r;
  // cerr << l << " " << r << endl;
  dp[60][0][0][0] = 1;
  for (int i = 60; i > 0; --i) {
    int dl = (l >> (i-1)) & 1;
    int dr = (r >> (i-1)) & 1;
    for (int dx = 0; dx < 2; ++dx) {
      for (int dy = 0; dy < 2; ++dy) {
        if (dx == 1 && dy == 0) continue;
        // (1, 1, 1)
        {
          int nl = 1, nr = 1, nc = 1;
          dp[i-1][nl][nr][nc] += dp[i][1][1][1];
        }
        // (1, 1, 0)
        if (dx != 0 || dy != 1) {
          int nl = 1, nr = 1, nc = 0;
          if (dx == 1 && dy == 1) nc = 1;
          dp[i-1][nl][nr][nc] += dp[i][1][1][0];
        }
        // (1, 0, 1)
        if (dy <= dr) {
          int nl = 1, nr = 0, nc = 1;
          if (dy < dr) nr = 1;
          dp[i-1][nl][nr][nc] += dp[i][1][0][1];
        }
        // (1, 0, 0)
        if ((dx != 0 || dy != 1) && dy <= dr) {
          int nl = 1, nr = 0, nc = 0;
          if (dy < dr) nr = 1;
          if (dx == 1 && dy == 1) nc = 1;
          dp[i-1][nl][nr][nc] += dp[i][1][0][0];
        }
        // (0, 1, 1)
        if (dx >= dl) {
          int nl = 0, nr = 1, nc = 1;
          if (dx > dl) nl = 1;
          dp[i-1][nl][nr][nc] += dp[i][0][1][1];
        }
        // (0, 1, 0)
        if ((dx != 0 || dy != 1) && dx >= dl) {
          int nl = 0, nr = 1, nc = 0;
          if (dx > dl) nl = 1;
