void f(vector<vector<vector<mint>>>& dp, long long x) {
	int p = 0;
	while (x >= (1ll << p)) p++;
	dp[1][p][0] = 1;
	for (int i = p; i > 0; i--) {
		for (int k = 0; k < p; k++) {
			dp[0][i - 1][k] += dp[0][i][k];
			dp[0][i - 1][k + 1] += dp[0][i][k];
			if (x & (1ll << (i - 1))) {
				dp[1][i - 1][k + 1] += dp[1][i][k];
				dp[0][i - 1][k] += dp[1][i][k];
			} else {
				dp[1][i - 1][k] += dp[1][i][k];
			}
		}
	}
}

template <class T> T fastpow(T a, long long p) {
	T tmp = a;
	T ret = 1;
	while (p) {
		if (p & 1) ret *= tmp;
		p >>= 1;
		tmp = tmp * tmp;
	}
	return ret;
}

