	if(x >= l)
		return solvey(bit, y, r);
	return (solve(bit - 1, x, y, l, r) + solve(bit - 1, x , y | (1ll << bit), l, r) + solve(bit - 1, x | (1ll << bit), y | (1ll << bit), l, r)) % mod;
}
int main()
{
	p3[0] = 1;
	for(int i = 1; i < 100; i++)
		p3[i] = p3[i - 1] * 3 % mod;
	cin >> l >> r;
	for(int i = 0; i <= 60; i++)
		ans = (ans + solve(i - 1, (1ll << i), (1ll << i), l, r)) % mod;
	cout << ans;
	return 0;
}

