	for ( int i = 0; i < 60; i++ ){
		ct += count( 1LL<<i, 1LL<<i, (1LL<<i)-1, i );
	}
	//cout << call_ct << "/ 0:" << call_0 << " 1:" << call_1 << " n:" << call_n << endl;
