const int K = 60;
int low[K], high[K];
int dp[K][2][2][2][2];
int highest;

void add(int& x, int y) {
  x += y;
  if (x >= MOD) x -= MOD;
}

int solve(int pos, bool one, bool tight, bool tight_low, bool tight_high) {
  if (pos < 0) {
    return 1;
  }
  // trace(pos, low[pos], high[pos], tight_low, tight_high);
  int& ret = dp[pos][one][tight][tight_low][tight_high];
  if (ret >= 0) return ret;
  ret = 0;
  for (int i = 0; i < 2; ++i) {
    for (int j = 0; j < 2; ++j) {
      if (tight_high && i > high[pos]) continue;
      if (tight_low && j < low[pos]) continue;
      if (!one && i != j) continue;
      if (i < j) continue;
      bool nxt_tight_low = tight_low && j == low[pos];
      bool nxt_tight_high = tight_high && i == high[pos];
      bool nxt_tight = tight && i == j;
      bool nxt_one = one || (i == 1 && j == 1);
      add(ret, solve(pos - 1, nxt_one, nxt_tight, nxt_tight_low,
                     nxt_tight_high));
    }
  }
  return ret;
}

