        t1 *= 3;
        t1 %= mod;
        t1 += t2;
        t1 %= mod;
        t2 *= 2;
        t2 %= mod;
      }
    }
    ans += t1;
    ans %= mod;
    ans += t2;
    ans %= mod;
  } else {
    int64_t t1 = 1, t2 = 0, t3 = 0, t4 = 0;
    // no, l-free, r-free, free.
    // r -- l
    for (int64_t i = l_msb - 1; 0 <= i; i--) {
      t4 *= 3;
      t4 %= mod;
      if (l_b[i] && r_b[i]) {
        t4 += t3;
        t4 %= mod;
        t3 *= 2;
        t3 %= mod;
      } else if (l_b[i] && !r_b[i]) {
        t4 += t3;
        t4 %= mod;
        t3 *= 2;
        t3 %= mod;
        t4 += t2;
        t4 %= mod;
        t2 *= 2;
        t2 %= mod;

        t3 += t1;
        t3 %= mod;
        t2 += t1;
        t2 %= mod;

      } else if (!l_b[i] && r_b[i]) {
        t1 = 0;
      } else {
        t4 += t2;
        t4 %= mod;
        t2 *= 2;
        t2 %= mod;
      }
    }
    ans += t1;
    ans %= mod;
    ans += t2;
    ans %= mod;
    ans += t3;
    ans %= mod;
    ans += t4;
    ans %= mod;
  }

  std::cout << ans << std::endl;

  return 0;
}

