const int Mod = 1000000007;
long long bit[61], pow[61];

long long recursion(long long L, long long R)
{
	int i, j;
	if (L > R) return 0;
	else if (L == R) return 1;
	else if (L == 0) {
		for (i = 0; bit[i] <= R; i++);
		return (recursion(0, R ^ bit[i-1]) * 2 + pow[i-1]) % Mod;
	} else {
		for (i = 0; bit[i] <= L; i++);
		for (j = 0; bit[j] <= R; j++);
		if (i == j) return recursion(L ^ bit[i-1], R ^ bit[j-1]);
		else return (recursion(0, R ^ bit[j-1]) + recursion(L, R ^ bit[j-1]) + recursion(0, L ^ (bit[j-1] - 1))) % Mod;
	}
}

