{
	long long L, R;
	scanf("%lld %lld", &L, &R);

	int i, j, k;
	long long ans;
	for (i = 1, bit[0] = 1, pow[0] = 1; i <= 60; i++) {
		bit[i] = bit[i-1] << 1;
		pow[i] = pow[i-1] * 3 % Mod;
	}
	for (i = 0; bit[i] <= L; i++);
	for (j = 0; bit[j] <= R; j++);
	if (i == j) ans = recursion(L ^ bit[i-1], R ^ bit[j-1]);
	else {
		ans = recursion(0, L ^ (bit[i] - 1)) + recursion(0, R ^ bit[j-1]);
		for (k = i + 1; k < j; k++) ans += pow[k-1];
		ans %= Mod;
	}
	printf("%lld\n", ans);
	fflush(stdout);
	return 0;
}

