long long dgdp(long long xl,long long yl){
  long long dp[2][2]={0},ndp[2][2]={0},i,j,k,xf,yf,xt,yt;
  for(i=62;i>=0;i--){
    if((xl&(1ll<<i))!=0){xf=1;}else{xf=0;}
    if((yl&(1ll<<i))!=0){yf=1;}else{yf=0;}
    for(j=0;j<=1;j++){
      for(k=0;k<=1;k++){
        if(j==1 && k==0){continue;}
        if(xf==1 && j==0){xt=0;}
        else if(xf==0 && j==1){xt=-1;}
        else{xt=1;}
        if(yf==1 && k==0){yt=0;}
        else if(yf==0 && k==1){yt=-1;}
        else{yt=1;}
        ndp[0][0]+=dp[0][0];
        if(yt!=-1){ndp[0][yt]+=dp[0][1];}
        if(xt!=-1){ndp[xt][0]+=dp[1][0];}
        if(xt!=-1&&yt!=-1){ndp[xt][yt]+=dp[1][1];}
      }
    }
    for(j=0;j<=1;j++){
      for(k=0;k<=1;k++){
        dp[j][k]=ndp[j][k]%mod;
        ndp[j][k]=0;
      }
    }
    if((1ll<<(i+1))-1 <= xl){xf=0;}
    else if((1ll<<i) <= xl){xf=1;}
    else{xf=-1;}
    if((1ll<<(i+1))-1 <= yl){yf=0;}
    else if((1ll<<i) <= yl){yf=1;}
    else{yf=-1;}
    if(xf!=-1 && yf!=-1){dp[xf][yf]++;}
  }
  return (dp[0][0]+dp[0][1]+dp[1][0]+dp[1][1])%mod;
}

