lint solve(int pos, bool left, bool right, bool msb) {
    // printf("%d %d %d %d\n", pos, left, right, msb);
    if (pos == -1)
        return 1;
    lint &ret = memo[pos][left][right][msb];
    if (ret != -1)
        return ret;
    ret = 0LL;
    bool lb = (L & (1LL << pos)) ? false : true;
    bool rb = (R & (1LL << pos)) ? true : false;
    // x0, y0
    if (left || lb)
        ret += 1LL * solve(pos - 1, left, rb ? 1 : right, msb);
    // x0, y1
    if ((left || lb) && (right || rb) && msb)
        ret += 1LL * solve(pos - 1, left, right, msb);
    // x1, y1
    if (right || rb)
        ret += 1LL * solve(pos - 1, lb ? 1 : left, right, 1);
    ret %= mod;
    return ret;
}

