					for(int s = 0; s < 2; s++) {

						long pre = dp[i][j][k][s];

						int lb = (l >> i) & 1;
						int rb = (r >> i) & 1;

						int nj = j;
						int nk = k;
						int ns = s;

						for(int x = 0; x < 2; x++) {
							for(int y = 0; y < 2; y++) {
								if(x == 1 && y == 0) {
									continue;
								}


								if(x == 1 && y == 1) {
									ns = 1;
								}

								if(j == 0 && lb == 1 && x == 0) {
									continue;
								}

								if(k == 0 && rb == 0 && y == 1) {
									continue;
								}


								if(lb == 0 && x == 1) {
									nj = 1;
								}

								if(rb == 1 && y == 0) {
									nk = 1;
								}


								dp[i][nj][nk][ns] = (dp[i][nj][nk][ns] + pre) % mod;
							}
						}
					}
				}
			}

		}

		long ans = 0;
		for(int j = 0; j < 2; j++) {
			for(int k = 0; k < 2; k++) {
				for(int s = 0; s < 2; s++) {
					ans = (ans + dp[0][j][k][s])%mod;
				}
			}
		}

		System.out.println(ans);
	}



