public class Main {
    static long[][][][] dp = new long[64][2][2][2];
    static long l, r;
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        l = fsc.nextLong();
        r = fsc.nextLong();
        for (int i = 0; i < 64; i++) {
            for (int gt = 0; gt < 2; gt++) {
                for (int lt = 0; lt < 2; lt++) {
                    for (int msb = 0; msb < 2; msb++) {
                        dp[i][gt][lt][msb] = -1;
                    }
                }
            }
        }
        System.out.println(dp(0, 0, 0, 0));
    }

    public static long dp(int i, int gt, int lt, int msb) {
        if (i >= 64) {
            return 1;
        }
        if (dp[i][gt][lt][msb] >= 0) {
            return dp[i][gt][lt][msb];
        }
        long ret = 0;
        boolean x0 = gt == 1 || ((1l << (63 - i)) & l) == 0;
        boolean y1 = lt == 1 || ((1l << (63 - i)) & r) != 0;
        // x: 0, y: 0
        if (x0) {
            ret += dp(i + 1, gt, ((1l << (63 - i)) & r) != 0 ? 1 : lt, msb);
        }
        // x: 0, y: 1
        if (msb == 1 && x0 && y1) {
            ret += dp(i + 1, gt, lt, msb);
        }
        // x: 1, y: 1
        if (y1) {
            ret += dp(i + 1, ((1l << (63 - i)) & l) == 0 ? 1 : gt, lt, 1);
        }
        return dp[i][gt][lt][msb] = ret % Const.MOD;
    }
}


class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) {
            return buffer[ptr++];
        } else {
            return -1;
        }
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
            ptr++;
        }
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

