public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC138 F問題
		 * 考察メモ
		 * え、x xor yは加算に近い値だよなー(繰り上がりが無いだけなので)
		 * これがyをxで割った余りになる、ということは？
		 * 仮にyがxより1bit以上大きかったとすると、xorの方はそのbitが残り、割った余りには当該bitがない
		 * よってyはxの2倍より小さい
		 * よってy<x<2yが成り立つので、yをxで割った余りはつまりy-xに等しい
		 * あ、x=yなら問題ないよ、これは正しく答えになる(x%y=x^y=0)
		 * つまりy-x=y^xなので
		 * 次にマイナスをbit演算で解釈してみよう
		 * 引き算というのは、符号反転にほぼ等しいと考えることができる
		 * 変わるのは繰り下がり処理なので、つまり次のような問題とできる
		 * 1. yとxは同じbit数で、最上位bitは(自明だが)1である
		 * 2. (yの方が大きいので)あるbitで、yが1でありxが0であるものが存在する
		 * 3. (繰り下がりが無いので)そのあとの値は全て等しい
		 * よって、まず最初のbit数(32通り?)、次の変わる部分を調べる
		 * この時残りの値は簡単な計算で出せるので終わり
		 *
		 */
		long L = io.nextLong(), R = io.nextLong();
		ModInteger ans = new ModInteger(1000000007);
		for (int i = 1;(1L << i) <= R;++ i) { // iが最上位bit
			for (int j = 0;j < i;++ j) { // jがyの方を真に大きくするbit
				// この時、空きbit列については互いに等しい値が入る
				// これが、L以上R以下であるようになっていればいい
				// まず、L以上となるような値の個数を求め、次にR以下になるような個数を求めれば良いはず
				long big = (1L << i) | (1L << j);
				long small = (2L << i) - 1;
				small ^= 1L << j;
				//io.println("s:" + small + ", b:" + big +"," + (1 << i) + ":" + (1 << j));
				for (int k = i;k >= 0;-- k) {
					if (k == i || k == j) continue;
					if ((big | 1L << k) <= R) big |= 1L << k;
					if ((small ^ 1L << k) >= L) small ^= 1L << k;
				}
				if (small < L || big > R) continue;
				//io.println("s:" + small + ", b:" + big);
				long min = (small & (1L << j) - 1) | (small & (1L << i) - (2L << j)) >> 1;
				long max = (big & (1L << j) - 1) | (big & (1L << i) - (2L << j)) >> 1;
				//io.println(min + "," + max);
				ans.addEqual(max - min + 1);
			}
		}
		io.println(ans.addEqual(R - L + 1));
	}

