class Sol{
	public void Solve(){

		// xを固定すると
		//        x = 1, x = 2, x = 3, x = 4
		// y % x      0,     0,     0,     0
		// y % x             1,     1,     1
		// y % x                    2,     2
		// y % x                           3
		// 
		// なので
		// y % x == y ^ x == i なら yの候補は y == i ^ x に一意に定まり
		//        x = 1, x = 2, x = 3, x = 4
		// y        0^1,   0^2,   0^3,   0^4
		// y               1^2,   1^3,   1^4
		// y                      2^3,   2^4
		// y                             3^4
		// 
		// のなかで y % x == y ^ x であって L<=x<=y<=R となっているものを数えればよい
		//  y % x == y ^ x　は ∃nであって y - n * x == y ^ x が成り立てばよいが
		//    これは xの最上位ビットに着目すると n > 1 では常に成り立たない 
		//    n == 1 の時は y - x == y ^ x でありこれは y ⊇ x に置き換わる．
		// 
		// (i, j) in range(0,inf) * range(0,inf)を持ってきて
		//  x = i, y = j ^ i　と書けば，(i, j)の満たすべき条件は
		//     L <= i     (L <= x)
		//     i <= j ^ i (x <= y)
		//     j ^ i <= R (y <= R)
		//     j < i
		//     j ^ i ⊇ i (y ⊇ x)
		//  の5つであり，これらは全てdigit eventで判定できるので，桁dpをする．


		// dp[state]:
		//   stateは (L < x) << 3 | (x < y) << 2 | (y < R) << 1 | (j < i) << 0
		//   各ビット0は等号で保留している

		int M = 60;
		var dp = new mlong[1 << 4];  
		dp[0] = 1;

		for(int d = M; d >= 0; d--){
			var ndp = new mlong[1 << 4];
			for(int i=0;i<2;i++){
				for(int j=0;j<2;j++){
					for(int s=0;s<1<<4;s++){
						int x = i;
						int y = i ^ j;
						int l = (int)((L >> d) & 1);
						int r = (int)((R >> d) & 1);

						if(y < x) continue;

						int[] sbit = new int[4];
						for(int k=0;k<4;k++) sbit[k] = (s >> k) & 1;
						int ns = s;

						if(sbit[3] == 0 && l > x) continue;
						if(sbit[2] == 0 && x > y) continue;
						if(sbit[1] == 0 && y > r) continue;
						if(sbit[0] == 0 && j > i) continue;

						if(sbit[3] == 0 && l < x) ns |= 1 << 3;
						if(sbit[2] == 0 && x < y) ns |= 1 << 2;
						if(sbit[1] == 0 && y < r) ns |= 1 << 1;
						if(sbit[0] == 0 && j < i) ns |= 1 << 0;

						ndp[ns] += dp[s];
					}
				}
			}
			dp = ndp;
		}

		// OK部分だけを足す．L <= x, x <= y, y <= R, j < i
		mlong ans = 0;
		for(int s=0;s<1<<4;s++){
			if(((s >> 0) & 1) == 0) continue;
			ans += dp[s];
		}
		Console.WriteLine(ans);


	}

