class Program {
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    const int M2 = 998244353;
    const long LM = 1L << 60;
    const double eps = 1e-11;
    static void Main(string[] args)
    {
        long l, r;
        sc.Multi(out l, out r);
        long ans = 0;
        for (int i = 0; i < 60; i++)
        {
            long b = 1L << i;
            if (l <= b * 2 - 1 && b <= r) {
                var dp = new long[2][];
                dp[0] = new long[2];
                dp[1] = new long[2];

                int s = 0, t = 0;
                if (b * 2 > r) s = 1;
                if (b <= l) t = 1;
                dp[s][t] = 1;
                for (int j = i - 1; j >= 0; j--)
                {
                    var nex = new long[2][];
                    nex[0] = new long[2];
                    nex[1] = new long[2];
                    long rr = (r >> j) & 1;
                    long ll = (l >> j) & 1;
                    if (rr == 1 && ll == 1) {
                        nex[0][0] = (dp[0][0] * 3 + dp[1][0]) % M;
                        nex[1][0] = dp[1][0] * 2 % M;
                        nex[0][1] = dp[0][1];
                        nex[1][1] = dp[1][1];
                    }
                    else if (rr == 1 && ll == 0) {
                        nex[0][0] = (dp[0][0] * 3 + dp[1][0] + dp[0][1]) % M;
                        nex[1][0] = (dp[1][0] * 2 + dp[1][1]) % M;
                        nex[0][1] = (dp[0][1] * 2 + dp[1][1]) % M;
                        nex[1][1] = dp[1][1];
                    }
                    else if (rr == 0 && ll == 1) {
                        nex[0][0] = dp[0][0] * 3 % M;
                        nex[1][0] = dp[1][0] % M;
                        nex[0][1] = dp[0][1] % M;
                    }
                    else {
                        nex[0][0] = (dp[0][0] * 3 + dp[0][1]) % M;
                        nex[1][0] = dp[1][0];
                        nex[0][1] = dp[0][1] * 2 % M;
                        nex[1][1] = dp[1][1];
                    }
                    dp = nex;
                }
                for (int j = 0; j < 2; j++)
                {
                    for (int k = 0; k < 2; k++)
                    {
                        ans = (ans + dp[j][k]) % M;
                    }
                }
            }
        }
        Prt(ans);
        sw.Flush();
    }

