            var scanner = new IO.StreamScanner(Console.OpenStandardInput());
            var l = scanner.Long();
            var r = scanner.Long();

            var ans = GetAns(l, r);
            IO.Printer.Out.WriteLine(ans);
            IO.Printer.Out.Flush();
        }

        public static long GetAns(long l, long r)
        {
            var mod = 1000000007L;

            var lAns = GetAns(l - 1);
            var rAns = GetAns(r);

            return (rAns - lAns + mod) % mod;
        }

        public static long GetAns(long r)
        {
            var mod = 1000000007L;

            var wk = r;
            var digit = 0;
            while(wk != 0L)
            {
                digit++;
                wk /= 10L;
            }

            var dp = new long[digit + 1, 2];
            dp[0, 0] = 1;
            for (int i = 0; i < digit; i++)
            {
                var bit = r % 10;

                for (int val = 0; val <= 9; val++)
                {
                    // under
                    dp[i + 1, 0] += dp[i, 0];
                    dp[i + 1, 0] %= mod;

                    // just
                    if (val < bit)
                    {
                        // just
                        dp[i + 1, 0] += dp[i, 1];
                        dp[i + 1, 0] %= mod;
                    }
                    else if (val == bit)
                    {
                        // just
                        dp[i + 1, 1] += dp[i, 1];
                        dp[i + 1, 1] %= mod;
                    }
                }

                r /= 10;
            }

            return (dp[digit, 0] + dp[digit, 1]) % mod;
        }
    }


