class F
{
	static void Main()
	{
		var a = Console.ReadLine().Split().Select(long.Parse).ToArray();
		long L = a[0], R = a[1];

		BigInteger c = 0;
		pow2 = new long[61];
		pow3 = new BigInteger[61];
		pow2[0] = 1;
		pow3[0] = 1;
		for (var i = 1; i <= 60; pow2[i] = 2 * pow2[i - 1], pow3[i] = 3 * pow3[i - 1], i++) ;

		for (int i = 0; i < 60; i++)
		{
			var p2l = pow2[i];
			var p2r = pow2[i + 1] - 1;

			if (R < p2l) break;
			if (p2r < L) continue;
			if (L <= p2l && p2r <= R) { c += pow3[i]; continue; }

			if (p2r <= R)
			{
				for (var x = L; x <= p2r; c += pow2[CountBit(x, false, i - 1)], x++) ;
			}
			else if (L <= p2l)
			{
				c += SumCount(R - p2l + 1, i - 1);
			}
			else
			{
				for (var x = L; x <= R; x++)
					for (var y = x; y <= R; y++)
						if (y - x == (y ^ x)) c++;
			}
		}
		Console.WriteLine(c % 1000000007);
	}

	static long[] pow2;
	static BigInteger[] pow3;

	static int CountBit(long v, bool f, int maxBit)
	{
		var c = 0;
		var b = new BitArray(new[] { (int)v, (int)(v >> 32) });
		for (var i = 0; i <= maxBit; i++) if (b[i] == f) c++;
		return c;
	}

	static BigInteger SumCount(long max, int maxBit)
	{
		BigInteger c = 0;
		var b = new BitArray(new[] { (int)max, (int)(max >> 32) });
		for (int c2 = 0, i = maxBit; i >= 0; i--) if (b[i]) c += pow2[c2++] * pow3[i];
		return c;
	}
}

using System;

#region ModInt

/// <summary>
/// [0,<see cref="Mod"/>) までの値を取るような数
/// </summary>
public struct ModInt
{
    /// <summary>
    /// 剰余を取る値．
    /// </summary>
    public const long Mod = (int) 1e9 + 7;

    /// <summary>
    /// 実際の数値．
    /// </summary>
    public long num;

    /// <summary>
    /// 値が <paramref name="n"/> であるようなインスタンスを構築します．
    /// </summary>
    /// <param name="n">インスタンスが持つ値</param>
    /// <remarks>パフォーマンスの問題上，コンストラクタ内では剰余を取りません．そのため，<paramref name="n"/> ∈ [0,<see cref="Mod"/>) を満たすような <paramref name="n"/> を渡してください．このコンストラクタは O(1) で実行されます．</remarks>
    public ModInt(long n)
    {
        num = n;
    }

    /// <summary>
    /// このインスタンスの数値を文字列に変換します．
    /// </summary>
    /// <returns>[0,<see cref="Mod"/>) の範囲内の整数を 10 進表記したもの．</returns>
    public override string ToString()
    {
        return num.ToString();
    }

    public static ModInt operator +(ModInt l, ModInt r)
    {
        l.num += r.num;
        if (l.num >= Mod) l.num -= Mod;
        return l;
    }

    public static ModInt operator -(ModInt l, ModInt r)
    {
        l.num -= r.num;
        if (l.num < 0) l.num += Mod;
        return l;
    }

    public static ModInt operator *(ModInt l, ModInt r)
    {
        return new ModInt(l.num * r.num % Mod);
    }

    public static implicit operator ModInt(long n)
    {
        n %= Mod;
        if (n < 0) n += Mod;
        return new ModInt(n);
    }

    /// <summary>
    /// 与えられた 2 つの数値からべき剰余を計算します．
    /// </summary>
    /// <param name="v">べき乗の底</param>
    /// <param name="k">べき指数</param>
    /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
    public static ModInt Pow(ModInt v, long k)
    {
        return Pow(v.num, k);
    }

    /// <summary>
    /// 与えられた 2 つの数値からべき剰余を計算します．
    /// </summary>
    /// <param name="v">べき乗の底</param>
    /// <param name="k">べき指数</param>
    /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
    public static ModInt Pow(long v, long k)
    {
        long ret = 1;
        for (k %= Mod - 1; k > 0; k >>= 1, v = v * v % Mod)
            if ((k & 1) == 1)
                ret = ret * v % Mod;
        return new ModInt(ret);
    }

    /// <summary>
    /// 与えられた数の逆元を計算します．
    /// </summary>
    /// <param name="v">逆元を取る対象となる数</param>
    /// <returns>逆元となるような値</returns>
    /// <remarks>法が素数であることを仮定して，フェルマーの小定理に従って逆元を O(log N) で計算します．</remarks>
    public static ModInt Inverse(ModInt v)
    {
        return Pow(v, Mod - 2);
    }
}

#endregion

public class Program
{
    private long L, R;
    private ModInt[,,,] Memo;
    private bool[,,,] B;

    public void Solve()
    {
        var sc = new Scanner();
        L = sc.NextLong();
        R = sc.NextLong();


        //i, XがL以上確定したか, YがR以下確定したか, 最上位bit確定したか
        Memo = new ModInt[60, 2, 2, 2];
        B = new bool[60, 2, 2, 2];

        Console.WriteLine(Calc(59, 0, 0, 0));
    }

    private ModInt Calc(int i, int xFlag, int yFlag, int zFlag)
    {
        if (i < 0)
        {
            return 1;
        }

        if (B[i, xFlag, yFlag, zFlag])
        {
            return Memo[i, xFlag, yFlag, zFlag];
        }

        ModInt result = 0;

        #region x 0 y 0

        {
            var flag = true;
            if (xFlag == 0)
            {
                if (GetBit(L, i) == 1)
                {
                    flag = false;
                }
            }

            var tmpyFlag = yFlag;
            if (yFlag == 0)
            {
                if (GetBit(R, i) == 1)
                {
                    tmpyFlag = 1;
                }
            }

            if (flag)
                result += Calc(i - 1, xFlag, tmpyFlag, zFlag);
        }

        #endregion

        #region x 0 y 1

        {
            var flag = true;

            if (zFlag == 0)
            {
                flag = false;
            }

            if (xFlag == 0)
            {
                if (GetBit(L, i) == 1)
                {
                    flag = false;
                }
            }

            if (yFlag == 0)
            {
                if (GetBit(R, i) == 0)
                {
                    flag = false;
                }
            }

            if (flag)
            {
                result += Calc(i - 1, xFlag, yFlag, zFlag);
            }
        }

        #endregion

        #region x 1 y 1

        {
            zFlag = 1;
            var flag = true;
            var tmpxFlag = xFlag;
            if (xFlag == 0)
            {
                if (GetBit(L, i) == 0)
                {
                    tmpxFlag = 1;
                }
            }

            if (yFlag == 0)
            {
                if (GetBit(R, i) == 0)
                {
                    flag = false;
                }
            }

            if (flag)
            {
                result += Calc(i - 1, tmpxFlag, yFlag, zFlag);
            }
        }
        #endregion


        Memo[i, xFlag, yFlag, zFlag] = result;
        B[i, xFlag, yFlag, zFlag] = true;
        return result;
    }

    private int GetBit(long n, int i)
    {
        long b = 1L << i;
        return (n & b) > 0 ? 1 : 0;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

