		static void Main()
		{
			var cin = new Scanner();
			ulong l = (ulong)cin.Long();
			ulong r = (ulong)cin.Long();

			var memo = new ModInt?[64, 2, 2, 2];

			ModInt Dfs(int bit, int isUpperL, int isLowerR, int getsMsb)
			{
				if (bit == -1) {
					return 1;
				}

				if (memo[bit, isUpperL, isLowerR, getsMsb].HasValue) {
					return memo[bit, isUpperL, isLowerR, getsMsb].Value;
				}

				ModInt ret = 0;

				ulong mask = 1UL << bit;

				bool canYis1 = ((r & mask) != 0) || isLowerR != 0;
				bool canXis0 = ((l & mask) == 0) || isUpperL != 0;

				if (canYis1) {
					ret += Dfs(
						bit - 1,
						(l & mask) == 0 ? 1 : isUpperL,
						isLowerR,
						1);
				}

				if (canXis0 && canYis1 && (getsMsb != 0)) {
					ret += Dfs(
						bit - 1,
						isUpperL,
						isLowerR,
						getsMsb);
				}

				if (canXis0) {
					ret += Dfs(
						bit - 1,
						isUpperL,
						(r & mask) != 0 ? 1 : isLowerR,
						getsMsb);
				}

				memo[bit, isUpperL, isLowerR, getsMsb] = ret;
				return ret;
			}

			var ans = Dfs(63, 0, 0, 0);

			Console.WriteLine(ans);
		}
