public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        L = cr;
        R = cr;
        return Dfs(63, 0, 0, 0);
    }

    Mod Dfs(int b, int on, int lok, int rok)
    {
        if (b < 0) return on;
        if (dp[b][on][lok][rok] != Mod.invalid) return dp[b][on][lok][rok];
        Mod res = 0;
        for (int l = 0; l <= 1; l++)
            for (int r = l; r <= 1; r++)
            {
                if (L.On(b) && lok == 0 && l == 0) continue;
                if (!R.On(b) && rok == 0 && r == 1) continue;
                if (on == 0 && l != r) continue;
                res += Dfs(b - 1, on | (l & r), lok | (L.On(b) ? 0 : l), rok | (R.On(b) ? 1 - r : 0));
            }
        return dp[b][on][lok][rok] = res;
    }
    Mod[][][][] dp = NewArray(64, 2, 2, 2, Mod.invalid);
    long L;
    long R;
}


