class E
{
    static void Main()
    {
        var line = Console.ReadLine().Split(' ').Select(x => Int64.Parse(x)).ToArray();
        var L = line[0];
        var R = line[1];
        int count = 0;

        for(var x = L; x <= R; x ++)
        {
            for (var y = L; y <= R; y++)
            {
                if(x <= y)
                {
                    var a = y ^ x;
                    var b = y % x;
                    if(a == b)
                    {
                        count += 1;
                    }
                }
            }
        }

        int ans = count % ((int)Math.Pow(10,9) + 7);
        Console.WriteLine(ans);
    }
}

