  {
    static void Main(string[] args)
    {
      Console.WriteLine(Run(args));
      //   Console.WriteLine(calc(8, 9));
    }

    static long K = (long)Math.Pow(10, 9) + 7;
    private static double Run(string[] args)
    {
      var input = ConsoleReader.LongArray();
      var l = input[0];
      var r = input[1];

      var count = 0L;
      var ls = Convert.ToString(l, 2);
      var rs = Convert.ToString(r, 2);
      if (rs.Length - ls.Length >= 2)
      {
        //   Console.WriteLine(string.Format("{0,8}", ls));
        //   Console.WriteLine(string.Format("{0,8}", rs));
        // Math.pow(3, 桁数 - 1) 桁の値が全部揃ってるとき
        for (int i = ls.Length + 1; i < rs.Length; i++)
        {
          count += (long)Math.Pow(3, i - 1);
        }

        var lmaxs = string.Join(string.Empty, Enumerable.Repeat('1', ls.Length));
        var lmax = Convert.ToInt64(lmaxs, 2);
        count += calc(l, lmax);

        var rmins = string.Join(string.Empty, Enumerable.Concat(Enumerable.Repeat('1', 1), Enumerable.Repeat('0', rs.Length - 1)));
        var rmin = Convert.ToInt64(rmins, 2);
        count += calc(rmin, r);
      }
      else
      {
        count += calc(l, r);
      }
      return count % K;
    }

    private static long calc(long min, long max)
    {
      // ここを高速化しないと話にならない…
      var ret = 0;
      for (var y = min; y <= max; y++)
      {
        // var ys = Convert.ToString(y, 2);
        // var p = 0;
        // foreach (var b in ys)
        // {
        //   if (b == '1')
        //   {
        //     p++;
        //   }
        // }
        // ret += (long)Math.Pow(2, p - 1);
        for (var x = min; x <= y; x++)
        {
          var rem = y % x;
          var xor = y ^ x;
          // var xs = Convert.ToString(x, 2);
          // var ys = Convert.ToString(y, 2);
          // Console.WriteLine(String.Join(",", string.Format("{0,8}", ys), string.Format("{0,8}", xs), rem, xor));
          if (rem.Equals(xor))
          {
            ret++;
          }
        }
      }
      return ret % K;
    }
  }

