internal partial class Solver {

    long?[,,] memo;
    int mod = 1000000000 + 7;

    public void Run() {
        var L = nl();
        var R = nl();
        memo = new long?[100, 2, 2];
        long ans = 0;

        for (int i = 62; i >= 0; i--) {
            var l = L >> i;
            var r = R >> i;
            if (l <= 1 && 1 <= r) {
                ans += Dfs(L, R, i - 1, moreThanL: l < 1, lessThanR: 1 < r);
                ans %= mod;
            }
        }
        cout.WriteLine(ans);
    }

    int[] ys = new int[] { 0, 1, 1 };
    int[] xs = new int[] { 0, 0, 1 };

    long Dfs(long L, long R, int pos, bool moreThanL, bool lessThanR) {
        if (pos < 0) return 1;
        if (!memo[pos, moreThanL ? 1 : 0, lessThanR ? 1 : 0].HasValue) {
            long val = 0;

            var l = (L >> pos) & 1;
            var r = (R >> pos) & 1;
            for (int i = 0; i < 3; i++) {
                var x = xs[i];
                var y = ys[i];
                if (!moreThanL && x < l) continue;
                if (!lessThanR && r < y) continue;

                val += Dfs(L, R, pos - 1, moreThanL || (l < x), lessThanR || (y < r));
                val %= mod;
            }


            memo[pos, moreThanL ? 1 : 0, lessThanR ? 1 : 0] = val;
        }
        return memo[pos, moreThanL ? 1 : 0, lessThanR ? 1 : 0].Value;
    }
}

