const MOD int64 = 1000000007
func main() {
  var l,r,ans int64
  fmt.Scan(&l,&r)
  dp := [61][2][2][2]int64{}
  dp[60][0][0][0] = 1
  for i:=59;i>=0;i-- {
    lb := int(l>>uint(i))&1
    rb := int(r>>uint(i))&1
    for j:=0;j<2;j++ {
      for k:=0;k<2;k++ {
        for s:=0;s<2;s++ {
          for x:=0;x<2;x++ {
            for y:=0;y<2;y++ {
              if x-y == 1 { continue }
              jj,kk,ss := j,k,s
              if s == 0 && x != y { continue }
              if x*y == 1 { ss = 1 }
              if lb-j-x == 1 { continue }
              if x-lb == 1 { jj = 1 }
              if y-k-rb == 1 { continue }
              if rb-y == 1 { kk = 1 }
              dp[i][jj][kk][ss] = (dp[i][jj][kk][ss]+dp[i+1][j][k][s])%MOD
            }
          }
        }
      }
    }
  }
  for j:=0;j<2;j++ {
    for k:=0;k<2;k++ {
      for s:=0;s<2;s++ { ans += dp[0][j][k][s] }
    }
  }
  fmt.Println(ans%MOD)
}

