	// dp[i][msb-appeared][top-tight][bottom-tight]: 上から i: 0, 1,.. 桁 目を決めた時の個数。 msb-appeared は 1 が一度でも現れたかどうか。 tight は max / min とその桁まで一致しているケースの個数
	dp := make([][][][]int, maxDigit+1)
	for i := range dp {
		dp[i] = make([][][]int, 2)

		for j := range dp[i] {
			dp[i][j] = make([][]int, 2)

			for k := range dp[i][j] {
				dp[i][j][k] = make([]int, 2)
			}
		}
	}

	dp[0][0][1][1] = 1

	// for bit := maxDigit - 1; bit >= 0; bit-- {
	for i := 1; i <= maxDigit; i++ {
		maxHasBit := R>>uint(maxDigit-i)&1 == 1
		minHasBit := L>>uint(maxDigit-i)&1 == 1

		// 桁 DP では貰うより配る方がやりやすい
		for msb := 0; msb <= 1; msb++ {
			for tTight := 0; tTight <= 1; tTight++ {
				for bTight := 0; bTight <= 1; bTight++ {
					for y := 0; y <= 1; y++ {
						for x := 0; x <= y; x++ {
							if msb == 0 && y != x {
								continue
							}

							if tTight == 1 && !maxHasBit && y == 1 {
								continue
							}

							if bTight == 1 && minHasBit && x == 0 {
								continue
							}

							// 前の桁の msb, tTight, bTight からこの桁で y, x を選んだ時にこの桁で msb, tTight, bTight か？を考える
							msbNext := TernaryInt(msb == 1 || y == 1, 1, 0)
							tTightNext := TernaryInt(tTight == 1 && maxHasBit == (y == 1), 1, 0)
							bTightNext := TernaryInt(bTight == 1 && minHasBit == (x == 1), 1, 0)
							dp[i][msbNext][tTightNext][bTightNext] += dp[i-1][msb][tTight][bTight]
						}
					}
				}
			}

			for m := 0; m <= 1; m++ {
				for t := 0; t <= 1; t++ {
					for b := 0; b <= 1; b++ {
						dp[i][m][t][b] %= MOD
					}
				}
			}
		}
	}

	var res int
	for i := 1; i <= 1; i++ {
		for j := 0; j <= 1; j++ {
			for k := 0; k <= 1; k++ {
				res += dp[maxDigit][i][j][k]
				res %= MOD
			}
		}
	}

	io.Println(res)
}

