const p = 1000000007

func Memo(M *[][][][]int, L, R *[]int, k, x, y, b int) int {
  if k < 0 { return 1 }
  if 0 <= (*M)[k][x][y][b] { return (*M)[k][x][y][b] }
  m := 0
  if x | (1 - (*L)[k]) == 1 { m += Memo(M, L, R, k - 1, x, y | (*R)[k], b) }
  if y | (*R)[k] == 1 { m += Memo(M, L, R, k - 1, x | (1 - (*L)[k]), y, 1) }
  if (x | (1 - (*L)[k]) == 1) && (y | (*R)[k] == 1) && (b == 1) { m += Memo(M, L, R, k - 1, x, y, b) }
  m %= p
  (*M)[k][x][y][b] = m
  return m
}

func Solve() {
  var L, R int
  NextInt(&L, &R)
  Lb := make([]int, 60)
  for l, i := L, 0; i < 60; l, i = l / 2, i + 1 {
    Lb[i] = l % 2
  }
  Rb := make([]int, 60)
  for r, i := R, 0; i < 60; r, i = r / 2, i + 1 {
    Rb[i] = r % 2
  }
  M := make([][][][]int, 60)
  for i := range M {
    M[i] = make([][][]int, 2)
    for x := range M[i] {
      M[i][x] = make([][]int, 2)
      for y := range M[i][x] {
        M[i][x][y] = make([]int, 2)
        for b := range M[i][x][y] {
          M[i][x][y][b] = -1
        }
      }
    }
  }
  Write(Memo(&M, &Lb, &Rb, 59, 0, 0, 0))
}

func main() {
  Solve()
  Output()
}

