					}
				}
			}
		}
	}

	var res int
	for i := 1; i <= 1; i++ {
		for j := 0; j <= 1; j++ {
			for k := 0; k <= 1; k++ {
				res += dp[maxDigit][i][j][k]
				res %= MOD
			}
		}
	}

	io.Println(res)
}

