func solve(l, r uint64) uint64 {
	mod := uint64(1e9 + 7)
	var ans uint64
	for x := l; x <= r; x++ {
		for y := l; y <= x; y++ {
			if x%y == x^y {
				ans++
				ans %= mod
			}
		}
	}
	return ans
}

func count(l, r uint64) int {
	var dp [65][2][2][2]int

	// dp[桁数][下がLより大きいか][上がR未満か][1の位置が同じかどうか]
	dp[0][0][0][0] = 1
	for i := 0; i < 64; i++ {
		lb := int((l >> uint(63-i)) & 1)
		rb := int((r >> uint(63-i)) & 1)

		for ii := 0; ii < 2; ii++ {
			for iii := 0; iii < 2; iii++ {
				for iiii := 0; iiii < 2; iiii++ {
					for x := 0; x < 2; x++ {
						for y := 0; y < 2; y++ {
							aii, aiii, aiiii := ii, iii, iiii
							if x == 1 && y == 0 {
								continue
							}
							if ii == 0 {
								if lb == 0 && x == 1 {
									aii = 1
								}

								if lb == 1 && x == 0 {
									continue
								}
							}
							if iii == 0 {
								if rb == 1 && y == 0 {
									aiii = 1
								}
								if rb == 0 && y == 1 {
									continue
								}
							}
							if iiii == 0 {
								if x&y == 1 {
									aiiii = 1
								}
								if x != y {
									continue
								}
							}
							dp[i+1][aii][aiii][aiiii] = mint(dp[i+1][aii][aiii][aiiii] + dp[i][ii][iii][iiii])
						}
					}
				}
			}
		}

	}

	ans := 0

	for ii := 0; ii < 2; ii++ {
		for iii := 0; iii < 2; iii++ {
			for iiii := 0; iiii < 2; iiii++ {
				ans = mint(ans + dp[64][ii][iii][iiii])
			}
		}
	}
	return ans
}

func mint(a int) int {
	mod := a % int(1e9+7)
	if mod < 0 {
		mod += int(1e9 + 7)
	}
	return mod
}

