Output main2(Input input)
{
    int rank = bsr(input.r);
    auto temp = calc(rank, input.l, input.r + 1);

    Output output;
    output.result = temp % (10 ^^ 9 + 7);
    return output;
}

BigInt calc(int enclosingRank, ulong begin, ulong end)
{
    if (begin == 2^^enclosingRank && end == 2^^(enclosingRank+1))
        return count[enclosingRank];

    ulong border = 1UL << enclosingRank;
    if (begin <= border && border < end)
        return calc(enclosingRank-1, begin, border) + calc(border, count[enclosingRank], border, end);
    else
        return calc(border, count[enclosingRank], begin, end);
}

unittest
{
    assert(calc(1, 1, 4) == 4);
    assert(calc(1, 2, 4) == 3);
    assert(calc(bsr(1000000000000000000), 1, 1000000000000000000 + 1) % (10^^9 + 7) == 68038601);
}

BigInt calc(ulong width, BigInt rangeTotal, ulong begin, ulong end)
{
    assert (width != 0);
    if (begin + width == end)
        return rangeTotal;

    ulong border = begin + width / 2;
    if (border < end)
        return calc(width / 2, rangeTotal / 3, begin, border) + calc(width / 2, rangeTotal / 3 * 2, border, end);
    else if (border == end)
        return rangeTotal / 3;
    else
        return calc(width / 2, rangeTotal / 3, begin, end);
}

