def solve(N):
    n=N.bit_length()
    dp=[[0 for i in range(4)] for j in range(n)]
    dp[0][0]=1+(N%2==1)
    dp[0][1]=1+2*(N%2==1)
    dp[0][2]=2
    dp[0][3]=3
    for i in range(1,n):
        for j in range(4):
            if j==0:
                if N>>i&1==1:
                    dp[i][j]=dp[i-1][2]+dp[i-1][1]
                else:
                    dp[i][j]=dp[i-1][0]
            elif j==1:
                if N>>i&1==1:
                    dp[i][j]=dp[i-1][3]+2*dp[i-1][1]
                else:
                    dp[i][j]=dp[i-1][1]
            elif j==2:
                dp[i][j]=dp[i-1][2]+dp[i-1][3]
            else:
                dp[i][j]=3*dp[i-1][3]

    return dp[-1][0]-1

def extra(N):
    if N==0:
        return 0
    n=N.bit_length()
    dp=[[0 for i in range(4)] for j in range(n)]
    dp[0][0]=1+(N%2==1)
    dp[0][1]=2+(N%2==1)
    dp[0][2]=2
    dp[0][3]=3
    for i in range(1,n):
        for j in range(4):
            if j==0:
                if N>>i&1==1:
                    dp[i][j]=dp[i-1][2]+dp[i-1][1]
                else:
                    dp[i][j]=dp[i-1][0]
            elif j==1:
                if N>>i&1==1:
                    dp[i][j]=2*dp[i-1][3]+dp[i-1][1]
                else:
                    dp[i][j]=2*dp[i-1][1]
            elif j==2:
                dp[i][j]=dp[i-1][2]+dp[i-1][3]
            else:
                dp[i][j]=3*dp[i-1][3]

    return dp[-1][0]-1

