def calc(keta,l,r):

    if keta==-1:
        if l>=L and r<=R:
            return 1
        else:
            return 0

    ANS=0

    if l==r==0:
        if (1<<keta)<=R:
            ANS=ANS+calc(keta-1,1<<keta,1<<keta)
            ANS%=mod

        ANS=ANS+calc(keta-1,0,0)
        ANS%=mod

    else:
        if l>=L and (1<<(keta+1))+r<=R:
            ANS=ANS+pow(3,keta+1,mod)
            ANS%=mod

        else:
            if r+(1<<keta)<=R:
                ANS+=calc(keta-1,l+(1<<keta),r+(1<<keta))
                ANS%=mod

            if r+(1<<keta)<=R and l+(1<<keta)>L:
                ANS+=calc(keta-1,l,r+(1<<keta))
                ANS%=mod

            if l+(1<<keta)>L:
                ANS+=calc(keta-1,l,r)
                ANS%=mod

    return ANS

