mod=1000000007

@lru_cache()
def calc(l,r):
    if l>r:
        return 0
    if r==0:
        return 1
    b_l,b_r=l.bit_length(),r.bit_length()
    if b_l==b_r:
        return calc(l-(1<<(b_l-1)),r-(1<<(b_r-1)))
    if r==(1<<(b_r-1))-1 and l==0:
        return pow(3,b_r,mod)
    return (calc(l,r-(1<<(b_r-1)))+calc(l,(1<<(b_r-1))-1)+calc(0,r-(1<<b_r-1)))%mod

