def subcount(j, L, R):
    if j >= L.bit_length():
        return 0
    dp = [[0]*4 for _ in range(70)]

    cnt = 0
    if R.bit_length() != j+1:
        cnt += 1
    if L.bit_length() != j+1:
        cnt += 2
    dp[j][cnt] = 1

    for i in range(j, 0, -1):
        yf = R & (1<<(i-1))
        xf = L & (1<<(i-1))

        d0 = dp[i][0]
        if yf and xf:
            dp[i-1][0] += d0
            dp[i-1][2] += d0
            dp[i-1][3] += d0
        elif yf:
            dp[i-1][0] += d0
            dp[i-1][1] += d0
        elif xf:
            dp[i-1][2] += d0
        else:
            dp[i-1][0] += d0

        d1 = dp[i][1]
        if xf:
            dp[i-1][1] += d1
            dp[i-1][3] += 2*d1
        else:
            dp[i-1][1] += 2*d1

        d2 = dp[i][2]
        if yf:
            dp[i-1][2] += 2*d2
            dp[i-1][3] += d2
        else:
            dp[i-1][2] += d2

        d3 = dp[i][3]
        dp[i-1][3] += 3*d3

        dp[i-1][0] %= mod
        dp[i-1][1] %= mod        
        dp[i-1][2] %= mod
        dp[i-1][3] %= mod

    return sum(dp[0][i] for i in range(4))

