// ===


// 11 11 01 01 10 00
// 00 01 00 01 00 00

fn solve(l: i64, r: i64) -> i64 {
    let mut dp = dvec!(0; 62, 2, 2, 2);
    dp[61][0][0][0] = 1;
    for i in (1..62).rev() {
        let mask = 1i64<<(i-1);
        let ti = i-1;
        for yflg in 0..2 {
            for xflg in 0..2 {
                for first in 0..2 {
                    let base = dp[i][yflg][xflg][first];
                    for y in 0..2 {
                        for x in 0..2 {
                            if y == 1 && x == 0 && first == 0 {
                                continue;
                            }
                            if y == 0 && x == 1 {
                                continue;
                            }
                            if y == 1 && yflg == 0 && r & mask == 0 {
                                continue;
                            }
                            if x == 1 && xflg == 0 && l & mask == 0 {
                                continue;
                            }
                            let tfirst = first | ifv!(y == 1 && x == 1, 1, 0);
                            let tyflg = yflg | ifv!(y == 0 && r & mask == mask, 1, 0);
                            let txflg = xflg | ifv!(x == 0 && l & mask == mask, 1, 0);
                            dp[ti][tyflg][txflg][tfirst] += base;
                            dp[ti][tyflg][txflg][tfirst] %= MOD;

                        }
                    }
                }
            }
        }
    }

    let mut ret = 0;
    for y in 0..2 {
        for x in 0..2 {
            ret += dp[0][y][x][1];
        }
    }
    // debug!(l, r, ret);
    ret % MOD
}

const MOD: i64 = 1e9 as i64 + 7;

fn main() {
    input! {
        l: i64, r: i64
    };

    let ans = solve(r, r) + MOD - solve(l-1, r);
    println!("{}", ans % MOD);
}

