            .and_then(|c| match (state.1, c.cmp(alph)) {
                (true, std::cmp::Ordering::Equal) => Some((state.0 + 1, true)),
                (true, std::cmp::Ordering::Less) => None,
                _ => Some((state.0 + 1, false)),
            })
    }
    fn accept(&self, state: &Self::State) -> bool {
        self.eq || !state.1
    }
}
