fn to_bin(mut x: u64) -> Vec<u8> {
    let mut res = Vec::new();
    while x != 0 {
        res.push((x%2) as u8);
        x /= 2;
    }
    res.reverse();
    res
}

fn count(
    l: &[u8], r: &[u8], xt: bool, yt: bool, valid: bool,
    memo: &mut Vec<Vec<Option<ModP>>>
) -> ModP {
    let flag_index = (xt as usize) * 4 + (yt as usize) * 2 + (valid as usize);
    memo[flag_index][l.len()].unwrap_or_else(|| {
        let ans = if l.is_empty() { modp(1) } else {
            let (&l0, l_tl) = l.split_first().unwrap();
            let (&r0, r_tl) = r.split_first().unwrap();
            if yt && r0 == 0 {
                if xt && l0 == 1 {
                    modp(0)
                } else {
                    count(l_tl, r_tl, xt, yt, valid, memo) // (x, y) = (0, 0)
                }
            } else {
                if xt && l0 == 1 {
                    count(l_tl, r_tl, xt, yt, true, memo) // (x, y) = (1, 1)
                } else {
                    count(l_tl, r_tl, xt, false, valid, memo) // (x, y) = (0, 0)
                        + if valid { count(l_tl, r_tl, xt, yt, true, memo) } else { modp(0) } // (x, y) = (0, 1)
                    + count(l_tl, r_tl, false, yt, true, memo) // (x, y) = (1, 1)
                }
            }
        };
        memo[flag_index][l.len()] = Some(ans);
        ans
    })
}

fn main() {
    read!(l = u64, r = u64);
    let r_bin = to_bin(r);
    let l_bin_suff = to_bin(l);
    let mut l_bin = vec![0; r_bin.len() - l_bin_suff.len()];
    l_bin.extend_from_slice(&l_bin_suff);
    let mut memo = vec![vec![None; l_bin.len() + 1]; 8];
    println!("{}", count(&l_bin, &r_bin, true, true, false, &mut memo));
}

