fn main() {
    input! { l, r };
    let s = format!("{:b}", l)
        .chars()
        .map(|c| (c as u8 - '0' as u8) as usize)
        .collect::<Vec<_>>();
    let t = format!("{:b}", r)
        .chars()
        .map(|c| (c as u8 - '0' as u8) as usize)
        .collect::<Vec<_>>();
    let s = (0..t.len() - s.len())
        .map(|_| 0)
        .chain(s)
        .collect::<Vec<_>>();
    let mut dp = vec![vec![vec![vec![Modi64(0); 2]; 2]; 2]; t.len() + 1];
    dp[0][0][0][0] = 1.into();
    for i in 0..t.len() {
        for j in 0..2 {
            for k in 0..2 {
                for l in 0..2 {
                    let d = dp[i][j][k][l];
                    for m in 0..2 {
                        for n in 0..2 {
                            let ni = i + 1;
                            let mut nj = j;
                            let mut nk = k;
                            let mut nl = l;
                            if j == 0 {
                                if n < t[i] {
                                    nj = 1;
                                } else if n > t[i] {
                                    continue;
                                }
                            }
                            if k == 0 {
                                if m > s[i] {
                                    nk = 1;
                                } else if m < s[i] {
                                    continue;
                                }
                            }
                            if m == 1 && n == 0 {
                                continue;
                            }
                            if l == 0 {
                                if m == 1 && n == 1 {
                                    nl = 1;
                                } else if m == 1 || n == 1 {
                                    continue;
                                }
                            }
                            dp[ni][nj][nk][nl] += d;
                        }
                    }
                }
            }
        }
    }
    let mut ans = Modi64(0);
    for j in 0..2 {
        for k in 0..2 {
            for l in 0..2 {
                ans += dp[s.len()][j][k][l];
            }
        }
    }
    println!("{}", ans);
}

