    let (l, r) = (v[0], v[1]);
    let mut dp = vec![vec![vec![vec![Modulo(0); 2]; 2]; 2]; 63];
    dp[0][0][0][0] += 1;
    for i in 0..62 {
        let lb = ((l >> (61 - i)) & 1) as usize;
        let rb = ((r >> (61 - i)) & 1) as usize;
        for prev_li in 0..2 {
            for prev_ri in 0..2 {
                for prev_si in 0..2 {
                    for y in 0..2 {
                        for x in 0..2 {
                            if prev_ri == 0 && y > rb {
                                continue;
                            }
                            if prev_li == 0 && x < lb {
                                continue;
                            }
                            if x > y {
                                continue;
                            }
                            if prev_si == 0 && y > x {
                                continue;
                            }
                            let next_si = prev_si | y;
                            let mut next_ri = prev_ri;
                            if y < rb {
                                next_ri = 1;
                            };
                            let mut next_li = prev_li;
                            if x > lb {
                                next_li = 1
                            };
                            let prev = dp[i][prev_ri][prev_li][prev_si];
                            dp[i + 1][next_ri][next_li][next_si] += prev;
                        }
                    }
                }
            }
        }
    }

