fn solve(n: usize, fl: usize, fr: usize, fmsb: usize, l: usize, r: usize, tab: &mut Vec<Vec<Vec<Vec<Option<usize>>>>>) -> usize {
    if n == 0 {
        return 1;
    }
    if let Some(ret) = tab[n][fl][fr][fmsb]  {
        return ret;
    }
    let d = 1000000007;
    let lb = l & 1 << n - 1;
    let rb = r & 1 << n - 1;
    let mut ret = 0;
    if fl == 1 || lb == 0 {
        if rb > 0 {
            ret += solve(n - 1, fl, 1, fmsb, l, r, tab);
        } else {
            ret += solve(n - 1, fl, fr, fmsb, l, r, tab);
        }
    }
    if (fl == 1 || lb == 0) && (fr == 1 || rb > 0) && fmsb == 1 {
        ret += solve(n - 1, fl, fr, fmsb, l, r, tab);
    }
    if fr == 1 || rb > 0 {
        if lb > 0 {
            ret += solve(n - 1, fl, fr, 1, l, r, tab);
        } else {
            ret += solve(n - 1, 1, fr, 1, l, r, tab);
        }
    }
    ret %= d;
    tab[n][fl][fr][fmsb] = Some(ret);
    ret
}

