const MODULO: usize = 1_000_000_007;

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let l: usize = scan(tokens);
    let r: usize = scan(tokens);
    println!("{}", f(l, r));
}

fn f(l: usize, r: usize) -> usize {
    // #{ (x, y) | l <= x <= y <= r, p(x, y) }
    if l == r {
        1
    } else if l % 2 == 1 {
        (g(l, r) + f(l + 1, r)) % MODULO
    } else if r % 2 == 0 {
        (f(l, r - 1) + h(l, r)) % MODULO
    } else {
        3 * f(l / 2, r / 2) % MODULO
    }
}

fn g(l: usize, r: usize) -> usize {
    // #{ y | l <= y <= r, p(l, y) }
    if l == r {
        1
    } else if r % 2 == 0 {
        (g(l, r - 1) + p(l, r)) % MODULO
    } else if l == 1 {
        1
    } else if l % 2 == 1 {
        g(l / 2, r / 2)
    } else {
        2 * g(l / 2, r / 2) % MODULO
    }
}

fn h(l: usize, r: usize) -> usize {
    // #{ x | l <= x <= r, p(x, r) }
    if l == r {
        1
    } else if l % 2 == 1 {
        (p(l, r) + h(l + 1, r)) % MODULO
    } else if r % 2 == 0 {
        h(l / 2, r / 2)
    } else {
        2 * h(l / 2, r / 2) % MODULO
    }
}

fn p(x: usize, y: usize) -> usize {
    if y % x == y ^ x {
        1
    } else {
        0
    }
}

