const MOD: usize = 1e+9 as usize + 7;

fn calc(
    depth: usize,
    upper_l: usize,
    lower_r: usize,
    rev: usize,
    l: usize,
    r: usize,
    memo: &mut Vec<Vec<Vec<Vec<usize>>>>,
) -> usize {
    if memo[upper_l][lower_r][rev][depth] != MOD {
        return memo[upper_l][lower_r][rev][depth];
    }
    let bit = 1 << depth;
    if bit > r || (bit * 2 > r && bit <= r && lower_r == 0) {
        return 0;
    }
    let mut ret = 0;
    if rev == 0 && (bit > l || (bit * 2 > l && bit <= l && upper_l == 1)) {
        ret = 1;
    }
    for i in 0..2 {
        let nlower_r = if (r & bit) > 0 {
            i == 0 || lower_r == 1
        } else {
            i == 0 && lower_r == 1
        };
        let nlower_r = if nlower_r { 1 } else { 0 };
        for j in 0..2 {
            if i == 0 && j == 1 {
                continue;
            }
            let nupper_l = if (l & bit) > 0 {
                j == 1 && upper_l == 1
            } else {
                j == 1 || upper_l == 1
            };
            let nupper_l = if nupper_l { 1 } else { 0 };
            let nrev = if i < j || (rev == 1 && i == j) { 1 } else { 0 };
            ret = (ret + calc(depth + 1, nupper_l, nlower_r, nrev, l, r, memo)) % MOD;
        }
    }
    memo[upper_l][lower_r][rev][depth] = ret;
    // println!("{} {} {} {} {}", depth, upper_l, lower_r, rev, ret);
    return ret;
}

