#[derive(Clone)]
struct edge{
    from:usize,
    to:usize,
    cost:i64,
}
struct Bellman_ford{
    es:Vec<edge>,
    d:Vec<i64>,
    V:usize,
    E:usize,
    prev:Vec<i64>
}
impl Bellman_ford{
    pub fn new(V:usize, E:usize, g:Vec<Vec<usize>>, cost:Vec<i64>)->Self{
        let mut es = vec![];
        let mut d = vec![INF; V];
        for i in 0..g.len(){
            es.push(edge{from:g[i][0], to:g[i][1], cost:cost[i]});
        }
        return Bellman_ford{V:V, E:E, d:d, es:es, prev:vec![-1;V]};
    }
    pub fn shortest_path(&mut self, s:usize){
        self.d[s] = 0;
        while(true){
            let mut update = false;
            for i in 0..self.E{
                let mut e = self.es[i].clone();
                if self.d[e.from] != INF && self.d[e.to] > self.d[e.from] + e.cost{
                    self.d[e.to] = self.d[e.from]+e.cost;
                    update = true;
                }
            }
            if !update{
                break;
            }
        }
    }
    pub fn find_negative_loop(&mut self)->bool{
        for i in 0..self.d.len(){
            self.d[i] = 0;
        }
        let mut res = false;
        for j in 0..self.V{
            for i in 0..self.E{
                let mut e = self.es[i].clone();
                if self.d[e.from] != INF && self.d[e.to] > self.d[e.from] + e.cost{
                    self.d[e.to] = self.d[e.from]+e.cost;
                    if j == self.V -1 {res = true;}
                }
            }
        }
        return res;
    }
    pub fn reproduct_shortest_path_prep(&mut self, s:usize){
        self.d = vec![INF;self.d.len()];
        self.prev = vec![-1;self.V];
        let mut used = vec![false;self.V];
        self.d[s] = 0;
        let mut cost = vec![vec![INF;self.V];self.V];
        for i in 0..self.E{
            let mut e = self.es[i].clone();
            cost[e.from][e.to] = e.cost;
        }
        while(true){
            let mut v = -1;
            for u in 0..self.V{
                if !used[u] && ( v == -1 || self.d[u] < self.d[v as usize]){v = u as i64;}
            }
            if v == -1{break;}
            used[v as usize] = true;
            for u in 0..self.V{
                if self.d[u] > self.d[v as usize] + cost[v as usize][u]{
                    self.d[u] = self.d[v as usize] + cost[v as usize][u];
                    self.prev[u] = v;
                }
            }
        }
    }
    pub fn get_path(& self,t:usize)->Vec<i64>{
        let mut path = vec![];
        let mut t = t as i64;
        while(t != -1){
            path.push(t);
            t = self.prev[t as usize];
        }
        path.reverse();
        return path;
    }
}

