fn dijkstra(s:usize, g:&Vec<Vec<(usize, i64)>>)->(Vec<usize>, Vec<i64>){
    let mut d = vec![INF;g.len()];
    let mut prev = vec![g.len();g.len()];
    d[s] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, s));
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut v = top.1;
        let mut l = top.0 * -1;
        if l > d[v]{
            continue;
        }
        for i in 0..g[v].len(){
            let nl = l + g[v][i].1;
            let n = g[v][i].0;
            if d[n] > nl{
                prev[n] = v;
                d[n] = nl;
                h.push((nl*-1, n));
            }
        }
    }
    (prev, d)
}
// http://is2011.2-d.jp/moin/moin.cgi/amylase/icpc#A.2BUYYwaHb0fdowbk6kcLk-
fn cc_intersect((cx, cy, cr): (f64, f64, f64), (dx, dy, dr) : (f64, f64, f64))
                -> Vec<(f64, f64)> {
    let dist = ((cx - dx) * (cx - dx) + (cy - dy) * (cy - dy)).sqrt();
    if dist > cr + dr + EPS {
        return vec![];
    }
    if dist < (cr - dr).abs() - EPS {
        return vec![];
    }
    let s = (cr + dr + dist) / 2.0;
    let area = (s * (s - cr) * (s - dr) * (s - dist)).sqrt();
    let h = 2.0 * area / dist;
    let (vx, vy) = (dx - cx, dy - cy);
    let vabs = (vx * vx + vy * vy).sqrt();
    let (vx, vy) = (vx / vabs, vy / vabs);
    let ss = (cr * cr - h * h).sqrt();
    let (mx, my) = (cx + ss * vx, cy + ss * vy);
    let (nx, ny) = (-vy, vx);
    vec![(mx + nx * h, my + ny * h), (mx - nx * h, my - ny * h)]
}
fn dijkstra2(X:usize, Y:usize, g:&Vec<Vec<char>>, xx:i64)->Vec<Vec<i64>>{
    let mut d = vec![vec![INF;g[0].len()];g.len()];
    d[X][Y] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, X as i64, Y as i64));
    let dx = vec![0,0,-1, 1];
    let dy = vec![1, -1, 0, 0];
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut x = top.1;
        let mut y = top.2;
        let mut l = top.0 * -1;
        if l > d[x as usize][y as usize]{
            continue;
        }
        for i in 0..4{
            let mut nx = dx[i]+x;
            let mut ny = dy[i]+y;
            if 0<=nx && nx<g.len() as i64 && 0<=ny && ny<g[0].len() as i64{
                let mut nx = nx as usize;
                let mut ny = ny as usize;
                let nl = l + if g[nx][ny] == '#'{xx}else{1};
                if d[nx][ny]>nl{
                    d[nx][ny] = nl;
                    h.push((nl*-1, nx as i64, ny as i64));
                }
            }

        }
    }
    d
}
