const INF: i64 = 1 << 60;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let l: usize = it.next().unwrap().parse().unwrap();
    let r: usize = it.next().unwrap().parse().unwrap();
    const MOD: u64 = 1_000_000_007;
    let mut dp = [[0u64; 2]; 2];
    for shift in (0..60).rev() {
        let (x, y) = ((l >> shift) & 1, (r >> shift) & 1);
        let mut next = [[0; 2]; 2];
        for i in 0..2 {
            for j in 0..2 {
                let v = dp[i][j] % MOD;
                if x == 0 || i == 1 {
                    next[i][j | y] += v;
                }
                if (x == 0 || i == 1) && (y == 1 || j == 1) {
                    next[i][j] += v;
                }
                if y == 1 || j == 1 {
                    next[i | if x == 0 {1} else {0}][j] += v;
                }
            }
        }
        if 1 >= (l >> shift) && 1 <= (r >> shift) {
            next[if x == 0 {1} else {0}][if 1 < (r >> shift) {1} else {0}] += 1;
        }
        dp = next;
    }
    let mut ans = 0;
    for i in 0..2 {
        for j in 0..2 {
            ans += dp[i][j];
        }
    }
    ans %= MOD;
    println!("{}", ans);
