    let mut dp = vec![vec![vec![vec![0; 2]; 2]; 2]; digit_num + 1];
    dp[0][0][0][0] = 1;
    for i in 0..digit_num {
        let r_bit = (r >> (digit_num - 1 - i)) & 1;
        let l_bit = (l >> (digit_num - 1 - i)) & 1;
        for r_assured in 0..2 {
            for l_assured in 0..2 {
                for max_samed in 0..2 {
                    for x in 0..2 {
