                            if x == 1 && y == 0 {
                                continue;
                            }
                            if max_samed == 0 && x != y {
                                continue;
                            }
                            let mut nm = max_samed;
                            if x == 1 && y == 1 {
                                nm = 1;
                            }
                            if x == 0 && l_assured == 0 && l_bit == 1 {
                                continue;
                            }
