fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, l: usize, r: usize);
    const n: usize = 62;
    let mut dp = vec![vec![vec![vec![Mint(0usize); 2]; 2]; 2]; n];
    dp[0][0][0][0] = Mint(1usize);
    for i in 0..(n - 1) {
        let li = (l >> (n - 2 - i)) & 1;
        let ri = (r >> (n - 2 - i)) & 1;
        for z in 0..=1 {
            for a in 0..=1 {
                for b in 0..=1 {
                    let tmp = dp[i][z][a][b];
                    // (0, 0)
                    if li == 0 || a == 1 {
                        if ri == 0 {
                            dp[i + 1][z][a][b] += tmp
                        } else {
                            dp[i + 1][z][a][1] += tmp;
                        }
                    }
                    // (0, 1)
                    if (li == 0 || a == 1) && (ri == 1 || b == 1) && z == 1 {
                        dp[i + 1][z][a][b] += tmp;
                    }

                    // (1, 1)
                    if ri == 1 || b == 1 {
                        if li == 1 {
                            dp[i + 1][1][a][b] += tmp;
                        } else {
                            dp[i + 1][1][1][b] += tmp;
                        }
                    }
                }
            }
        }
    }
    eprintln!("{:?}", dp[n - 3]); // DEBUG
    eprintln!("{:?}", dp[n - 2]); // DEBUG
    let mut ret = Mint(0);
    for z in 0..=1 {
        for a in 0..=1 {
            for b in 0..=1 {
                ret += dp[n - 1][z][a][b]
            }
        }
    }
    println!("{}", ret);
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

