#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MOD: usize = 1e+9 as usize + 7;

fn calc(
    depth: usize,
    upper_l: usize,
    lower_r: usize,
    l: usize,
    r: usize,
    memo: &mut Vec<Vec<Vec<usize>>>,
) -> usize {
    if memo[upper_l][lower_r][depth] != MOD {
        return memo[upper_l][lower_r][depth];
    }
    let bit = 1 << depth;
    if bit > r || (bit * 2 > r && bit <= r && lower_r == 0) {
        return 0;
    }
    let mut ret = 0;
    if bit > l || (bit * 2 > l && bit <= l && upper_l == 1) {
        ret = 1;
    }
    for i in 0..2 {
        let nlower_r = if (r & bit) > 0 {
            i == 0 || lower_r == 1
        } else {
            i == 0 && lower_r == 1
        };
        let nlower_r = if nlower_r { 1 } else { 0 };
        for j in 0..2 {
            if i == 0 && j == 1 {
                continue;
            }
            let nupper_l = if (l & bit) > 0 {
                j == 1 && upper_l == 1
            } else {
                j == 1 || upper_l == 1
            };
            let nupper_l = if nupper_l { 1 } else { 0 };
            ret = (ret + calc(depth + 1, nupper_l, nlower_r, l, r, memo)) % MOD;
        }
    }
    memo[upper_l][lower_r][depth] = ret;
    // println!("{} {} {} {} {}", depth, upper_l, lower_r, rev, ret);
    return ret;
}

fn main() {
    let l = read::<usize>();
    let r = read::<usize>();
    let mut memo = vec![vec![vec![MOD; 70]; 2]; 2];
    let ans = calc(0, 1, 1, l, r, &mut memo);
    println!("{}", ans);
}

fn run() {
    proconio::input! {
        l: usize,
        r: usize,
    }
    const MOD: u64 = 1_000_000_007;
    let mut dp = [[0u64; 2]; 2];
    dp[0][0] = 0;
    for i in (0..60).rev() {
        let mut next = [[0; 2]; 2];
        if l >> i <= 1 && r >> i >= 1 {
            let a = 1 ^ (l >> i & 1);
            let b = (r >> i > 1) as usize;
            next[a][b] += 1;
        }
        for (a, dp) in dp.iter().enumerate() {
            for (b, &v) in dp.iter().enumerate() {
                for &(x, y) in [(0, 0), (0, 1), (1, 1)].iter() {
                    if a == 0 && l >> i & 1 > x {
                        continue;
                    }
                    if b == 0 && r >> i & 1 < y {
                        continue;
                    }
                    let a = (a == 1 || x > (l >> i) & 1) as usize;
                    let b = (b == 1 || y < (r >> i) & 1) as usize;
                    next[a][b] += v;
                }
            }
        }
        next.iter_mut().flatten().for_each(|p| *p %= MOD);
        dp = next;
    }
    let ans = dp.iter().flatten().sum::<u64>() % MOD;
    println!("{}", ans);
}

fn main() {
    run();
}

