const MODULO: usize = 1_000_000_007;

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let l: usize = scan(tokens);
    let r: usize = scan(tokens);
    println!("{}", f(l, r, 1, 1, 1, 1, 0));
}

fn f(l: usize, r: usize, bb: usize, bu: usize, ub: usize, uu: usize, res: usize) -> usize {
    if r == 0 {
        return res;
    }
    f(
        l >> 1,
        r >> 1,
        if l & 1 == 0 {
            if r & 1 == 0 {
                bb
            } else {
                (bu + bb + ub) % MODULO
            }
        } else {
            if r & 1 == 0 {
                0
            } else {
                bb
            }
        },
        if l & 1 == 0 {
            (bu + bu + uu) % MODULO
        } else {
            bu
        },
        if r & 1 == 0 {
            ub
        } else {
            (uu + ub + ub) % MODULO
        },
        (uu + uu + uu) % MODULO,
        if l == 0 {
            if r == 1 {
                (res + ub) % MODULO
            } else {
                (res + uu) % MODULO
            }
        } else if l == 1 {
            if r == 1 {
                (res + bb) % MODULO
            } else {
                (res + bu) % MODULO
            }
        } else {
            res
        },
    )
}

use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

