fn main() {
    let l: i64 = input();
    let r: i64 = input();
    const MOD: i64 = 1000000007;

    let mut dp = vec![vec![vec![vec![0; 2]; 2]; 2]; 62];
    dp[61][0][0][0] = 1;
    for i in (0..61).rev() {
        let lb = l >> i & 1;
        let rb = r >> i & 1;
        for j in 0..2 {
            for k in 0..2 {
                for l in 0..2 {
                    for x in 0..2 {
                        for y in 0..2 {
                            if x == 1 && y == 0 {
                                continue;
                            }
                            if j == 0 && lb == 1 && x == 0 {
                                continue;
                            }
                            let nextj = if lb == 0 && x == 1 { 1 } else { j };
                            if k == 0 && rb == 0 && y == 1 {
                                continue;
                            }
                            let nextk = if rb == 1 && y == 0 { 1 } else { k };
                            if l == 0 && x != y {
                                continue;
                            }
                            let nextl = if x == 1 && y == 1 { 1 } else { l };
                            dp[i][nextj][nextk][nextl] += dp[i + 1][j][k][l];
                            dp[i][nextj][nextk][nextl] %= MOD;
                        }
                    }
                }
            }
        }
    }

    let mut ans = 0i64;
    for j in 0..2 {
        for k in 0..2 {
            for l in 0..2 {
                ans += dp[0][j][k][l];
                ans %= MOD;
            }
        }
    }

    println!("{}", ans);
}

