  println!("{}", count(&dfa, r.len(), &alphabet));
}

use proconio::input;
use std::collections::HashMap;

type State = (usize,bool,bool,bool);
const MOD:i64 = 1_000_000_007;

enum Resp {
    Bad,
    Fin,
    Nex(State)
}
use Resp::Bad;
use Resp::Fin;
use Resp::Nex;

fn trans(st:State,x:usize,y:usize,l:i64,r:i64) -> Resp{
    let x = x as i64;
    let y = y as i64;
    if y<x {
        return Bad;
    }
    let (p,yx,ry,xl) = st;
    if !yx && y>x {
        return Bad;
    }
    if !ry && ((r>>p)&1)<y {
        return Bad;
    }
    if !xl && ((l>>p)&1)>x {
        return Bad;
    }
    if p==0 {
        return Fin;
    }
    let nex_yx = x==1 || yx;
    let nex_ry = ((r>>p)&1)>y || ry;
    let nex_xl = ((l>>p)&1)<x || xl;
    Nex((p-1,nex_yx,nex_ry,nex_xl))
}
fn calc(st:State,mut dp:&mut HashMap<State,i64>,l:i64,r:i64) -> i64{
    if dp.contains_key(&st) {
        return dp[&st];
    }
    let mut ans = 0;
    for i in 0..2 {
        for j in 0..2 {
            let ret = trans(st,i,j,l,r);
            ans +=  match ret {
                        Bad => 0,
                        Fin => 1,
                        Nex(nexst) => calc(nexst,&mut dp,l,r)
                    };
            ans %= MOD;
        }
    }
    dp.insert(st,ans);
    // println!("{:?} {}",st,ans);
    ans
}
fn main() {
    input! {
        l:i64,r:i64
    };

    let mut dp = HashMap::new();
    let st:State = (60,false,false,false);

    let ans = calc(st,&mut dp,l,r);
    println!("{}",ans);
}

pub trait IterScan: Sized {
