fn f(l: usize, r: usize, s: usize) -> usize {
    let b = 1 << s;
    if r < b {
        f(l, r, s - 1)
    } else if l < b {
        (k(l, s) + h(r - b, s)) % MODULO
    } else {
        g(l - b, r - b, s - 1)
    }
}

fn g(l: usize, r: usize, s: usize) -> usize {
    let b = 1 << s;
    if l > r {
        0
    } else if l == r {
        1
    } else if r < b {
        g(l, r, s - 1)
    } else if l < b {
        (k(l, s) + g(l, r - b, s) + h(r - b, s)) % MODULO
    } else {
        g(l - b, r - b, s)
    }
}

fn h(x: usize, s: usize) -> usize {
    let b = 1 << s;
    if x == 0 {
        1
    } else if x < b {
        h(x, s - 1)
    } else {
        (power(3, s) + 2 * h(x - b, s)) % MODULO
    }
}

fn k(x: usize, s: usize) -> usize {
    if s == 0 {
        1
    } else if x < 1 << (s - 1) {
        (k(x, s - 1) + power(3, s - 1)) % MODULO
    } else {
        h((1 << s) - 1 - x, s)
    }
}

fn power(mut b: usize, mut e: usize) -> usize {
    let mut a = 1;
    while e != 0 {
        if e & 1 != 0 {
            a = a * b % MODULO;
        }
        b = b * b % MODULO;
        e >>= 1;
    }
    a
}

